INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37268, NULL, N'What percentage of the facility is covered by static posts  (Please explain in the comments section)', NULL, N'On-Site Security Force', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1095, NULL, NULL)
