INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37270, NULL, N'What percentage of the facility is covered by roving patrols?  (Please explain in the comments section)', NULL, N'On-Site Security Force', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1095, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37271, NULL, N'What percentage of the facility is enclosed in fencing  (Please explain in the comments section)', NULL, N'On-Site Security Force', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1095, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37272, NULL, N'Is there an adequate clear zone (an area that allows for clear sight of fence perimeter with no vegetation, objects or privacy slats) around the perimeter to allow the detection of unauthorized personnel or breaches in the fence?', N'Establish an adequate clear zone around all perimeter fencing and boundary markers. Develop a policy establishing vegetation maintenance requirements/expectations for the property/organization.  This plan should list specific criteria/expectations, a periodic vegetation inspection timeline and maintenance/trimming schedule.', N'Physical Security Features', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1096, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37273, NULL, N'Are fences, walls and other barriers constructed at a height and consistency to prevent unauthorized access? ', N'The security working group should work with a provider to determine the needs of the facility and the options available to establish an effective, secure perimeter.', N'Physical Security Features', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1096, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37274, NULL, N'Are the appropriate warning signs, (e.g. No Trespassing, CCTV in Use, etc.), displayed around the perimeter of the premises?', N'The security working group should consider posting the appropriate signage to discourage undesirable behavior.', N'Physical Security Features', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1096, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37275, NULL, N'Does the facility use vehicle gates?  (Please explain in the comments section)', NULL, N'Physical Security Features', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1096, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37276, NULL, N'Does the facility use pedestrian gates?  (Please explain in the comments section)', NULL, N'Physical Security Features', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1096, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37277, NULL, N'Does the facility have ground floor windows?   (Please explain in the comments section)', NULL, N'Physical Security Features', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1096, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37278, NULL, N'How far from the ground or other accessible walking surface are the ground floor and second story windows?  (Please explain in the comments section)', NULL, N'Physical Security Features', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1096, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37279, NULL, N'Are there protective measures on the ground floor windows for the facility?', N'Effective locks, protective window glazing, alarm sensors on all windows and glass breakage sensors would alleviate this vulnerability.', N'Physical Security Features', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1096, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37280, NULL, N'Does the facility have an air handling system with an external air intake less than or equal to 10 feet from the ground with unrestricted access?', N'Restricting access to air intakes can prevent toxic substances from being introduced into the interior of the building via the air handling system.', N'Physical Security Features', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1096, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37281, NULL, N'Does the facility utilize video surveillance?', N'Work with providers to develop a robust surveillance system which fits the needs of the facility and organization', N'Surveillance System ', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1097, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37282, NULL, N'Does a trained security staff monitor the video surveillance system?', N'Staff responsible for monitoring and/or reviewing video footage should be sufficiently trained to suit the needs of the facility and/or organization. ', N'Surveillance System ', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1097, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37283, NULL, N'Who has access to the video system?', N'Only key personnel specified by senior leadership should have access to the video surveillance system.', N'Surveillance System ', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1097, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37284, NULL, N'Is the footage monitored constantly (active)?', N'Monitoring the footage in real-time provides inceased situational awareness.', N'Surveillance System ', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1097, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37285, NULL, N'Is the footage only reviewed as needed (passive)?', NULL, N'Surveillance System ', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1097, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37286, NULL, N'Who has the ability to review camera coverage?', N'Only key personnel specified by senior leadership should have access to the video surveillance system.', N'Surveillance System ', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1097, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37287, NULL, N'Once footage of an event is saved/downloaded, is the data/footage stored in a secure manner with a documented chain of custody?', N'Video footage may contain specific, sensitive information that may need to be handled securely to prevent unauthorized disclosure or release. Work with the security working group to develop a policy which suits the needs of the organization accordingly.', N'Surveillance System ', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1097, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37288, NULL, N'Is the video surveillance system equipped with video analytics?', N'Video analytics software offers a low-cost solution to make more effective and efficient use of the current video surveillance system. The capabilities of video analytics should be explored by the security working group to see the current technological capabilities and how they may fit the needs of the facility/organization.', N'Surveillance System ', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1097, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37289, NULL, N'Does the video surveillance system have a recording cycle?  ', N'Work with providers to develop a robust surveillance system which fits the needs of the facility and organization and will have a sufficient recording cycle of at least 30 days.  ', N'Surveillance System ', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1097, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37290, NULL, N'How long will the video surveillance system store footage without being prompted to save the footage for a longer period of time?', N'Work with providers to develop a robust surveillance system which fits the needs of the facility and organization and will have a sufficient recording cycle of at least 30 days.  ', N'Surveillance System ', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1097, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37291, NULL, N'Does the system have the ability to store saved footage indefinitely? ', N'Work with providers to develop a secure saved footage storage system with adequate access control and documentation of the chain of custody for potential evidence purposes.', N'Surveillance System ', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1097, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37292, NULL, N'Does the system have the ability to pan/tilt/zoom?', N'Work with providers to develop a robust surveillance system which fits the needs of the facility and organization.  While PTZ cameras may not be beneficial for every camera position, the need for PTZ cameras in key strategic locations should be addressed.', N'Surveillance System ', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1097, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37293, NULL, N'Are all cameras in good working order?', N'Develop a policy establishing surveillance system maintenance requirements/expectations for the property/organization. This plan should list specific criteria/expectations, a daily/weekly camera system check and a monthly/quarterly/annual maintenance schedule. This policy should also establish a work order/urgent repair process to minimize camera system downtime.', N'Surveillance System ', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1097, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37294, NULL, N'Do all cameras capture footage clear enough for their intended purpose?', N'Work with providers to develop a robust surveillance system which fits the needs of the facility and organization.  Cameras should be of sufficient quality to capture the footage as intended in all lighting and weather conditions.', N'Surveillance System ', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1097, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37295, NULL, N'Are cameras mounted in locations inaccessible to passers by to prevent vandalism/sabotage?', N'Work with providers to develop a robust surveillance system which fits the needs of the facility and organization.  Cameras should be installed in such a  way to prevent accidental or intentional damage.', N'Surveillance System ', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1097, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37296, NULL, N'Does the facility have a sufficient amount of cameras to capture footage of areas of the facility requiring coverage?', N'Work with providers to develop a robust surveillance system which fits the needs of the facility and organization.  An adequate amount of cameras should be implemented and utilized effectively to maintain proper surveillance of the facility.', N'Surveillance System ', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1097, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37297, NULL, N'Are all pedestrian points of entry and exit into the building(s) provided camera coverage?', N'Work with providers to develop a robust surveillance system which fits the needs of the facility and organization.  An adequate amount of cameras should be implemented and utilized effectively to maintain proper surveillance of all points of entry and exit of the facility.', N'Surveillance System ', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1097, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37298, NULL, N'Are all loading dock areas provided camera coverage?', N'Work with providers to develop a robust surveillance system which fits the needs of the facility and organization. Video monitoring of the loading dock area(s) should be a high priority. These areas are not only a point of entry/exit, but are often vulnerable to IED/VBIED attacks.', N'Surveillance System ', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1097, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37299, NULL, N'Are all utility rooms provided camera coverage?', N'Work with providers to develop a robust surveillance system which fits the needs of the facility and organization. Video monitoring of utility rooms can capture the potential loss of dependencies. This footage can be very useful to determine the cause of the interruption, as well as capture any potential sabotage.', N'Surveillance System ', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1097, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37300, NULL, N'Are all vehicle approach avenues provided camera coverage?', N'Work with providers to develop a robust surveillance system which fits the needs of the facility and organization. Footage of avenues of vehicle approach should be captured. This footage is useful when conducting counter-surveillance operations, as well as establishing proof of those who arrive and depart the facility, with a timestamp.', N'Surveillance System ', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1097, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37301, NULL, N'Are all parking lots provided camera coverage?', N'Work with providers to develop a robust surveillance system which fits the needs of the facility and organization. Parking lots should have adequate coverage for facility and employee security needs.', N'Surveillance System ', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1097, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37302, NULL, N'Are all IT closets provided camera coverage?', N'Work with providers to develop a robust surveillance system which fits the needs of the facility and organization.  IT closets, like other utility closets, should have adequate coverage to capture the potential loss of dependencies.  This footage can be very useful in determining the cause of the interruption, as well as any potential acts of sabotage.', N'Surveillance System ', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1097, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37303, NULL, N'Are all customer service/customer accessible areas provided camera coverage?', N'Work with providers to develop a robust surveillance system which fits the needs of the facility and organization. Areas with public access should be covered to not only capture any undesirable behaviors, but also any potential accidents (trips, slips, falls, etc.).', N'Surveillance System ', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1097, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37304, NULL, N'Are all mission critical areas provided camera coverage?', N'Work with providers to develop a robust surveillance system which fits the needs of the facility and organization.  Mission critical areas of the facility should be provided camera coverage to maintain a constant video record of the most vulnerable and/or important areas of the facility.', N'Surveillance System ', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1097, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37305, NULL, N'Is the entire exterior of the facility have 360 degrees of camera coverage?', N'Work with providers to develop a robust surveillance system which fits the needs of the facility and organization. Complete video coverage of the exterior of the facility will assist with collecting early warning information. Bad actors will often surveil the facility and the operations of the facility to determine their most desirable time to carry out their plans. Usually, this phase begins outside the facility. Proper counter-surveillance training, policies and equipment can assist in detecting bad actors in this phase of planning.', N'Surveillance System ', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1097, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37306, NULL, N'Are the cameras nighttime capable?', N'Work with providers to develop a robust surveillance system which fits the needs of the facility and organization. Camera systems should be able to effectively capture usable footage during all lighting conditions.', N'Surveillance System ', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1097, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37307, NULL, N'When in full bloom, does any foliage interfere with the camera system?', N'Develop a policy establishing vegetation and foliage control for the property.  This plan should list specific criteria/expectations and an annual maintenance/trimming schedule, with consideration of the extended hours of darkness during the winter months.', N'Surveillance System ', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1097, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37308, NULL, N'Is the facility protected by an intrusion detection system?', N'Invest in a consolidated system which manages access control systems, intrusion detection systems and camera systems across the organization.  These systems require less maintenance and can be updated all at once, across the organization by one operator.', N'Intrusion Detection System', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1098, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37309, NULL, N'Is the security alarm system monitored by a central station?', N'Invest in a consolidated system which manages access control systems, intrusion detection systems and camera systems across the entire organization.  These systems require less maintenance and can be updated all at once, across the organization by one operator.', N'Intrusion Detection System', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1098, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37310, NULL, N'Does the security system have a duress function? Commonly called a panic alarm?', N'Consider installing panic buttons in the appropriate areas (customer service areas, senior leaders’ offices, etc.) to work in concert with a consolidated system.', N'Intrusion Detection System', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1098, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37311, NULL, N'Does the organization''s security system work properly, and is it tested and serviced on a regular basis?', N'Develop a policy establishing security system maintenance requirements/expectations for the property/organization. This plan should list specific criteria/expectations, a monthly system check and a quarterly/annual maintenance schedule.', N'Intrusion Detection System', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1098, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37312, NULL, N'Does the organization have standard operating procedures for staff responding to alarm activations during operating hours and after hours?', N'A Security Working Group should develop a standardized liaison/building custodian arrival plan in conjunction with responding law enforcement agencies to mitigate the risk to responding staff. No staff should ever knowingly arrive on scene to an alarm activation before law enforcement declares the scene safe.', N'Intrusion Detection System', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1098, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37313, NULL, N'Does the intrusion detection system have a cellular or back-up power supply?', N'A dedicated cellular connection and backup supply will allow your IDS to communicate with the dispatch center even when power and communication lines are lost.', N'Intrusion Detection System', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1098, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37314, NULL, N'Are the alarm arming and de-arming codes ever changed?', N'Alarm codes should be maintained in a manner to suit the needs of the facility and the staffing situation, as needed.', N'Intrusion Detection System', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1098, NULL, NULL)
