INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37324, NULL, N'Is the facility open to any group not affiliated with tenant organizations (i.e. gatherings in an auditorium, etc.)?', N'The security working group should thoroughly review the processes involved with granting access to the facility to properly protect the organization''s interests. Security, safety and liability specifics should be analyzed accordingly.', N'Access Control', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 4, NULL, NULL)
