INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37327, NULL, N'Are visitors required to provide proof of identification and sign in/out?', N'All visitors should be required to provide proof of identification and sign in/out.  Not only will this ensure all visitors are being addressed by staff, but it will also provide a roster to show who is in the building at any given time.', N'Access Control', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37328, NULL, N'Do all staff, volunteer leaders, visitors, and vendors wear identification credentials while on premises?', N'Implementing this requirement will allow staff to easily identify persons who have or have not been screened and are authorized access to the facility, as well as to specific parts of the facility.', N'Access Control', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37329, NULL, N'Are visitors required to wear visitor passes designed to look different from staff identification?', N'This requirement will assist staff in immediately identifying visitors from a distance.', N'Access Control', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37330, NULL, N'Are visitor passes collected from visitors when they leave the building?', N'All visitor passes should be collected as the visitors exit the facility to ensure they are not used at a later time for unauthorized access.', N'Access Control', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37331, NULL, N'Do staff challenge or offer to assist people not wearing a visitor’s pass or identification credential?', N'The security working group should determine what type of guidance is to be given to staff. ', N'Access Control', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37332, NULL, N'Are signs used to designate non public areas and establish procedures to prevent unauthorized access?', N'This type of signage is useful to deter unauthorized access to restricted areas. This will also assist staff in recognizing an access breach if/when it does occur. ', N'Access Control', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37333, NULL, N'Are doors to critical areas secured and are there procedures to limit access to authorized personnel only?', N'Best practice is to secure critical doors to prevent unauthorized access. ', N'Access Control', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37334, NULL, N'Are doors to utility, mechanical, electrical, and telecom rooms secured?', N'Best practice is to secure critical doors to prevent unauthorized access. ', N'Access Control', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37335, NULL, N'Are all exterior doors and windows locked during off-hours?', N'Best practice is to secure exterior doors and windows during off-hours.', N'Access Control', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37336, NULL, N'Are all primary access doors secured and require a staff member (physically or electronically) to let them in?', N'Best practice is to secure all primary access doors from unauthorized access. ', N'Access Control', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37337, NULL, N'Are all non-primary access doors locked when not in use?', N'Best practice is to secure all primary access doors from unauthorized access. ', N'Access Control', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37338, NULL, N'Are all doors checked regularly to ensure they are secured per facility policy?', N'Conducting security checks will allow stakeholders to not only ensure the facility is secure, but also monitor security-related habits exhibited by staff (propping doors, piggybacking, etc.).', N'Access Control', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37339, NULL, N'Are primary doors and windows reinforced with bullet-resistant glass and/or security laminate?', N'These options may slow down a potential attacker, allowing staff more time to react to the situation. ', N'Access Control', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37340, NULL, N'Are fire escapes secured in such a way to prevent unauthorized access to the facility?', N'The security working group should consult with local fire agencies to find a solution.', N'Access Control', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 4, NULL, NULL)
