INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37344, NULL, N'Are effective parking control procedures in place and being followed?', N'The security working group should establish guidance and protocols for parking control which suits the needs of the facility.', N'Parking Control', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1100, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37345, NULL, N'Are fire lanes and no parking zones clearly marked?', N'Fire lanes and other no parking zones should be clearly marked as such. The security working group should establish protocols for unauthorized parking which suits the needs of the organization.', N'Parking Control', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1100, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37346, NULL, N'How long would an unfamiliar vehicle be parked in the parking lot before raising suspicions?', N'Proper parking control will mitigate the risks associated with unauthorized parking, to include unauthorized surveillance of the facility/ operations and VBIEDs.', N'Parking Control', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1100, NULL, NULL)
