INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37508, NULL, N'Is there a manager/department in charge of business continuity?', N'A specific person should be responsible for the overall management of the COOP plan. A team comprised of individuals from all sections of the organization should be a part of the continuity planning team.', N'Continuity of Operations', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1117, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37509, NULL, N'Does the facility have a written business continuity plan?', N'A written business continuity plan should be implemented after being developed by the continuity planning team and approved by senior management and general counsel.', N'Continuity of Operations', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1117, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37510, NULL, N'Has the plan been reviewed and approved by senior management/general counsel?', N'A written business continuity plan should be implemented after being developed by the continuity planning team and approved by senior management and general counsel.', N'Continuity of Operations', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1117, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37511, NULL, N'Does the plan specifically list trigger points to enact the COOP?', N'The COOP should list specific triggering points to clearly outline when to enact the plan.', N'Continuity of Operations', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1117, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37512, NULL, N'Does the plan include specific devolution procedures/purviews?', N'The plan should include specific devolution procedures and purviews.', N'Continuity of Operations', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1117, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37513, NULL, N'Does the plan include specific delegations of authority?', N'The plan should clearly outline specific delegations of authority.', N'Continuity of Operations', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1117, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37514, NULL, N'Does the plan include specific succession of command/control as required?', N'The plan should include specific succession of command and control.', N'Continuity of Operations', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1117, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37515, NULL, N'Does the plan list out the essential functions of the organization completed at this site?', N'The plan should list out the essential core functions of the organization completed at this site. ', N'Continuity of Operations', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1117, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37516, NULL, N'Does the plan list the required resources to conduct essential functions?', N'The plan should include provisions for resources to complete essential functions.', N'Continuity of Operations', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1117, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37517, NULL, N'Does the plan contain alternate locations? (Primary, Alternate, Contingent, Emergency- P.A.C.E.)', N'The plan should include thorough details of alternate locations to be used in the event that the primary facility is lost. These details should include, at a minimum: size, capacity, ADA accessibility information, utility providers, parking information and all contract/MOU/MOA agreement information.', N'Continuity of Operations', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1117, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37518, NULL, N'Does the plan cover the four pillars of continuity (Leadership, Personnel, Location, Resources/Records)?', N'The COOP plan should be based upon the four pillars of continuity. A thorough understanding of this process is required to have an effective COOP for most organizations.', N'Continuity of Operations', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1117, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37519, NULL, N'Are personnel trained on the plan?', N'All key personnel should be trained to obtain a thorough understanding of the COOP. All personnel should be trained to perform their specific duties when the COOP is enacted.', N'Continuity of Operations', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1117, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37520, NULL, N'Is the plan exercised at least once a year?', N'The COOP should be exercised annually, or as changes occur.  Capabilities should be evaluated/verified and capability gaps should be noted in the evaluation.  Gaps should be addressed in a process improvement plan using the POETE (Planning, Organizing, Equipping, Training and Exercising)  cycle.', N'Continuity of Operations', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1117, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37521, NULL, N'Is there an appropriate maintenance plan in place for the COOP?', N'A maintenance plan should be included within the COOP. The continuity maintenance plan should include the specific responsibilities and schedule to ensure the COOP is updated as needed.', N'Continuity of Operations', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1117, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37522, NULL, N'Are staff offered guidance on family preparedness for continuity purposes?', N'Staff should be given guidance on personal and family preparedness for their own needs during and after an emergency. If staff are expected to complete their duties for the organization, they must first be prepared to care for themselves and their families.', N'Continuity of Operations', N'Physical Security', NULL, NULL, N'MOPhysical', NULL, NULL, NULL, 1117, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37523, N'AC-1', N'a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:

1. [Selection (one or more): Organization-level; Mission/business process-level; System level] access control policy that:
(a) Addresses purpose, scope, roles, responsibilities, management commitment,
coordination among organizational entities, and compliance; and
(b) Is consistent with applicable laws, executive orders, directives, regulations, policies,
standards, and guidelines; and

2. Procedures to facilitate the implementation of the access control policy and the
associated access controls;
b. Designate an [Assignment: organization-defined official] to manage the development,
documentation, and dissemination of the access control policy and procedures; and
c. Review and update the current access control:
1. Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and
2. Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].
', N'<p><strong>WMATA Policy</strong></p><p>Reference P/I 15.28 Cybersecurity Policy for requirements.</p><p><strong><u>OT Systems Only: </strong></u>The policy specifically addresses the unique properties and requirements of OT and the relationship to non-OT systems. OT access by vendors and maintenance staff can occur over a very large facility footprint or geographic area and into unobserved spaces such as mechanical/electrical rooms, ceilings, floors, field substations, switch and valve vaults, and pump stations.</p><p>Related Controls: IA-1, PM-9, PM-24, PS-8, SI-12</p><p></p><p><br><strong><u>NIST 800-82 Rev 3: <br></strong></u>OT Discussion: The policy specifically addresses the unique properties and requirements of OT <br>and the relationship to non-OT systems. OT access by vendors and maintenance staff can occur <br>over a large facility footprint or geographic area and into unobserved spaces, such as mechanical<br>or electrical rooms, ceilings, floors, field substations, switch and valve vaults, and pump stations. </p>', N'Access Control', N'Policy and Procedures', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37524, N'AC-10', N'Limit the number of concurrent sessions for each [Assignment: organization-defined account and/or account type] to [Assignment: organization-defined number].', N'<p><strong>WMATA Policy</strong></p><p>Limit the number of concurrent sessions for each system account and/or account type to one session for both general and privileged users, unless documented in the SSP and approved by the AO.</p><p><strong><u>OT Systems Only:</strong></u> The number, account type, and privileges of concurrent sessions considers the roles and responsibilities of the affected individuals. Example compensating controls include providing increased auditing measures. </p><p>Related Controls: SC-23</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: The number, account type, and privileges of concurrent sessions consider the <br>roles and responsibilities of the affected individuals. Example compensating controls include <br>providing increased auditing measures. </p>', N'Access Control', N'Concurrent Session Control', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37525, N'AC-11', N'a. Prevent further access to the system by [Selection (one or more): initiating a device lock after [Assignment: organization-defined time period] of inactivity; requiring the user to initiate a device lock before leaving the system unattended]; andb. Retain the device lock until the user reestablishes access using established identification and authentication procedures.', N'<p><strong>WMATA Policy</strong></p><p>a.  Prevent further access to the system by automatically initiating a device lock after 15 minutes of inactivity.</p><p>b. Retain the device lock until the user reestablishes access using established identification and authentication procedures.</p><p><strong><u>OT Systems Only:</strong></u> This control assumes a staffed environment where users interact with system displays. This control may be tailored appropriately where systems do not have displays configured, systems are placed in an access-controlled facility or locked enclosure, or immediate operator response is required in emergency situations. Example compensating controls include locating the display in an area with physical access controls that limit access to individuals with permission and need-to-know for the displayed information.</p><p>Related Controls: AC-2, AC-7, IA-11, PL-4</p><p>c. Security Controls Enhancement(s):</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: This control assumes a staffed environment where users interact with system displays. This control may be tailored appropriately where systems do not have displays configured, systems are placed in an access-controlled facility or locked enclosure, or immediate operator response is required in emergency situations. Example compensating controls include locating the display in an area with physical access controls that limit access to individuals with permission and need-to-know for the displayed information.</p>', N'Access Control', N'Device Lock', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37526, N'AC-11 (1)', N'<p><b>Device Lock | Pattern-hiding Displays</b></p>Conceal, via the device lock, information previously visible on the display with a publicly viewable image.', N'<p><strong>WMATA Policy</strong></p><p>Conceal, via the device lock, information previously visible on the display with a publicly viewable image.</p><p><strong><u>OT Systems Only:</strong></u> Physical protection may be employed to prevent access to a display or prevent attachment of a display. In situations where the OT cannot conceal displayed information, the organization employs nonautomated mechanisms or procedures as compensating controls in accordance with the general tailoring guidance.</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Physical protection may be employed to prevent access to a display or the attachment of a display. When the OT cannot conceal displayed information, the organization employs nonautomated mechanisms or procedures as compensating controls in accordance with the general tailoring guidance. </p>', N'Access Control', N'Device Lock', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37527, N'AC-12', N'Automatically terminate a user session after [Assignment: organization-defined conditions or trigger events requiring session disconnect].', N'<p><strong>WMATA Policy</strong></p><p>Automatically terminate a user session when it has been idle for more than 15 minutes, as a result of a targeted response to certain types of incidents, or time-of-day restrictions on system use as documented in the SSP.</p><p><strong><u>OT Systems Only: </strong></u>Example compensating controls include providing increased auditing measures or limiting remote access privileges to key personnel. </p><p>Related Controls: MA-4, SC-10, SC-23</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Example compensating controls include providing increased auditing measures or limiting remote access privileges to key personnel.</p>', N'Access Control', N'Session Termination', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37528, N'AC-14', N'a. Identify [Assignment: organization-defined user actions] that can be performed on the system without identification or authentication consistent with organizational mission and business functions; andb. Document and provide supporting rationale in the security plan for the system, user actions not requiring identification or authentication.', N'<p><strong>WMATA Policy</strong></p><p>a. Actions permitted within information systems or networks that do not require identification and authentication are:</p><p>i)  General user and general public access to public websites or other publicly accessible WMATA systems, not otherwise protected by security controls; or</p><p>ii) Other defined and approved use cases.</p><p>b.  System/business owners must identify and provide justification in the Account Management Plan user actions that can be performed on systems not requiring identification and authentication. Justification must specify the following:</p><p>i)  Actions that can be performed on the information system without identification and <br>authentication limited to the extent necessary to accomplish Mission/Business Objectives;</p><p>ii)  Identification of the responsible entity for ensuring access control and monitoring is <br>conducted;</p><p>iii) Supporting rationale for not requiring identification and authentication; and</p><p>iv) Identification of compensating security controls at the directory and file level for all <br>application specific and system accounts which do not require authentication. Implement<br>only using least privilege, with access given only to necessary directories and files.</p><p>Related Controls: AC-8, IA-2, PL-2</p>', N'Access Control', N'Permitted Actions Without Identification Or Authentication', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37529, N'AC-17', N'a. Establish and document usage restrictions, configuration/connection requirements, and implementation guidance for each type of remote access allowed; andb. Authorize each type of remote access to the system prior to allowing such connections.', N'<p><strong>WMATA Policy</strong></p><p>a. Establish and document usage restrictions, configuration/connection requirements, and <br>implementation guidance for each type of remote access allowed; and</p><p>b. Authorize each type of remote access to the system prior to allowing such connections. Such <br>connections shall include, but are not limited to:</p><p>i)  For access to the WMATA network, users shall leverage Secure Socket Layer (SSL) VPN, IPSec VPN, <br>or an alternate Virtual Infrastructure as approved by the AO under the following use cases:</p><p>(1) Third-party vendors who require access to WMATA systems and networks;</p><p>(2) Personnel or systems requiring secure Site-to-site connection;</p><p>(3) Users not using WMATA corporate systems; and</p><p>(4) Privileged remote access users</p><p>ii) Multi-factor Authentication (MFA) is required for remote access.</p><p>iii) Data shall not be transferred from Virtual Infrastructure to a local device.</p><p><strong><u>OT Systems Only: </strong></u>In situations where the OT cannot implement any or all of the components of this control, the organization employs other mechanisms or procedures as compensating controls in accordance with the general tailoring practice.</p><p>Related Controls: AC-2, AC-3, AC-4, AC-18, AC-19, AC-20, CA-3, CM-10, IA-2, IA-3, IA-8, MA-4, PE-17, PL-2, PL-4, SC-10, SC-12, SC-13, SI-4</p><p>c. Security Controls Enhancement(s):</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: When the OT cannot implement any or all of the components of this control, the organization employs other mechanisms or procedures as compensating controls in accordance with the general tailoring guidance. </p>', N'Access Control', N'Remote Access', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37530, N'AC-17 (1)', N'<p><b>Remote Access | Monitoring and Control</b></p>Employ automated mechanisms to monitor and control remote access methods.', N'<p><strong>WMATA Policy</strong></p><p>Employ automated mechanisms to monitor and control remote access methods.</p><p><strong><u>OT Systems Only:</strong></u> Example compensating controls include employing nonautomated mechanisms or procedures as compensating controls. Compensating controls could include limiting remote access to a specified period of time or placing a call from the OT site to the authenticated remote entity.</p><p>Related Controls: AU-2, AU-6, AU-12</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Example compensating controls include employing nonautomated mechanisms or procedures as compensating controls. Compensating controls could include limiting remote access to a specified period of time or placing a call from the OT site to the authenticated remote entity. </p>', N'Access Control', N'Remote Access', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37531, N'AC-17 (10)', N'<p><b>Remote Access | Authenticate Remote Commands</b></p>Implement [Assignment: organization-defined mechanisms] to authenticate [Assignment: organization-defined remote commands].', N'<p><strong>WMATA Policy</strong></p><p>Implement [Assignment: organization-defined mechanisms] to authenticate [Assignment: organization-defined remote commands].</p><p>Related Controls: SC-12, SC-13, SC-23</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>Rationale for adding AC-17 (10) to MOD and HIGH baselines: The ability to authenticate remote commands is important to prevent unauthorized commands that may have immediate or serious consequences, such as injury, death, property damage, the loss of high-value assets, the failure of mission or business functions, or compromise of sensitive information. </p>', N'Access Control', N'Remote Access', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37532, N'AC-17 (2)', N'<p><b>Remote Access | Protection of Confidentiality and Integrity Using Encryption</b></p>Implement cryptographic mechanisms to protect the confidentiality and integrity of remote access sessions.', N'<p><strong>WMATA Policy</strong></p><p>Implement cryptographic mechanisms to protect the confidentiality and integrity of<br>remote access sessions.</p><p><strong><u>OT Systems Only: </strong></u>Encryption-based technologies should be used to support the confidentiality and integrity of remote access sessions. While OT devices often lack the ability to support modern encryption, additional devices (e.g., VPNs) can be added to support these features.</p><p>Related Controls: SC-8, SC-12, SC-13</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Encryption-based technologies should be used to support the confidentiality and integrity of remote access sessions. While OT devices often lack the ability to support modern encryption, additional devices (e.g., VPNs) can be added to support these features. This control should not be confused with SC-8 – Transmission Confidentiality and Integrity, which discusses confidentiality and integrity requirements for general communications, including between OT devices. </p><p><strong><u><br></strong></u></p>', N'Access Control', N'Remote Access', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37533, N'AC-17 (3)', N'<p><b>Remote Access | Managed Access Control Points</b></p>Route remote accesses through authorized and managed network access control points.', N'<p><strong>WMATA Policy</strong></p><p>Route remote accesses through authorized and managed network access control points.</p><p><strong><u>OT Systems Only:</strong></u> Example compensating controls include connection-specific manual authentication of the remote entity.</p><p>Related Controls: SC-7</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Example compensating controls include connectionspecific manual authentication of the remote entity. </p><p><br></p>', N'Access Control', N'Remote Access', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37534, N'AC-17 (4)', N'(a) Authorize the execution of privileged commands and access to security-relevant information via remote access only in a format that provides assessable evidence and for the following needs: [Assignment: organization-defined needs]; and(b) Document the rationale for remote access in the security plan for the system.', N'<p><strong>WMATA Policy</strong></p><p>Authorize the execution of privileged commands and access to security-relevant information via remote access only in a format that provides assessable evidence and<br>for the following needs:</p><p>(1) Administrators (security or system) managing devices in a secure zone via an AO- approved dedicated host (e.g., Virtual Desktop Infrastructure (VDI), jump server, or bastion host); and</p><p>(2) Document the rationale for remote access in the security plan for the system.</p><p>Related Controls: AC-6, SC-12, SC-13</p><p></p>', N'Access Control', N'Remote Access', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37535, N'AC-17 (9)', N'<p><b>Remote Access | Disconnect or Disable Access</b></p>Provide the capability to disconnect or disable remote access to the system within [Assignment: organization-defined time period].', N'<p><strong>WMATA Policy</strong></p><p>Provide the capability to disconnect or disable remote access to the system within [Assignment: organization-defined time period].<br>	<br><strong><u>OT Systems Only:</strong></u> Implementation of the remote access disconnect should not impact OT operations. OT personnel should be trained on how to use the remote access disconnect.</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Implementation of the remote access disconnect should not impact OT operations. OT personnel should be trained on how to use the remote access disconnect.</p><p>Rationale for adding AC-17 (9) to LOW, MOD, and HIGH baselines: As more OT systems become accessible remotely, the capability to disconnect or disable remote access is critical to managing risk and may be required to provide stable and safe operations. </p>', N'Access Control', N'Remote Access', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37536, N'AC-18', N'a. Establish configuration requirements, connection requirements, and implementation guidance for each type of wireless access; andb. Authorize each type of wireless access to the system prior to allowing such connections.', N'<p><strong>WMATA Policy</strong></p><p>a.  Establish and document configuration requirements, connection requirements, and implementation guidance for each type of wireless access; and</p><p>b. The AO shall authorize each type of wireless access to the system prior to allowing such <br>connections.</p><p>c.  The following wireless technologies are prohibited in the WMATA environment unless otherwise authorized by the CISO:</p><p>i) Microwave;</p><p>ii) Packet radio (ultra-high frequency, very high frequency, satellite communications, and Internet of Things (IoT) wireless radio frequency);</p><p>iii) 802.11 technologies;</p><p>iv) Bluetooth in accordance with NIST SP 800-121 Rev. 2, Guide to Bluetooth Security; and</p><p>v) Cellular</p><p>d. No other forms of hotspots (e.g., Windows 10 as a hotspot) shall be permitted.</p><p>e. Tethering shall only be permitted between WMATA issued devices. Devices with network access used for tethering shall be on the WMATA corporate network.</p><p>f.  In addition, the following requirements shall be met in the deployment, configuration, <br>administration of wireless networks:</p><p>i)  Wireless network design and implementation must incorporate WIPS</p><p>ii)  Only wireless access points authorized by the AO shall be connected to an internal WMATA network.</p><p>iii) Only WMATA-owned or leased equipment with installed authentication certificates shall be permitted access to an internal WLAN. Systems and devices without approved authentication certificates shall be restricted to the WMATA guest network.</p><p>iv) With the exception of public and guest wireless access, all wireless networks shall use <br>authentication protocols that provide authenticator protection and mutual authentication.</p><p>v) Contractors, vendors and visitors to WMATA facilities permitted to use personal or non- WMATA issued devices shall be restricted to the WMATA guest network.</p><p>vi) All system configurations shall be hardened using DISA STIGs as specified in Control 3.4 Configuration Management, Section 6, “CM-6 Configuration Settings.”</p><p><strong><u>OT Systems Only: </strong></u>In situations where OT cannot implement any or all of the components of this control, the organization employs other mechanisms or procedures as compensating controls in accordance with eh the general tailoring guidance. </p><p>Related Controls: AC-2, AC-3, AC-17, AC-19, CA-9, CM-6, CM-7, IA-2, IA-3, IA-8, PL-4, SI-4</p><p>g. Security Controls Enhancement(s):</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion:  When OT cannot implement any or all of the components of this control, the organization employs other mechanisms or procedures as compensating controls in accordance with the general tailoring guidance. </p>', N'Access Control', N'Wireless Access', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37537, N'AC-18 (1)', N'<p><b>Wireless Access | Authentication and Encryption</b></p>Protect wireless access to the system using authentication of [Selection (one or more): users; devices] and encryption.', N'<p><strong>WMATA Policy</strong></p><p>(1) Protect wireless access to the system using authentication of devices leveraging requirements in accordance with Control 3.17 System and Communications Protection, Section 10, “SC-13 Cryptographic Protection”; and</p><p>(2) Enhance the protection of wireless access to the system using authentication of<br>users if deemed necessary by the AO</p><p><strong><u>OT Systems Only: </strong></u>Implementation of authentication and encryption is driven by the OT environment. There are some scenarios where devices and users cannot all be authenticated and encrypted due to operational or technology constraints. In such scenarios, compensating controls include providing increased auditing for wireless access, limiting wireless access privileges to key personnel, or using AC-18 (5) to reduce the boundary of wireless access.</p><p>Related Controls: SC-8, SC-12, SC-13</p><p><strong><u>NIST 800-82 Rev 3:<br></strong></u>OT Discussion: The implementation of authentication and encryption is driven by the OT environment. If devices and users cannot all be authenticated and encrypted due to operational or technology constraints, compensating controls include providing increased auditing for wireless access, limiting wireless access privileges to key personnel, or using AC-18 (5) to reduce the boundary of wireless access. </p>', N'Access Control', N'Wireless Access', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37538, N'AC-18 (3)', N'Disable, when not intended for use, wireless networking capabilities embedded within system components prior to issuance and deployment.', N'<p><strong>WMATA Policy</strong></p><p>Disable, when not intended for use, wireless networking capabilities embedded within<br>system components prior to issuance and deployment.</p><p></p>', N'Access Control', N'Wireless Access', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37539, N'AC-18 (4)', N'Identify and explicitly authorize users allowed to independently configure wireless networking capabilities.', N'<p><strong>WMATA Policy</strong></p><p>Identify and explicitly authorize users allowed to independently configure wireless<br>networking capabilities.</p><p>Related Controls: SC-7, SC-15</p>', N'Access Control', N'Wireless Access', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37540, N'AC-18 (5)', N'<p><b>Wireless Access | Antennas and Transmission Power Levels</b></p>Select radio antennas and calibrate transmission power levels to reduce the probability that signals from wireless access points can be received outside of organization-controlled boundaries.', N'<p><strong>WMATA Policy</strong></p><p>Select radio antennas and calibrate transmission power levels to reduce the probability that signals from wireless access points can be received outside of organization-<br>controlled boundaries.</p><p><strong><u>OT Systems Only:</strong></u> Availability and interference for wireless signals may be a concern within OT environments. Antennas and power levels should be designated to overcome and achieve availability goals. Where confidentiality is concerned, antennas and power levels can also be designed to minimize signal exposure outside of the facility.</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion:  Availability and interference for wireless signals may be a concern within OT environments. Antennas and power levels should be designed to overcome and achieve availability goals. Where confidentiality is concerned, antennas and power levels can also be designed to minimize signal exposure outside of the facility. </p>', N'Access Control', N'Wireless Access', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37541, N'AC-19', N'a. Establish configuration requirements, connection requirements, and implementation guidance for organization-controlled mobile devices, to include when such devices are outside of controlled areas; andb. Authorize the connection of mobile devices to organizational systems.', N'<p><strong>WMATA Policy</strong></p><p>a.  Establish configuration requirements, connection requirements, and implementation guidance for organization-controlled mobile devices, to include when such devices are outside of controlled areas;</p><p>i)  All mobile devices shall receive updates minimally every 30 days, or more frequently based on the risk profile of the system as determined by the AO.</p><p>ii)  Emergency updates may require a system to connect or be capable of connecting in advance of scheduled updates.</p><p>iii) All mobile devices must connect to the WMATA network via VPN, direct connection, or must have updates managed by an approved Mobile Device Management (MDM) solution.</p><p>b. Authorize the connection of mobile devices to organizational systems;</p><p>c. All mobile devices shall be configured with a secure baseline in accordance with Control 3.4 Configuration Management, Section 6, “CM-6 Configuration Settings”;</p><p>d.  Enable wireless connectivity in compliance with Control 3.1 Access Control, Section 14, “AC- 18 Wireless Access”;</p><p>e. All mobile devices shall have a screen lock and/or timeout set in accordance with Control 3.1 Access Control, Section 11, “AC-12 Session Termination”; and</p><p>f.  Purge or wipe information from mobile devices remotely if systems or components are lost or obtained by unauthorized individuals.</p><p>Related Controls: AC-3, AC-4, AC-7, AC-11, AC-12, AC-17, AC-18, AC-20, CA-9, CM-2, CM-6, IA-2, IA-3, MP-2, MP-4, MP-5, MP-7, PL-4, SC-7, SI-3, SI-4</p><p>g. Security Controls Enhancement(s):</p>', N'Access Control', N'Access Control For Mobile Devices', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37542, N'AC-19 (5)', N'Employ [Selection: full-device encryption; container-based encryption] to protect the confidentiality and integrity of information on [Assignment: organization-defined mobile devices].', N'<p><strong>WMATA Policy</strong></p><p>(1) Employ full-device encryption or container-based encryption to protect the confidentiality and integrity of information on all devices (e.g., laptops, desktops, servers, mobile devices, tablets, thumb drives, etc.) which are authorized to process and store WMATA data, specifically:</p><p>(a) Devices leveraging Microsoft Windows shall employ full disk encryption via BitLocker;</p><p>(b) Devices leveraging non-Windows operating systems shall leverage full disk encryption as approved by the AO;</p><p>(c) Personal or WMATA owned mobile devices shall leverage container-based encryption using an MDM solution. Container configuration shall consider access to, processing, storage and transmission capabilities of WMATA data (e.g., email, text, pictures, documents, downloads, on-board sensors that allow the device to capture information, and/or built-in features for synchronizing local data with remote locations). Container based solutions shall include functionality for the remote <br>wiping, purging, or disablement of the container and all contents therein.</p><p>When available, systems shall employ products on the NIST Cryptographic Module Validation Program, WMATA Approved Product List, and as defined in WMATA policy.</p><p>Related Controls: SC-12, SC-13, SC-28</p>', N'Access Control', N'Access Control For Mobile Devices', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37543, N'AC-2', N'a. Define and document the types of accounts allowed and specifically prohibited for use within the system;b. Assign account managers;c. Require [Assignment: organization-defined prerequisites and criteria] for group and role membership;d. Specify:    1. Authorized users of the system;    2. Group and role membership; and    3. Access authorizations (i.e., privileges) and [Assignment: organization-defined attributes (as required)] for each account;e. Require approvals by [Assignment: organization-defined personnel or roles] for requests to create accounts;f. Create, enable, modify, disable, and remove accounts in accordance with [Assignment: organization-defined policy, procedures, prerequisites, and criteria];g. Monitor the use of accounts;h. Notify account managers and [Assignment: organization-defined personnel or roles] within:    1. [Assignment: organization-defined time period] when accounts are no longer required;    2. [Assignment: organization-defined time period] when users are terminated or transferred; and    3. [Assignment: organization-defined time period] when system usage or need-to-know changes for an individual;i. Authorize access to the system based on:    1. A valid access authorization;    2. Intended system usage; and    3. [Assignment: organization-defined attributes (as required)];j. Review accounts for compliance with account management requirements [Assignment: organization-defined frequency];k. Establish and implement a process for changing shared or group account authenticators (if deployed) when individuals are removed from the group; andl. Align account management processes with personnel termination and transfer processes.', N'<p><strong>WMATA Policy</strong></p><p>a. Define and document the types of accounts allowed and specifically prohibited for use within the <br>system;</p><p>b. Assign account managers;</p><p>c. Require approval and role-based training for group and role membership;</p><p>d. Specify:</p><p>i)  Authorized users of the system;</p><p>ii) Group and role membership; and</p><p>iii) Access authorizations (i.e., privileges and entitlements) and account attributes for each <br>account when applicable.</p><p>e. Require approvals by required stakeholders with access control responsibilities of the <br>accreditation boundary for requests to create accounts;</p><p>f.  Create, enable, modify, disable, and remove accounts in accordance with:</p><p>i)  Control 3.1 Access Control, Section 5, “AC-5 Separation of Duties” and Section 6, “AC- 6 Least <br>Privilege”;</p><p>ii) Standard Operating Procedures (SOP) and Work Instructions (WI); and</p><p>iii) Security Configuration Checklists to include Defense Information Systems Agency (DISA) <br>Security Technical Implementation Guides (STIGs) and Center for Internet Security (CIS) Benchmarks;</p><p>g. Monitor the use of accounts;</p><p>h.  Notify account managers, other required stakeholders, and designated organizational personnel <br>with access control responsibilities of the accreditation boundary immediately, but no later than <br>twenty-four hours when:</p><p>i)  accounts are no longer required;</p><p>ii) users are terminated or transferred; and</p><p>iii) system usage or need-to-know changes for an individual;</p><p>i.  Authorize access to the system based on the following:</p><p>i)  A valid access authorization;</p><p>ii)  Intended system usage (i.e., based on role, type of account, time of day, day of week, and <br>point of origin); and</p><p>iii) Control 3.1 Access Control, Section 5, “AC-5 Separation of Duties” and Section 6, “AC- 6 Least <br>Privilege”.</p><p>j.  Review accounts for compliance with account management requirements:</p><p>i)  Annual recertification is required for all user accounts; and</p><p>ii)  Quarterly recertification is required for all privileged user accounts in accordance with <br>Control 3.1 Access Control, Section 6, “AC-6 Least Privilege”.</p><p>k.  Establish and implement a process for changing shared or group account authenticators (if <br>deployed) when individuals are removed from the group in accordance with Control 3.9 Identification <br>and Authentication, Section 5, “IA-5 Authenticator Management”; and</p><p>l.  Align account management processes with personnel termination and transfer processes.</p><p><strong><u>OT Systems Only: </strong></u>In OT systems, physical security, personnel security, intrusion detection, or auditing measures may assist in supporting this control objective. <br><strong><u><br>OT Systems Only:</strong></u> OT systems may assist in supporting this control objective through physical security, personnel security, intrusion detection, or auditing. </p><p>Related Controls : AC-3, AC-5, AC-6, AC-17, AC-18, AC-20, AU-2, AU-12, CM-5, IA-2, IA-4, IA-5, IA-8, MA-3, MA-5, PE-2, PL-4, PS-2, PS-4, PS-5, PS-7, PT-2, PT-3, SC-7, SC-12, SC-13</p><p>m. Security Controls Enhancement(s):</p><p><strong><u>NIST 800-82 Rev 3: </strong></u><br>OT Discussion: In OT systems, physical security, personnel security, intrusion detection, or <br>auditing measures may support this control objective. </p>', N'Access Control', N'Access Control Policy and Procedures', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37544, N'AC-2 (1)', N'Support the management of system accounts using [Assignment: organization-defined automated mechanisms].', N'<p><strong>WMATA Policy</strong></p><p>Automate the management of system accounts.</p><p></p>', N'Access Control', N'Account Management', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37545, N'AC-2 (11)', N'Enforce [Assignment: organization-defined circumstances and/or usage conditions] for [Assignment: organization-defined system accounts].', N'<p><strong>WMATA Policy</strong></p><p>(1) Enforce only authorized access as specified in Control 3.1 Access Control, Section<br>2, “AC-2 Account Management”, for all accounts.</p><p>(2) No users of WMATA systems have an inherent right to WMATA electronic access, and such access is at the discretion of executive and senior leadership.</p><p>(3) Information technology equipment availability and/or limitations may preclude an employee or contractor from having electronic access.</p><p>(4) Use of WMATA electronic access for non-WMATA purposes may be revoked or<br>limited at any time by appropriate WMATA department heads/office directors.</p><p></p>', N'Access Control', N'Account Management', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37546, N'AC-2 (12)', N'(a) Monitor system accounts for [Assignment: organization-defined atypical usage]; and(b) Report atypical usage of system accounts to [Assignment: organization-defined personnel or roles].', N'<p><strong>WMATA Policy</strong></p><p>(1) Monitor all accounts for atypical or suspicious usage; and</p><p>(2) Report atypical usage of accounts to required stakeholders.</p><p>Related Controls: AU-6, AU-7, CA-7, IR-8, SI-4</p>', N'Access Control', N'Account Management', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37547, N'AC-2 (13)', N'<p><b>Disable Accounts for High-risk Individuals</b></p>Disable accounts of individuals within [Assignment: organization-defined time period] of discovery of [Assignment: organization-defined significant risks].', N'<p><strong>WMATA Policy</strong></p><p>Disable accounts of individuals as referenced in Control 3.1 Access Control, Section 2,<br>“AC-2 (3) Disable Accounts.</p><p><strong><u>OT Systems Only:</strong></u>  Close coordination occurs between OT, Human Resources (HR), IT, and Physical Security personnel to ensure timely removal of high-risk individuals. </p><p>Related Controls: AU-6, SI-4</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Close coordination occurs between OT, HR, IT, and physical security personnel to ensure the timely removal of high-risk individuals. </p>', N'Access Control', N'Account Management', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37548, N'AC-2 (2)', N'<p><b>Automated Temporary and Emergency Account Management</b></p>Automatically [Selection: remove; disable] temporary and emergency accounts after [Assignment: organization-defined time period for each type of account].', N'<p><strong>WMATA Policy</strong></p><p>Under normal usage temporary or emergency accounts are not authorized except where approved by the <br>CISO. The removal or disabling of such accounts shall be automatic after a predefined time period.</p><p><strong><u>OT Systems Only:</strong></u> In situations where the OT (e.g., field devices) cannot support temporary or emergency accounts, this enhancement does not apply. Example compensating controls include employing nonautomated mechanisms or procedures. </p><p><strong><u>NIST 800-82 Rev 3:</strong>      </u><br>OT Discussion: When the OT (e.g., field devices) cannot support temporary or emergency accounts, this enhancement does not apply. Example compensating controls include employing nonautomated mechanisms or procedures. </p>', N'Access Control', N'Account Management', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37549, N'AC-2 (3)', N'Disable accounts within [Assignment: organization-defined time period] when the accounts:(a) Have expired;(b) Are no longer associated with a user or individual;(c) Are in violation of organizational policy; or(d) Have been inactive for [Assignment: organization-defined time period].', N'<p><strong>WMATA Policy</strong></p><p>(1) Accounts will be disabled when they:<br>(a) Have expired;</p><p>(b) Are no longer associated with a user or individual; or</p><p>(c) Are in violation of organizational policy.<br>(2) Accounts shall be disabled within designated timeframes based on the following:</p><p>(a) For high categorized systems, high-risk individuals and privileged accounts,<br>access shall be disabled within 30 minutes.</p><p>(b) For systems categorized as moderate, access shall be disabled within 60<br>minutes.</p><p>(c) For all other systems, access shall be disabled no later than 24 hours.</p><p>(3) Inactive accounts shall be disabled:</p><p>(a) For general users, not to exceed 90 days of inactivity; and</p><p>(b) For privileged users, 90 days or less of inactivity, based on the categorization of<br>the system, individual risk levels, and account type.</p>', N'Access Control', N'Account Management', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37550, N'AC-2 (4)', N'Automatically audit account creation, modification, enabling, disabling, and removal actions.', N'<p><strong>WMATA Policy</strong></p><p>Information systems shall automatically audit account creation, modification, enabling,<br>disabling, and removal actions, and notify the appropriate personnel of these events.</p><p>Related Controls: AU-2, AU-6</p>', N'Access Control', N'Account Management', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37551, N'AC-2 (5)', N'<p><b>Inactivity Logout</b></p>Require that users log out when [Assignment: organization-defined time period of expected inactivity or description of when to log out].', N'<p><strong>WMATA Policy</strong></p><p>Require that users are logged out when the session inactivity time has exceeded the designated threshold as established by the AO. At a minimum, users are required to log<br>out after 24 hours.</p><p><strong><u>OT Systems Only:</strong></u> This control enhancement defines situations or timeframes in which users log out of accounts in policy; automatic enforcement is not addressed by this control enhancement. Organizations determine if this control enhancement is appropriate for the mission and/or functions of the OT system and define the timeframe or scenarios. If no timeframe or scenario(s) apply, the organization-defined parameter reflects as such.</p><p>Related Controls: AC-11  </p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: This control enhancement defines situations or timeframes in which users log out of accounts in the policy. Automatic enforcement is not addressed by this control enhancement. Organizations determine whether this control enhancement is appropriate for the mission and/or functions of the OT system and define the timeframe or scenarios. If no timeframe or scenarios apply, the organization-defined parameter reflects as much. </p>', N'Access Control', N'Account Management', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37552, N'AC-20', N'a. [Selection (one or more): Establish [Assignment: organization-defined terms and conditions]; Identify [Assignment: organization-defined controls asserted to be implemented on external systems]], consistent with the trust relationships established with other organizations owning, operating, and/or maintaining external systems, allowing authorized individuals to:     1. Access the system from external systems; and     2. Process, store, or transmit organization-controlled information using external systems; orb. Prohibit the use of [Assignment: organizationally-defined types of external systems].', N'<p><strong>WMATA Policy</strong></p><p>a. Establish terms, conditions, and controls that shall be implemented on external systems, consistent with the trust relationships established with other organizations owning, operating, and/or maintaining external systems, allowing authorized individuals to:</p><p>i)  Access the system from external systems; and</p><p>ii) Process, store, or transmit organization-controlled information using external systems; or</p><p>b. Prohibit the use of unauthorized systems and devices.</p><p><strong><u>OT Systems Only:</u> </strong>Organizations refine the definition of “external” to reflect lines of authority and responsibility; granularity of organization entity; and their relationships. An organization may consider a system to be external if that system performs different functions, implements different policies, falls under different management authorities, or does not provide sufficient visibility into the implementation of controls to allow the establishment of a satisfactory trust relationship. For example, an OT system and a business data processing system may be considered external to each other depending on the organization’s system boundaries. </p><p>Access to an OT for support by a business partner, such as a vendor or support contractor, is another common example. The definition and trustworthiness of external systems is reexamined with respect to OT functions, purposes, technology, and limitations to establish a clearly documented technical or business case for use and acceptance of the risk inherent in the use of an external system. </p><p>Related Controls: AC-2, AC-3, AC-17, AC-19, CA-3, PL-2, PL-4, SA-9, SC-7</p><p>c. Security Controls Enhancement(s):</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Organizations refine the definition of “external” to reflect lines of authority and responsibility, the granularity of an organization entity, and their relationships. An organization may consider a system to be external if that system performs different functions, implements different policies, falls under different management authorities, or does not provide sufficient <br>visibility into the implementation of controls to allow the establishment of a satisfactory trust relationship. For example, an OT system and a business data processing system may be considered external to each other depending on the organization’s system boundaries. </p><p>Access to an OT for support by a business partner, such as a vendor or support contractor, is another common example. The definition and trustworthiness of external systems is reexamined with respect to OT functions, purposes, technology, and limitations to establish a clearly documented technical or business case for use and an acceptance of the risk inherent in the use of <br>an external system.</p>', N'Access Control', N'Use of External Systems', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37553, N'AC-20 (1)', N'Permit authorized individuals to use an external system to access the system or to process, store, or transmit organization-controlled information only after:(a) Verification of the implementation of controls on the external system as specified in the organization’s security and privacy policies and security and privacy plans; or(b) Retention of approved system connection or processing agreements with the organizational entity hosting the external system.', N'<p><strong>WMATA Policy</strong></p><p>(1) Permit authorized individuals to use an external system to access the system or to<br>process, store, or transmit organization-controlled information only after:</p><p>(a) Verification of the implementation of controls on the external system as specified in the organization’s security and privacy policies and security and privacy plans; or</p><p>(b) Retention of approved system connection or processing agreements with the<br>organizational entity hosting the external system.</p><p>Related Controls: CA-2</p>', N'Access Control', N'Use of External Systems', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37554, N'AC-20 (2)', N'Restrict the use of organization-controlled portable storage devices by authorized individuals on external systems using [Assignment: organization-defined restrictions].', N'<p><strong>WMATA Policy</strong></p><p>(1) Restrict the use of organization-controlled portable storage devices on external<br>systems using encryption.</p><p>Related Controls: MP-7, SC-41</p>', N'Access Control', N'Use of External Systems', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37555, N'AC-21', N'a. Enable authorized users to determine whether access authorizations assigned to a sharing partner match the information’s access and use restrictions for [Assignment: organization-defined information sharing circumstances where user discretion is required]; andb. Employ [Assignment: organization-defined automated mechanisms or manual processes] to assist users in making information sharing and collaboration decisions.', N'<p><strong>WMATA Policy</strong></p><p>a.  Enable authorized users to determine whether access authorizations assigned to a sharing partner match the information’s access and use restrictions for information sharing circumstances; and</p><p>b. Employ automated mechanisms when possible, to assist users in making information sharing and collaboration decisions.</p><p>c.  Information sharing shall apply to information that may be restricted in some manner based on formal or administrative determination. Examples of such information include, contract- sensitive information, Health Insurance Portability and Accountability Act (HIPAA) information, Payment card industry (PCI) information, privileged information, proprietary information, and personally identifiable information.</p><p>d.  Organizational data and systems approved for sharing with external partners must have written agreements regarding the responsibilities of the external partner that address the business,  security  and  technical  requirements  regarding  the  use  and  custodial responsibilities of the data and systems.</p><p>e.  If the sharing of data or systems with external partners is a component of a service, and not otherwise governed by legal requirements, the organizations may choose to use a Service Level Agreement (SLA) that clearly defines the responsibilities, services, priorities and performance metrics of the services to be provided.</p><p>f.  Organization software or information systems that allow the sharing of files and data <br>containing restricted and/or highly restricted information shall be used to share data only if the appropriate security controls, as documented in the SSP, are properly configured and implemented. Appropriate security controls shall include the following:</p><p>i)  Authentication controls to ensure that authorized users are identified.</p><p>ii)  Access controls to limit an individual’s access to only the restricted and/or highly <br>restricted data necessary for that person to perform his/her role.</p><p>iii) Authorization controls to enforce version control and record retention requirements such that only designated individuals are able to modify or delete sensitive or critical records.</p><p>iv) Audit controls that record individual actions on files and records, such as file fication.</p><p>v) Audit logs shall be retained in accordance with the Audit and Accountability control.</p><p>Related Controls: AC-3, AC-4, PT-2, PT-7, RA-3, SC-15</p>', N'Access Control', N'Information Sharing', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37556, N'AC-22', N'a. Designate individuals authorized to make information publicly accessible;b. Train authorized individuals to ensure that publicly accessible information does not contain nonpublic information;c. Review the proposed content of information prior to posting onto the publicly accessible system to ensure that nonpublic information is not included; andd. Review the content on the publicly accessible system for nonpublic information [Assignment: organization-defined frequency] and remove such information, if discovered.', N'<p><strong>WMATA Policy</strong></p><p>a. Designate individuals authorized to make information publicly accessible;</p><p>b.  Train authorized individuals to ensure that publicly accessible information does not contain nonpublic information in accordance with Control 3.8 Data Sensitivity, Section 9, “Categorization of Information”.</p><p>c.  Review the proposed content of information prior to posting onto the publicly accessible system to ensure that nonpublic information is not included; and</p><p>d. Review the content on the publicly accessible system for nonpublic information quarterly, and remove such information, if discovered.</p><p><strong><u>OT Systems Only:</strong></u> Generally, public access to OT systems is not permitted. Select information may be transferred to a publicly accessible system, possibly with added controls. The organization should review what information is being made accessible prior to publication. </p><p>Related Controls: AC-3, AT-2, AT-3</p><p><strong><u>NIST 800-82 Rev 3:</strong></u> <br>OT Discussion:  Generally, public access to OT systems is not permitted. Select information may be transferred to a publicly accessible system, possibly with added controls. The organization should review what information is being made accessible prior to publication. </p>', N'Access Control', N'Publicly Accessible Content', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37557, N'AC-25', N'Implement a reference monitor for [Assignment: organization-defined access control policies] that is tamperproof, always invoked, and small enough to be subject to analysis and testing, the completeness of which can be assured.', N'<p><strong>WMATA Policy</strong></p><p>a. Implement a reference monitor for operating systems.</p><p>Related Controls: AC-3, SA-8, SA-17, SC-3, SC-39, SI-13 </p>', N'Access Control', N'Reference Monitor', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37558, N'AC-3', N'Enforce approved authorizations for logical access to information and system resources in accordance with applicable access control policies.', N'<p><strong>WMATA Policy</strong></p><p>a. Enforce approved authorizations for logical access to information and system resources in accordance with applicable access control processes and procedures.</p><p><strong><u>OT Systems Only:</strong></u> The organization ensures that access enforcement mechanisms do not adversely impact the operational performance of the OT. Example compensating controls include encapsulation. Policy for logical access control to non-addressable and non-routable system resources and the associated information is made explicit. Access control mechanisms include hardware, firmware, and software that control the device or have device access, such as device drivers and communications controllers. Physical access control may serve as a compensating control for logical access control; however, it may not provide sufficient granularity in situations where users require access to different functions.</p><p>Related Controls:  AC-2, AC-4, AC-5, AC-6, AC-17, AC-18, AC-19, AC-20, AC-21, AC-22, AC-25, AT-2, AT-3, AU-9, CA-9, CM-5, CM-11, IA-2, IA-5, IA-6, IA-7, IA-11, MA-3, MA-4, MA-5, MP-4, PM-2, PS-3, PT-2, PT-3, SA-17, SC-2, SC-3, SC-4, SC-12, SC-13, SC-28, SI-4, SI-8</p><p>b.  Security Controls Enhancement(s):</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: The organization ensures that access enforcement mechanisms do not adversely <br>impact the operational performance of the OT. Example compensating controls include <br>encapsulation. The policy for logical access control to non-addressable and non-routable system <br>resources and the associated information is made explicit. Access control mechanisms include <br>hardware, firmware, and software that control the device or have device access, such as device <br>drivers and communications controllers. Physical access control may serve as a compensating <br>control for logical access control. However, it may not provide sufficient granularity when users <br>require access to different functions.</p>', N'Access Control', N'Access Enforcement', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37559, N'AC-3 (11)', N'<p><b>Access Enforcement | Restrict Access to Specific Information Types</b></p>Restrict access to data repositories containing [Assignment: organization-defined information types].', N'<p><strong>WMATA Policy</strong></p><p>Restrict access to data repositories containing [Assignment: organization-defined information types].</p><p><strong><u>OT Systems Only:</strong></u> The organization identifies and restricts access to information that could impact the OT environment, accounting for information types that are sensitive, proprietary, contain trade secrets, or support safety functions. <br>	<br>Related Controls:  CM-8, CM-12, PM-5</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: The organization identifies and restricts access to information that could impact the OT environment and accounts for information types that are sensitive, proprietary, contain trade secrets, or support safety functions. </p><p>Rationale for adding AC-3 (11) to HIGH baseline: The loss of availability, integrity, and <br>confidentiality of certain types of information that reside on a high-impact OT system may result <br>in severe or catastrophic adverse effects on operations, assets, or individuals, including severe <br>degradation or loss of mission capability, major damage to organizational assets, or harm to <br>individuals involving the loss of life or life-threatening injuries. <br></p>', N'Access Control', N'Access Enforcement', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37560, N'AC-3 (14)', N'Provide [Assignment: organization-defined mechanisms] to enable individuals to have access to the following elements of their personally identifiable information: [Assignment: organization-defined elements].', N'<p><strong>WMATA Policy</strong></p><p>Provide mechanisms, such as request forms and applications interfaces to enable<br>individuals to access their personally identifiable information (PII).</p><p>Related Controls: IA-8, PM-20, PM-21, PM-22, PT-6</p>', N'Access Control', N'Access Enforcement', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37561, N'AC-3 (7)', N'Enforce a role-based access control policy over defined subjects and objects and control access based upon [Assignment: organization-defined roles and users authorized to assume such roles].', N'<p><strong>WMATA Policy</strong></p><p>Enforce role-based access control over defined subjects and objects by controlling access. Each  system shall establish an account management plan, inclusive of roles and responsibilities required to execute the plan, pursuant to Control 3.1 Access Control,<br>Section 2, “AC-2 Account Management”.</p>', N'Access Control', N'Access Enforcement', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37562, N'AC-4', N'Enforce approved authorizations for controlling the flow of information within the system and between connected systems based on [Assignment: organization-defined information flow control policies].', N'<p><strong>WMATA Policy</strong></p><p>a.  Ensure that the flow of information within the system, and between connected systems, is  documented and authorized. All WMATA systems shall have a Data Flow Diagram that documents the  storage movement, and processing of data in the system.</p><p><strong><u>OT Systems Only: </strong></u>Information flow policy may be achieved using a combination of logical and physical flow restriction techniques. Inspection of message content may enforce information flow policy. For example, industrial OT protocols may be restricted using inbound and outbound traffic rules on a network control device between OT and IT networks. For non-routable communication such as serial connections, devices may be configured to limit commands to and from specific tags within the OT device. Information flow policy may be supported by labeling or coloring physical connectors to aid in connecting networks. Devices that do not have a business need to communicate should not be connected (i.e., air gapped).</p><p>Related Controls:  AC-3, AC-6, AC-17, AC-19, AC-21, AU-10, CA-3, CA-9, CM-7, PL-9, PM-24, SA-17, SC-4, SC-7</p><p>b. Security Controls Enhancement(s):</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Information flow policy may be achieved using a combination of logical and <br>physical flow restriction techniques. The inspection of message content may enforce information <br>flow policy. For example, industrial OT protocols may be restricted using inbound and outbound <br>traffic rules on a network control device between OT and IT networks. For non-routable <br>communication, such as serial connections, devices may be configured to limit commands to and <br>from specific tags within the OT device. The information flow policy may be supported by <br>labeling or coloring physical connectors to aid in connecting networks. Devices that do not have <br>a business need to communicate should not be connected (i.e., air gapped). </p>', N'Access Control', N'Information Flow Enforcement', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37563, N'AC-4 (4)', N'Prevent encrypted information from bypassing [Assignment: organization-defined information flow control mechanisms] by [Selection (one or more): decrypting the information; blocking the flow of the encrypted information; terminating communications sessions attempting to pass encrypted information; [Assignment: organization-defined procedure or method]].', N'<p><strong>WMATA Policy</strong></p><p>Prevent encrypted information from bypassing flow control mechanisms to include<br>content checking, security policy filters, and data type identifiers by:</p><p>(1) Decrypting the information;</p><p>(2) Blocking the flow of the unauthorized encrypted information;</p><p>(3) Terminating communications sessions attempting to pass unauthorized encrypted<br>information;</p><p>Related Controls: SI-4</p>', N'Access Control', N'Information Flow Enforcement', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37564, N'AC-5', N'a. Identify and document [Assignment: organization-defined duties of individuals requiring separation]; andb. Define system access authorizations to support separation of duties.', N'<p><strong>WMATA Policy</strong></p><p>a. The following roles shall have duties separated:</p><p>i)  General user activities (e.g., resource or file access);</p><p>ii) System and application development (e.g., programmers);</p><p>iii) Database administration and management (e.g., database administrators)</p><p>iv) Technical operations and system or network administration (e.g., system administrator, and <br>network administrator, system maintenance personnel); and</p><p>v) Security Administration and Management (e.g., Security Administrator, ISSM/O).</p><p>b. Define system access authorizations to support separation of duties.</p><p>c.  An individual user may have a general user account and one privileged level account only unless <br>additional accesses are documented and approved in the Account Management Plan.</p><p><strong><u>OT Systems Only: </strong></u>Example compensating controls include providing increased personnel security and auditing. The organization carefully considers the appropriateness of a single individual performing multiple critical roles. </p><p>Related Controls: AC-2, AC-3, AC-6, AU-9, CM-5, CM-11, CP-9, IA-2, IA-4, IA-5, IA-12, MA-3, MA-5, PS-2, SA-8, SA-17</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Example compensating controls include providing increased personnel security <br>and auditing. The organization carefully considers the appropriateness of a single individual <br>performing multiple critical roles.</p>', N'Access Control', N'Separation of Duties', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37565, N'AC-6', N'Employ the principle of least privilege, allowing only authorized accesses for users (or processes acting on behalf of users) that are necessary to accomplish assigned organizational tasks.', N'<p><strong>WMATA Policy</strong></p><p>a.  Employ the principle of least privilege, allowing only authorized accesses for users (or <br>processes acting on behalf of users) that are necessary to accomplish assigned organizational tasks <br>in accordance with WMATA missions and business functions. Least privilege applies to all stages of <br>the System Development Lifecycle (SDLC).</p><p>b.  Only authorized individuals shall access, manage, and perform updates to sensitive information <br>as classified in Control 3.8 Data Sensitivity.</p><p><strong><u>OT Systems Only: </strong></u>Example compensating controls include providing increased personnel security and auditing. The organization carefully considers the appropriateness of a single individual having multiple critical privileges. System privilege models may be tailored to enforce integrity and availability (e.g., lower privileges include read access and higher privileges include write access).</p><p>Related Controls : AC-2, AC-3, AC-5, CM-5, CM-11, PL-2, PM-12, SA-8, SA-15, SA-17  </p><p>c. Security Controls Enhancement(s):</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Example compensating controls include providing increased personnel security <br>and auditing. The organization carefully considers the appropriateness of a single individual <br>having multiple critical privileges. System privilege models may be tailored to enforce integrity <br>and availability (e.g., lower privileges include read access, and higher privileges include write <br>access).</p>', N'Access Control', N'Least Privilege', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37566, N'AC-6 (1)', N'<p><b>Least Privilege | Authorize Access to Security Functions</b></p>Authorize access for [Assignment: organization-defined individuals or roles] to:(a) [Assignment: organization-defined security functions (deployed in hardware, software, and firmware)]; and(b) [Assignment: organization-defined security-relevant information].', N'<p><strong>WMATA Policy</strong></p><p>(1) All security functions deployed in hardware, software, and firmware shall be documented in the System Security Plan (SSP) and all security functions shall be clearly annotated.</p><p>(2) Authorize access for individuals or roles to security functions, to include security <br>administrators,  system  administrators,  system  security  officers,  system programmers, and other privileged users, inclusive of:</p><p>(a) Security functions (deployed in hardware, software, and firmware) to include establishing system  accounts,  configuring  access  authorizations  (i.e., permissions, privileges), configuring settings for events to be audited, and establishing intrusion detection parameters; and</p><p>(b) Security-relevant information, to include filtering rules for routers or firewalls, <br>configuration parameters for security services, cryptographic key management information, and access control lists.</p><p>(c) All other security functions defined in the SSP.</p><p><strong><u>OT Systems Only:</strong></u> In situations where the OT components (e.g., PLCs) cannot support logging of privileged functions, other system components within the authorization boundary may be used (e.g., engineering workstations or physical access monitoring).</p><p>Related Controls: AC-17, AC-18, AC-19, AU-9, PE-2</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: When OT components (e.g., PLCs) cannot support the logging of privileged functions, other system components within the authorization boundary may be used (e.g., engineering workstations or physical access monitoring). </p><p></p><p></p>', N'Access Control', N'Least Privilege', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37567, N'AC-6 (10)', N'<p><b>Least Privilege | Prohibit Non-privileged Users from Executing Privileged Functions</b></p>Prevent non-privileged users from executing privileged functions.', N'<p><strong>WMATA Policy</strong></p><p>Prevent non-privileged users from executing privileged functions.</p><p><strong><u>OT Systems Only:</strong></u> Example compensating controls include enhanced auditing. </p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Example compensating controls include enhanced auditing.</p><p><br></p>', N'Access Control', N'Least Privilege', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37568, N'AC-6 (2)', N'<p><b>Least Privilege | Non-privileged Access for Nonsecurity Functions</b></p>Require that users of system accounts (or roles) with access to [Assignment: organization-defined security functions or security-relevant information] use non-privileged accounts or roles, when accessing nonsecurity functions.', N'<p><strong>WMATA Policy</strong></p><p>Require that users of system accounts (or roles) with access to security functions or security-relevant information use non-privileged accounts or roles, when accessing non- security functions. Security functions include but are not limited to those functions described in Control 3.1 Access Control, Section 6, (b), (i), “AC-6 (1) Authorize Access to Security Function”.</p><p><strong><u>OT Systems Only:</strong></u> In situations where the OT components (e.g., PLCs) cannot support logging of privileged functions, other system components within the authorization boundary may be used (e.g., engineering workstations or physical access monitoring). </p><p>Related Controls: AC-17, AC-18, AC-19, PL-4</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: When OT components (e.g., PLCs) cannot support the logging of privileged functions, other system components within the authorization boundary may be used (e.g., engineering workstations or physical access <br>monitoring). </p>', N'Access Control', N'Least Privilege', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37569, N'AC-6 (3)', N'<p><b>Least Privilege | Network Access to Privileged Commands</b></p>Authorize network access to [Assignment: organization-defined privileged commands] only for [Assignment: organization-defined compelling operational needs] and document the rationale for such access in the security plan for the system.', N'<p><strong>WMATA Policy</strong></p><p>Authorize network access to privileged commands only for assigned duties and/or responsibilities and document the rationale for such access in the SSP.</p><p><strong><u>OT Systems Only:</strong></u> In situations where the OT components (e.g., PLCs) cannot support logging of privileged functions, other system components within the authorization boundary may be used (e.g., engineering workstations or physical access monitoring). </p><p>Related Controls: AC-17, AC-18, AC-19</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: When OT components (e.g., PLCs) cannot support the logging of privileged functions, other system components within the authorization boundary may be used (e.g., engineering workstations or physical access <br>monitoring). </p>', N'Access Control', N'Least Privilege', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37570, N'AC-6 (5)', N'<p><b>Least Privilege | Privileged Accounts</b></p>Restrict privileged accounts on the system to [Assignment: organization-defined personnel or roles].', N'<p><strong>WMATA Policy</strong></p><p>Restrict privileged accounts on the system to authorized personnel as documented in the Enterprise Identity and Access Management (EIAM) system.</p><p><strong><u>OT Systems Only: </strong></u>In situations where the OT components (e.g., PLCs) cannot support logging of privileged functions, other system components within the authorization boundary may be used (e.g., engineering workstations or physical access monitoring). </p><p>Related Controls: IA-2, MA-3, MA-4</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: When OT components (e.g., PLCs) cannot support the logging of privileged functions, other system components within the authorization boundary may be used (e.g., engineering workstations or physical access <br>monitoring). </p>', N'Access Control', N'Least Privilege', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37571, N'AC-6 (7)', N'(a) Review [Assignment: organization-defined frequency] the privileges assigned to [Assignment: organization-defined roles or classes of users] to validate the need for such privileges; and(b) Reassign or remove privileges, if necessary, to correctly reflect organizational mission and business needs.', N'<p><strong>WMATA Policy</strong></p><p>(1) Review and recertify annually the privileges assigned to general users and roles or<br>classes of users to validate the need for such privileges; and</p><p>(2) Review and recertify quarterly the privileges assigned to privileged users and any associated <br>roles to validate the need for such privileges; and</p><p>(3) Reassign or remove privileges, if necessary, to correctly reflect organizational<br>mission and business needs.</p><p>Related Controls: CA-7</p>', N'Access Control', N'Least Privilege', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37572, N'AC-6 (9)', N'<p><b>Least Privilege | Log Use of Privileged Functions</b></p>Log the execution of privileged functions.', N'<p><strong>WMATA Policy</strong></p><p>Log the execution of privileged functions.</p><p><strong><u>OT Systems Only:</strong></u> In situations where the OT components (e.g., PLCs) cannot support logging of privileged functions, other system components within the authorization boundary may be used (e.g., engineering workstations or physical access monitoring).</p><p>Related Controls: AU-2, AU-3, AU-12</p><p><strong><u>NIST 800-82 Rev 3:<br></strong></u>OT Discussion: When OT components (e.g., PLCs) cannot support the logging of privileged functions, other system components within the authorization boundary may be used (e.g., engineering workstations or physical access monitoring). </p>', N'Access Control', N'Least Privilege', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37573, N'AC-7', N'a. Enforce a limit of [Assignment: organization-defined number] consecutive invalid logon attempts by a user during a [Assignment: organization-defined time period]; andb. Automatically [Selection (one or more): lock the account or node for an [Assignment: organization-defined time period]; lock the account or node until released by an administrator; delay next logon prompt per [Assignment: organization-defined delay algorithm]; notify system administrator; take other [Assignment: organization-defined action]] when the maximum number of unsuccessful attempts is exceeded.', N'<p><strong>WMATA Policy</strong></p><p>When the maximum number of unsuccessful attempts is exceeded:</p><p>a.  Enforce a limit of three failed invalid logon attempts by a user during a 15-minute time <br>period;</p><p>b.  Automatically lock the account or node until released by an administrator when the maximum number of unsuccessful attempts is exceeded. See Control 3.9 Identification and Authentication control;</p><p>c. Automate unlocking of a system as documented in the SSP and approved by the AO; and</p><p>d.  For public-facing or Intranet web-based applications, automatically lock the account until released by an administrator or prompt the user to answer a secret question in addition to requiring a Completely Automated Public Turing test to tell Computer and Humans Apart (CAPTCHA) or answering challenge questions to prevent automated attacks.</p><p><strong><u>OT Systems Only: </strong></u>Many OT systems remain in continuous operation and operators remain logged onto the system at all times. A “log-over” capability may be employed. Example compensating controls include logging or recording all unsuccessful login attempts and alerting OT security personnel through alarms or other means when the number of organization-defined consecutive invalid access attempts is exceeded. Unsuccessful logon attempt limits are enforced for accounts (e.g., administrator) or systems (e.g., engineering workstations) not required for continuous operation. </p><p>Related Controls: AC-2, AU-2, AU-6, IA-5</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Many OT systems remain in continuous operation, and operators remain logged <br>onto the system at all times. A “log-over” capability may be employed. Example compensating <br>controls include logging or recording all unsuccessful logon attempts and alerting OT security <br>personnel through alarms or other means when the number of organization-defined consecutive <br>invalid access attempts is exceeded. Unsuccessful logon attempt limits are enforced for accounts <br>(e.g., administrator) or systems (e.g., engineering workstations) that are not required for <br>continuous operation. </p>', N'Access Control', N'Unsuccessful Logon Attempts', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37574, N'AC-8', N'a. Display [Assignment: organization-defined system use notification message or banner] to users before granting access to the system that provides privacy and security notices consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines and state that:     1. Users are accessing a U.S. Government system;     2. System usage may be monitored, recorded, and subject to audit;     3. Unauthorized use of the system is prohibited and subject to criminal and civil penalties; and     4. Use of the system indicates consent to monitoring and recording;b. Retain the notification message or banner on the screen until users acknowledge the usage conditions and take explicit actions to log on to or further access the system; andc. For publicly accessible systems:     1. Display system use information [Assignment: organization-defined conditions], before granting further access to the publicly accessible      system;     2. Display references, if any, to monitoring, recording, or auditing that are consistent with privacy accommodations for such systems that      generally prohibit those activities; and     3. Include a description of the authorized uses of the system.', N'<p><strong>WMATA Policy</strong></p><p>a.  Display the official WMATA system use notification to users before granting access to the system that provides privacy and security notices consistent with applicable laws, directives, regulations, policies, standards, and guidelines and state that:</p><p>i)  Users are accessing a WMATA system;</p><p>ii) System usage may be monitored, recorded, and subject to audit;</p><p>iii) Unauthorized use of the system is prohibited and subject to criminal and civil penalties; and</p><p>iv) Use of the system indicates consent to monitoring and recording;</p><p>b. Retain the notification message or banner on the screen until users acknowledge the usage conditions and take explicit actions to logon to or further access the system; and</p><p>c. For publicly accessible systems:</p><p>i)  Display the official WMATA system use notice before granting access to publicly accessible systems. System use notices shall be displayed on all user logon pages.</p><p>ii)  Display references, if any, to monitoring, recording, or auditing that are consistent with <br>privacy accommodations for such systems that generally prohibit those activities; and</p><p>iii) Include a description of the authorized uses of the system.</p><p><strong><u>OT Systems Only:</strong></u> Many OT systems must remain in continuous operation and system use notification may not be supported or effective. Example compensating controls include posting physical notices in OT facilities or providing recurring training on system use prior to permitting access. </p><p>Related Controls: AC-14, PL-4, SI-4</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Many OT systems must remain in continuous operation, and system use notification may not be supported or effective. Example compensating controls include posting physical notices in OT facilities or providing recurring training on system use prior to permitting access.</p>', N'Access Control', N'System Use Notification', NULL, NULL, N'WMATA', NULL, NULL, NULL, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37575, N'AT-1', N'a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:     1. [Selection (one or more): Organization-level; Mission/business process-level; System-level] awareness and training policy that:          (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and           compliance; and          (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and     2. Procedures to facilitate the implementation of the awareness and training policy and the associated awareness and training controls;          b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the           awareness and training policy and procedures; and          c. Review and update the current awareness and training:               1. Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and               2. Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].', N'<p><strong>WMATA Policy</strong></p><p>Reference P/I 15.28 Cybersecurity Policy for requirements.</p><p>Related Controls: PM-9, PS-8, SI-12</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion:  The policy specifically addresses the unique properties and requirements of OT and the relationship to non-OT systems.</p>', N'Awareness and Training', N'Awareness and Training Policy and Procedures', NULL, NULL, N'WMATA', NULL, NULL, NULL, 63, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37576, N'AT-2', N'a. Provide security and privacy literacy training to system users (including managers, senior executives, and contractors):     1. As part of initial training for new users and [Assignment: organization-defined frequency] thereafter; and     2. When required by system changes or following [Assignment: organization-defined events];b. Employ the following techniques to increase the security and privacy awareness of system users [Assignment: organization-defined awareness techniques];c. Update literacy training and awareness content [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; andd. Incorporate lessons learned from internal or external security incidents or breaches into literacy training and awareness techniques.', N'<p><strong>WMATA Policy</strong></p><p>a. Provide security and privacy literacy training to users:</p><p>i)  As part of initial training for new users and annually thereafter; and</p><p>ii) When required by system changes or following events that may precipitate an update to literacy training and awareness content.</p><p>b. Employ techniques to increase the security and privacy awareness of users, such as:</p><p>i)  Displaying posters;</p><p>ii) Offering supplies inscribed with security and privacy reminders;</p><p>iii) Displaying logon screen and screensaver messages;</p><p>iv) Generating email advisories or notices from organizational officials; and</p><p>v) Conducting awareness events.</p><p>c.  Update literacy training and awareness content annually and following events that may <br>precipitate an update, including but not limited to assessment or audit findings, cybersecurity or privacy incidents, or changes in applicable laws, directives, regulations, policies, standards, and guidelines; and</p><p>d. Incorporate lessons learned from internal or external cybersecurity incidents or breaches into literacy training and awareness techniques.</p><p>e.  Mandate security awareness and training for users within 90 days of initial employment and annually thereafter; and </p><p>f.  For suspended accounts, reinstate network access after successfully completing the Security Awareness Training course.</p><p><strong><u>OT Systems Only:</strong></u> Security awareness training includes initial and periodic review of OT-specific policies, standard operating procedures, security trends, and vulnerabilities. The OT security awareness program is consistent with the requirements of the security awareness and training policy established by the organization. </p><p>Related Controls: AC-3, AC-17, AC-22, AT-3, AT-4, CP-3, IA-4, IR-2, IR-7, IR-9, PL-4, PM-13, PM-21, PS-7, PT-2, SA-8, SA-16</p><p>g. Security Controls Enhancement(s):</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Security awareness training includes initial and periodic review of OT-specific policies, standard operating procedures, security trends, and vulnerabilities. The OT security awareness program is consistent with the requirements of the security awareness and training policy established by the organization.</p>', N'Awareness and Training', N'Literacy Training and Awareness', NULL, NULL, N'WMATA', NULL, NULL, NULL, 63, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37577, N'AT-2 (2)', N'Provide literacy training on recognizing and reporting potential indicators of insider threat.', N'<p><strong>WMATA Policy</strong></p><p>Provide literacy training on recognizing and reporting potential indicators of insider threat.</p><p>Related Controls: IR-9, PM-12</p>', N'Awareness and Training', N'Literacy Training and Awareness', NULL, NULL, N'WMATA', NULL, NULL, NULL, 63, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37578, N'AT-2 (3)', N'Provide literacy training on recognizing and reporting potential and actual instances of social engineering and social mining.', N'<p><strong>WMATA Policy</strong></p><p>(1) Provide literacy training on recognizing and reporting potential and actual instances of social engineering and social mining.</p><p>f. Mandate security awareness and training for users within 90 days of initial employment and annually thereafter; and</p><p>g. For suspended accounts, reinstate network access after successfully completing the Security Awareness Training course.<br></p>', N'Awareness and Training', N'Literacy Training and Awareness', NULL, NULL, N'WMATA', NULL, NULL, NULL, 63, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37579, N'AT-2 (4)', N'<p><b>Literacy Training and Awareness | Suspicious Communications and Anomalous System Behavior</b></p>Provide literacy training on recognizing suspicious communications and anomalous behavior in organizational systems using [Assignment: organization-defined indicators of malicious code].', N'<p><strong>WMATA Policy</strong></p><p>Provide literacy training on recognizing suspicious communications and anomalous behavior in organizational systems using [Assignment: organization-defined indicators of malicious code].</p><p><strong><u>OT Systems Only: </strong></u>Identify and communicate suspicious and anomalous behaviors within the OT environment. Some examples of OT suspicious or anomalous behavior may include a PLC still in programming mode when it is expected to be in run mode, process trips with undetermined root cause, malware on an HMI, unexpected mouse movement, or process changes that are not being performed by the operator </p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Identify and communicate suspicious and anomalous behaviors within the OT environment. Some examples of OT suspicious or anomalous behavior may include a PLC still in programming mode when it is expected to be in run mode, process trips with an undetermined root cause, malware on an HMI, unexpected mouse movement, or process changes that are not being performed by the operator. </p><p>Rationale for adding AT-2 (4) to MOD and HIGH baselines: Training OT personnel on potentially suspicious communications and anomalous behaviors as well as the actions to take if <br>anomalous system behavior occurs can supplement system detection and protection mechanisms <br>for improved response. </p>', N'Awareness and Training', N'Literacy Training and Awareness', NULL, NULL, N'WMATA', NULL, NULL, NULL, 63, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37580, N'AT-3', N'a. Provide role-based security and privacy training to personnel with the following roles and responsibilities: [Assignment: organization-defined roles and responsibilities]:     1. Before authorizing access to the system, information, or performing assigned duties, and [Assignment: organization-defined frequency]      thereafter; and     2. When required by system changes;b. Update role-based training content [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; andc. Incorporate lessons learned from internal or external security incidents or breaches into role-based training.', N'<p><strong>WMATA Policy</strong></p><p>a. Provide role-based (e.g., user, privileged user, etc.) security and privacy training to personnel:</p><p>i) Before authorizing access to the system, information, or performing assigned duties, and annually thereafter; and</p><p>ii) When required by system changes;</p><p>b. Update role-based training content annually and following events that may precipitate an update, including but not limited to, assessment or audit findings, cybersecurity or privacy incidents, or changes in applicable laws, directives, regulations, policies, standards, and guidelines; and</p><p>c. Incorporate lessons learned from internal or external cybersecurity incidents or breaches into role-based training.</p><p><strong><u>OT Systems Only:</strong></u> Security training includes initial and periodic review of OT-specific policies, standard operating procedures, security trends, and vulnerabilities. The OT security training program is consistent with the requirements of the security awareness and training policy established by the organization. The training may be customized for specific OT roles, which could include operators, maintainers, engineers, supervisors, and administrators. </p><p>Related Controls: AC-3, AC-17, AC-22, AT-2, AT-4, CP-3, IR-2, IR-4, IR-7, IR-9, PL-4, PM-13, PM-23, PS-7, PS-9, SA-3, SA-8, SA-11, SA-16, SR-5, SR-6, SR-11</p><p>d.  Security Controls Enhancement(s):</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Security training includes initial and periodic review of OT-specific policies, <br>standard operating procedures, security trends, and vulnerabilities. The OT security training <br>program is consistent with the requirements of the security awareness and training policy <br>established by the organization. The training may be customized for specific OT roles, which <br>could include operators, maintainers, engineers, supervisors, and administrators. </p>', N'Awareness and Training', N'Role-based Training', NULL, NULL, N'WMATA', NULL, NULL, NULL, 63, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37581, N'AT-3 (5)', N'Provide [Assignment: organization-defined personnel or roles] with initial and [Assignment: organization-defined frequency] training in the employment and operation of personally identifiable information processing and transparency controls.', N'<p><strong>WMATA Policy</strong></p><p>Provide applicable personnel with initial and annual training in the employment and operation of personally identifiable information processing and transparency controls.</p><p>Related Controls: PT-2, PT-3, PT-5, PT-6</p>', N'Awareness and Training', N'Role-Based Training', NULL, NULL, N'WMATA', NULL, NULL, NULL, 63, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37582, N'AT-4', N'a. Document and monitor information security and privacy training activities, including security and privacy awareness training and specific role-based security and privacy training; andb. Retain individual training records for [Assignment: organization-defined time period].', N'<p><strong>WMATA Policy</strong></p><p>a. Document and monitor information security and privacy training activities, including security and privacy awareness training and specific role-based security and privacy training;</p><p>b. Retain individual training records to align with enterprise learning and management application requirements; and</p><p>c. Reporting training compliance minimally on a quarterly basis.</p><p>Related Controls: AT-2, AT-3, CP-3, IR-2, PM-14, SI-12</p><p><br></p>', N'Awareness and Training', N'Training Records', NULL, NULL, N'WMATA', NULL, NULL, NULL, 63, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37583, N'AU-1', N'a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:     1. [Selection (one or more): Organization-level; Mission/business process-level; System-level] audit and accountability policy that:          (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and           compliance; and          (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and     2. Procedures to facilitate the implementation of the audit and accountability policy and the associated audit and accountability controls;b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the audit and accountability policy and procedures; andc. Review and update the current audit and accountability:     1. Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and     2. Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].', N'<p><strong>WMATA Policy</strong></p><p>Reference P/I 15.28 Cybersecurity Policy for requirements.</p><p>Related Controls: PM-9, PS-8, SI-12</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: The policy specifically addresses the unique properties and requirements of OT <br>and the relationship to non-OT systems.</p>', N'Audit and Accountability', N'Audit and Accountability Policy and Procedures', NULL, NULL, N'WMATA', NULL, NULL, NULL, 6, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37584, N'AU-10', N'Provide irrefutable evidence that an individual (or process acting on behalf of an individual) has performed [Assignment: organization-defined actions to be covered by non-repudiation].', N'<p><strong>WMATA Policy</strong></p><p>Provide irrefutable evidence that an individual (or process acting on behalf of an individual) has performed actions to include creating information, sending and receiving messages, and approving information.</p><p><strong><u>OT Systems Only: </strong></u>OT devices may not enforce non-repudiation of audit records and may require compensating controls. Example compensating controls include physical security systems, cameras to monitor user access, or a separate device for log collection. </p><p>Related Controls: AU-9, SA-8, PM-12, SC-8, SC-12, SC-13, SC-17, SC-23</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: OT devices may not enforce non-repudiation of audit records and may require <br>compensating controls. Example compensating controls include physical security systems, <br>cameras to monitor user access, or a separate device for log collection.</p>', N'Audit and Accountability', N'Non-repudiation', NULL, NULL, N'WMATA', NULL, NULL, NULL, 6, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37585, N'AU-11', N'Retain audit records for [Assignment: organization-defined time period consistent with records retention policy] to provide support for after-the-fact investigations of incidents and to meet regulatory and organizational information retention requirements.', N'<p><strong>WMATA Policy</strong></p><p>a.  Retain audit records for all WMATA systems for at least five years or longer if specified by applicable regulation, law, or external compliance mandate to provide support for after-the- fact investigations of incidents and to meet regulatory and organizational information retention requirements.</p><p>Related Controls: AU-2, AU-4, AU-5, AU-6, AU-9, MP-6, RA-5, SI-12</p>', N'Audit and Accountability', N'Audit Record Retention', NULL, NULL, N'WMATA', NULL, NULL, NULL, 6, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37586, N'AU-12', N'a. Provide audit record generation capability for the event types the system is capable of auditing as defined in AU-2a on [Assignment: organization-defined system components];b. Allow [Assignment: organization-defined personnel or roles] to select the event types that are to be logged by specific components of the system; andc. Generate audit records for the event types defined in AU-2c that include the audit record content defined in AU-3.', N'<p><strong>WMATA Policy</strong></p><p>a.  Provide audit record generation capability for the event types the system is capable of auditing in accordance with Control 3.3 Audit and Accountability, Section 2, (a), “AU-2 Event Logging”, on all system components;</p><p>b.  Allow required stakeholders to select the event types that are to be logged by specific components of the system; and</p><p>c.  Generate audit records for the event types in accordance with Control 3.3 Audit and <br>Accountability, Section 2, (c), “AU-2 Event Logging”, that includes the audit record content in accordance with Control 3.3 Audit and Accountability, Section 3, “AU-3 Content of Audit Records”.</p><p>Related Controls: AC-6, AC-17, AU-2, AU-3, AU-4, AU-5, AU-6, AU-7, CM-5, MA-4, MP-4, PM-12, SA-8, SC-18, SI-3, SI-4, SI-7, SI-10</p><p>d. Security Controls Enhancement(s):</p><p></p>', N'Audit and Accountability', N'Audit Record Generation', NULL, NULL, N'WMATA', NULL, NULL, NULL, 6, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37587, N'AU-12 (1)', N'<p><b>Audit Record Generation | System-wide and Time-correlated Audit Trail</b></p>Compile audit records from [Assignment: organization-defined system components] into a system-wide (logical or physical) audit trail that is time-correlated to within [Assignment: organization-defined level of tolerance for the relationship between time stamps of individual records in the audit trail].', N'<p><strong>WMATA Policy</strong></p><p>Compile audit records from all system components into a system-wide (logical or physical) audit trail that is time-correlated to within 30 seconds of WMATA standard time as defined in WMATA policy. All systems shall use network time.</p><p>Related Controls: AU-8, SC-45</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Example compensating controls include providing time-correlated audit records on a separate system.</p>', N'Audit and Accountability', N'Audit Record Generation', NULL, NULL, N'WMATA', NULL, NULL, NULL, 6, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37588, N'AU-12 (3)', N'<p><b>Audit Record Generation | Changes by Authorized Individuals</b></p>Provide and implement the capability for [Assignment: organization-defined individuals or roles] to change the logging to be performed on [Assignment: organization-defined system components] based on [Assignment: organization-defined selectable event criteria] within [Assignment: organization-defined time thresholds].', N'<p><strong>WMATA Policy</strong></p><p>Provide and implement the capability for system administrators to change the criteria for logging to be performed on information systems based on System Owner<br>requirements as approved by the AO.</p><p>Related Controls: AC-3</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Example compensating controls include employing nonautomated mechanisms or procedures. <br></p>', N'Audit and Accountability', N'Audit Record Generation', NULL, NULL, N'WMATA', NULL, NULL, NULL, 6, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37589, N'AU-14', N'a. Provide and implement the capability for [Assignment: organization-defined users or roles] to [Selection (one or more): record; view; hear; log] the content of a user session under [Assignment: organization-defined circumstances]; andb. Develop, integrate, and use session auditing activities in consultation with legal counsel and in accordance with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines.', N'<p><strong>WMATA Policy</strong></p><p>a. Provide and implement the capability for [Assignment: organization-defined users or roles] <br>to [Selection (one or more): record; view; hear; log] the content of a user session under <br>[Assignment: organization-defined circumstances]; and</p><p>b. Develop, integrate, and use session auditing activities in consultation with legal counsel and <br>in accordance with applicable laws, executive orders, directives, regulations, policies, <br>standards, and guidelines.</p>', N'Audit and Accountability', N'Session Audit', NULL, NULL, N'WMATA', NULL, NULL, NULL, 6, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37590, N'AU-2', N'a. Identify the types of events that the system is capable of logging in support of the audit function: [Assignment: organization-defined event types that the system is capable of logging];b. Coordinate the event logging function with other organizational entities requiring audit-related information to guide and inform the selection criteria for events to be logged;c. Specify the following event types for logging within the system: [Assignment: organization-defined event types (subset of the event types defined in AU-2a.) along with the frequency of (or situation requiring) logging for each identified event type];d. Provide a rationale for why the event types selected for logging are deemed to be adequate to support after-the-fact investigations of incidents; ande. Review and update the event types selected for logging [Assignment: organization-defined frequency].', N'<p><strong>WMATA Policy</strong></p><p>a.  Identify the types of events that the system is capable of logging in support of the audit function and document those events in the System Security Plans (SSP). Additionally, all exceptions to the audit event types shall be authorized by the AO and documented in SSPs. This list includes but is not limited to:</p><p>i)  Password changes;</p><p>ii) Failed or successful logons or accesses related to systems;</p><p>iii) Logoffs;</p><p>iv) Security or privacy attribute changes;</p><p>v) Administrative privilege usage;</p><p>vi) Personal Identity Verification (PIV) credential usage;</p><p>vii) Data action changes;</p><p>viii) Query parameters;</p><p>ix) External credential usage;</p><p>x) Encryption errors or failures occur;</p><p>xi) Authentication events to include successful and unsuccessful (failed):</p><p>(1) Information Requests and Server Responses;</p><p>(2) Identities of individuals or processes;</p><p>(3) IP addresses involved;</p><p>(4) Use of credentials for logical access to systems or physical access to facilities;</p><p>xii) User activities to include event types, locations, dates and times of activities within the system; event success and failure; data and object access, modifications and deletions; queries and query parameter access, modifications and deletions; and attempts to access system objects (e.g., files, folders, registry keys, and printers);</p><p>xiii) Privileged functions to include the creation, modification, disablement, and deletion (removal) of accounts; audit logs; sensitive information (includes security or privacy attributes or data); administrator events and event success and failure (activities, such as windows “runas” or Linux “su” use, use of suid/guid, chown, su); starting and stopping of  services  and  audit functions,  installation  and  modifications  to  system software/application, firmware, processes and services;</p><p>xiv) Software, firmware and hardware errors, and system resources involved;</p><p>xv) Web applications shall log all user and administrator activity to include application and service startup, shutdown and failure; authentication and authorization successes and failures; data access, account creation, modifications, deletions, and permission changes; and</p><p>xvi) Additional types of events may be required based on emerging threats or federal <br>recommendations.</p><p>b.  Coordinate the event logging function with other organizational entities requiring audit-related information to guide and inform the selection criteria for events to be logged.</p><p>c.  All events in accordance with Control 3.3 Audit and Accountability, Section 2, “AU-2 Event Logging”, shall be logged as they occur, and for each incidence of the occurrence, and any required alert and/or notifications shall be implemented in compliance with Control 3.3 Audit and Accountability, Section 5, (b), (iv), “AU-5 (2) Real-Time Alerts”;</p><p>d. Provide a rationale for why the event types selected for logging are deemed to be adequate to support after-the-fact investigations of incidents; and</p><p>e. Review and update the event types selected for logging annually.</p><p>f.  All systems or applications that store, process, or transmit sensitive information as defined in WMATA policy, shall log access, modification, and deletion to sensitive information. When feasible, the content associated with the sensitive information (e.g., credit card numbers, Social Security Numbers (SSN), Protected Health Information (PHI), Electronic (ePHI), etc.) shall not be stored in audit records in accordance with Control 3.3 Audit and Accountability, Section 3, (f), (i), AU-3 (1) “Additional Audit Information” and Section 3, (f), (ii), AU-3 (3) “Limit Personally Identifiable Information (PII) Elements”.</p><p><strong><u>OT Systems Only:</strong></u> Organizations may want to include relevant OT events (e.g., alerts, alarms, configuration and status changes, operator actions) in their event logging, which may be designated as audit events.</p><p>Related Controls: AC-2, AC-3, AC-6, AC-7, AC-8, AC-17, AU-3, AU-4, AU-5, AU-6, AU-7, AU-11, AU-12, CM-3, CM-5, CM-6, IA-3, MA-4, MP-4, PE-3, PM-21, PT-2, PT-7, RA-8, SA-8, SC-7, SC-18, SI-3, SI-4, SI-7, SI-10, SI-11</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Organizations may want to include relevant OT events (e.g., alerts, alarms, <br>configuration and status changes, operator actions) in their event logging, which may be <br>designated as audit events.</p>', N'Audit and Accountability', N'Event Logging', NULL, NULL, N'WMATA', NULL, NULL, NULL, 6, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37591, N'AU-3', N'a. What type of event occurred;b. When the event occurred;c. Where the event occurred;d. Source of the event;e. Outcome of the event; andf. Identity of any individuals, subjects, or objects/entities associated with the event.', N'<p><strong>WMATA Policy</strong></p><p>Ensure that audit records contain information that establishes the following:<br>a. What type of event occurred;</p><p>b. When the event occurred;</p><p>c. Where the event occurred;</p><p>d. Source of the event;</p><p>e. Outcome of the event; and</p><p>f.  Identity of any individuals, subjects, or objects/entities associated with the event.</p><p>Related Controls: AU-2, AU-8, AU-12, MA-4, PL-9, SA-8, SI-7, SI-11</p><p>g. Security Controls Enhancement(s):</p><p><br></p>', N'Audit and Accountability', N'Content Of Audit Records', NULL, NULL, N'WMATA', NULL, NULL, NULL, 6, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37592, N'AU-3 (1)', N'Generate audit records containing the following additional information: [Assignment: organization-defined additional information].', N'<p><strong>WMATA Policy</strong></p><p>Generate audit records that contain content specified in Control 3.3 Audit and Accountability, Section 3, AU-3 (a) – (c), “Content of Audit Records”. In addition, ensure that audit records contain access control or flow control rules that are invoked, and<br>individual user identities are used for access to group accounts.</p>', N'Audit and Accountability', N'Content Of Audit Records', NULL, NULL, N'WMATA', NULL, NULL, NULL, 6, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37593, N'AU-3 (3)', N'Limit personally identifiable information contained in audit records to the following elements identified in the privacy risk assessment: [Assignment: organization-defined elements].', N'<p><strong>WMATA Policy</strong></p><p>Limit PII and other forms of sensitive data in accordance with Control 3.8 Data<br>Sensitivity, in audit records to the maximum extent feasible.</p><p>Related Controls: RA-3</p>', N'Audit and Accountability', N'Content Of Audit Records', NULL, NULL, N'WMATA', NULL, NULL, NULL, 6, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37594, N'AU-4', N'Allocate audit log storage capacity to accommodate [Assignment: organization-defined audit log retention requirements].', N'<p><strong>WMATA Policy</strong></p><p>Allocate audit log storage capacity to accommodate application or system requirements. Assess capacity requirements for audit logging to never exceed 75% capacity. Exceptions to the capacity limit in the range of 76-89% must be approved by the AO and include the following justifications:</p><p>a. Demonstrated acceptable system performance above 75% capacity limit;</p><p>b. Define the limited business impact of system failure;</p><p>c. Business explanation why 75% capacity limit cannot be achieved; </p><p>Capacity limit shall not exceed 90%.</p><p>Reassess capacity requirements whenever exceeding the authorized threshold. Additionally, reassessing capacity requirements for audit logging based on system changes, performance, and alerts.</p><p>Related Controls: AU-2, AU-5, AU-6, AU-7, AU-9, AU-11, AU-12, SI-4</p><p>Security Controls Enhancement(s):</p>', N'Audit and Accountability', N'Audit Log Storage Capacity', NULL, NULL, N'WMATA', NULL, NULL, NULL, 6, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37595, N'AU-4 (1)', N'<p><b>Audit Log Storage Capacity | Transfer to Alternate Storage</b></p>Transfer audit logs [Assignment: organization-defined frequency] to a different system, system component, or media other than the system or system component conducting the logging.', N'<p><strong>WMATA Policy</strong></p><p>Transfer audit logs [Assignment: organization-defined frequency] to a different system, system component, or media other than the system or system component conducting the logging. </p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion:  Rationale for adding AU-4 (1) to LOW, MOD, and HIGH baselines: Organizational <br>requirements may require the storage of very large amounts of data, which OT components may <br>not be able to support directly. </p>', N'Audit and Accountability', N'Audit Log Storage Capacity', NULL, NULL, N'WMATA', NULL, NULL, NULL, 6, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37596, N'AU-5', N'a. Alert [Assignment: organization-defined personnel or roles] within [Assignment: organization-defined time period] in the event of an audit logging process failure; andb. Take the following additional actions: [Assignment: organization-defined additional actions].', N'<p><strong>WMATA Policy</strong></p><p>a. Alert the required stakeholders immediately in the event of an audit logging process failure; and</p><p>b. Take the following additional actions:</p><p>i)  Systems shall specify in the SSP actions that are taken in the event of an audit processing failure, to include overwriting oldest audit records and shutting down the system.  All  database systems  shall  comply  with  hardening  checklists  (e.g., STIGs/Benchmarks) and shutdown in the event there is an audit processing failure.</p><p>If overwriting is to be employed, audit logs shall be centralized or moved to external storage to preserve the audit content in accordance with Control 3.3 Audit and Accountability, Section 11, “AU-11 Audit Record Retention”.</p><p>If the system is to be shut down due to an audit process failure, the relevant Audit and <br>Accountability (AU), Planning (PL) and Contingency Planning (CP) controls within the SSP and associated contingency plan and/or Information System Contingency Plan (ISCP) shall be updated to reflect how operations shall be maintained in the event of a<br>em component outage.</p><p>All systems shall have functional audit generation capabilities.</p><p>ii)  In the event of an audit process logging failure, investigate root cause and create an <br>incident:</p><p>(1) With Metro Enterprise Monitoring Center (MEMC) for operational incidents; and</p><p>(2) With DMCS for malicious or cybersecurity incidents.</p><p>Related Controls: AU-2, AU-4, AU-7, AU-9, AU-11, AU-12, SI-4, SI-12</p><p>c. Security Controls Enhancement(s):<br></p>', N'Audit and Accountability', N'Response to Audit Logging Process Failures', NULL, NULL, N'WMATA', NULL, NULL, NULL, 6, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37597, N'AU-5 (1)', N'Provide a warning to [Assignment: organization-defined personnel, roles, and/or locations] within [Assignment: organization-defined time period] when allocated audit log storage volume reaches [Assignment: organization-defined percentage] of repository maximum audit log storage capacity.', N'<p><strong>WMATA Policy</strong></p><p>Provide a warning to MEMC and any other required stakeholders, immediately when allocated audit log storage volume reaches 75%, and again at 90% of repository<br>maximum audit log storage capacity.</p>', N'Audit and Accountability', N'Response to Audit Logging Process Failures', NULL, NULL, N'WMATA', NULL, NULL, NULL, 6, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37598, N'AU-5 (2)', N'Provide an alert within [Assignment: organization-defined real-time period] to [Assignment: organization-defined personnel, roles, and/or locations] when the following audit failure events occur: [Assignment: organization-defined audit logging failure events requiring real-time alerts].', N'<p><strong>WMATA Policy</strong></p><p>Provide an alert immediately to the required stakeholders when the following audit failure events occur, at a minimum:</p><p>(1) System and service is stopped or severely degraded, or</p><p>(2) Audit processing capability or component failures or errors occur within a system, to include:</p><p>(a) Audit log is full; and</p><p>(b) Audit log cannot log authentication attempts and responses.</p>', N'Audit and Accountability', N'Response to Audit Logging Process Failures', NULL, NULL, N'WMATA', NULL, NULL, NULL, 6, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37599, N'AU-6', N'a. Review and analyze system audit records [Assignment: organization-defined frequency] for indications of [Assignment: organization-defined inappropriate or unusual activity] and the potential impact of the inappropriate or unusual activity;b. Report findings to [Assignment: organization-defined personnel or roles]; andc. Adjust the level of audit record review, analysis, and reporting within the system when there is a change in risk based on law enforcement information, intelligence information, or other credible sources of information.', N'<p><strong>WMATA Policy</strong></p><p>a.  Review and analyze system audit records at least monthly for indications of defined <br>inappropriate or unusual activity and the potential impact of the inappropriate or unusual activity;</p><p>b. Report findings to required stakeholders and DMCS; and</p><p>c.  Adjust the level of audit record review, analysis, and reporting within the system when there is a change in risk based on law enforcement information, intelligence information, or other credible sources of information.</p><p>Related Controls: AC-2, AC-3, AC-5, AC-6, AC-7, AC-17, AU-7, CA-2, CA-7, CM-2, CM-5, CM-6, CM-10, CM-11, IA-2, IA-3, IA-5, IA-8, IR-5, MA-4, MP-4, PE-3, PE-6, RA-5, SA-8, SC-7, SI-3, SI-4, SI-7</p><p>d. Security Controls Enhancement(s):</p>', N'Audit and Accountability', N'Audit Record Review, Analysis, and Reporting', NULL, NULL, N'WMATA', NULL, NULL, NULL, 6, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37600, N'AU-6 (1)', N'<p><b>Audit Record Review, Analysis, and Reporting | Automated Process Integration</b></p>Integrate audit record review, analysis, and reporting processes using [Assignment: organization-defined automated mechanisms].', N'<p><strong>WMATA Policy</strong></p><p>Integrate audit record review, analysis, and reporting processes via an enterprise solution (or solutions) to enable services, such as incident response, continuous monitoring, contingency planning, and investigation and response to suspicious<br>activities.</p><p><strong><u>OT Systems Only:</strong></u> Example compensating controls include manual mechanisms or procedures. For devices where audit records cannot be feasibly collected, periodic manual review may be necessary.</p><p>Related Controls: PM-7</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion:  Example compensating controls include manual <br>mechanisms or procedures. For devices where audit records cannot be feasibly collected, <br>periodic manual review may be necessary.</p>', N'Audit and Accountability', N'Audit Record Review, Analysis, and Reporting', NULL, NULL, N'WMATA', NULL, NULL, NULL, 6, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37601, N'AU-6 (3)', N'Analyze and correlate audit records across different repositories to gain organization-wide situational awareness.', N'<p><strong>WMATA Policy</strong></p><p>Analyze and correlate audit records across different repositories to gain organization-<br>wide situational awareness.</p><p>Related Controls: AU-12, IR-4</p>', N'Audit and Accountability', N'Audit Record Review, Analysis, and Reporting', NULL, NULL, N'WMATA', NULL, NULL, NULL, 6, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37602, N'AU-6 (5)', N'Integrate analysis of audit records with analysis of [Selection (one or more): vulnerability scanning information; performance data; system monitoring information; [Assignment: organization-defined data/information collected from other sources]] to further enhance the ability to identify inappropriate or unusual activity.', N'<p><strong>WMATA Policy</strong></p><p>Integrate analysis of audit records with analysis of vulnerability scanning information; <br>performance data; and system monitoring information at a minimum to further enhance the ability to identify inappropriate or unusual activity.</p><p>Related Controls: AU-12, IR-4</p>', N'Audit and Accountability', N'Audit Record Review, Analysis, and Reporting', NULL, NULL, N'WMATA', NULL, NULL, NULL, 6, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37603, N'AU-6 (6)', N'Correlate information from audit records with information obtained from monitoring physical access to further enhance the ability to identify suspicious, inappropriate, unusual, or malevolent activity.', N'<p><strong>WMATA Policy</strong></p><p>Correlate information from audit records with information obtained from monitoring physical access to further enhance the ability to identify suspicious, inappropriate,<br>unusual, or malevolent activity.</p>', N'Audit and Accountability', N'Audit Record Review, Analysis, and Reporting', NULL, NULL, N'WMATA', NULL, NULL, NULL, 6, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37604, N'AU-7', N'a. Supports on-demand audit record review, analysis, and reporting requirements and after-the-fact investigations of incidents; andb. Does not alter the original content or time ordering of audit records.', N'<p><strong>WMATA Policy</strong></p><p>a. Supports on-demand audit record review, analysis, and reporting requirements and after- the-fact investigations of incidents; and</p><p>b. Does not alter the original content or time ordering of audit records.</p><p>Related Controls: AC-2, AU-2, AU-3, AU-4, AU-5, AU-6, AU-12, CM-5, IA-5, IR-4, PM-12, SI-4</p><p>c. Security Controls Enhancement(s):</p>', N'Audit and Accountability', N'Audit Record Reduction and Report Generation', NULL, NULL, N'WMATA', NULL, NULL, NULL, 6, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37605, N'AU-7 (1)', N'Provide and implement the capability to process, sort, and search audit records for events of interest based on the following content: [Assignment: organization-defined fields within audit records].', N'<p><strong>WMATA Policy</strong></p><p>Provide and implement the capability to process, sort, and search audit records for events of interest based on the following content: system resources involved, information objects accessed, identities of individuals or processes, event types, event locations, event dates and times, IP addresses involved, and event success or failure. The DM department may define event criteria to any degree of granularity required, such as locations selectable by a general networking location or by a specific system component.</p>', N'Audit and Accountability', N'Audit Record Reduction and Report Generation', NULL, NULL, N'WMATA', NULL, NULL, NULL, 6, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37606, N'AU-8', N'a. Use internal system clocks to generate time stamps for audit records; andb. Record time stamps for audit records that meet [Assignment: organization-defined granularity of time measurement] and that use Coordinated Universal Time, have a fixed local time offset from Coordinated Universal Time, or that include the local time offset as part of the time stamp.', N'<p><strong>WMATA Policy</strong></p><p>a. Use internal system clocks to generate time stamps for audit records; and</p><p>b.  Record time stamps for audit records that meet accuracy to within 100 milliseconds and that use Coordinated Universal Time (UTC), have a fixed local time offset from UTC, or include the local time offset as part of the time stamp.</p><p><strong><u>OT Systems Only:</strong></u> Example compensating controls include using a separate system designated as an authoritative time source. See related control SC-45</p><p>Related Controls: AU-3, AU-12, SC-45</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Example compensating controls include using a separate system designated as an <br>authoritative time source. See related control SC-45. </p>', N'Audit and Accountability', N'Time Stamps', NULL, NULL, N'WMATA', NULL, NULL, NULL, 6, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37607, N'AU-9', N'a. Protect audit information and audit logging tools from unauthorized access, modification, and deletion; andb. Alert [Assignment: organization-defined personnel or roles] upon detection of unauthorized access, modification, or deletion of audit information.', N'<p><strong>WMATA Policy</strong></p><p>a.  Protect audit information and audit logging tools from unauthorized access, modification, and deletion; and</p><p>b. Alert required stakeholders upon detection of unauthorized access, modification, or deletion of audit information.</p><p>Related Controls: AC-3, AC-6, AU-6, AU-11, MP-2, MP-4, PE-2, PE-3, PE-6, SA-8, SC-8, SI-4</p><p>c. Security Controls Enhancement(s):</p>', N'Audit and Accountability', N'Protection of Audit Information', NULL, NULL, N'WMATA', NULL, NULL, NULL, 6, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37608, N'AU-9 (2)', N'Store audit records [Assignment: organization-defined frequency] in a repository that is part of a physically different system or system component than the system or component being audited.', N'<p><strong>WMATA Policy</strong></p><p>Store audit records at least daily in a repository that is part of a physically different<br>system or system component than the system or component being audited.</p><p>Related Controls: AU-4, AU-5</p>', N'Audit and Accountability', N'Protection of Audit Information', NULL, NULL, N'WMATA', NULL, NULL, NULL, 6, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37609, N'AU-9 (3)', N'Implement cryptographic mechanisms to protect the integrity of audit information and audit tools.', N'<p><strong>WMATA Policy</strong></p><p>Implement cryptographic mechanisms to protect the integrity of audit information and<br>audit tools.</p><p>Related Controls: AU-10, SC-12, SC-13</p>', N'Audit and Accountability', N'Protection of Audit Information', NULL, NULL, N'WMATA', NULL, NULL, NULL, 6, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37610, N'AU-9 (4)', N'Authorize access to management of audit logging functionality to only [Assignment: organization-defined subset of privileged users or roles].', N'<p><strong>WMATA Policy</strong></p><p>Authorize access to management of audit logging functionality to only:</p><p>(1) Required stakeholders based on least privileges for the purposes of configuring and supporting information systems; and</p><p>(2) All DMCS Cyber Fusion Center (CFC) personnel.</p><p>Related Controls: AC-5</p>', N'Audit and Accountability', N'Protection of Audit Information', NULL, NULL, N'WMATA', NULL, NULL, NULL, 6, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37611, N'CA-1', N'a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:     1. [Selection (one or more): Organization-level; Mission/business process-level; System-level] assessment, authorization, and monitoring      policy that:          (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and           compliance; and          (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and     2. Procedures to facilitate the implementation of the assessment, authorization, and monitoring policy and the associated assessment, authorization, and monitoring controls;b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the assessment, authorization, and monitoring policy and procedures; andc. Review and update the current assessment, authorization, and monitoring:     1. Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and     2. Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].', N'<p><strong>WMATA Policy</strong></p><p>Reference P/I 15.28 Cybersecurity Policy for requirements.</p><p>Related Controls: PM-9, PS-8, SI-12</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: The policy specifically addresses the unique properties and requirements of OT <br>and the relationship to non-OT systems. </p>', N'Assessment, Authorization, and Monitoring', N'Assessment, Authorization and Monitoring Policy and Procedures', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1085, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37612, N'CA-2', N'a. Select the appropriate assessor or assessment team for the type of assessment to be conducted;b. Develop a control assessment plan that describes the scope of the assessment including:     1. Controls and control enhancements under assessment;     2. Assessment procedures to be used to determine control effectiveness; and     3. Assessment environment, assessment team, and assessment roles and responsibilities;c. Ensure the control assessment plan is reviewed and approved by the authorizing official or designated representative prior to conducting the assessment;d. Assess the controls in the system and its environment of operation [Assignment: organization-defined frequency] to determine the extent to which the controls are implemented correctly, operating as intended, and producing the desired outcome with respect to meeting established security and privacy requirements;e. Produce a control assessment report that document the results of the assessment; andf. Provide the results of the control assessment to [Assignment: organization-defined individuals or roles].', N'<p><strong>WMATA Policy</strong></p><p>a. Select the appropriate assessor or assessment team for the type of assessment to be conducted;</p><p>b. Develop a control assessment plan that describes the scope of the assessment including:</p><p>i)  Controls and control enhancements under assessment;</p><p>ii) Assessment procedures to be used to determine control effectiveness; and</p><p>iii) Assessment environment, assessment team, and assessment roles and responsibilities;</p><p>c.  Ensure the control assessment plan is reviewed and approved by the AO or designated representative prior to conducting the assessment;</p><p>d.  Assess the controls in the system and its environment of operation annually, or after any significant change, to determine the extent to which the controls are implemented correctly, operating as intended, and producing the desired outcome with respect to meeting established security and privacy requirements;</p><p>e. Produce a control assessment report that document the results of the assessment; and</p><p>f.  Provide the results of the control assessment to the required stakeholders.</p><p><strong><u>OT Systems Only: </strong></u>Assessments are performed and documented by qualified assessors (i.e., experienced in assessing OT) authorized by the organization. The individual/group conducting the assessment fully understands the organizational information security policies and procedures, the OT security policies and procedures, and the specific health, safety, and environmental risks associated with a particular facility and/or process. The organization ensures that the assessment does not affect system operation or result in unintentional system modification. If assessment activities must be performed on the production OT, it may need to be taken off-line before an assessment can be conducted, or the assessment should be scheduled to occur during planned OT outages whenever possible.</p><p>Related Controls: AC-20, CA-5, CA-6, CA-7, PM-9, RA-5, SA-11, SI-3, SI-12, SR-2, SR-3</p><p>g. Security Controls Enhancement(s):</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Assessments are performed and documented by qualified assessors (i.e., experienced in assessing OT) authorized by the organization. The individual or group conducting the assessment fully understands the organizational information security policies and procedures, the OT security policies and procedures, and the specific health, safety, and environmental risks associated with a particular facility and/or process. The organization ensures that the assessment does not affect system operation or result in unintentional system modification. If assessment activities must be performed on the production OT, it may need to be taken offline before an assessment can be conducted, or the assessment should be scheduled to occur during planned OT outages whenever possible.</p>', N'Assessment, Authorization, and Monitoring', N'Control Assessments', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1085, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37613, N'CA-2 (1)', N'Employ independent assessors or assessment teams to conduct control assessments.', N'<p><strong>WMATA Policy</strong></p><p>Employ independent assessors or assessment teams to conduct security control<br>assessments.<br></p>', N'Assessment, Authorization, and Monitoring', N'Control Assessments', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1085, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37614, N'CA-2 (2)', N'Include as part of control assessments, [Assignment: organization-defined frequency], [Selection: announced; unannounced], [Selection (one or more): in-depth monitoring; security instrumentation; automated security test cases; vulnerability scanning; malicious user testing; insider threat assessment; performance and load testing; data leakage or data loss assessment; [Assignment: organization-defined other forms of assessment]].', N'<p><strong>WMATA Policy</strong></p><p>Conduct announced and/or unannounced control assessments at least once prior to a system receiving authorization to move into a production environment, after a significant change, and annually thereafter for all systems in production, to include one or more of the following at the discretion of the AO:</p><p>(1) Leverage current vulnerability scan results;</p><p>(2) Penetration testing in compliance with Control 3.2 Assessment, Authorization and Monitoring, Section 7, “CA-8 Penetration Testing”;</p><p>(3) In-depth user activity monitoring;</p><p>(4) Security instrumentation;</p><p>(5) Automated security test cases;</p><p>(6) Simulate malicious user activities and conduct testing;</p><p>(7) Insider threat assessment;</p><p>(8) Performance and load testing; and</p><p>(9) Data leakage or data loss assessment</p><p><strong><u>OT Systems Only: </strong></u>The organization conducts risk analysis to support selection of an assessment target (e.g., the live system, an off-line replica or lab system).</p><p>Related Controls: PE-3, SI-2</p><p><br><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: The organization conducts risk analysis to support the selection of an assessment target (e.g., the live system, an offline replica, or lab system). </p>', N'Assessment, Authorization, and Monitoring', N'Control Assessments', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1085, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37615, N'CA-3', N'a. Approve and manage the exchange of information between the system and other systems using [Selection (one or more): interconnection security agreements; information exchange security agreements; memoranda of understanding or agreement; service level agreements; user agreements; nondisclosure agreements; [Assignment: organization-defined type of agreement]];b. Document, as part of each exchange agreement, the interface characteristics, security and privacy requirements, controls, and responsibilities for each system, and the impact level of the information communicated; andc. Review and update the agreements [Assignment: organization-defined frequency].', N'<p><strong>WMATA Policy</strong></p><p>a. Approve and manage the exchange of information between systems using appropriate exchange agreements; and</p><p>b. Document, as part of each exchange agreement, the interface characteristics, security and privacy requirements, controls, and responsibilities for each system, and the impact level of the information communicated; and</p><p>c. Review and update the agreements annually.</p><p><strong><u>OT Systems Only: </strong></u>Organizations perform risk-benefit analysis to support determining whether an OT should be connected to other system(s). The authorizing official (AO) fully understands the organizational information security policies and procedures; the OT security policies and procedures; the risks to organizational operations and assets, individuals, other organizations, and the nation associated with the connection to other system(s); the individuals and organizations that operate and maintain the systems, including maintenance contractors or service providers; and the specific health, safety, and environmental risks associated with a particular interconnection. Connections from the OT environment to other security zones may cross the authorization boundary, such that two different authorizing officials may be required to approve the connection. Decisions to accept risk are documented.<br>	<br>Related Controls: AC-4, AC-20, CA-6, IA-3, IR-4, PL-2, PT-7, RA-3, SA-9, SC-7, SI-12</p><p>d. Security Controls Enhancement(s):</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Organizations perform risk-benefit analysis to determine whether an OT should be connected to other systems. The authorizing official (AO) fully understands the organizational information security policies and procedures; the OT security policies and procedures; the risks <br>to organizational operations and assets, individuals, other organizations, and the Nation associated with the connection to other systems; the individuals and organizations that operate and maintain the systems, including maintenance contractors or service providers; and the specific health, safety, and environmental risks associated with a particular interconnection. Connections from the OT environment to other security zones may cross the authorization boundary such that two different authorizing officials may be required to approve the connection. Decisions to accept risk are documented.<br></p>', N'Assessment, Authorization, and Monitoring', N'Information Exchange', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1085, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37616, N'CA-3 (6)', N'Verify that individuals or systems transferring data between interconnecting systems have the requisite authorizations (i.e., write permissions or privileges) prior to accepting such data.', N'<p><strong>WMATA Policy</strong></p><p>Verify that individuals or systems transferring data between interconnecting systems have the requisite authorizations (i.e., write permissions or privileges) prior to accepting data.</p><p>Related Controls: AC-2, AC-3, AC-4</p>', N'Assessment, Authorization, and Monitoring', N'Information Exchange', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1085, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37617, N'CA-5', N'a. Develop a plan of action and milestones for the system to document the planned remediation actions of the organization to correct weaknesses or deficiencies noted during the assessment of the controls and to reduce or eliminate known vulnerabilities in the system; andb. Update existing plan of action and milestones [Assignment: organization-defined frequency] based on the findings from control assessments, independent audits or reviews, and continuous monitoring activities.', N'<p><strong>WMATA Policy</strong></p><p>a.  Develop a plan of action and milestones for the system to document the planned remediation actions of the organization to correct weaknesses or deficiencies noted during the assessment of the controls and to reduce or eliminate known vulnerabilities in the system; and</p><p>b. Update existing plan of action and milestones monthly based on the findings from control assessments, independent audits or reviews, and continuous monitoring activities.</p><p><strong><u>OT Systems Only:</strong></u> OT Discussion: Corrective actions identified in assessments may not be immediately actionable in an OT environment; therefore, short-term mitigations may be implemented to reduce risk as part of the gap closure plan or plan of action and milestones.</p><p>Related Controls: CA-2, CA-7, PM-4, PM-7, RA-7, SI-2, SI-</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Corrective actions identified in assessments may not be immediately actionable in an OT environment. Therefore, short-term mitigations may be implemented to reduce risk as part of the gap closure plan or plan of action and milestones.</p>', N'Assessment, Authorization, and Monitoring', N'Plan of Action and Milestones', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1085, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37618, N'CA-6', N'a. Assign a senior official as the authorizing official for the system;b. Assign a senior official as the authorizing official for common controls available for inheritance by organizational systems;c. Ensure that the authorizing official for the system, before commencing operations:     1. Accepts the use of common controls inherited by the system; and     2. Authorizes the system to operate;d. Ensure that the authorizing official for common controls authorizes the use of those controls for inheritance by organizational systems;e. Update the authorizations [Assignment: organization-defined frequency].', N'<p><strong>WMATA Policy</strong></p><p>a. Assign a senior official as the authorizing official for the system;</p><p>b.  Assign a senior official as the authorizing official for common controls available for <br>inheritance by organizational systems;</p><p>c. Ensure that the authorizing official for the system, before commencing operations:</p><p>i)  Accepts the use of common controls inherited by the system; and</p><p>ii) Authorizes the system to operate;</p><p>d. Ensure that the authorizing official for common controls authorizes the use of those controls for inheritance by organizational systems;</p><p>e. Update the authorizations annually.</p><p>Related Controls: CA-2, CA-3, CA-7, PM-9, PM-10, RA-3, SA-10, SI-12</p>', N'Assessment, Authorization, and Monitoring', N'Authorization', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1085, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37619, N'CA-7', N'Develop a system-level continuous monitoring strategy and implement continuous monitoring in accordance with the organization-level continuous monitoring strategy that includes:a. Establishing the following system-level metrics to be monitored: [Assignment: organization-defined system-level metrics];b. Establishing [Assignment: organization-defined frequencies] for monitoring and [Assignment: organization-defined frequencies] for assessment of control effectiveness;c. Ongoing control assessments in accordance with the continuous monitoring strategy;d. Ongoing monitoring of system and organization-defined metrics in accordance with the continuous monitoring strategy;e. Correlation and analysis of information generated by control assessments and monitoring;f. Response actions to address results of the analysis of control assessment and monitoring information; andg. Reporting the security and privacy status of the system to [Assignment: organization-defined personnel or roles] [Assignment: organization-defined frequency].', N'<p><strong>WMATA Policy</strong></p><p>Develop a system-level continuous monitoring strategy and implement continuous monitoring in accordance with the organization-level continuous monitoring strategy that includes:</p><p>a. Establishing the following system-level metrics to be monitored:</p><p>i)  Tier 1 (Organization-wide Metrics):</p><p>(1) Number of Assessed and Authorized systems per year;</p><p>(2) Number of authorized and unauthorized information systems components per quarter (includes systems with End of Life (EOL) components);</p><p>(3) Number of software vulnerabilities by mission/business function, categorized by Critical, High, Moderate and Low impact/risk per quarter;</p><p>(4) Number of POAMs open and closed per quarter;</p><p>(5) Rate of compliance to the annual cybersecurity awareness and training certification; and</p><p>(6) Rate of noncompliance to the annual cybersecurity awareness and training certification.</p><p>ii) Tier 2 (Mission/Business Process Metrics):</p><p>(1) Number of authorized and unauthorized information systems components per month (includes systems with EOL components);</p><p>(2) Number of software vulnerabilities by mission/business function, categorized by Critical, High, Moderate and Low impact/risk per month;</p><p>(3) Number of POAMs open and closed per month; and</p><p>(4) Number of ISCM security control failures per month,</p><p>iii) Tier 3 (System-level Metrics):</p><p>(1) Number of software vulnerabilities by system;</p><p>(2) Number of authorized and unauthorized information systems components per month (includes systems with EOL components);</p><p>(3) Number of software vulnerabilities by mission/business function, categorized by Critical, High, Moderate and Low impact/risk per month;</p><p>(4) Number of POAMs open and closed per month; and</p><p>(5) Number of ISCM security control failures based on the review monthly.</p><p>b. Assess and monitor control effectiveness in alignment with the frequencies defined in the continuous monitoring strategy;</p><p>c. Ongoing control assessments in accordance with the continuous monitoring strategy;</p><p>d. Ongoing monitoring of system and organization-defined metrics in accordance with the continuous monitoring strategy;</p><p>e. Correlation and analysis of information generated by control assessments and monitoring;</p><p>f.  Response actions to address results of the analysis of control assessment and monitoring information; and</p><p>g. Reporting the security and privacy status of the system to the AO annually.</p><p><strong><u>OT Systems Only: </strong></u>Continuous monitoring programs for OT are designed, documented, and implemented with input from OT personnel. The organization ensures that continuous monitoring does not interfere with OT functions. The individual/group designing and conducting the continuous monitoring for the OT systems implements monitoring consistent with the organizational information security policies and procedures, the OT security policies and procedures, and the specific health, safety, and environmental risks associated with a particular facility and/or process. Continuous monitoring can be automated or manual at a frequency sufficient to support risk-based decisions. For example, the organization may determine for lower-risk, isolated systems to monitor event logs manually on a specified frequency less often than for higher-risk, networked systems.</p><p>Related Controls: AC-2, AC-6, AC-17, AT-4, AU-6, CA-2, CA-5, CA-6, CM-3, CM-4, CM-6, CM-11, IA-5, IR-5, MA-2, MA-3, MA-4, PE-3, PE-6, PE-14, PE-16, PL-2, PM-4, PM-6, PM-9, PM-10, PM-12, PM-14, PM-23, PM-28, PM-31, PS-7, PT-7, RA-3, RA-5, RA-7, SA-8, SA-9, SA-11, SC-5, SC-7, SC-18, SI-3, SI-4, SI-12, SR-6</p><p>h. Security Controls Enhancement(s):</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Continuous monitoring programs for OT are designed, documented, and implemented with input from OT personnel. The organization ensures that continuous monitoring does not interfere with OT functions. The individual or group designing and conducting the continuous monitoring for the OT systems implements a monitoring program that is consistent with the organizational information security policies and procedures, the OT security policies and procedures, and the specific health, safety, and environmental risks associated with a particular facility and/or process. Continuous monitoring can be automated or manual at a frequency sufficient to support risk-based decisions. For example, the organization may monitor event logs manually on a specified frequency less often for lower-risk, isolated systems than for higher-risk, networked systems. </p>', N'Assessment, Authorization, and Monitoring', N'Continuous Monitoring', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1085, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37620, N'CA-7 (1)', N'Employ independent assessors or assessment teams to monitor the controls in the system on an ongoing basis.', N'<p><strong>WMATA Policy</strong></p><p>Employ independent assessors or assessment teams to monitor the controls in the<br>system on an ongoing basis.</p>', N'Assessment, Authorization, and Monitoring', N'Continuous Monitoring', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1085, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37621, N'CA-7 (4)', N'Ensure risk monitoring is an integral part of the continuous monitoring strategy that includes the following:(a) Effectiveness monitoring;(b) Compliance monitoring; and(c) Change monitoring.', N'<p><strong>WMATA Policy</strong></p><p>Ensure risk monitoring is an integral part of the continuous monitoring strategy that<br>includes the following:</p><p>(1) Effectiveness monitoring;</p><p>(2) Compliance monitoring; and</p><p>(3) Change monitoring.</p>', N'Assessment, Authorization, and Monitoring', N'Continuous Monitoring', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1085, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37622, N'CA-8', N'Conduct penetration testing [Assignment: organization-defined frequency] on [Assignment: organization-defined systems or system components].', N'<p><strong>WMATA Policy</strong></p><p>a.  Conduct penetration testing annually or as prescribed and approved by the AO in the SSP.  Penetration testing shall be performed at the discretion of DMCS on new products and services before deployment within WMATA’s computing environment or prior to hosting WMATA data on the system/service.</p><p><strong><u>OT Systems Only: </strong></u>Penetration testing is used with care on OT networks to ensure that OT functions are not adversely impacted by the testing process. In general, OT systems are highly sensitive to timing constraints and have limited resources. Example compensating controls include employing a replicated, virtualized, or simulated system to conduct penetration testing. Production OT may need to be taken off-line before testing can be conducted. If OT systems are taken off-line for testing, tests are scheduled to occur during planned OT outages whenever possible. If penetration testing is performed on non-OT networks, extra care is taken to ensure that tests do not propagate into the OT network.</p><p>Related Controls: RA-5, RA-10, SA-11, SR-5, SR-6</p><p>b. Security Controls Enhancement(s):</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Penetration testing is used with care on OT networks to ensure that OT functions are not adversely impacted by the testing process. In general, OT systems are highly sensitive to timing constraints and have limited resources. Example compensating controls include employing a replicated, virtualized, or simulated system to conduct penetration testing. Production OT may need to be taken offline before testing can be conducted. If OT systems are taken offline for testing, tests are scheduled to occur during planned OT outages whenever possible. If penetration testing is performed on non-OT networks, extra care is taken to ensure that tests do not propagate into the OT network. </p>', N'Assessment, Authorization, and Monitoring', N'Penetration Testing', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1085, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37623, N'CA-8 (1)', N'<p><b>Penetration Testing | Independent Penetration Testing Agent or Team</b></p>Employ an independent penetration testing agent or team to perform penetration testing on the system or system components.', N'<p><strong>WMATA Policy</strong></p><p>Employ an independent penetration testing agent or team to perform penetration testing on the system or system components.</p><p>Related Controls: CA-2</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>Rationale for removing CA-8 (1) from HIGH baseline: Specific expertise is necessary to conduct effective penetration testing on OT systems, and it may not be feasible to identify independent personnel with the appropriate skillset or knowledge to perform penetration testing on an OT <br>environment. While an independent penetration test agent or team is recommended, it may not be feasible for all high-impact OT systems.</p>', N'Assessment, Authorization, and Monitoring', N'Penetration Testing', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1085, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37624, N'CA-9', N'a. Authorize internal connections of [Assignment: organization-defined system components or classes of components] to the system;b. Document, for each internal connection, the interface characteristics, security and privacy requirements, and the nature of the information communicated;c. Terminate internal system connections after [Assignment: organization-defined conditions]; andd. Review [Assignment: organization-defined frequency] the continued need for each internal connection.', N'<p><strong>WMATA Policy</strong></p><p>a.  Authorize internal connections of system components or classes of components that are a part of the same system to include, but not limited to, mobile devices (e.g., smartphones and tablets), notebook and desktop computers, printers, copiers, facsimile machines, scanners, sensors, and servers;</p><p>b. Document, for each internal connection, the interface characteristics, security and privacy requirements, and the nature of the information communicated;</p><p>c.  Terminate internal system connections when no longer needed or as documented in an approved change order as a part of the configuration change control process, in accordance with Control 3.4 Configuration Management; and</p><p>d. Review annually the continued need for each internal connection.</p><p><strong><u>OT Systems Only:</strong></u> Organizations perform risk-benefit analysis to determine whether OT equipment should be connected to other internal system components, then document these connections. The AO fully understands the potential risks associated with approving individual connections or approving a class of components to be connected. As an example, the AO may broadly approve the connection of any sensors limited to 4 to 20 milliamp (mA) communication, while other connection types (e.g., serial or ethernet) require individual approval. Decisions to accept risk are documented.</p><p>Related Controls: AC-3, AC-4, AC-18, AC-19, CM-2, IA-3, SC-7, SI-12</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Organizations perform risk-benefit analysis to determine whether OT equipment should be connected to other internal system components and then document those connections. The AO fully understands the potential risks associated with approving individual connections or approving a class of components to be connected. For example, the AO may broadly approve the connection of any sensors limited to 4 to 20 milliamp (mA) communication, while other connection types (e.g., serial or Ethernet) require individual approval. Decisions to accept risk are documented.</p>', N'Assessment, Authorization, and Monitoring', N'Internal System Connections', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1085, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37625, N'CM-1', N'a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:     1. [Selection (one or more): Organization-level; Mission/business process-level; System-level] configuration management policy that:          (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and           compliance; and          (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and     2. Procedures to facilitate the implementation of the configuration management policy and the associated configuration management controls;b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the configuration management policy and procedures; andc. Review and update the current configuration management:     1. Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and     2. Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].', N'<p><strong>WMATA Policy</strong></p><p>Reference P/I 15.28 Cybersecurity Policy for requirements.</p><p>Related Controls: PM-9, PS-8, SA-8, SI-12</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: The policy specifically addresses the unique properties and requirements of OT <br>and the relationship to non-OT systems.</p>', N'Configuration Management', N'Configuration Management Policy and Procedures', NULL, NULL, N'WMATA', NULL, NULL, NULL, 10, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37626, N'CM-10', N'a. Use software and associated documentation in accordance with contract agreements and copyright laws;b. Track the use of software and associated documentation protected by quantity licenses to control copying and distribution; andc. Control and document the use of peer-to-peer file sharing technology to ensure that this capability is not used for the unauthorized distribution, display, performance, or reproduction of copyrighted work.', N'<p><strong>WMATA Policy</strong></p><p>a. Use software and associated documentation in accordance with contract agreements and copyright laws.</p><p>b. Track the use of software and associated documentation protected by quantity licenses to control copying and distribution; and</p><p>c.  Control and document the use of peer-to-peer file sharing technology to ensure that this capability is not used for the unauthorized distribution, display, performance, or reproduction of copyrighted work.</p><p>Related Controls: AC-17, AU-6, CM-7, CM-8, PM-30, SC-7</p>', N'Configuration Management', N'Software Usage Restrictions', NULL, NULL, N'WMATA', NULL, NULL, NULL, 10, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37627, N'CM-11', N'a. Establish [Assignment: organization-defined policies] governing the installation of software by users;b. Enforce software installation policies through the following methods: [Assignment: organization-defined methods]; andc. Monitor policy compliance [Assignment: organization-defined frequency].', N'<p><strong>WMATA Policy</strong></p><p>a. Users without authorized privileges shall not be permitted to install software on corporate systems;</p><p>b. Enforce software installation policies using procedural and automated methods.</p><p>c. Monitor policy compliance on a continual basis.</p><p>Related Controls: AC-3, AU-6, CM-2, CM-3, CM-5, CM-6, CM-7, CM-8, PL-4, SI-4, SI-7</p>', N'Configuration Management', N'User-Installed Software', NULL, NULL, N'WMATA', NULL, NULL, NULL, 10, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37628, N'CM-12', N'a. Identify and document the location of [Assignment: organization-defined information] and the specific system components on which the information is processed and stored;b. Identify and document the users who have access to the system and system components where the information is processed and stored; andc. Document changes to the location (i.e., system or system components) where the information is processed and stored.', N'<p><strong>WMATA Policy</strong></p><p>a. Identify and document the location(s) of information and the specific system components on which the information is processed and stored.</p><p>b. Identify and document the users who have access to the system and system components where the information is processed and stored; and</p><p>c.  Document changes to the location (i.e., system or system components) where the information is processed and stored.</p><p><strong><u>OT Systems Only:</strong></u> Organizations identify specific information types or components to track where information is being processed and stored. Information to consider in the OT environment may include shared account passwords; PLC backup files; detailed network drawings; and risk assessments that identify specific threats with the environment. </p><p>Related Controls:  AC-2, AC-3, AC-4, AC-6, CM-8, PM-5, RA-2, SA-4, SA-8, SA-17, SC-4, SC-28, SI-4, SI-7</p><p>d. Security Controls Enhancement(s):</p><p><strong><u>NIST 800-82 Rev 3:<br></strong></u>OT Discussion: Organizations identify specific information types or components to track where information is being processed and stored. Information to consider in the OT environment may include shared account passwords, PLC backup files, detailed network drawings, and risk <br>assessments that identify specific threats with the environment. </p>', N'Configuration Management', N'Information Location', NULL, NULL, N'WMATA', NULL, NULL, NULL, 10, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37629, N'CM-12 (1)', N'Use automated tools to identify [Assignment: organization-defined information by information type] on [Assignment: organization-defined system components] to ensure controls are in place to protect organizational information and individual privacy.', N'<p><strong>WMATA Policy</strong></p><p>Use automated tools to identify information by information type (including sensitive information) on system components to ensure controls are in place to protect<br>organizational information and individual privacy.</p>', N'Configuration Management', N'Information Location', NULL, NULL, N'WMATA', NULL, NULL, NULL, 10, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37630, N'CM-2', N'a. Develop, document, and maintain under configuration control, a current baseline configuration of the system; andb. Review and update the baseline configuration of the system:     1. [Assignment: organization-defined frequency];     2. When required due to [Assignment: organization-defined circumstances]; and     3. When system components are installed or upgraded.', N'<p><strong>WMATA Policy</strong></p><p>a.  Develop, document, and maintain, under configuration control, a current baseline configuration of the system; and</p><p>b. Review and update the baseline configuration of the system:</p><p>i)  At least annually;</p><p>ii) When required due to a significant change; and</p><p>iii) When system components are installed or upgraded.</p><p>Related Controls: AC-19, AU-6, CA-9, CM-1, CM-3, CM-5, CM-6, CM-8, CM-9, CP-9, CP-10, CP-12, MA-2, PL-8, PM-5, SA-8, SA-10, SA-15, SC-18</p><p>c. Security Controls Enhancement(s):</p>', N'Configuration Management', N'Baseline Configuration', NULL, NULL, N'WMATA', NULL, NULL, NULL, 10, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37631, N'CM-2 (2)', N'Maintain the currency, completeness, accuracy, and availability of the baseline configuration of the system using [Assignment: organization-defined automated mechanisms].', N'<p><strong>WMATA Policy</strong></p><p>Maintain the currency, completeness, accuracy, and availability of the baseline configuration of the system using configuration management tools; hardware, software, firmware inventory tools, and network management tools. Automated tools shall be employed consistent with Control 3.4 Configuration Management, Section 8, (c), (ii), “CM-8 (2) Automated Maintenance”, to ensure that system component inventory and baseline configurations are aligned. Automated tools shall be <br>employed at the organization level, mission and business process level, and system level on workstations, servers, notebook computers, network components, and mobile devices.</p><p>See Control 3.4 Configuration Management, Section 8, “CM-8 System Component Inventory” for a list of required system component inventory requirements, and Control 3.4 Configuration Management, Section 6, “CM-6 Configuration Settings” for secure baseline configuration requirements.</p><p>Related Controls: CM-7, CM-6, CM-8, IA-3, RA-5</p>', N'Configuration Management', N'Baseline Configuration', NULL, NULL, N'WMATA', NULL, NULL, NULL, 10, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37632, N'CM-2 (3)', N'Retain [Assignment: organization-defined number] of previous versions of baseline configurations of the system to support rollback.', N'<p><strong>WMATA Policy</strong></p><p>Retain no less than two previous versions of baseline configurations of the system to<br>support rollback.</p>', N'Configuration Management', N'Baseline Configuration', NULL, NULL, N'WMATA', NULL, NULL, NULL, 10, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37633, N'CM-2 (7)', N'(a) Issue [Assignment: organization-defined systems or system components] with [Assignment: organization-defined configurations] to individuals traveling to locations that the organization deems to be of significant risk; and(b) Apply the following controls to the systems or components when the individuals return from travel: [Assignment: organization-defined controls].', N'<p><strong>WMATA Policy</strong></p><p>(1)  Issue mobile systems or devices to include laptops, tablets, and mobile phones with<br>sanitized hard drives, limited applications, and more stringent configuration settings to include all applicable security checklist settings set forth in Control 3.4 Configuration <br>Management, Section 6, “CM-6 Configuration Settings”, to individuals traveling to locations that the organization deems to be of significant risk to include international travel; and</p><p>(2)  Apply the following controls to the systems or components when the individuals return from travel and examine the mobile systems or devices for signs of tampering. If any tampering is suspected, provide the mobile system or device to DMCS for forensic analysis.</p><p>(3)  All mobile systems or devices shall be purged and reimaged upon return to WMATA. All mobile systems or devices shall be replaced if necessary. If replaced, the original mobile system or device will be disposed of in accordance with WMATA policy.</p><p>Related Controls: CM-6, MP-4, MP-5</p>', N'Configuration Management', N'Baseline Configuration', NULL, NULL, N'WMATA', NULL, NULL, NULL, 10, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37634, N'CM-3', N'a. Determine and document the types of changes to the system that are configuration-controlled;b. Review proposed configuration-controlled changes to the system and approve or disapprove such changes with explicit consideration for security and privacy impact analyses;c. Document configuration change decisions associated with the system;d. Implement approved configuration-controlled changes to the system;e. Retain records of configuration-controlled changes to the system for [Assignment: organization-defined time period];f. Monitor and review activities associated with configuration-controlled changes to the system; andg. Coordinate and provide oversight for configuration change control activities through [Assignment: organization-defined configuration change control element] that convenes [Selection (one or more): [Assignment: organization-defined frequency]; when [Assignment: organization-defined configuration change conditions]].', N'<p><strong>WMATA Policy</strong></p><p>a. Determine and document the types of changes to the system that are configuration- controlled;</p><p>b. Review proposed configuration-controlled changes to the system and approve or disapprove such changes with explicit consideration for security and privacy impact analyses;</p><p>c. Document configuration change decisions associated with the system;</p><p>d. Establish an enterprise CCB to review, approve, and coordinate all changes to WMATA systems, CIs, or system components;</p><p>e. Require all configuration changes to have business owner approval prior to the CCB;</p><p>f.  Implement approved configuration-controlled changes to the system by non-developers;</p><p>g.  Prior to implementation of approved configuration control changes pertaining to source code changes or software upgrades, create a backup of software and components based on a last known working configuration to ensure rollback capability prior to the implementation.</p><p>h.  Prior to CCB approval configuration control changes, such as source code changes or software upgrades, shall be validated against a trusted source to ensure the integrity of the code or installation files.</p><p>i.  Retain records of configuration-controlled changes to the system for at least five years or longer if specified by regulation, law, or external compliance mandate;</p><p>j.  Monitor and review activities associated with configuration-controlled changes to the system; and</p><p>k.  Coordinate and provide oversight for configuration change control activities through the CCB that convenes weekly. Normal changes shall be presented to the TWG prior to being presented at the CCB.</p><p><strong><u>OT Systems Only:</strong></u> Configuration change control procedures should align with the organization’s management of change practices. <br>	<br>Related Controls: CA-7, CM-2, CM-4, CM-5, CM-6, CM-9, CM-11, IA-3, MA-2, PE-16, PT-6, RA-8, SA-8, SA-10, SC-28, SI-2, SI-3, SI-4, SI-7, SI-10, SR-11<br>l.	Security Controls Enhancement(s):</p><p>l. Security Controls Enhancement(s):</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Configuration change control procedures should align with the organization’s <br>management of change practices.</p><p></p>', N'Configuration Management', N'Configuration Change Control', NULL, NULL, N'WMATA', NULL, NULL, NULL, 10, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37635, N'CM-3 (1)', N'Use [Assignment: organization-defined automated mechanisms] to:(a) Document proposed changes to the system;(b) Notify [Assignment: organization-defined approval authorities] of proposed changes to the system and request change approval;(c) Highlight proposed changes to the system that have not been approved or disapproved within [Assignment: organization-defined time period];(d) Prohibit changes to the system until designated approvals are received;(e) Document all changes to the system; and(f) Notify [Assignment: organization-defined personnel] when approved changes to the system are completed.', N'<p><strong>WMATA Policy</strong></p><p>Use automated mechanisms to:</p><p>(1) Document proposed changes to the system;</p><p>(2) Notify both the CCB and TWG of proposed changes to the system and request change approval as required;</p><p>(3) Highlight proposed changes to the system that have not been approved or disapproved within one month;</p><p>(4) Prohibit changes to the system until designated approvals are received;</p><p>(5) Document all changes to the system; and</p><p>(6) Notify the required stakeholders when approved changes to the system are<br>completed.</p>', N'Configuration Management', N'Configuration Change Control', NULL, NULL, N'WMATA', NULL, NULL, NULL, 10, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37636, N'CM-3 (2)', N'Test, validate, and document changes to the system before finalizing the implementation of the changes.', N'<p><strong>WMATA Policy</strong></p><p>Test, validate, and document changes to the system before finalizing the implementation of the changes.</p>', N'Configuration Management', N'Configuration Change Control', NULL, NULL, N'WMATA', NULL, NULL, NULL, 10, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37637, N'CM-3 (4)', N'Require [Assignment: organization-defined security and privacy representatives] to be members of the [Assignment: organization-defined configuration change control element].', N'<p><strong>WMATA Policy</strong></p><p>Require the CISO and the Privacy Officer, or designees, to be members of the DM CCB.</p>', N'Configuration Management', N'Configuration Change Control', NULL, NULL, N'WMATA', NULL, NULL, NULL, 10, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37638, N'CM-3 (6)', N'Ensure that cryptographic mechanisms used to provide the following controls are under configuration management: [Assignment: organization-defined controls].', N'<p><strong>WMATA Policy</strong></p><p>Ensure that cryptographic mechanisms used to provide the following controls are under<br>configuration management:</p><p><br>(1) Cryptographic Module Authentication</p><p>(2) Cryptographic Key Establishment and Management</p><p>(3) Cryptographic Protection</p><p>(4) Public Key Certificates</p><p>Related Controls: SC-12</p>', N'Configuration Management', N'Configuration Change Control', NULL, NULL, N'WMATA', NULL, NULL, NULL, 10, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37639, N'CM-3 (7)', N'<p><b>Configuration Change Control | Review System Changes</b></p>Review changes to the system [Assignment: organization-defined frequency] or when [Assignment: organization-defined circumstances] to determine whether unauthorized changes have occurred.', N'<p><strong>WMATA Policy</strong></p><p>Review changes to the system [Assignment: organization-defined frequency] or when [Assignment: organization-defined circumstances] to determine whether unauthorized changes have occurred. </p><p><strong><u>OT Systems Only: </strong></u>The organization takes into consideration OT-specific requirements when determining frequency and/or circumstances for reviewing system changes. As an example, safety instrumented systems may be justified for review of system changes on a predetermined frequency to ensure that no inadvertent changes have been made to the logic solver portion of a safety instrumented function. <br>	<br>Related Controls: AU-6, AU-7, CM-3</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: The organization considers OT-specific requirements when determining the frequency and/or circumstances for reviewing system changes. For example, safety instrumented systems may be justified for the review of system changes on a predetermined frequency to ensure that no inadvertent changes have been made to the logic solver portion of a safety instrumented function. </p>', N'Configuration Management', N'Configuration Change Control', NULL, NULL, N'WMATA', NULL, NULL, NULL, 10, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37640, N'CM-3 (8)', N'<p><b>Configuration Change Control | Prevent or Restrict Configuration Changes</b></p>Prevent or restrict changes to the configuration of the system under the following circumstances: [Assignment: organization-defined circumstances].', N'<p><strong>WMATA Policy</strong></p><p>Prevent or restrict changes to the configuration of the system under the following circumstances: [Assignment: organization-defined circumstances]. <br>	<br><strong><u>OT Systems Only: </strong></u>The organization prevents or restricts configuration changes based on a risk determination that the system should not be modified without additional permission. For example, some PLCs have physical key switches that are used to place the PLC in a mode that allows for programming changes. Physical key switches can restrict configuration changes so that physical access is required to make a modification to the system.</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: The organization prevents or restricts configuration changes based on a risk determination that the system should not be modified without additional permission. For example, some PLCs have physical key switches that are used to place the PLC in a mode that allows for programming changes. Physical key switches can restrict configuration <br>changes so that physical access is required to make a modification to the system.</p>', N'Configuration Management', N'Configuration Change Control', NULL, NULL, N'WMATA', NULL, NULL, NULL, 10, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37641, N'CM-4', N'Analyze changes to the system to determine potential security and privacy impacts prior to change implementation.', N'<p><strong>WMATA Policy</strong></p><p>a. Analyze changes to the system to determine potential security and privacy impacts prior to change implementation.</p><p><strong><u>OT Systems Only: </strong></u>The organization considers OT safety and security interdependencies. OT security and safety personnel are included in change process management if the change to the system may have an impact on safety or security. </p><p>Related Controls: CA-7, CM-3, CM-8, CM-9, MA-2, RA-3, RA-5, RA-8, SA-5, SA-8, SA-10, SI-2</p><p>b. Security Controls Enhancement(s):</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: The organization considers OT safety and security interdependencies. OT security and safety personnel are included in change process management if the change to the system may impact safety or security.<br></p>', N'Configuration Management', N'Impact Analyses', NULL, NULL, N'WMATA', NULL, NULL, NULL, 10, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37642, N'CM-4 (1)', N'Analyze changes to the system in a separate test environment before implementation in an operational environment, looking for security and privacy impacts due to flaws, weaknesses, incompatibility, or intentional malice.', N'<p><strong>WMATA Policy</strong></p><p>Analyze changes to the system in a separate test environment before implementation in an operational environment, looking for security and privacy impacts due to flaws,<br>weaknesses, incompatibility, or intentional malice.</p><p>Related Controls: SA-11, SC-7</p>', N'Configuration Management', N'Impact Analyses', NULL, NULL, N'WMATA', NULL, NULL, NULL, 10, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37643, N'CM-4 (2)', N'After system changes, verify that the impacted controls are implemented correctly, operating as intended, and producing the desired outcome with regard to meeting the security and privacy requirements for the system.', N'<p><strong>WMATA Policy</strong></p><p>After system changes, verify that the impacted controls are implemented correctly, operating as intended, and producing the desired outcome regarding meeting the<br>security and privacy requirements for the system.</p><p>Related Controls: SA-11, SC-3, SI-6</p>', N'Configuration Management', N'Impact Analyses', NULL, NULL, N'WMATA', NULL, NULL, NULL, 10, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37644, N'CM-5', N'Define, document, approve, and enforce physical and logical access restrictions associated with changes to the system.', N'<p><strong>WMATA Policy</strong></p><p>a. Define, document, approve, and enforce physical and logical access restrictions associated with changes to the system.</p><p>b. Restrict access for Developers to production application objects, elements, and data.</p><p><strong><u>OT Systems Only:</strong></u> Some OT devices allow for the configuration and use of mode change switches. Where available, these should be used to prevent unauthorized changes. As an example, many PLCs have key switches that allow the device to be placed in a programming mode or a running mode. Those PLCs should be placed in a running or remote mode to prevent unauthorized programming changes, and the key should be removed from the key switch and managed appropriately. <br>	<br>Related Controls: AC-3, AC-5, AC-6, CM-9, PE-3, SC-28, SI-2, SI-10</p><p>c.  Security Controls Enhancement(s):</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Some OT devices allow for the configuration and use of mode change switches. Where available, these should be used to prevent unauthorized changes. For example, many PLCs have key switches that allow the device to be placed in a programming mode or a running <br>mode. Those PLCs should be placed in a running or remote mode to prevent unauthorized programming changes, and the key should be removed from the key switch and managed appropriately. </p>', N'Configuration Management', N'Access Restrictions for Change', NULL, NULL, N'WMATA', NULL, NULL, NULL, 10, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37645, N'CM-5 (1)', N'(a) Enforce access restrictions using [Assignment: organization-defined automated mechanisms]; and(b) Automatically generate audit records of the enforcement actions.', N'<p><strong>WMATA Policy</strong></p><p>(1) Enforce access restrictions using DMCS-approved automated mechanisms; and</p><p>(2) Automatically generate audit records of the enforcement actions.</p><p>Related Controls: AU-2, AU-6, AU-7, AU-12, CM-6, CM-11, SI-12</p>', N'Configuration Management', N'Access Restrictions for Change', NULL, NULL, N'WMATA', NULL, NULL, NULL, 10, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37646, N'CM-6', N'a. Establish and document configuration settings for components employed within the system that reflect the most restrictive mode consistent with operational requirements using [Assignment: organization-defined common secure configurations];b. Implement the configuration settings;c. Identify, document, and approve any deviations from established configuration settings for [Assignment: organization-defined system components] based on [Assignment: organization-defined operational requirements]; andd. Monitor and control changes to the configuration settings in accordance with organizational policies and procedures.', N'<p><strong>WMATA Policy</strong></p><p>a.  Establish and document configuration settings for components employed within the system that reflect the most restrictive mode consistent with operational requirements using applicable Security Technical Implementation Guides (STIG) and the Center for Internet Security (CIS) Benchmarks designated and approved by DMCS, which results in approved security checklists. Applicable settings shall take precedence over other policy configuration settings unless otherwise approved by the Authorizing Officer (AO).</p><p>b. Implement the configuration settings based on the approved security checklist;</p><p>c.  Identify, document, and receive approval from the AO for any deviations from established configuration settings. Temporary deviation requests shall be documented in a POA&M for continuous monitoring, tracking, and remediation, and specify any system component(s) and operational requirements that prevent implementation of the security setting(s); and</p><p>d. Monitor and control changes to the configuration settings in accordance with organizational policies and procedures.</p><p>e. All WMATA systems and devices shall have approved baselines in accordance with the configuration settings established in Control 3.4 Configuration Management, Section 6, “CM- 6 Configuration Settings”.</p><p>Related Controls: AC-3, AC-19, AU-2, AU-6, CA-9, CM-2, CM-3, CM-5, CM-6, CM-7, CM-11, CP-7, CP-9, CP-10, IA-3, IA-5, PL-8, PL-9, RA-5, SA-4, SA-5, SA-8, SA-9, SC-18, SC-28, SI-2, SI-4, SI-6</p><p>f. Security Controls Enhancement(s):</p>', N'Configuration Management', N'Configuration Settings', NULL, NULL, N'WMATA', NULL, NULL, NULL, 10, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37647, N'CM-6 (1)', N'Manage, apply, and verify configuration settings for [Assignment: organization-defined system components] using [Assignment: organization-defined automated mechanisms].', N'<p><strong>WMATA Policy</strong></p><p>(1) Manage, apply, and verify configuration settings for system components using<br>DMCS approved automated mechanisms.</p><p>Related Controls: CA-7</p>', N'Configuration Management', N'Configuration Settings', NULL, NULL, N'WMATA', NULL, NULL, NULL, 10, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37648, N'CM-6 (2)', N'Take the following actions in response to unauthorized changes to [Assignment: organization-defined configuration settings]: [Assignment: organization-defined actions].', N'<p><strong>WMATA Policy</strong></p><p>(1) Take the following actions in response to unauthorized changes to configuration<br>settings:</p><p>(a) Alert designated personnel to restore authorized configuration settings or halt affected system processing. These requirements shall be documented in the SSP.</p><p>(b) If system processing is halted, execute the Information System Contingency Plan (ISCP)/Disaster Recovery Plan (DRP).</p><p>Related Controls: IR-4, IR-6, SI-7</p>', N'Configuration Management', N'Configuration Settings', NULL, NULL, N'WMATA', NULL, NULL, NULL, 10, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37649, N'CM-7', N'a. Configure the system to provide only [Assignment: organization-defined mission essential capabilities]; andb. Prohibit or restrict the use of the following functions, ports, protocols, software, and/or services: [Assignment: organization-defined prohibited or restricted functions, system ports, protocols, software, and/or services].', N'<p><strong>WMATA Policy</strong></p><p>a. Configure the system to provide only mission essential capabilities consistent with the business mission or operations; and</p><p>b.  Prohibit or restrict the use of the disallowed, unnecessary and nonsecure functions, ports, protocols, software, and/or services published in the PPSM to prevent unauthorized connection of components, transfer of information, and tunneling.</p><p><strong><u>OT Systems Only: </strong></u>The organization implements least functionality by allowing only specified functions, protocols, and/or services required for OT operations. For non-routable protocols such as serial communications, interrupts could be disabled or set points could be made read-only except for privileged users to limit functionality. Ports are part of the address space in network protocols and are often associated with specific protocols or functions. For routable protocols, ports can be disabled on many networking devices to limit functionality to the minimum required for operation.  </p><p>Related Controls: AC-3, AC-4, CM-2, CM-5, CM-6, CM-11, RA-5, SA-4, SA-5, SA-8, SA-9, SA-15, SC-2, SC-3, SC-7, SI-4</p><p>c. Security Controls Enhancement(s):</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: The organization implements least functionality by allowing only the specified functions, protocols, and/or services required for OT operations. For non-routable protocols, such as serial communications, interrupts could be disabled or set points could be made readonly except for privileged users to limit functionality. Ports are part of the address space in network protocols and are often associated with specific protocols or functions. For routable protocols, ports can be disabled on many networking devices to limit functionality to the <br>minimum required for operation.</p><p></p>', N'Configuration Management', N'Least Functionality', NULL, NULL, N'WMATA', NULL, NULL, NULL, 10, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37650, N'CM-7 (1)', N'(a) Review the system [Assignment: organization-defined frequency] to identify unnecessary and/or nonsecure functions, ports, protocols, software, and services; and(b) Disable or remove [Assignment: organization-defined functions, ports, protocols, software, and services within the system deemed to be unnecessary and/or nonsecure].', N'<p><strong>WMATA Policy</strong></p><p>(1) Review the system at least annually, as a part of system changes, or when a significant change occurs to identify unnecessary and/or nonsecure functions, ports, protocols, software, and services; and</p><p>(2) Disable or remove disallowed, unnecessary and nonsecure functions, ports,<br>protocols, software, and services within the system.</p><p>Related Controls: AC-18</p>', N'Configuration Management', N'Least Functionality', NULL, NULL, N'WMATA', NULL, NULL, NULL, 10, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37651, N'CM-7 (2)', N'Prevent program execution in accordance with [Selection (one or more): [Assignment: organization-defined policies, rules of behavior, and/or access agreements regarding software program usage and restrictions]; rules authorizing the terms and conditions of software program usage].', N'<p><strong>WMATA Policy</strong></p><p>(1) Where feasible, limit component functionality to a single function per component.</p><p>(2) Remove unused or unnecessary software and disable unused or unnecessary physical and logical ports and protocols to prevent unauthorized connection of components, transfer of information, and tunneling.</p><p>(3) Employ network scanning tools, intrusion detection and prevention systems, and end-point protection technologies, such as firewalls and host-based intrusion detection systems, to identify and prevent the use of prohibited functions, protocols,<br>ports, and services.</p><p>Related Controls: CM-8, PL-4, PL-9, PM-5, PS-6</p>', N'Configuration Management', N'Least Functionality', NULL, NULL, N'WMATA', NULL, NULL, NULL, 10, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37652, N'CM-7 (5)', N'<p><b>Least Functionality | Authorized Software</b></p>Unauthorized software programs can be limited to specific versions or from a specific source. The concept of prohibiting the execution of unauthorized software may also be applied to user actions, system ports and protocols, IP addresses/ranges, websites, and MAC addresses.', N'<p><strong>WMATA Policy</strong></p><p>(1) The operation of software, as designated on the APL, which are authorized to<br>execute on the system;</p><p>(2) Employ a deny-all, permit-by-exception policy to allow the execution of authorized software programs on the system; and</p><p>(3) Review and update the APL annually.</p><p><strong><u>OT Systems Only:</strong></u> The set of applications that run in OT is relatively static, making allowlisting practical. DHS recommends using application allowlisting for OT equipment.</p><p>Related Controls:  CM-2, CM-6, CM-8, CM-10, PL-9, PM-5, SA-10, SI-7</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: The set of applications that run in OT is relatively static, making allowlisting practical. DHS recommends using application allowlisting for OT equipment.</p>', N'Configuration Management', N'Least Functionality', NULL, NULL, N'WMATA', NULL, NULL, NULL, 10, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37653, N'CM-8', N'a. Develop and document an inventory of system components that:     1. Accurately reflects the system;     2. Includes all components within the system;     3. Does not include duplicate accounting of components or components assigned to any other system;     4. Is at the level of granularity deemed necessary for tracking and reporting; and     5. Includes the following information to achieve system component accountability: [Assignment: organization-defined information deemed      necessary to achieve effective system component accountability]; andb. Review and update the system component inventory [Assignment: organization-defined frequency].', N'<p><strong>WMATA Policy</strong></p><p>a.  Develop and document an inventory of system components within the enterprise CMDB that:</p><p>i)  Accurately reflects the system;</p><p>ii) Includes all components within the system;</p><p>iii) Does not include duplicate accounting of components or components assigned to any other system;</p><p>iv) Is at the level of granularity deemed necessary for tracking and reporting; and</p><p>v) Includes the following information to achieve system component accountability:</p><p>(1) Hardware, software, and firmware inventories:</p><p>(a) Hardware inventory includes specifications (manufacturer, type, model, serial number, physical location).</p><p>(b) Software inventory includes software name, software license information (minimally inclusive of expiration date, license type, number of licenses), serial numbers (if applicable), information system/component owner, IP/hostname, software products and version numbers for all components, application URLs (for scanning), responsible point of contact and role/organizational unit per Control 3.4 Configuration Management, Section 8, (c), (iv), “CM-8 (4) Accountability Information”, and for a networked component/device, the machine name (including DNS name, Netbios Name), network address (IPv4 & IPv6).</p><p>(c) Firmware inventory includes vendor name, product, and version.</p><p>b.  Review and update the system component inventory quarterly. Monitoring for any changes to the system component inventory and monitoring for the addition of unauthorized system components may be accomplished on an ongoing basis or by the periodic scanning of systems for that purpose. Automated mechanisms may also be used to prevent the connection of unauthorized components as noted in Control 3.4 Configuration Management Section 8, (c), (iii), “CM-8 (3) Automated Unauthorized <br>Component Detection”.</p><p>c.  Systems or system components that do not have or cannot support agents (e.g., IoT devices or sensors) shall be isolated, sandboxed, or segmented by placing them in separate domains or subnets, or by quarantining such components.</p><p>Related Controls:  CM-2, CM-7, CM-8,  CM-9, CM-10, CM-11, CP-2, CP-9, MA-2, MA-6, PL-9, PM-5, SA-4, SA-5, SI-2, SR-4</p><p>d. Security Controls Enhancement(s):</p>', N'Configuration Management', N'System Component Inventory', NULL, NULL, N'WMATA', NULL, NULL, NULL, 10, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37654, N'CM-8 (1)', N'Update the inventory of system components as part of component installations, removals, and system updates.', N'<p><strong>WMATA Policy</strong></p><p>(1) Update the inventory of system components as part of component installations,<br>removals, and system updates.</p><p>Related Controls:  PM-16</p>', N'Configuration Management', N'System Component Inventory', NULL, NULL, N'WMATA', NULL, NULL, NULL, 10, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37655, N'CM-8 (2)', N'Maintain the currency, completeness, accuracy, and availability of the inventory of system components using [Assignment: organization-defined automated mechanisms].', N'<p><strong>WMATA Policy</strong></p><p>(1) Maintain the currency, completeness, accuracy, and availability of the inventory of system components using automated mechanisms to maintain the accuracy of the<br>CMDB.</p>', N'Configuration Management', N'System Component Inventory', NULL, NULL, N'WMATA', NULL, NULL, NULL, 10, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37656, N'CM-8 (3)', N'(a) Detect the presence of unauthorized hardware, software, and firmware components within the system using [Assignment: organization-defined automated mechanisms] [Assignment: organization-defined frequency]; and(b) Take the following actions when unauthorized components are detected: [Selection (one or more): disable network access by such components; isolate the components; notify [Assignment: organization-defined personnel or roles]].', N'<p><strong>WMATA Policy</strong></p><p>(1) Immediately (real-time) remediate any detected unauthorized hardware, software, and firmware components within the system using automated mechanisms such as rogue system or device detectors, and Network Access Control (NAC);</p><p>(2) Take the following actions when unauthorized components are detected: quarantine the components; notify required stakeholders.</p><p>(3) Authorized components that fail to meet vulnerability management requirements<br>shall be placed into a remediation zone until requirements are met.</p><p>Related Controls:  AC-19, CA-7, RA-5, SC-3, SC-39, SI-3, SI-4, SI-7</p>', N'Configuration Management', N'System Component Inventory', NULL, NULL, N'WMATA', NULL, NULL, NULL, 10, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37657, N'CM-8 (4)', N'Include in the system component inventory information, a means for identifying by [Selection (one or more): name; position; role], individuals responsible and accountable for administering those components.', N'<p><strong>WMATA Policy</strong></p><p>(1) Include in the system component inventory information, a means for identifying by name and position the System Owner accountable for administering those components and by name and/or position the System Administrator responsible for<br>administering those components.</p><p>Related Controls: AC-3</p>', N'Configuration Management', N'System Component Inventory', NULL, NULL, N'WMATA', NULL, NULL, NULL, 10, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37658, N'CM-9', N'Develop, document, and implement a configuration management plan for the system that:a. Addresses roles, responsibilities, and configuration management processes and procedures;b. Establishes a process for identifying configuration items throughout the system development life cycle and for managing the configuration of the configuration items;c. Defines the configuration items for the system and places the configuration items under configuration management;d. Is reviewed and approved by [Assignment: organization-defined personnel or roles]; ande. Protects the configuration management plan from unauthorized disclosure and modification.', N'<p><strong>WMATA Policy</strong></p><p>a. Develop, document, and implement a configuration management plan for the system that:</p><p>i)  Addresses roles, responsibilities, and configuration management processes and procedures;</p><p>ii)  Establishes a process for identifying configuration items throughout the system development life cycle and for managing the configuration of the configuration items;</p><p>iii) Defines the configuration items for the system and places the configuration items under <br>configuration management;</p><p>iv) Is reviewed and approved by the business owner(s), system owner, and CCB;</p><p>v) Protects the configuration management plan from unauthorized disclosure and modification; and</p><p>vi) Identifies a process for configuration monitoring.</p><p><strong><u>OT Systems Only:</strong></u> Configuration management plans apply to internal and external (e.g., contractors, integrators) resources responsible for device configuration.</p><p>Related Controls: CM-2, CM-3, CM-4, CM-5, CM-8, PL-2, RA-8, SA-10, SI-12</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Configuration management plans apply to the internal and external (e.g., contractors, integrators) resources responsible for device configuration. </p>', N'Configuration Management', N'Configuration Management Plan', NULL, NULL, N'WMATA', NULL, NULL, NULL, 10, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37659, N'CP-1', N'a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:     1. [Selection (one or more): Organization-level; Mission/business process-level; System-level] contingency planning policy that:          (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and           compliance; and          (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and     2. Procedures to facilitate the implementation of the contingency planning policy and the associated contingency planning controls;b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the contingency planning policy and procedures; andc. Review and update the current contingency planning:     1. Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and     2. Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].', N'<p><strong>WMATA Policy</strong></p><p>Reference P/I 15.28 Cybersecurity Policy for requirements.</p><p>Related Controls: PM-9, PS-8, SI-12</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: The policy specifically addresses the unique properties and requirements of OT <br>and the relationship to non-OT systems</p>', N'Contingency Planning', N'Contingency Planning Policy and Procedures', NULL, NULL, N'WMATA', NULL, NULL, NULL, 64, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37660, N'CP-10', N'Provide for the recovery and reconstitution of the system to a known state within [Assignment: organization-defined time period consistent with recovery time and recovery point objectives] after a disruption, compromise, or failure.', N'<p><strong>WMATA Policy</strong></p><p>a.  Provide for the recovery and reconstitution of the system to a known state within the time period specified in the CP consistent with recovery time and recovery point objectives in the BIA after a disruption, compromise, or failure.</p><p><strong><u>OT Systems Only: </strong></u>Reconstitution of the OT includes consideration whether system state variables should be restored to initial values or values before disruption (e.g., are valves restored to full open, full closed, or settings prior to disruption). Restoring system state variables may be disruptive to ongoing physical-processes (e.g., valves initially closed may adversely affect system cooling).</p><p>Related Controls: CP-2, CP-4, CP-6, CP-7, CP-9, IR-4, SA-8, SC-24, SI-13</p><p>b. Security Controls Enhancement(s):</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Reconstitution of the OT includes considering whether system state variables should be restored to initial values or the values before disruption (e.g., are valves restored to full open, full closed, or settings prior to disruption). Restoring system state variables may be disruptive to ongoing physical processes (e.g., valves initially closed may adversely affect system cooling). </p>', N'Contingency Planning', N'System Recovery and Reconstitution', NULL, NULL, N'WMATA', NULL, NULL, NULL, 64, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37661, N'CP-10 (2)', N'Implement transaction recovery for systems that are transaction-based.', N'<p><strong>WMATA Policy</strong></p><p>Implement transaction recovery for systems that are transaction-based to include database management systems (DBMS) and other transaction processing systems (e.g., systems that process financial transactions). When available, transaction rollback<br>and journaling shall be implemented.</p>', N'Contingency Planning', N'System Recovery and Reconstitution', NULL, NULL, N'WMATA', NULL, NULL, NULL, 64, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37662, N'CP-10 (4)', N'Provide the capability to restore system components within [Assignment: organization-defined restoration time periods] from configuration-controlled and integrity-protected information representing a known, operational state for the components.', N'<p><strong>WMATA Policy</strong></p><p>Provide the capability to restore system components from configuration-controlled and integrity-protected information representing a known, operational state for the components within restoration time periods consistent with objectives specified in the CP and associated BIA.</p><p>Related Controls: CM-2, CM-6</p>', N'Contingency Planning', N'System Recovery and Reconstitution', NULL, NULL, N'WMATA', NULL, NULL, NULL, 64, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37663, N'CP-10 (6)', N'<p><b>System Recovery and Reconstitution | Component Protection</b></p>Protect system components used for recovery and reconstitution.', N'<p><strong>WMATA Policy</strong></p><p>Protect system components used for recovery and reconstitution.</p><p>Related Controls: AC-3, AC-6, MP-2, MP-4, PE-3, PE-6</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Organizations should consider recovery and reconstitution timeframes when storing spare equipment, including environmental hazards that could damage the equipment. Storage locations and environments should be chosen appropriately for the type of backup equipment.</p><p>Rationale for adding CP-10 (6) to MOD and HIGH baselines: OT system components stored without protection against environmental threats and unauthorized physical or logical access can be susceptible to compromise or damage. Certain system components may include embedded <br>electronics that must be protected from environmental hazards.</p>', N'Contingency Planning', N'System Recovery and Reconstitution', NULL, NULL, N'WMATA', NULL, NULL, NULL, 64, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37664, N'CP-12', N'When [Assignment: organization-defined conditions] are detected, enter a safe mode of operation with [Assignment: organization-defined restrictions of safe mode of operation].', N'<p><strong>WMATA Policy</strong></p><p>When [Assignment: organization-defined conditions] are detected, enter a safe mode of operation with [Assignment: organization-defined restrictions of safe mode of operation]. <br>	<br>Related Controls: CM-2, SA-8, SC-24, SI-13, SI-17</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>Rationale for adding CP-12 to LOW, MOD, and HIGH baselines: This control provides a framework for the organization to plan its policy and procedures for dealing with IT and OT conditions beyond its control in the environment of operations to minimize potential safety and environmental impacts.</p>', N'Contingency Planning', N'Safe Mode', NULL, NULL, N'WMATA', NULL, NULL, NULL, 64, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37665, N'CP-2', N'a. Develop a contingency plan for the system that:     1. Identifies essential mission and business functions and associated contingency requirements;     2. Provides recovery objectives, restoration priorities, and metrics;     3. Addresses contingency roles, responsibilities, assigned individuals with contact information;     4. Addresses maintaining essential mission and business functions despite a system disruption, compromise, or failure;     5. Addresses eventual, full system restoration without deterioration of the controls originally planned and implemented;     6. Addresses the sharing of contingency information; and     7. Is reviewed and approved by [Assignment: organization-defined personnel or roles];b. Distribute copies of the contingency plan to [Assignment: organization-defined key contingency personnel (identified by name and/or by role) and organizational elements];c. Coordinate contingency planning activities with incident handling activities;d. Review the contingency plan for the system [Assignment: organization-defined frequency];e. Update the contingency plan to address changes to the organization, system, or environment of operation and problems encountered during contingency plan implementation, execution, or testing;f. Communicate contingency plan changes to [Assignment: organization-defined key contingency personnel (identified by name and/or by role) and organizational elements];g. Incorporate lessons learned from contingency plan testing, training, or actual contingency activities into contingency testing and training; andh. Protect the contingency plan from unauthorized disclosure and modification.', N'<p><strong>WMATA Policy</strong></p><p>a. Develop an ISCP for the system that:</p><p>i)  Identifies essential mission and business functions and associated contingency requirements;</p><p>ii) Provides recovery objectives, restoration priorities, and metrics;</p><p>iii) Addresses contingency roles, responsibilities, assigned individuals with contact information;</p><p>iv) Addresses maintaining essential mission and business functions despite a system disruption, compromise, or failure;</p><p>v)  Addresses eventual, full system restoration without deterioration of the controls originally planned and implemented;</p><p>vi) Addresses the sharing of contingency information; and</p><p>vii) Is reviewed and approved by the SO prior to submission to the AO for acceptance</p><p>b. Distribute copies of the ISCP to required stakeholders;</p><p>c. Coordinate contingency planning activities with incident handling activities;</p><p>d. Review the ISCP for the system annually;</p><p>e.  Update the ISCP to address changes to the organization, system, or environment of operation and problems encountered during ISCP implementation, execution, or testing;</p><p>f.  Communicate ISCP changes to required stakeholders;</p><p>g. Incorporate lessons learned from ISCP testing, training, or actual contingency activities into contingency testing and training; and</p><p>h. Protect the ISCP from unauthorized disclosure and modification.</p><p>i.  <strong>Disaster Recovery Plan (DRP) </strong><br>Establish a DRP which applies to major, usually physical disruptions to service that deny access to the primary facility infrastructure for an extended period. A DRP is an information system-focused plan designed to restore operability of the target system, application, or computer facility infrastructure at an alternate site after an emergency. The DRP must provide for full restoration at the primary facility. The DRP may be supported by multiple information system contingency plans to address recovery of impacted individual systems once the alternate facility has been established. A DRP may support a Business Continuity Plan (BCP) or Continuity of Operation Plan (COOP) by recovering supporting systems for mission/business processes or mission essential functions at an alternate location. The DRP only addresses information system disruptions that require relocation of operations.<br>	<br><strong><u>OT Systems Only:</strong></u> The organization defines contingency plans for categories of disruptions or failures. In the case of a contingency, the OT equipment executes preprogrammed functions such as alert the operator of the failure and then do nothing, alert the operator and then safely shut down the industrial process, or alert the operator and then maintain the last operational setting prior to failure. Contingency plans for widespread disruption may involve specialized organizations (e.g., FEMA, emergency services, regulatory authorities).</p><p>Related Controls:  CP-3, CP-4, CP-6, CP-7, CP-8, CP-9, CP-10, IR-4, IR-6, IR-8, IR-9, MA-6, MP-2, MP-4, MP-5, PL-2, PM-8, PM-11, SA-15, SC-7, SC-23, SI-12</p><p>i. Security Controls Enhancement(s):</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: The organization defines contingency plans for categories of disruptions or failures. In the case of a contingency, the OT equipment executes preprogrammed functions, such as alerting the operator of the failure and then doing nothing, alerting the operator and then safely shutting down the industrial process, or alerting the operator and then maintaining the last operational setting prior to failure. Contingency plans for widespread disruption may involve specialized organizations (e.g., FEMA, emergency services, regulatory authorities). </p><p></p>', N'Contingency Planning', N'Contingency Plan', NULL, NULL, N'WMATA', NULL, NULL, NULL, 64, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37666, N'CP-2 (1)', N'Coordinate contingency plan development with organizational elements responsible for related plans.', N'<p><strong>WMATA Policy</strong></p><p>Coordinate ISCP development and testing with organizational elements responsible for related plans ensuring that other contingency, continuity, disaster recovery, crisis communication, incident response, and occupant emergency plans are aligned and<br>coordinated with CPs.</p>', N'Contingency Planning', N'Contingency Plan', NULL, NULL, N'WMATA', NULL, NULL, NULL, 64, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37667, N'CP-2 (2)', N'Conduct capacity planning so that necessary capacity for information processing, telecommunications, and environmental support exists during contingency operations.', N'<p><strong>WMATA Policy</strong></p><p>Conduct capacity planning so that necessary capacity for information processing,<br>telecommunications, and environmental support exists during contingency operations.</p><p>Related Controls: PE-11, PE-12, PE-13, PE-14, PE-18, SC-5</p>', N'Contingency Planning', N'Contingency Plan', NULL, NULL, N'WMATA', NULL, NULL, NULL, 64, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37668, N'CP-2 (3)', N'Plan for the resumption of [Selection: all; essential] mission and business functions within [Assignment: organization-defined time period] of contingency plan activation.', N'<p><strong>WMATA Policy</strong></p><p>Plan for the resumption of all mission and business functions within the RTO and RPO as specified as part of the business continuity planning and documented in the system’s<br>Business Impact Analysis (BIA).</p>', N'Contingency Planning', N'Contingency Plan', NULL, NULL, N'WMATA', NULL, NULL, NULL, 64, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37669, N'CP-2 (5)', N'Plan for the continuance of [Selection: all; essential] mission and business functions with minimal or no loss of operational continuity and sustains that continuity until full system restoration at primary processing and/or storage sites.', N'<p><strong>WMATA Policy</strong></p><p>Plan for the continuance of all mission and business functions with minimal or no loss of operational continuity and sustain that continuity until full system restoration at primary processing and/or storage sites as part of business continuity planning as documented in the system BIA.</p>', N'Contingency Planning', N'Contingency Plan', NULL, NULL, N'WMATA', NULL, NULL, NULL, 64, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37670, N'CP-2 (8)', N'Identify critical system assets supporting [Selection: all; essential] mission and business functions.', N'<p><strong>WMATA Policy</strong></p><p>Identify critical system assets supporting all mission and business functions as part of<br>criticality analysis and/or business continuity planning as documented in the system BIA.</p><p>Related Controls: CM-8, RA-9</p>', N'Contingency Planning', N'Contingency Plan', NULL, NULL, N'WMATA', NULL, NULL, NULL, 64, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37671, N'CP-3', N'a. Provide contingency training to system users consistent with assigned roles and responsibilities:     1. Within [Assignment: organization-defined time period] of assuming a contingency role or responsibility;     2. When required by system changes; and     3. [Assignment: organization-defined frequency] thereafter; andb. Review and update contingency training content [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].', N'<p><strong>WMATA Policy</strong></p><p>a.  Provide contingency training to system users consistent with assigned roles and <br>responsibilities:</p><p>i)  Within 30 days of assuming a contingency role or responsibility;</p><p>ii) When required by system changes; and</p><p>iii) Annually thereafter; and</p><p>b. Review and update contingency training content annually and following events to include, but not limited to, ISCP testing or an actual contingency (lessons learned), assessment or audit findings, security or privacy incidents, or changes in laws, directives, regulations, policies, standards, and guidelines.</p><p>Related Controls: AT-2, AT-3, AT-4, CP-2, CP-4, CP-8, IR-2, IR-4, IR-9</p><p>c.  Security Controls Enhancement(s):</p><p></p>', N'Contingency Planning', N'Contingency Training', NULL, NULL, N'WMATA', NULL, NULL, NULL, 64, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37672, N'CP-3 (1)', N'Incorporate simulated events into contingency training to facilitate effective response by personnel in crisis situations.', N'<p><strong>WMATA Policy</strong></p><p>Incorporate simulated events into contingency training to facilitate effective response by personnel in crisis situations.</p>', N'Contingency Planning', N'Contingency Training', NULL, NULL, N'WMATA', NULL, NULL, NULL, 64, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37673, N'CP-4', N'a. Test the contingency plan for the system [Assignment: organization-defined frequency] using the following tests to determine the effectiveness of the plan and the readiness to execute the plan: [Assignment: organization-defined tests].b. Review the contingency plan test results; andc. Initiate corrective actions, if needed.', N'<p><strong>WMATA Policy</strong></p><p>a.  Test the ISCP for the system annually using the following tests to determine the<br>effectiveness of the plan and the readiness to execute the plan:</p><p>i)  Full exercise consisting of a test of all instructions within an ISCP every two years;</p><p>ii) Tabletops can be conducted in lieu of the full exercise in the off years;</p><p>b. Review the ISCP test results; and</p><p>c. Initiate corrective actions, if needed.</p><p>Related Controls: AT-3, CP-2, CP-3, CP-8, CP-9, IR-3, IR-4, PL-2, PM-14, SR-2</p><p>d. Security Controls Enhancement(s):</p>', N'Contingency Planning', N'Contingency Plan Testing', NULL, NULL, N'WMATA', NULL, NULL, NULL, 64, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37674, N'CP-4 (1)', N'Coordinate contingency plan testing with organizational elements responsible for related plans.', N'<p><strong>WMATA Policy</strong></p><p>Coordinate ISCP testing with organizational elements responsible for related plans.</p><p>Related Controls: IR-8, PM-8</p>', N'Contingency Planning', N'Contingency Plan Testing', NULL, NULL, N'WMATA', NULL, NULL, NULL, 64, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37675, N'CP-4 (2)', N'<p><b>Contingency Plan Testing | Alternate Processing Site</b></p>Test the contingency plan at the alternate processing site:(a) To familiarize contingency personnel with the facility and available resources; and(b) To evaluate the capabilities of the alternate processing site to support contingency operations.', N'<p><strong>WMATA Policy</strong></p><p>Test the ISCP at the alternate processing site:</p><p>(1) To familiarize contingency personnel with the facility and available resources; and</p><p>(2) To evaluate the capabilities of the alternate processing site to support contingency<br>operations.</p><p><strong><u>OT Systems Only: </strong></u>Not all systems will have alternate processing sites as discussed in CP-7.</p><p>Related Controls: CP-7</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Not all systems will have alternate processing sites, as discussed in CP-7. </p>', N'Contingency Planning', N'Contingency Plan Testing', NULL, NULL, N'WMATA', NULL, NULL, NULL, 64, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37676, N'CP-6', N'a. Establish an alternate storage site, including necessary agreements to permit the storage and retrieval of system backup information; andb. Ensure that the alternate storage site provides controls equivalent to that of the primary site.', N'<p><strong>WMATA Policy</strong></p><p>a. Establish an alternate storage site, maximizing geographical separation within the region, from the primary site. including necessary agreements to permit the storage and retrieval of system backup information; and</p><p>b. Ensure that the alternate storage site provides controls equivalent to that of the primary site.</p><p>c.  Monthly, create (and transmit to the alternate storage site) full backups and maintain those backups for at least six months, and do not overwrite, purge, or delete the backups within the six-month period. The backups must be maintained and logically isolated from each other, from differential backups, and from primary and alternate data centers.</p><p>Daily, create (and transmit to the alternate storage site) a differential backup and maintain those backups for 30 days.</p><p>d.  All backups shall be encrypted using cryptographic modules validated under the Cryptographic Modula Validation Program (CMVP), configured in "FIPS Mode," and using tion algorithms approved by the AO.</p><p>Related Controls:  CP-2, CP-7, CP-8, CP-9, CP-10, MP-4, MP-5, PE-3, SI-13</p><p>e. Security Controls Enhancement(s):</p>', N'Contingency Planning', N'Alternate Storage Site', NULL, NULL, N'WMATA', NULL, NULL, NULL, 64, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37677, N'CP-6 (1)', N'Identify an alternate storage site that is sufficiently separated from the primary storage site to reduce susceptibility to the same threats.', N'<p><strong>WMATA Policy</strong></p><p>Identify an alternate storage site that is sufficiently separated from the primary storage<br>site to reduce susceptibility to the same threats.</p><p>Related Controls: RA-3</p>', N'Contingency Planning', N'Alternate Storage Site', NULL, NULL, N'WMATA', NULL, NULL, NULL, 64, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37678, N'CP-6 (2)', N'Configure the alternate storage site to facilitate recovery operations in accordance with recovery time and recovery point objectives.', N'<p><strong>WMATA Policy</strong></p><p>Configure the alternate storage site to facilitate recovery operations in accordance with<br>recovery time and recovery point objectives.</p>', N'Contingency Planning', N'Alternate Storage Site', NULL, NULL, N'WMATA', NULL, NULL, NULL, 64, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37679, N'CP-6 (3)', N'Identify potential accessibility problems to the alternate storage site in the event of an area-wide disruption or disaster and outline explicit mitigation actions.', N'<p><strong>WMATA Policy</strong></p><p>Identify potential accessibility problems to the alternate storage site in the event of an<br>area-wide disruption or disaster and outline explicit mitigation actions.</p><p>Related Controls: RA-3</p>', N'Contingency Planning', N'Alternate Storage Site', NULL, NULL, N'WMATA', NULL, NULL, NULL, 64, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37680, N'CP-7', N'a. Establish an alternate processing site, including necessary agreements to permit the transfer and resumption of [Assignment: organization-defined system operations] for essential mission and business functions within [Assignment: organization-defined time period consistent with recovery time and recovery point objectives] when the primary processing capabilities are unavailable;b. Make available at the alternate processing site, the equipment and supplies required to transfer and resume operations or put contracts in place to support delivery to the site within the organization-defined time period for transfer and resumption; andc. Provide controls at the alternate processing site that are equivalent to those at the primary site.', N'<p><strong>WMATA Policy</strong></p><p>a.  Establish an alternate processing site, including necessary agreements to permit the transfer and resumption of system operations for essential mission and business functions within the time period specified in the CP consistent with recovery time and recovery point objectives specified in the BIA when the primary processing capabilities are unavailable. Minimally, recovery time shall meet the following standards;</p><p>i)  High: Instantaneous to one minute;</p><p>ii) Moderate: Not to exceed 24 hours;</p><p>iii) Low: Not to exceed two weeks (applications with no redundant capability at one of the primary data centers)</p><p>b.  Make available at the alternate processing site, the equipment, and supplies (including hardware) required to transfer and resume operations or put contracts in place to support delivery to the site within the organization-defined time period for transfer and resumption; and</p><p>c. Provide controls at the alternate processing site that are equivalent to those at the primary site.</p><p><strong><u>OT Systems Only:</strong></u> Many site-wide supervisory or optimization servers (i.e., Level 3 and above of the Purdue model ) can be supported from an alternative processing site. It is likely not feasible for control systems or field devices, such as sensors or final elements (i.e., Level 1 and 0 of the Purdue model), to be made available from an alternative processing site. </p><p>Related Controls:  CP-2, CP-6, CP-8, CP-9, CP-10, MA-6, PE-3, PE-11, PE-12, PE-17, SI-13</p><p>d. Security Controls Enhancement(s):</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Many site-wide supervisory or optimization servers (i.e., Level 3 and above of the Purdue model) can be supported from an alternate processing site. It is likely not feasible for control systems or field devices, such as sensors or final elements (i.e., Level 1 and 0 of the <br>Purdue model), to be made available from an alternate processing site.</p>', N'Contingency Planning', N'Alternate Processing Site', NULL, NULL, N'WMATA', NULL, NULL, NULL, 64, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37681, N'CP-7 (1)', N'Identify an alternate processing site that is sufficiently separated from the primary processing site to reduce susceptibility to the same threats.', N'<p><strong>WMATA Policy</strong></p><p>Identify an alternate processing site that is sufficiently separated from the primary<br>processing site to reduce susceptibility to the same threats.</p><p>Related Controls: RA-3</p>', N'Contingency Planning', N'Alternate Processing Site', NULL, NULL, N'WMATA', NULL, NULL, NULL, 64, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37682, N'CP-7 (2)', N'Identify potential accessibility problems to alternate processing sites in the event of an area-wide disruption or disaster and outlines explicit mitigation actions.', N'<p><strong>WMATA Policy</strong></p><p>Identify potential accessibility problems to alternate processing sites in the event of an<br>area-wide disruption or disaster and outlines explicit mitigation actions.</p><p>Related Controls: RA-3</p>', N'Contingency Planning', N'Alternate Processing Site', NULL, NULL, N'WMATA', NULL, NULL, NULL, 64, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37683, N'CP-7 (3)', N'Develop alternate processing site agreements that contain priority-of-service provisions in accordance with availability requirements (including recovery time objectives).', N'<p><strong>WMATA Policy</strong></p><p>Develop alternate processing site agreements that contain priority-of-service provisions in accordance with availability requirements (including recovery time objectives).</p>', N'Contingency Planning', N'Alternate Processing Site', NULL, NULL, N'WMATA', NULL, NULL, NULL, 64, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37684, N'CP-7 (4)', N'Prepare the alternate processing site so that the site can serve as the operational site supporting essential mission and business functions.', N'<p><strong>WMATA Policy</strong></p><p>Prepare the alternate processing site so that the site can serve as the operational site<br>supporting essential mission and business functions.</p><p>Related Controls: CM-2, CM-6, CP-4</p>', N'Contingency Planning', N'Alternate Processing Site', NULL, NULL, N'WMATA', NULL, NULL, NULL, 64, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37685, N'CP-8', N'Establish alternate telecommunications services, including necessary agreements to permit the resumption of [Assignment: organization-defined system operations] for essential mission and business functions within [Assignment: organization-defined time period] when the primary telecommunications capabilities are unavailable at either the primary or alternate processing or storage sites.', N'<p><strong>WMATA Policy</strong></p><p>a.  Establish alternate telecommunications services, including necessary agreements to permit the resumption of system operations for essential mission and business functions within the time period specified in the CP consistent with the BIA when the primary telecommunications capabilities are unavailable at either the primary or alternate processing or storage sites.</p><p><strong><u>OT Systems Only:</strong></u> Quality of service factors for OT include latency and throughput. </p><p>Related Controls:  CP-2, CP-6, CP-7, SC-7</p><p>b. Security Controls Enhancement(s):</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Quality of service factors for OT include latency and throughput. </p>', N'Contingency Planning', N'Telecommunications Services', NULL, NULL, N'WMATA', NULL, NULL, NULL, 64, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37686, N'CP-8 (1)', N'<p><b>Telecommunications Services | Priority of Service Provisions</b></p>(a) Develop primary and alternate telecommunications service agreements that contain priority-of-service provisions in accordance with availability requirements (including recovery time objectives); and(b) Request Telecommunications Service Priority for all telecommunications services used for national security emergency preparedness if the primary and/or alternate telecommunications services are provided by a common carrier.', N'<p><strong>WMATA Policy</strong></p><p>(1) Develop primary and alternate telecommunications service agreements that contain <br>priority-of-service provisions in accordance with availability requirements (including recovery time objectives); and</p><p>(2) Request Telecommunications Service Priority for all telecommunications services used for national security emergency preparedness if the primary and/or alternate<br>telecommunications services are provided by a common carrier.</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Testing for reliability and integrity increases confidence that the system can be restored after an incident and minimizes the impact associated with downtime and outages. The ability to test backups is often dependent on the resources needed to appropriately represent the environment, such as the availability of spare devices and testing equipment. Testing backup and restoration on OT is often limited to systems with redundancy or spare equipment. In certain cases, sampling will be limited to those redundant systems. Compensating controls may include alternative methods for testing backups, such as hash or checksum validations.</p>', N'Contingency Planning', N'Telecommunications Services', NULL, NULL, N'WMATA', NULL, NULL, NULL, 64, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37687, N'CP-8 (2)', N'<p><b>Telecommunications Services | Single Points of Failure</b></p>Obtain alternate telecommunications services to reduce the likelihood of sharing a single point of failure with primary telecommunications services.', N'<p><strong>WMATA Policy</strong></p><p>Obtain alternate telecommunications services to reduce the likelihood of sharing a single point of failure with primary telecommunications services.</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Testing for reliability and integrity increases confidence that the system can be restored after an incident and minimizes the impact associated with downtime and outages. The ability to test backups is often dependent on the resources needed to appropriately represent the environment, such as the availability of spare devices and testing equipment. Testing backup and restoration on OT is often limited to systems with redundancy or spare equipment. In certain cases, sampling will be limited to those redundant systems. Compensating controls may include alternative methods for testing backups, such as hash or checksum validations.</p>', N'Contingency Planning', N'Telecommunications Services', NULL, NULL, N'WMATA', NULL, NULL, NULL, 64, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37688, N'CP-8 (3)', N'Obtain alternate telecommunications services from providers that are separated from primary service providers to reduce susceptibility to the same threats.', N'<p><strong>WMATA Policy</strong></p><p>Obtain alternate telecommunications services from providers that are separated from<br>primary service providers to reduce susceptibility to the same threats.</p>', N'Contingency Planning', N'Telecommunications Services', NULL, NULL, N'WMATA', NULL, NULL, NULL, 64, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37689, N'CP-8 (4)', N'(a) Require primary and alternate telecommunications service providers to have contingency plans;(b) Review provider contingency plans to ensure that the plans meet organizational contingency requirements; and(c) Obtain evidence of contingency testing and training by providers [Assignment: organization-defined frequency].', N'<p><strong>WMATA Policy</strong></p><p>(1) Require primary and alternate telecommunications service providers to have ISCPs;</p><p>(2) Review provider ISCPS to ensure that the plans meet organizational contingency requirements; and</p><p>(3) Obtain evidence of contingency testing and training by providers annually.</p><p>Related Controls: CP-3, CP-4</p>', N'Contingency Planning', N'Telecommunications Services', NULL, NULL, N'WMATA', NULL, NULL, NULL, 64, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37690, N'CP-9', N'a. Conduct backups of user-level information contained in [Assignment: organization-defined system components] [Assignment: organization-defined frequency consistent with recovery time and recovery point objectives];b. Conduct backups of system-level information contained in the system [Assignment: organization-defined frequency consistent with recovery time and recovery point objectives];c. Conduct backups of system documentation, including security- and privacy-related documentation [Assignment: organization-defined frequency consistent with recovery time and recovery point objectives]; andd. Protect the confidentiality, integrity, and availability of backup information.', N'<p><strong>WMATA Policy</strong></p><p>a. Conduct backups of user-level information contained in systems and system components based on the RPO, and leveraging a differential backup approach;</p><p>b. Conduct backups of system-level information contained in systems and system components based on the RPO, and leveraging a differential backup approach;</p><p>c.  Conduct full backups of user-level information, system-level information, and system documentation, including security- and privacy-related documentation, at least weekly; and</p><p>d. Protect the confidentiality, integrity, and availability of backup information.</p><p>Related Controls: CP-2, CP-6, CP-10, MP-4, MP-5, SC-8, SC-12, SC-13, SI-4, SI-13</p><p>e. Security Controls Enhancement(s):</p>', N'Contingency Planning', N'System Backup', NULL, NULL, N'WMATA', NULL, NULL, NULL, 64, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37691, N'CP-9 (1)', N'Test backup information [Assignment: organization-defined frequency] to verify media reliability and information integrity.', N'<p><strong>WMATA Policy</strong></p><p>Test backup information at least monthly to verify media reliability and information<br>integrity.</p><p><strong><u>OT Systems Only:</strong></u> Testing for reliability and integrity increases confidence that the system can be restored after an incident, and minimizes the impact associated with downtime and outages. The ability to test backups is often dependent on resources, such as the availability of spare devices and testing equipment, needed to appropriately represent the environment. Testing backup and restoration on OT is often limited to systems with redundancy or spare equipment; in certain cases, sampling will be limited to those redundant systems. Compensating controls may include alternative methods for testing backups such as hash or checksum validations.</p><p>Related Controls: CP-4</p>', N'Contingency Planning', N'System Backup', NULL, NULL, N'WMATA', NULL, NULL, NULL, 64, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37692, N'CP-9 (2)', N'Use a sample of backup information in the restoration of selected system functions as part of contingency plan testing.', N'<p><strong>WMATA Policy</strong></p><p>Use a sample of backup information in the restoration of selected system functions as<br>part of ISCP testing, and at least monthly.</p><p><strong><u>OT Systems Only:</strong></u> Testing for reliability and integrity increases confidence that the system can be restored after an incident, and minimizes the impact associated with downtime and outages. The ability to test backups is often dependent on resources, such as the availability of spare devices and testing equipment, needed to appropriately represent the environment. Testing backup and restoration on OT is often limited to systems with redundancy or spare equipment; in certain cases, sampling will be limited to those redundant systems. Compensating controls may include alternative methods for testing backups such as hash or checksum validations. </p><p>Related Controls: CP-4</p>', N'Contingency Planning', N'System Backup', NULL, NULL, N'WMATA', NULL, NULL, NULL, 64, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37693, N'CP-9 (3)', N'Store backup copies of [Assignment: organization-defined critical system software and other security-related information] in a separate facility or in a fire rated container that is not collocated with the operational system.', N'<p><strong>WMATA Policy</strong></p><p>Store backup copies of critical system software and other security-related information in a separate facility or in a fire rated container that is not collocated with the operational system.</p><p>Related Controls: CM-2, CM-6, CM-8</p>', N'Contingency Planning', N'System Backup', NULL, NULL, N'WMATA', NULL, NULL, NULL, 64, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37694, N'CP-9 (5)', N'Transfer system backup information to the alternate storage site [Assignment: organization-defined time period and transfer rate consistent with the recovery time and recovery point objectives].', N'<p><strong>WMATA Policy</strong></p><p>Transfer system backup information to the alternate storage site based on standards established in CP-6, “Alternate Storage Site”. System backup information can be transferred to alternate storage sites either electronically or by the physical shipment of storage media.</p><p>Related Controls: CP-6,  CP-7, MP-3, MP-4, MP-5</p>', N'Contingency Planning', N'System Backup', NULL, NULL, N'WMATA', NULL, NULL, NULL, 64, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37695, N'CP-9 (8)', N'Implement cryptographic mechanisms to prevent unauthorized disclosure and modification of [Assignment: organization-defined backup information].', N'<p><strong>WMATA Policy</strong></p><p>Implement cryptographic mechanisms to prevent unauthorized disclosure and modification of system backup information in storage at both primary and alternate locations.</p><p>Related Controls: SC-12, SC-13, SC-28</p>', N'Contingency Planning', N'System Backup', NULL, NULL, N'WMATA', NULL, NULL, NULL, 64, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37696, N'IA-1', N'a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:     1. [Selection (one or more): Organization-level; Mission/business process-level; System-level] identification and authentication policy that:          (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and           compliance; and          (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and     2. Procedures to facilitate the implementation of the identification and authentication policy and the associated identification and authentication      controls;b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the identification and authentication policy and procedures; andc. Review and update the current identification and authentication:     1. Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and     2. Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].', N'<p><strong>WMATA Policy</strong></p><p>Reference P/I 15.28 Cybersecurity Policy for requirements.</p><p>Related Controls: AC-1, PM-9, PS-8, SI-12</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: The policy specifically addresses the unique properties and requirements of OT <br>and the relationship to non-OT systems.</p>', N'Identification and Authentication', N'Identification and Authentication Policy and Procedures', NULL, NULL, N'WMATA', NULL, NULL, NULL, 65, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37697, N'IA-11', N'Require users to re-authenticate when [Assignment: organization-defined circumstances or situations requiring re-authentication].', N'<p><strong>WMATA Policy</strong></p><p>Require users to re-authenticate when roles, authenticators, or credentials change as a result of a security incident, when security categories of systems change, and after 15 minutes of a fixed time period (e.g., if a session has been idle).</p><p>Related Controls: AC-3, AC-11, IA-2, IA-3, IA-4, IA-8</p>', N'Identification and Authentication', N'Re-Authentication', NULL, NULL, N'WMATA', NULL, NULL, NULL, 65, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37698, N'IA-12', N'a. Identity proof users that require accounts for logical access to systems based on appropriate identity assurance level requirements as specified in applicable standards and guidelines;b. Resolve user identities to a unique individual; andc. Collect, validate, and verify identity evidence.', N'<p><strong>WMATA Policy</strong></p><p>a. Identity-proof users that require accounts for logical access to systems based on appropriate <br>identity assurance level requirements as specified in applicable standards and guidelines;</p><p>b. Resolve user identities to a unique individual; and</p><p>c. Collect, validate, and verify identity evidence. Security Controls Enhancement(s):</p><p><strong><u>OT Systems Only:</strong></u> Identity proofing is likely performed by different departments within the organization. It is encouraged to leverage existing organization systems (i.e., HR or IT processes) to perform this control. Security Controls Enhancement(s):</p><p>Related Controls: AC-5, IA-1, IA-2, IA-3, IA-4, IA-5, IA-6, IA-8</p><p>d. Security Controls Enhancement(s):</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Identity proofing is likely performed by different departments within the organization. Existing organizational systems (e.g., HR or IT processes) should be leveraged to perform this control. </p>', N'Identification and Authentication', N'Identity Proofing', NULL, NULL, N'WMATA', NULL, NULL, NULL, 65, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37699, N'IA-12 (1)', N'<p><b>Identity Proofing | Supervisor Authorization</b></p>Require that the registration process to receive an account for logical access includes supervisor or sponsor authorization.', N'<p><strong>WMATA Policy</strong></p><p>Require that the registration process to receive an account for logical access includes supervisor or sponsor authorization.</p><p><strong><u>OT Systems Only: </strong></u>Maintenance, Engineering, or third-party organizations may require OT access in order to support operations. The organization should determine the AO for proving identity prior to allowing access to the OT environment. Consider obtaining supervisor or sponsor authorization, where the sponsor may be someone within operations.</p><p><strong><u>NIST 800-82 Rev 3:<br></strong></u>Control Enhancement: (1) OT Discussion: Maintenance, engineering, or third-party organizations may require OT access in order to support operations. The organization should determine the AO for proving identity prior to allowing access to the OT environment. Consider obtaining supervisor or sponsor authorization, where the sponsor may be someone within operations.</p>', N'Identification and Authentication', N'Identity Proofing', NULL, NULL, N'WMATA', NULL, NULL, NULL, 65, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37700, N'IA-12 (2)', N'<p><b>Identity Proofing | Identity Evidence</b></p>Require evidence of individual identification be presented to the registration authority.', N'<p><strong>WMATA Policy</strong></p><p>Require evidence of individual identification be presented to the RA.</p><p><strong><u>OT Systems Only: </strong></u>If the organization already performs these controls, it is recommended to leverage existing organizational processes. For example, Human Resources may provide a system for tracking identity evidence. OT does not need to develop an independent system for achieving this control. Rather, it is advised to leverage the existing processes developed by other departments within the organization.</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: If the organization already performs these controls, existing organizational processes should be leveraged. For example, HR may provide a system for tracking identity evidence. OT does not need to develop an independent system for achieving this control. </p>', N'Identification and Authentication', N'Identity Proofing', NULL, NULL, N'WMATA', NULL, NULL, NULL, 65, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37701, N'IA-12 (3)', N'<p><b>Identity Proofing | Identity Evidence Validation and Verification</b></p>Require that the presented identity evidence be validated and verified through [Assignment: organizational defined methods of validation and verification].', N'<p><strong>WMATA Policy</strong></p><p>Require that the presented identity evidence be validated and verified in accordance with acceptable identity source documents defined in Homeland Security Presidential Directive (HSPD) 12.</p><p><strong><u>OT Systems Only:</strong></u> If the organization already performs these controls, it is recommended to leverage existing organizational processes. For example, Human Resources may provide a system for tracking identity evidence. OT does not need to develop an independent system for achieving this control. Rather, it is advised to leverage the existing processes developed by other departments within the organization.</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: If the organization already performs these controls, existing organizational processes should be leveraged. For example, HR may provide a system for tracking identity evidence. OT does not need to develop an independent system for achieving this control. <br></p>', N'Identification and Authentication', N'Identity Proofing', NULL, NULL, N'WMATA', NULL, NULL, NULL, 65, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37702, N'IA-12 (4)', N'<p><b>Identity Proofing | In-person Validation and Verification</b></p>Require that the validation and verification of identity evidence be conducted in person before a designated registration authority.', N'<p><strong>WMATA Policy</strong></p><p>Require that the validation and verification of identity evidence be conducted in person before a designated RA.</p><p><strong><u>OT Systems Only: </strong></u>If the organization already performs these controls, it is recommended to leverage existing organizational processes. For example, Human Resources may provide a system for tracking identity evidence. OT does not need to develop an independent system for achieving this control. Rather, it is advised to leverage the existing processes developed by other departments within the organization.</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: If the organization already performs these controls, existing organizational processes should be leveraged. For example, HR may provide a system for tracking identity evidence. OT does not need to develop an independent system for achieving this control. </p>', N'Identification and Authentication', N'Identity Proofing', NULL, NULL, N'WMATA', NULL, NULL, NULL, 65, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37703, N'IA-12 (5)', N'<p><b>Identity Proofing | Address Confirmation</b></p>Require that a [Selection: registration code; notice of proofing] be delivered through an out-of-band channel to verify the users address (physical or digital) of record.', N'<p><strong>WMATA Policy</strong></p><p>Require that a [Selection: registration code; notice of proofing] be delivered through an out-of-band channel to verify the users address (physical or digital) of record.</p><p><strong><u>OT Systems Only:</strong></u> If the organization already performs these controls, it is recommended to leverage existing organizational processes. For example, Human Resources may provide a system for tracking identity evidence. OT does not need to develop an independent system for achieving this control. Rather, it is advised to leverage the existing processes developed by other departments within the organization.</p><p>Related Controls: IA-12</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: If the organization already performs these controls, existing organizational processes should be leveraged. For example, HR may provide a system for tracking identity evidence. OT does not need to develop an independent system for achieving this control. <br></p>', N'Identification and Authentication', N'Identity Proofing', NULL, NULL, N'WMATA', NULL, NULL, NULL, 65, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37704, N'IA-2', N'Uniquely identify and authenticate organizational users and associate that unique identification with processes acting on behalf of those users.', N'<p><strong>WMATA Policy</strong></p><p>a. Uniquely identify and authenticate users and associate that unique identification with processes acting on behalf of those users leveraging an authorized Identity and Access Management (IAM) solution.</p><p>Related Controls: AC-2, AC-3, AC-4, AC-14, AC-17, AC-18, AU-1, AU-6, IA-4, IA-5, IA-8, MA-4, MA-5, PE-2, PL-4, SA-4, SA-8</p><p>b. Security Controls Enhancement(s):</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: When shared accounts are required, compensating controls include providing increased physical security, personnel security, and auditing measures. For certain OT, the capability for immediate operator interaction is critical. Local emergency actions for OT are not hampered by identification or authentication requirements. Access to these systems may be restricted by appropriate physical controls.</p>', N'Identification and Authentication', N'Identification and Authentication (Organizational Users)', NULL, NULL, N'WMATA', NULL, NULL, NULL, 65, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37705, N'IA-2 (1)', N'<p><b>Identification and Authentication (organizational Users) | Multi-factor Authentication to Privileged Accounts</b></p>Implement multi-factor authentication for access to privileged accounts.', N'<p><strong>WMATA Policy</strong></p><p>Implement multi-factor authentication for access to privileged accounts.</p><p>OT Systems Only: As a compensating control, physical access restrictions may sufficiently represent one authentication factor, provided the system is not remotely accessible.</p><p>Related Controls: AC-5, AC-6</p><p><strong><u>NIST 800-82 Rev 3:<br></strong></u>OT Discussion: As a compensating control, physical access restrictions may sufficiently represent one authentication factor, provided that the system is not remotely accessible.</p>', N'Identification and Authentication', N'Identification and Authentication (Organizational Users)', NULL, NULL, N'WMATA', NULL, NULL, NULL, 65, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37706, N'IA-2 (12)', N'<p><b>Identification and Authentication (organizational Users) | Acceptance of PIV Credentials</b></p>Accept and electronically verify Personal Identity Verification-compliant credentials.', N'<p><strong>WMATA Policy</strong></p><p>Accept and electronically verify Personal Identity Verification-compliant credentials.</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: The acceptance of PIV credentials is only required for federal organizations, as defined by OMB Memorandum M-19-17 [OMB-M1917]. Nonfederal organizations should refer to IA-2 (1) (2) for guidance on multi-factor authentication credentials. Furthermore, many OT systems do not have the ability to accept PIV credentials and will require compensating controls.</p>', N'Identification and Authentication', N'Identification and Authentication (Organizational Users)', NULL, NULL, N'WMATA', NULL, NULL, NULL, 65, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37707, N'IA-2 (2)', N'<p><b>Identification and Authentication (organizational Users) | Multi-factor Authentication to Non-privileged Accounts</b></p>Implement multi-factor authentication for access to non-privileged accounts.', N'<p><strong>WMATA Policy</strong></p><p>Implement multi-factor authentication for access to non-privileged accounts.</p><p>OT Systems Only: As a compensating control, physical access restrictions may sufficiently represent one authentication factor, provided the system is not remotely accessible.</p><p>Related Controls: AC-5</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: As a compensating control, physical access restrictions may sufficiently represent one authentication factor, provided that the system is not remotely accessible.</p>', N'Identification and Authentication', N'Identification and Authentication (Organizational Users)', NULL, NULL, N'WMATA', NULL, NULL, NULL, 65, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37708, N'IA-2 (5)', N'<p><b>Identification and Authentication (organizational Users) | Individual Authentication with Group Authentication</b></p>When shared accounts or authenticators are employed, require users to be individually authenticated before granting access to the shared accounts or resources.', N'<p><strong>WMATA Policy</strong></p><p>Identifiers and authenticators shall not be shared within the WMATA Enterprise unless authorized by the AO/AODR. When shared identifiers or authenticators are in use, users shall be individually authenticated before access is granted to a shared account or resource.</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: For local access, physical access controls and logging may be used as an alternative to individual authentication on an OT system. For remote access, the remote access authentication mechanism will be used to identify, permit, and log individual access before permitting the use of shared accounts. </p>', N'Identification and Authentication', N'Identification and Authentication (Organizational Users)', NULL, NULL, N'WMATA', NULL, NULL, NULL, 65, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37709, N'IA-2 (8)', N'Implement replay-resistant authentication mechanisms for access to [Selection (one or more): privileged accounts; non-privileged accounts].', N'<p><strong>WMATA Policy</strong></p><p>Implement replay-resistant authentication mechanisms for access to privileged and non-privileged accounts.</p>', N'Identification and Authentication', N'Identification and Authentication (Organizational Users)', NULL, NULL, N'WMATA', NULL, NULL, NULL, 65, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37710, N'IA-3', N'Uniquely identify and authenticate [Assignment: organization-defined devices and/or types of devices] before establishing a [Selection (one or more): local; remote; network] connection.', N'<p><strong>WMATA Policy</strong></p><p>Uniquely identify and authenticate all devices and systems that connect to or access WMATA networks and/or systems before establishing a local, remote, or network connection. All certificates employed on WMATA systems and/or devices shall be from a trusted source identified by DMCS and authorized by the AO.</p><p>Related Controls: AC-17, AC-18, AC-19, AU-6, CA-3, CA-9, IA-4, IA-5, IA-11, IR-9, SI-4</p><p>a.  Security Controls Enhancement(s):</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: OT devices may not inherently support device authentication. If devices are local to one another, physical security measures that prevent unauthorized communication between devices can be used as compensating controls. For remote communication, additional hardware may be required to meet authentication requirements. </p><p>Rationale for adding IA-3 to LOW baseline: Given the variety of OT devices and physical locations of OT devices, organizations may consider whether OT devices that may be vulnerable to tampering or spoofing require unique identification and authentication and for what types of <br>connections. </p>', N'Identification and Authentication', N'Device Identification and Authentication', NULL, NULL, N'WMATA', NULL, NULL, NULL, 65, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37711, N'IA-3 (1)', N'<p><b>Device Identification and Authentication | Cryptographic Bidirectional Authentication</b></p>Authenticate [Assignment: organization-defined devices and/or types of devices] before establishing [Selection (one or more): local; remote; network] connection using bidirectional authentication that is cryptographically based.', N'<p><strong>WMATA Policy</strong></p><p>Authenticate before establishing connection using bidirectional authentication that is cryptographically based. </p><p>Related Controls: SC-8, SC-12, SC-13</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: For OT systems that include IIoT devices, these <br>enhancements may be needed to protect device-to-device communication. </p>', N'Identification and Authentication', N'Device Identification and Authentication', NULL, NULL, N'WMATA', NULL, NULL, NULL, 65, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37712, N'IA-3 (4)', N'<p><b>Device Identification and Authentication | Device Attestation</b></p>Handle device identification and authentication based on attestation by [Assignment: organization-defined configuration management process].', N'<p><strong>WMATA Policy</strong></p><p>Handle device identification and authentication based on attestation by [Assignment: organization-defined configuration management process]. </p><p>Related Controls: CM-2, CM-3, CM-6</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: For OT systems that include IIoT devices, these enhancements may be needed to protect device-to-device communication. <br></p>', N'Identification and Authentication', N'Device Identification and Authentication', NULL, NULL, N'WMATA', NULL, NULL, NULL, 65, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37713, N'IA-4', N'a. Receiving authorization from [Assignment: organization-defined personnel or roles] to assign an individual, group, role, service, or device identifier;b. Selecting an identifier that identifies an individual, group, role, service, or device;c. Assigning the identifier to the intended individual, group, role, service, or device; andd. Preventing reuse of identifiers for [Assignment: organization-defined time period].', N'<p><strong>WMATA Policy</strong></p><p>Manage system identifiers by:<br>a. Receiving authorization from System Owners to assign an individual, group, role, service, or device identifier;</p><p>b. Selecting an identifier that identifies an individual, group, role, service, or device;</p><p>c. Assigning the identifier to the intended individual, group, role, service, or device;</p><p>d. Not assigning the same identifier to a single individual for more than one role;</p><p>e. Only allowing the use of identifiers by a single individual; and</p><p>f.  Preventing reuse of identifiers, except for users that are rehired.</p><p>Related Controls: AC-5, IA-2, IA-3, IA-5, IA-8, IA-12, MA-4, PE-2, PE-3, PE-4, PL-4, PM-12, PS-3, PS-4, PS-5</p><p>g. Security Controls Enhancement(s):</p><p></p>', N'Identification and Authentication', N'Identifier Management', NULL, NULL, N'WMATA', NULL, NULL, NULL, 65, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37714, N'IA-4 (4)', N'<p><b>Identifier Management | Identify User Status</b></p>Manage individual identifiers by uniquely identifying each individual as [Assignment: organization-defined characteristic identifying individual status].', N'<p><strong>WMATA Policy</strong></p><p>Manage individual identifiers by uniquely identifying each individual by their affiliation with WMATA, minimally differentiating between employees and non-employees (e.g., contractors, foreign nationals, non-organizational users, etc.). Ensure that badges have different visual markings to indicate the status of individuals.</p><p><strong><u>OT Systems Only:</strong></u> Non-organizational, including foreign national, support for OT systems shall only be authorized by the CISO. </p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: This control enhancement is typically implemented by the organization rather than at the system level. However, to manage risk for certain OT environments, identifiers (e.g., badges) may have different markings to indicate the status of individuals, such as contractors, foreign nationals, and non-organizational users. </p>', N'Identification and Authentication', N'Identifier Management', NULL, NULL, N'WMATA', NULL, NULL, NULL, 65, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37715, N'IA-5', N'a. Verifying, as part of the initial authenticator distribution, the identity of the individual, group, role, service, or device receiving the authenticator;b. Establishing initial authenticator content for any authenticators issued by the organization;c. Ensuring that authenticators have sufficient strength of mechanism for their intended use;d. Establishing and implementing administrative procedures for initial authenticator distribution, for lost or compromised or damaged authenticators, and for revoking authenticators;e. Changing default authenticators prior to first use;f. Changing or refreshing authenticators [Assignment: organization-defined time period by authenticator type] or when [Assignment: organization-defined events] occur;g. Protecting authenticator content from unauthorized disclosure and modification;h. Requiring individuals to take, and having devices implement, specific controls to protect authenticators; andi. Changing authenticators for group or role accounts when membership to those accounts changes.', N'<p><strong>WMATA Policy</strong></p><p>Manage system authenticators by:</p><p>a. Verifying, as part of the initial authenticator distribution, the identity of the individual, <br>group, role, application, service, or device receiving the authenticator;</p><p>b. Establishing initial authenticator content for any authenticators issued by the organization;</p><p>c. Ensuring that authenticators have sufficient strength of mechanism for their intended use;</p><p>d. Establishing and implementing administrative procedures for initial authenticator distribution, <br>for lost or compromised or damaged authenticators, and for revoking authenticators;</p><p>e. Changing default authenticators immediately upon first use;</p><p>f.  No limits will be set on frequency of authenticator changing or refreshing of passwords;</p><p>g. Users shall be permitted to change passwords using self-service capabilities;</p><p>h. Changing or refreshing authenticators as follows:</p><p>i)  User Authenticators:</p><p>(1) Passwords (includes service accounts): 90 days;</p><p>(2) Certificates: three years; and</p><p>(3) One-time password (OTP) devices: at least every 30 seconds.</p><p>ii) Device, Service and Application Authenticators:</p><p>(1) Certificates: one year; and</p><p>(2) Passwords: 90 days.</p><p>i.  Configuring to expire. Users and owners of group authenticators (e.g., service accounts) shall automatically receive notification 30 days prior to expiration;</p><p>j.  Changing authenticators when there is a security incident or compromise of the authenticator, or at the direction of DMCS;</p><p>k. Protecting authenticator content from unauthorized disclosure and modification as defined in WMATA policy;</p><p>l.  Requiring individuals to use, and having devices implement, specific controls to protect <br>authenticators; and</p><p>m. Changing authenticators for group or role accounts when membership to those accounts changes.</p><p>n.  Maintaining a repository of certificates, associated expiration dates, and system <br>administrators; and</p><p>o. Notifying system administrators 30 days prior to expiration of certificates.</p><p><strong><u>OT Systems Only: </strong></u>Compensating controls for OT systems can include physical access controls and encapsulation of the OT to provide authentication external to the OT.</p><p>Related Controls: AC-3, AC-6, CM-6, IA-2, IA-4, IA-7, IA-8, MA-4, PE-2, PL-4, SC-12, SC-13</p><p>p. Security Controls Enhancement(s):</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Example compensating controls include physical access control and encapsulating the OT to provide authentication external to the OT. </p>', N'Identification and Authentication', N'Authenticator Management', NULL, NULL, N'WMATA', NULL, NULL, NULL, 65, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37716, N'IA-5 (1)', N'For password-based authentication:(a) Maintain a list of commonly-used, expected, or compromised passwords and update the list [Assignment: organization-defined frequency] and when organizational passwords are suspected to have been compromised directly or indirectly;(b) Verify, when users create or update passwords, that the passwords are not found on the list of commonly-used, expected, or compromised passwords in IA-5(1)(a);(c) Transmit passwords only over cryptographically-protected channels;(d) Store passwords using an approved salted key derivation function, preferably using a keyed hash;(e) Require immediate selection of a new password upon account recovery;(f) Allow user selection of long passwords and passphrases, including spaces and all printable characters;(g) Employ automated tools to assist the user in selecting strong password authenticators; and(h) Enforce the following composition and complexity rules: [Assignment: organization-defined composition and complexity rules].', N'<p><strong>WMATA Policy</strong></p><p>For password-based authentication:</p><p>(1) Maintain a Prohibited Password List (PPL) based on commonly-used, expected, or compromised passwords and update the list monthly;</p><p>(2) When a password identified on the PPL is in use at WMATA or the password is identified as compromised, change immediately, but no later than:</p><p>(a) 30 minutes for High categorized systems, high-risk individuals and privileged accounts;</p><p>(b) 60 minutes for systems categorized as Moderate; and</p><p>(c) 24 hours for all other information systems and/or accounts. All passwords shall be changed immediately.</p><p>(3) Verify, when users create or update passwords, that the passwords are not found on the PPL;</p><p>(4) Transmit passwords only over cryptographically-protected channels;</p><p>(5) Store passwords using an DMCS-approved salted key derivation function,<br>preferably using a keyed hash;</p><p>(6) Require immediate selection of a new password upon account recovery;</p><p>(7) If systems are enabled for use of passphrases they shall be allowed with the following <br>requirements:</p><p>(a) Minimum password length is 16 characters;</p><p>(b) Maximum password age must be 90 days or less;</p><p>(c) Password history (reuse) must be configured for 24 passwords remembered; and</p><p>(d) Maximum number of three allowed unsuccessful logon attempts.</p><p>(8) Employ automated tools to assist the user in selecting strong password authenticators; and</p><p>(9) Enforce composition and complexity rules based on the following:</p><p>(a) Cannot contain significant portions of the user’s account name or full name;</p><p>(b) Minimum password length is 16 characters;</p><p>(c) Must contain characters from all of the following four categories:</p><p>(i) English uppercase character (A through Z);</p><p>(ii) English lowercase character (a through z);</p><p>(iii) Base 10 digit (0 through 9); and</p><p>(iv) Nonalphabetic character (for example, !, $, #, %).</p><p>(d) Maximum number of repeating characters of the same character class is limited to four;</p><p>(e) Maximum password age must be 90 days or less;</p><p>(f) Password history (reuse) must be configured for 24 passwords remembered; and</p><p>(g) Maximum number of three allowed unsuccessful login attempts.</p><p>Related Controls: IA-6</p>', N'Identification and Authentication', N'Authenticator Management', NULL, NULL, N'WMATA', NULL, NULL, NULL, 65, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37717, N'IA-5 (2)', N'(a) For public key-based authentication:     (1) Enforce authorized access to the corresponding private key; and     (2) Map the authenticated identity to the account of the individual or group; and(b) When public key infrastructure (PKI) is used:     (1) Validate certificates by constructing and verifying a certification path to an accepted trust anchor, including checking certificate status      information; and     (2) Implement a local cache of revocation data to support path discovery and validation.', N'<p><strong>WMATA Policy</strong></p><p>(1) For public key-based authentication:</p><p>(a) Enforce authorized access to the corresponding private key; and</p><p>(b) Map the authenticated identity to the account of the individual or group; and</p><p>(2) When a public key is used:</p><p>(a) Validate certificates by constructing and verifying a certification path to an accepted trust anchor, including checking certificate status information; and</p><p>(b) Implement a local cache of revocation data to support path discovery and<br>validation.</p><p>Related Controls: IA-3, SC-17</p>', N'Identification and Authentication', N'Authenticator Management', NULL, NULL, N'WMATA', NULL, NULL, NULL, 65, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37718, N'IA-5 (6)', N'Protect authenticators commensurate with the security category of the information to which use of the authenticator permits access.', N'<p><strong>WMATA Policy</strong></p><p>Protect authenticators commensurate with the security category of the information to which use of the authenticator permits.</p><p>Related Controls: RA-2</p>', N'Identification and Authentication', N'Authenticator Management', NULL, NULL, N'WMATA', NULL, NULL, NULL, 65, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37719, N'IA-6', N'Obscure feedback of authentication information during the authentication process to protect the information from possible exploitation and use by unauthorized individuals.', N'<p><strong>WMATA Policy</strong></p><p>Obscure feedback of authentication information during the authentication process to protect the information from possible exploitation and use by unauthorized individuals.</p><p>Related Controls: AC-3</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: This control assumes a visual interface that provides feedback about authentication information during the authentication process. When OT authentication uses an interface that does not support visual feedback (e.g., protocol-based authentication), this control may be tailored out.</p>', N'Identification and Authentication', N'Authentication Feedback', NULL, NULL, N'WMATA', NULL, NULL, NULL, 65, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37720, N'IA-7', N'Implement mechanisms for authentication to a cryptographic module that meet the requirements of applicable laws, executive orders, directives, policies, regulations, standards, and guidelines for such authentication.', N'<p><strong>WMATA Policy</strong></p><p>Implement mechanisms for authentication to a cryptographic module that meet the requirements of applicable laws, directives, policies, regulations, standards, and guidelines for such authentication.</p><p>Related Controls: AC-3, IA-5, SA-4, SC-12, SC-13</p>', N'Identification and Authentication', N'Cryptographic Module Authentication', NULL, NULL, N'WMATA', NULL, NULL, NULL, 65, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37721, N'IA-8', N'Uniquely identify and authenticate non-organizational users or processes acting on behalf of non-organizational users.', N'<p><strong>WMATA Policy</strong></p><p>Access to WMATA systems shall be limited to users with credentials issued by WMATA.</p><p>Related Controls: AC-2, AC-6, AC-14, AC-17, AC-18, AU-6, IA-2, IA-4, IA-5, IA-11, MA-4, RA-3, SA-4, SC-8</p><p>a.  Security Controls Enhancement(s):</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: The OT Discussion for IA-2, Identification and Authentication (Organizational Users) is applicable for non-organizational users. </p>', N'Identification and Authentication', N'Identification and Authentication (non-organizational Users)', NULL, NULL, N'WMATA', NULL, NULL, NULL, 65, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37722, N'IA-8 (1)', N'<p><b>Identification and Authentication (non-organizational Users) | Acceptance of PIV Credentials from Other Agencies</b></p>Accept and electronically verify Personal Identity Verification-compliant credentials from other federal agencies.', N'<p><strong>WMATA Policy</strong></p><p>Accept and electronically verify Personal Identity Verification-compliant credentials from other federal agencies. </p><p><strong><u>OT Systems Only:</strong></u> Acceptance of PIV credentials is only required for organizations that follow OMB Memorandum M-19-17 [OMB-M1917] (e.g., federal agencies and contractors).</p><p>Related Controls: PE-3</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Acceptance of PIV credentials is only required for <br>organizations that follow OMB Memorandum M-19-17 [OMB-M1917] (e.g., federal agencies and contractors).</p>', N'Identification and Authentication', N'Identification and Authentication (non-organizational Users)', NULL, NULL, N'WMATA', NULL, NULL, NULL, 65, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37723, N'IA-8 (2)', N'<p><b>Identification and Authentication (non-organizational Users) | Acceptance of External Authenticators</b></p>(a) Accept only external authenticators that are NIST-compliant; and(b) Document and maintain a list of accepted external authenticators.', N'<p><strong>WMATA Policy</strong></p><p>(1)  Accept only external authenticators that are NIST-compliant; and<br>(2)  Document and maintain a list of accepted external authenticators. </p><p><strong><u>OT Systems Only: </strong></u>Example compensating controls include implementing support external to the OT and multi-factor authentication.</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Example compensating controls include implementing support external to the OT and multi-factor authentication.</p>', N'Identification and Authentication', N'Identification and Authentication (non-organizational Users)', NULL, NULL, N'WMATA', NULL, NULL, NULL, 65, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37724, N'IA-8 (4)', N'<p><b>Identification and Authentication (non-organizational Users) | Use of Defined Profiles</b></p>Conform to the following profiles for identity management [Assignment: organization-defined identity management profiles].', N'<p><strong>WMATA Policy</strong></p><p>Conform to the following profiles for identity management [Assignment: organization-defined identity management profiles].</p><p><strong><u>OT Systems Only: </strong></u>Example compensating controls include implementing support external to the OT and multi-factor authentication.</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Example compensating controls include implementing support external to the OT and multi-factor authentication.<br></p>', N'Identification and Authentication', N'Identification and Authentication (non-organizational Users)', NULL, NULL, N'WMATA', NULL, NULL, NULL, 65, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37725, N'IR-1', N'a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:     1. [Selection (one or more): Organization-level; Mission/business process-level; System-level] incident response policy that:          (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and           compliance; and          (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and     2. Procedures to facilitate the implementation of the incident response policy and the associated incident response controls;b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the incident response policy and procedures; andc. Review and update the current incident response:     1. Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and     2. Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].', N'<p><strong>WMATA Policy</strong></p><p>Reference P/I 15.28 Cybersecurity Policy for requirements.</p><p>Related Controls: PM-9, PS-8, SI-12</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: The policy specifically addresses the unique properties and requirements of OT and the relationship to non-OT systems.</p>', N'Incident Response', N'Cybersecurity Incident Response Policy and Procedures', NULL, NULL, N'WMATA', NULL, NULL, NULL, 17, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37726, N'IR-2', N'a. Provide incident response training to system users consistent with assigned roles and responsibilities:     1. Within [Assignment: organization-defined time period] of assuming an incident response role or responsibility or acquiring system access;     2. When required by system changes; and     3. [Assignment: organization-defined frequency] thereafter; andb. Review and update incident response training content [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].', N'<p><strong>WMATA Policy</strong></p><p>a. Incident response training shall be provided to designated system users consistent with their assigned roles and responsibilities:</p><p>i) Within 30 days of assuming an incident response role or responsibility or acquiring system access;</p><p>ii) When required by system changes; and</p><p>iii) Annually thereafter.</p><p>b. Review and update incident response training content annually and following substantial changes in WMATA incident response controls or Standard Operating Procedures (SOPs).</p><p>Related Controls: AT-2, AT-3, AT-4, CP-3, IR-3, IR-4, IR-8, IR-9</p><p>c. Security Controls Enhancement(s):</p>', N'Incident Response', N'Incident Response Training', NULL, NULL, N'WMATA', NULL, NULL, NULL, 17, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37727, N'IR-2 (1)', N'Incorporate simulated events into incident response training to facilitate the required response by personnel in crisis situations.', N'<p><strong>WMATA Policy</strong></p><p>Incorporate simulated events into incident response training to facilitate the required response by personnel in crisis situations.</p>', N'Incident Response', N'Incident Response Training', NULL, NULL, N'WMATA', NULL, NULL, NULL, 17, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37728, N'IR-2 (2)', N'Provide an incident response training environment using [Assignment: organization-defined automated mechanisms].', N'<p><strong>WMATA Policy</strong></p><p>Provide an incident response training environment using automated mechanisms which facilitate more thorough and realistic incident response training, more coverage of incident response issues, more realistic training scenarios and environments, and which stress the response capability.</p>', N'Incident Response', N'Incident Response Training', NULL, NULL, N'WMATA', NULL, NULL, NULL, 17, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37729, N'IR-2 (3)', N'Provide incident response training on how to identify and respond to a breach, including the organization’s process for reporting a breach.', N'<p><strong>WMATA Policy</strong></p><p>Provide incident response training on how to identify and respond to a breach, including the organization’s process for reporting a breach.</p>', N'Incident Response', N'Incident Response Training', NULL, NULL, N'WMATA', NULL, NULL, NULL, 17, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37730, N'IR-3', N'Test the effectiveness of the incident response capability for the system [Assignment: organization-defined frequency] using the following tests: [Assignment: organization-defined tests].', N'<p><strong>WMATA Policy</strong></p><p>a. Test the effectiveness of the incident response capability on a monthly basis using standardization and evaluation quizzes and incident response drills, and on a quarterly basis using tabletop or full-scale exercises.</p><p>Related Controls: CP-3, CP-4, IR-2, IR-4, IR-8, PM-14</p><p>b. Security Controls Enhancement(s):</p>', N'Incident Response', N'Incident Response Testing', NULL, NULL, N'WMATA', NULL, NULL, NULL, 17, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37731, N'IR-3 (2)', N'Coordinate incident response testing with organizational elements responsible for related plans.', N'<p><strong>WMATA Policy</strong></p><p>Coordinate incident response testing with organizational elements responsible for related plans.</p>', N'Incident Response', N'Incident Response Testing', NULL, NULL, N'WMATA', NULL, NULL, NULL, 17, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37732, N'IR-4', N'a. Implement an incident handling capability for incidents that is consistent with the incident response plan and includes preparation, detection and analysis, containment, eradication, and recovery;b. Coordinate incident handling activities with contingency planning activities;c. Incorporate lessons learned from ongoing incident handling activities into incident response procedures, training, and testing, and implement the resulting changes accordingly; andd. Ensure the rigor, intensity, scope, and results of incident handling activities are comparable and predictable across the organization.', N'<p><strong>WMATA Policy</strong></p><p>a. Implement an incident handling capability for incidents that is consistent with the incident response plan and includes preparation, detection and analysis, containment, eradication, and recovery;</p><p>b. Support incident response at the system level as dictated by the nature of the incident;</p><p>c. Coordinate incident handling activities with contingency planning activities;</p><p>d. Incorporate lessons learned from ongoing incident handling activities into incident response procedures, training, and testing, and implement the resulting changes accordingly; and</p><p>e. Ensure the rigor, intensity, scope, and results of incident handling activities are comparable and predictable across the organization.</p><p><strong><u>OT Systems Only: </strong></u>As part of the incident handling capability, the organization coordinates with external vendors, integrators, or suppliers as necessary to ensure they have the capability to address events specific to embedded components and devices. </p><p>Related Controls: AC-19, AU-6, AU-7, CM-6, CP-2, CP-3, CP-4, IR-2, IR-3, IR-5, IR-6, IR-8, PE-6, PL-2, PM-12, SA-8, SC-5, SC-7, SI-3, SI-4, SI-7</p><p>f. Security Controls Enhancement(s):</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: As part of the incident handling capability, the organization coordinates with external vendors, integrators, or suppliers as necessary to ensure that they have the capability to address events that are specific to embedded components and devices. </p>', N'Incident Response', N'Incident Handling', NULL, NULL, N'WMATA', NULL, NULL, NULL, 17, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37733, N'IR-4 (1)', N'Support the incident handling process using [Assignment: organization-defined automated mechanisms].', N'<p><strong>WMATA Policy</strong></p><p>Support the incident handling process using automated mechanisms that support incident handling processes, including online incident management systems and tools that support the collection of live response data, full network packet capture, and forensic analysis.</p>', N'Incident Response', N'Incident Handling', NULL, NULL, N'WMATA', NULL, NULL, NULL, 17, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37734, N'IR-4 (11)', N'Establish and maintain an integrated incident response team that can be deployed to any location identified by the organization in [Assignment: organization-defined time period].', N'<p><strong>WMATA Policy</strong></p><p>Establish and maintain an integrated incident response team that can be activated by the organization within one hour.</p><p>Related Controls: AT-3</p>', N'Incident Response', N'Incident Handling', NULL, NULL, N'WMATA', NULL, NULL, NULL, 17, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37735, N'IR-4 (4)', N'Correlate incident information and individual incident responses to achieve an organization-wide perspective on incident awareness and response.', N'<p><strong>WMATA Policy</strong></p><p>Correlate incident information and individual incident responses to achieve an organization-wide perspective on incident awareness and response.</p>', N'Incident Response', N'Incident Handling', NULL, NULL, N'WMATA', NULL, NULL, NULL, 17, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37736, N'IR-5', N'Track and document incidents.', N'<p><strong>WMATA Policy</strong></p><p>a. Track and document incidents.</p><p>Related Controls: AU-6, AU-7, IR-4, IR-6, IR-8, PE-6, PM-5, SC-5, SC-7, SI-3, SI-4, SI-7</p><p>b. Security Controls Enhancement(s):</p>', N'Incident Response', N'Incident Monitoring', NULL, NULL, N'WMATA', NULL, NULL, NULL, 17, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37737, N'IR-5 (1)', N'Track incidents and collect and analyze incident information using [Assignment: organization-defined automated mechanisms].', N'<p><strong>WMATA Policy</strong></p><p>Track incidents and collect and analyze incident information.</p>', N'Incident Response', N'Incident Monitoring', NULL, NULL, N'WMATA', NULL, NULL, NULL, 17, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37738, N'IR-6', N'a. Require personnel to report suspected incidents to the organizational incident response capability within [Assignment: organization-defined time period]; andb. Report incident information to [Assignment: organization-defined authorities].', N'<p><strong>WMATA Policy</strong></p><p>a. Require personnel to report suspected incidents to the organizational incident response capability immediately, but not to exceed 24 hours; and</p><p>b. Report incident information to the CISO via the Cyber Fusion Center’s (CFC) Security Operations Center (SOC).</p><p><strong><u>OT Systems Only:</strong></u> The organization should report incidents on a timely basis. CISA collaborates with international and private sector Computer Emergency Response Teams (CERTs) to share control systems-related security incidents and mitigation measures. </p><p>Related Controls: CM-6, CP-2, IR-4, IR-5, IR-8, IR-9</p><p>c. Security Controls Enhancement(s):</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: The organization should report incidents on a timely basis. CISA collaborates with international and private-sector computer emergency response teams (CERTs) to share control systems-related security incidents and mitigation measures.<br></p>', N'Incident Response', N'Incident Reporting', NULL, NULL, N'WMATA', NULL, NULL, NULL, 17, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37739, N'IR-6 (1)', N'<p><b>Incident Reporting | Automated Reporting</b></p>Report incidents using [Assignment: organization-defined automated mechanisms].', N'<p><strong>WMATA Policy</strong></p><p>Report incidents using the designated Security Orchestration, Automation and Response (SOAR).</p><p><strong><u>OT Systems Only:</strong></u> The automated mechanisms used to support the incident reporting process are not necessarily part of, or connected to, the OT. </p><p>Related Controls: IR-7</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: The automated mechanisms used to support the incident reporting process are not necessarily part of or connected to the OT.</p>', N'Incident Response', N'Incident Reporting', NULL, NULL, N'WMATA', NULL, NULL, NULL, 17, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37740, N'IR-6 (3)', N'Provide incident information to the provider of the product or service and other organizations involved in the supply chain or supply chain governance for systems or system components related to the incident.', N'<p><strong>WMATA Policy</strong></p><p>Provide incident information to the provider of the product or service and other organizations involved in the supply chain or supply chain governance for systems or system components related to the incident.</p><p>Related Controls: SR-8<br></p>', N'Incident Response', N'Incident Reporting', NULL, NULL, N'WMATA', NULL, NULL, NULL, 17, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37741, N'IR-7', N'Provide an incident response support resource, integral to the organizational incident response capability, that offers advice and assistance to users of the system for the handling and reporting of incidents.', N'<p><strong>WMATA Policy</strong></p><p>a. Provide an incident response support resource, integral to the organizational incident response capability, that offers advice and assistance to users of the system for the handling and reporting of incidents.</p><p>Related Controls: AT-2, AT-3, IR-4, IR-6, IR-8, PM-22, PM-26, SA-9, SI-18</p><p>b. Security Controls Enhancement(s):</p>', N'Incident Response', N'Incident Response Assistance', NULL, NULL, N'WMATA', NULL, NULL, NULL, 17, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37742, N'IR-7 (1)', N'Increase the availability of incident response information and support using [Assignment: organization-defined automated mechanisms].', N'<p><strong>WMATA Policy</strong></p><p>Increase the availability of incident response information and support using automated mechanisms which provide a push or pull capability for users to obtain incident response assistance (e.g., access to a website to query the assistance capability, the assistance capability to proactively send incident response information to users as part of increasing understanding of current response capabilities and support, etc.).</p>', N'Incident Response', N'Incident Response Assistance', NULL, NULL, N'WMATA', NULL, NULL, NULL, 17, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37743, N'IR-8', N'a. Develop an incident response plan that:     1. Provides the organization with a roadmap for implementing its incident response capability;     2. Describes the structure and organization of the incident response capability;     3. Provides a high-level approach for how the incident response capability fits into the overall organization;     4. Meets the unique requirements of the organization, which relate to mission, size, structure, and functions;     5. Defines reportable incidents;     6. Provides metrics for measuring the incident response capability within the organization;     7. Defines the resources and management support needed to effectively maintain and mature an incident response capability;     8. Addresses the sharing of incident information;     9. Is reviewed and approved by [Assignment: organization-defined personnel or roles] [Assignment: organization-defined frequency]; and    10. Explicitly designates responsibility for incident response to [Assignment: organization-defined entities, personnel, or roles].b. Distribute copies of the incident response plan to [Assignment: organization-defined incident response personnel (identified by name and/or by role) and organizational elements];c. Update the incident response plan to address system and organizational changes or problems encountered during plan implementation, execution, or testing;d. Communicate incident response plan changes to [Assignment: organization-defined incident response personnel (identified by name and/or by role) and organizational elements]; ande. Protect the incident response plan from unauthorized disclosure and modification.', N'<p><strong>WMATA Policy</strong></p><p>a. Develop an incident response plan that:</p><p>i) Provides the organization with a roadmap for implementing its incident response capability;</p><p>ii) Describes the structure and organization of the incident response capability;</p><p>iii) Provides a high-level approach for how the incident response capability fits into the overall organization;</p><p>iv) Meets the unique requirements of the organization, which relate to mission, size, structure, and functions;</p><p>v) Defines reportable incidents;</p><p>vi) Provides metrics for measuring the incident response capability within the organization;</p><p>vii) Defines the resources and management support needed to effectively maintain and mature an incident response capability;</p><p>viii) Addresses the sharing of incident information;</p><p>ix) Is reviewed and approved by the CISO or CISO’s designated representative annually; and</p><p>x) Explicitly designates responsibility for incident response to the Cyber Fusion Officer (CFO).</p><p>b. Create a Cybersecurity Incident Response Team (CIRT) charter which identifies the roles and responsibilities of members of the CIRT;</p><p>c. Distribute copies of the incident response plan to all members of the CFC and the CIRT;</p><p>d. Update the incident response plan to address system and organizational changes or problems encountered during plan implementation, execution, or testing;</p><p>e. Communicate incident response plan changes to all members of the CFC and the CIRT;</p><p>f. Protect the incident response plan from unauthorized disclosure and modification;</p><p>g. Identify personnel associated with incident response activities at the system level within the corresponding SSP addendum and at the CIRT (organizational) level within the CIRT charter addendum;</p><p>h. Notify DMCS within seven calendar days of the appointment of an individual to a qualifying incident response capacity; and</p><p>i. Certify personnel associated with incident response annually.</p><p>Related Controls: AC-2, CP-2, CP-4, IR-4, IR-7, IR-9, PE-6, PL-2, SA-15, SI-12, SR-8</p><p>j. Security Controls Enhancement(s):</p>', N'Incident Response', N'Incident Response Plan', NULL, NULL, N'WMATA', NULL, NULL, NULL, 17, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37744, N'IR-8 (1)', N'Include the following in the Incident Response Plan for breaches involving personally identifiable information:(a) A process to determine if notice to individuals or other organizations, including oversight organizations, is needed;(b) An assessment process to determine the extent of the harm, embarrassment, inconvenience, or unfairness to affected individuals and any mechanisms to mitigate such harms; and(c) Identification of applicable privacy requirements.', N'<p><strong>WMATA Policy</strong></p><p>(1) Include the following in the Incident Response Plan for breaches involving sensitive information:</p><p>(a) A process to determine if notice to individuals or other organizations, including oversight organizations, is needed;</p><p>(b) An assessment process to determine the extent of the harm, embarrassment, inconvenience, or unfairness to affected individuals and any mechanisms to mitigate such harms; and</p><p>(c) Identification of applicable privacy requirements.</p><p>Related Controls: PT-1, PT-2, PT-3, PT-4, PT-5, PT-7</p>', N'Incident Response', N'Incident Response Plan', NULL, NULL, N'WMATA', NULL, NULL, NULL, 17, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37745, N'IR-9', N'Respond to information spills by:a. Assigning [Assignment: organization-defined personnel or roles] with responsibility for responding to information spills;b. Identifying the specific information involved in the system contamination;c. Alerting [Assignment: organization-defined personnel or roles] of the information spill using a method of communication not associated with the spill;d. Isolating the contaminated system or system component;e. Eradicating the information from the contaminated system or component;f. Identifying other systems or system components that may have been subsequently contaminated; andg. Performing the following additional actions: [Assignment: organization-defined actions].', N'<p><strong>WMATA Policy</strong></p><p>a. Assigning CFC with responsibility for responding to information spills;</p><p>b. Identifying the specific information involved in the system contamination;</p><p>c. Alerting CIRT of the information spill using a method of communication not associated with the spill;</p><p>d. Isolating the contaminated system or system component;</p><p>e. Eradicating the information from the contaminated system or component;</p><p>f. Identifying other systems or system components that may have been subsequently contaminated; and</p><p>g. Performing the following additional actions:</p><p>i. Notification to the Cyber Fusion Officer (CFO) to notify any third parties to include cyber insurers and federal, state, and local authorities to initiate recovery or remediation efforts. <br>ii. Review and update incident response plans and procedures, and relevant SOPs and work instructions. <br>iii. Ensure that all users/handlers are in compliance with AT-2 and AT-3.<br>	<br>Related Controls: CP-2, IR-6, PM-26, PM-27, PT-2, PT-3, PT-7, RA-7</p><p>h. Security Controls Enhancement(s):</p>', N'Incident Response', N'Information Spillage Response', NULL, NULL, N'WMATA', NULL, NULL, NULL, 17, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37746, N'IR-9 (2)', N'Provide information spillage response training [Assignment: organization-defined frequency].', N'<p><strong>WMATA Policy</strong></p><p>Provide information spillage response training annually.</p><p>Related Controls: AT-2, AT-3, CP-3, IR-2</p>', N'Incident Response', N'Information Spillage Response', NULL, NULL, N'WMATA', NULL, NULL, NULL, 17, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37747, N'IR-9 (3)', N'Implement the following procedures to ensure that organizational personnel impacted by information spills can continue to carry out assigned tasks while contaminated systems are undergoing corrective actions: [Assignment: organization-defined procedures].', N'<p><strong>WMATA Policy</strong></p><p>The CFC shall develop procedures to ensure that organizational personnel impacted by information spills can continue to carry out assigned tasks while contaminated systems are undergoing corrective actions.</p>', N'Incident Response', N'Information Spillage Response', NULL, NULL, N'WMATA', NULL, NULL, NULL, 17, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37748, N'IR-9 (4)', N'Employ the following controls for personnel exposed to information not within assigned access authorizations: [Assignment: organization-defined controls].', N'<p><strong>WMATA Policy</strong></p><p>The CFC will make persons exposed to information to which they have not been authorized aware of any restrictions imposed by applicable law, regulation or other requirement based on exposure to such information. In addition, the CFC shall facilitate the notification to organizations and entities whose information has been compromised in accordance with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines.</p>', N'Incident Response', N'Information Spillage Response', NULL, NULL, N'WMATA', NULL, NULL, NULL, 17, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37749, N'MA-1', N'Control:a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:     1. [Selection (one or more): Organization-level; Mission/business process-level; System-level] maintenance policy that:          (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and           compliance; and          (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and     2. Procedures to facilitate the implementation of the maintenance policy and the associated maintenance controls;b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the maintenance policy and procedures; andc. Review and update the current maintenance:     1. Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and     2. Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].', N'<p><strong>WMATA Policy</strong></p><p>Reference P/I 15.28 Cybersecurity Policy for requirements.</p><p>Related Controls: PM-9, PS-8, SI-12</p><p><br><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: The policy specifically addresses the unique properties and requirements of OT and the relationship to non-OT systems. <br></p>', N'Maintenance', N'Maintenance Policy and Procedures', NULL, NULL, N'WMATA', NULL, NULL, NULL, 22, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37750, N'MA-2', N'a. Schedule, document, and review records of maintenance, repair, and replacement on system components in accordance with manufacturer or vendor specifications and/or organizational requirements;b. Approve and monitor all maintenance activities, whether performed on site or remotely and whether the system or system components are serviced on site or removed to another location;c. Require that [Assignment: organization-defined personnel or roles] explicitly approve the removal of the system or system components from organizational facilities for off-site maintenance, repair, or replacement;d. Sanitize equipment to remove the following information from associated media prior to removal from organizational facilities for off-site maintenance, repair, or replacement: [Assignment: organization-defined information];e. Check all potentially impacted controls to verify that the controls are still functioning properly following maintenance, repair, or replacement actions; andf. Include the following information in organizational maintenance records: [Assignment: organization-defined information].', N'<p><strong>WMATA Policy</strong></p><p>a. Schedule, document, and review records of maintenance, repair, and replacement of system components in accordance with manufacturer or vendor specifications and/or organizational requirements;</p><p>b.  Approve and monitor all maintenance activities, whether performed on-site or remotely and whether the system or system components are serviced on site or removed to another location;</p><p>c.  Require that System Owners or the CDO initiate the approval process for the removal of the system or system components from organizational facilities for off-site maintenance, repair, or replacement;</p><p>d. Require that the CDO explicitly approve the removal of the system or system components from organizational facilities for off-site maintenance, repair, or replacement;</p><p>e. Sanitize equipment in accordance with Control 3.12 Media Protection to remove information from associated media prior to removal from organizational facilities for off-site maintenance, repair, or replacement;</p><p>f.  Check all potentially impacted controls to verify that the controls are still functioning <br>properly following maintenance, repair, or replacement actions; and</p><p>g.  Include the following information in organizational maintenance records: date and time of maintenance, a description of the maintenance performed, full names and organization of individuals or groups performing the maintenance, name of the authorized escort, and system components with associated barcode or other identifier or equipment that are removed or replaced.</p><p>Related Controls: CM-2, CM-3, CM-4, CM-5, CM-8, MA-4, MP-6, PE-16, SI-2, SR-3, SR-4, SR-11</p><p>h. Security Controls Enhancement(s):</p>', N'Maintenance', N'Controlled Maintenance', NULL, NULL, N'WMATA', NULL, NULL, NULL, 22, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37751, N'MA-2 (2)', N'(a) Schedule, conduct, and document maintenance, repair, and replacement actions for the system using [Assignment: organization-defined automated mechanisms]; and(b) Produce up-to date, accurate, and complete records of all maintenance, repair, and replacement actions requested, scheduled, in process, and completed.', N'<p><strong>WMATA Policy</strong></p><p>(1) Schedule and document maintenance, repair, and replacement actions for the system using an enterprise configuration management database (CMDB);</p><p>(2) Conduct maintenance, repair, and replacement actions for the system using automated mechanisms whenever possible; and</p><p>(3) Produce up-to date, accurate, and complete records of all maintenance, repair, and<br>replacement actions requested, scheduled, in process, and completed.</p><p>Related Controls: MA-3</p>', N'Maintenance', N'Controlled Maintenance', NULL, NULL, N'WMATA', NULL, NULL, NULL, 22, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37752, N'MA-3', N'a. Approve, control, and monitor the use of system maintenance tools; andb. Review previously approved system maintenance tools [Assignment: organization-defined frequency].', N'<p><strong>WMATA Policy</strong></p><p>a. Approve, control, and monitor the use of system maintenance tools; and</p><p>b. Review previously approved system maintenance tools on a continual basis.</p><p>Related Controls: MA-2, PE-16</p><p>c. Security Controls Enhancement(s):</p>', N'Maintenance', N'Maintenance Tools', NULL, NULL, N'WMATA', NULL, NULL, NULL, 22, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37753, N'MA-3 (1)', N'Inspect the maintenance tools used by maintenance personnel for improper or unauthorized modifications.', N'<p><strong>WMATA Policy</strong></p><p>Inspect the maintenance tools used by maintenance personnel for improper or unauthorized modifications.</p><p>Related Controls: SI-7</p>', N'Maintenance', N'Maintenance Tools', NULL, NULL, N'WMATA', NULL, NULL, NULL, 22, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37754, N'MA-3 (2)', N'Check media containing diagnostic and test programs for malicious code before the media are used in the system.', N'<p><strong>WMATA Policy</strong></p><p>Check media containing diagnostic and test programs for malicious code before the media are used in the system.</p><p>Related Controls: SI-3</p>', N'Maintenance', N'Maintenance Tools', NULL, NULL, N'WMATA', NULL, NULL, NULL, 22, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37755, N'MA-3 (3)', N'Prevent the removal of maintenance equipment containing organizational information by:(a) Verifying that there is no organizational information contained on the equipment;(b) Sanitizing or destroying the equipment;(c) Retaining the equipment within the facility; or(d) Obtaining an exemption from [Assignment: organization-defined personnel or roles] explicitly authorizing removal of the equipment from the facility.', N'<p><strong>WMATA Policy</strong></p><p>Prevent the removal of maintenance equipment containing organizational information<br>by:</p><p>(1) Verifying that there is no organizational information contained on the equipment;</p><p>(2) Sanitizing or destroying the equipment in accordance with Control 3.12 Media Protection;</p><p>(3) Retaining the equipment within the facility; or</p><p>(4) Obtaining an exemption from the CDO explicitly authorizing removal of the<br>equipment from the facility.</p><p>Related Controls: MP-6</p>', N'Maintenance', N'Maintenance Tools', NULL, NULL, N'WMATA', NULL, NULL, NULL, 22, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37756, N'MA-3 (6)', N'Inspect maintenance tools to ensure the latest software updates and patches are installed.', N'<p><strong>WMATA Policy</strong></p><p>Inspect maintenance tools to ensure the latest software updates and patches are installed.</p><p>Related Controls: AC-3, AC-6</p>', N'Maintenance', N'Maintenance Tools', NULL, NULL, N'WMATA', NULL, NULL, NULL, 22, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37757, N'MA-4', N'a. Approve and monitor nonlocal maintenance and diagnostic activities;b. Allow the use of nonlocal maintenance and diagnostic tools only as consistent with organizational policy and documented in the security plan for the system;c. Employ strong authentication in the establishment of nonlocal maintenance and diagnostic sessions;d. Maintain records for nonlocal maintenance and diagnostic activities; ande. Terminate session and network connections when nonlocal maintenance is completed.', N'<p><strong>WMATA Policy</strong></p><p>a. Approve and monitor nonlocal maintenance and diagnostic activities;</p><p>b.  Allow the use of nonlocal maintenance and diagnostic tools only as consistent with <br>organizational policy and documented in the security plan for the system;</p><p>c. Employ strong authentication in the establishment of nonlocal maintenance and diagnostic sessions;</p><p>d. Maintain records for nonlocal maintenance and diagnostic activities; and</p><p>e. Terminate session and network connections when nonlocal maintenance is completed.</p><p>Related Controls: AC-2, AC-3, AC-6, AC-17, AU-2, AU-3, IA-2, IA-4, IA-5, IA-8, MA-2, MA-5, PL-2, SC-7, SC-10</p><p>f.  Security Controls Enhancement(s):</p><p></p>', N'Maintenance', N'Nonlocal Maintenance', NULL, NULL, N'WMATA', NULL, NULL, NULL, 22, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37758, N'MA-4 (1)', N'<p><b>Nonlocal Maintenance | Logging and Review</b></p>(a) Log [Assignment: organization-defined audit events] for nonlocal maintenance and diagnostic sessions; and(b) Review the audit records of the maintenance and diagnostic sessions to detect anomalous behavior.', N'<p><strong>WMATA Policy</strong></p><p>(1)  Log [Assignment: organization-defined audit events] for nonlocal maintenance and diagnostic sessions; and</p><p>(2)  Review the audit records of the maintenance and diagnostic sessions to detect anomalous behavior.</p><p>Related Controls: AU-6, AU-12</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>Rationale for adding MA-4 (1) to MOD and HIGH baselines: OT environments are often heavily dependent on nonlocal maintenance providers, so organizations should have the ability to review logs about relevant maintenance activities. </p>', N'Maintenance', N'Nonlocal Maintenance', NULL, NULL, N'WMATA', NULL, NULL, NULL, 22, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37759, N'MA-4 (3)', N'<p><b>Nonlocal Maintenance | Comparable Security and Sanitization</b></p>(a) Require that nonlocal maintenance and diagnostic services be performed from a system that implements a security capability comparable to the capability implemented on the system being serviced; or(b) Remove the component to be serviced from the system prior to nonlocal maintenance or diagnostic services; sanitize the component (for organizational information); and after the service is performed, inspect and sanitize the component (for potentially malicious software) before reconnecting the component to the system.', N'<p><strong>WMATA Policy</strong></p><p>(1) Require that nonlocal maintenance and diagnostic services be performed from a system that implements a security capability comparable to the capability implemented on the system being serviced; or</p><p>(2) Remove the component to be serviced from the system prior to nonlocal maintenance or diagnostic services; sanitize the component (for organizational information); and after the service is performed, inspect, and sanitize the component (for potentially malicious software) before reconnecting the component to the system.</p><p><strong><u>OT Systems Only: </strong></u>The organization may need access to nonlocal maintenance and diagnostic services in order to restore essential OT operations or services. Example compensating controls include limiting the extent of the maintenance and diagnostic services to the minimum essential activities, and carefully monitoring and auditing the non-local maintenance and diagnostic activities. </p><p>Related Controls: MP-6, SI-3, SI-7</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: The organization may need access to nonlocal maintenance and diagnostic services in order to restore essential OT operations or services. Example compensating controls include limiting the extent of the maintenance and diagnostic services to the minimum essential activities and carefully monitoring and auditing the nonlocal maintenance and diagnostic activities. </p>', N'Maintenance', N'Nonlocal Maintenance', NULL, NULL, N'WMATA', NULL, NULL, NULL, 22, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37760, N'MA-5', N'a. Establish a process for maintenance personnel authorization and maintain a list of authorized maintenance organizations or personnel;b. Verify that non-escorted personnel performing maintenance on the system possess the required access authorizations; andc. Designate organizational personnel with required access authorizations and technical competence to supervise the maintenance activities of personnel who do not possess the required access authorizations.', N'<p><strong>WMATA Policy</strong></p><p>a.  Establish a process for maintenance personnel authorization and maintain a list of authorized maintenance organizations or personnel;</p><p>b. Verify that non-escorted personnel performing maintenance on the system possess the required access authorizations; and</p><p>c.  Designate organizational personnel with required access authorizations and technical competence to supervise the maintenance activities of personnel who do not possess the required access authorizations.</p><p>Related Controls: AC-2, AC-3, AC-5, AC-6, IA-2, IA-8, MA-4, MP-2, PE-2, PE-3, PS-7, RA-3</p><p>d. Security Controls Enhancement(s):</p>', N'Maintenance', N'Maintenance Personnel', NULL, NULL, N'WMATA', NULL, NULL, NULL, 22, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37761, N'MA-5 (1)', N'(a) Implement procedures for the use of maintenance personnel that lack appropriate security clearances or are not U.S. citizens, that include the following requirements:     (1) Maintenance personnel who do not have needed access authorizations, clearances, or formal access approvals are escorted and      supervised during the performance of maintenance and diagnostic activities on the system by approved organizational personnel who are fully      cleared, have appropriate access authorizations, and are technically qualified; and     (2) Prior to initiating maintenance or diagnostic activities by personnel who do not have needed access authorizations, clearances or formal      access approvals, all volatile information storage components within the system are sanitized and all nonvolatile storage media are removed or      physically disconnected from the system and secured; and(b) Develop and implement [Assignment: organization-defined alternate controls] in the event a system component cannot be sanitized, removed, or disconnected from the system.', N'<p><strong>WMATA Policy</strong></p><p>(1) Implement procedures for the use of maintenance personnel that lack appropriate security clearances or are not U.S. citizens, that include the following requirements:</p><p>(a) Maintenance personnel who do not have needed access authorizations, clearances, or formal access approvals are escorted and supervised during the performance of maintenance and diagnostic activities on the system by approved organizational personnel who are fully cleared, have appropriate access authorizations, and are technically qualified; and</p><p>(b) Personnel who do not have needed access authorizations, clearances or formal access approvals shall not be permitted to initiate maintenance or diagnostic activities on the system. All exceptions shall be authorized by the Authorizing Official (AO); and</p><p>(2) Develop, document, and receive approval from the AO for any alternate controls to be <br>implemented or used in the event a system component cannot be sanitized, removed, or disconnected from the system.</p><p>Related Controls: MP-6, PL-2</p>', N'Maintenance', N'Maintenance Personnel', NULL, NULL, N'WMATA', NULL, NULL, NULL, 22, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37762, N'MA-6', N'Obtain maintenance support and/or spare parts for [Assignment: organization-defined system components] within [Assignment: organization-defined time period] of failure.', N'<p><strong>WMATA Policy</strong></p><p>Obtain maintenance support and/or spare parts and perform or complete maintenance activities for critical system components within the maximum tolerable downtime (MTD) specified for a system.</p><p>Related Controls: CM-8, CP-2, CP-7, RA-7, SA-15, SI-13, SR-2, SR-3, SR-4</p>', N'Maintenance', N'Timely Maintenance', NULL, NULL, N'WMATA', NULL, NULL, NULL, 22, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37763, N'MP-1', N'Control:a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:     1. [Selection (one or more): Organization-level; Mission/business process-level; System-level] media protection policy that:          (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and           compliance; and          (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and     2. Procedures to facilitate the implementation of the media protection policy and the associated media protection controls;b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the media protection policy and procedures; andc. Review and update the current media protection:     1. Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and     2. Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].', N'<p><strong>WMATA Policy</strong></p><p>Reference P/I 15.28 Cybersecurity Policy for requirements.</p><p>Related Controls: PM-9, PS-8, SI-12</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: The policy specifically addresses the unique properties and requirements of OT and the relationship to non-OT systems.</p>', N'Media Protection', N'Media Protection Policy and Procedures', NULL, NULL, N'WMATA', NULL, NULL, NULL, 66, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37764, N'MP-2', N'Restrict access to [Assignment: organization-defined types of digital and/or non-digital media] to [Assignment: organization-defined personnel or roles].', N'<p><strong>WMATA Policy</strong></p><p>Restrict access to digital and non-digital media to authorized personnel with media protection responsibilities.</p>', N'Media Protection', N'Media Access', NULL, NULL, N'WMATA', NULL, NULL, NULL, 66, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37765, N'MP-3', N'a. Mark system media indicating the distribution limitations, handling caveats, and applicable security markings (if any) of the information; andb. Exempt [Assignment: organization-defined types of system media] from marking if the media remain within [Assignment: organization-defined controlled areas].', N'<p><strong>WMATA Policy</strong></p><p>a. Mark system media indicating the distribution limitations, handling caveats, and applicable security markings (if any) of the information;</p><p>b. Media that stores information deemed to be in the public domain (or to be publicly releasable) shall be exempt from media marking requirements only if approved by the AO; and</p><p>c. All other digital and non-digital media shall be subject to media marking requirements.</p><p>Related Controls: AC-19, AU-9, CP-2, CP-9, CP-10, MA-5, MP-4, MP-6, PE-2, PE-3, SC-12, SC-13, SI-12</p>', N'Media Protection', N'Media Marking', NULL, NULL, N'WMATA', NULL, NULL, NULL, 66, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37766, N'MP-4', N'a. Physically control and securely store [Assignment: organization-defined types of digital and/or non-digital media] within [Assignment: organization-defined controlled areas]; andb. Protect system media types defined in MP-4a until the media are destroyed or sanitized using approved equipment, techniques, and procedures.', N'<p><strong>WMATA Policy</strong></p><p>a. Digital and non-digital media shall be physically controlled and securely stored within authorized locked cabinets or safes in secure/controlled facilities; and</p><p>b. Protect system media types until the media are destroyed or sanitized using approved equipment, techniques, and procedures.</p><p>Related Controls: AC-19, CP-2, CP-6, CP-9, CP-10, MP-2, MP-7, PE-3, PL-2, SC-12, SC-13, SC-28, SI-12</p>', N'Media Protection', N'Media Storage', NULL, NULL, N'WMATA', NULL, NULL, NULL, 66, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37767, N'MP-5', N'a. Protect and control [Assignment: organization-defined types of system media] during transport outside of controlled areas using [Assignment: organization-defined controls];b. Maintain accountability for system media during transport outside of controlled areas;c. Document activities associated with the transport of system media; andd. Restrict the activities associated with the transport of system media to authorized personnel.', N'<p><strong>WMATA Policy</strong></p><p>a. Protect and control sensitive digital media during transport outside of WMATA facilities using a FIPS 140-2 certified encryption module;</p><p>b. Maintain accountability for sensitive system media during transport outside of controlled areas;</p><p>c. Document activities in accordance with Control 3.8 Data Sensitivity associated with the transport of sensitive system media; and</p><p>d. Restrict the activities as referenced in the Data Centers associated with the transport of sensitive system media to authorized personnel.</p><p>Related Controls: AC-7, AC-19, CP-2, CP-9, MP-3, MP-4, PE-16, PL-2, SC-12, SC-13, SC-28</p><p><strong>In addition to the above NIST controls, the following cybersecurity requirements further define WMATA policy:</p><p>Media Transport</strong><br>Employ the following controls when using WMATA media at alternate work sites:</p><p>a. Controls in accordance with P/I 7.4.3 Telework Policy and associated appendices.</p><p>b. Any personnel working outside of the United States shall use virtual infrastructures to access WMATA systems and/or networks.</p><p>i) No WMATA information shall be transported or stored on physical or virtual systems or devices that are not owned and controlled by WMATA.</p><p>ii) Specific exemptions shall be documented for submittal and approved in advance by the AO.</p>', N'Media Protection', N'Media Transport', NULL, NULL, N'WMATA', NULL, NULL, NULL, 66, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37768, N'MP-6', N'a. Sanitize [Assignment: organization-defined system media] prior to disposal, release out of organizational control, or release for reuse using [Assignment: organization-defined sanitization techniques and procedures]; andb. Employ sanitization mechanisms with the strength and integrity commensurate with the security category or classification of the information.', N'<p><strong>WMATA Policy</strong></p><p>a. Sanitize digital media including prior to disposal, release out of organizational control, or release for reuse in alignment with NIST requirements; and</p><p>b. Employ sanitization mechanisms with the strength and integrity commensurate with the sensitivity of the information.</p><p>Related Controls: AC-3, AC-7, AU-11, MA-2, MA-3, MA-4, MA-5, PM-22, SI-12, SI-18, SI-19, SR-11</p><p>c. Security Controls Enhancement(s):</p><p><strong>In addition to the above NIST controls, the following cybersecurity requirements further define WMATA policy:</strong></p><p>Destructive Techniques<br>For assets that are not sanitized, destructive techniques may be used to protect WMATA information.</p>', N'Media Protection', N'Media Sanitization', NULL, NULL, N'WMATA', NULL, NULL, NULL, 66, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37769, N'MP-6 (1)', N'Review, approve, track, document, and verify media sanitization and disposal actions.', N'<p><strong>WMATA Policy</strong></p><p>Review, approve, track, document, and verify media sanitization and disposal actions.</p>', N'Media Protection', N'Media Sanitization', NULL, NULL, N'WMATA', NULL, NULL, NULL, 66, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37770, N'MP-6 (2)', N'Test sanitization equipment and procedures [Assignment: organization-defined frequency] to ensure that the intended sanitization is being achieved.', N'<p><strong>WMATA Policy</strong></p><p>Test sanitization equipment and procedures annually to ensure that the intended sanitization is being achieved.</p>', N'Media Protection', N'Media Sanitization', NULL, NULL, N'WMATA', NULL, NULL, NULL, 66, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37771, N'MP-6 (3)', N'Apply nondestructive sanitization techniques to portable storage devices prior to connecting such devices to the system under the following circumstances: [Assignment: organization-defined circumstances requiring sanitization of portable storage devices].', N'<p><strong>WMATA Policy</strong></p><p>Apply nondestructive sanitization techniques to portable storage devices including internal and external hard disk drives (e.g., solid state, magnetic), optical discs, magnetic or optical tapes, flash memory devices, flash memory cards, and other external or removable disks prior to connecting such devices to the system.</p>', N'Media Protection', N'Media Sanitization', NULL, NULL, N'WMATA', NULL, NULL, NULL, 66, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37772, N'MA-7', N'"Restrict or prohibit field maintenance on [Assignment: organization-defined systems or system components] to [Assignment: organization-defined trusted maintenance facilities].

OT Systems Only: Organizations identify OT system/systems components with specific calibration, maintenance, or other requirements and limit maintenance to specific facilities. Some examples may include safety critical systems or systems involved in custody transfer where accuracy tolerances are limited and additional quality control checks are required. 
	
Related Controls: MA-2, MA-4, MA-5

NIST 800-82 Rev 3:
OT Discussion: Organizations identify OT systems and system components with specific calibration, maintenance, or other requirements and limit maintenance to specific facilities. Some examples may include safety-critical systems or systems involved in custody transfer where accuracy tolerances are limited and additional quality control checks are required.

Rationale for adding MA-7 to LOW, MOD, and HIGH baselines: Some OT equipment have specific requirements for calibration, maintenance, and modification to meet regulatory or safety standards. Different deployed locations may impact the quality and precision of field maintenance. "
', N'<p><strong>WMATA Policy</strong></p><p>Restrict or prohibit field maintenance on [Assignment: organization-defined systems or system components] to [Assignment: organization-defined trusted maintenance facilities].</p><p><strong><u>OT Systems Only:</strong></u> Organizations identify OT system/systems components with specific calibration, maintenance, or other requirements and limit maintenance to specific facilities. Some examples may include safety critical systems or systems involved in custody transfer where accuracy tolerances are limited and additional quality control checks are required. <br>	<br>Related Controls: MA-2, MA-4, MA-5</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Organizations identify OT systems and system components with specific calibration, maintenance, or other requirements and limit maintenance to specific facilities. Some examples may include safety-critical systems or systems involved in custody transfer where accuracy tolerances are limited and additional quality control checks are required.</p><p>Rationale for adding MA-7 to LOW, MOD, and HIGH baselines: Some OT equipment have specific requirements for calibration, maintenance, and modification to meet regulatory or safety standards. Different deployed locations may impact the quality and precision of field maintenance. </p>', N'Maintenance', N'Field Maintenance', NULL, NULL, N'WMATA', NULL, NULL, NULL, 66, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37773, N'MP-7', N'a. [Selection: Restrict; Prohibit] the use of [Assignment: organization-defined types of system media] on [Assignment: organization-defined systems or system components] using [Assignment: organization-defined controls]; andb. Prohibit the use of portable storage devices in organizational systems when such devices have no identifiable owner.', N'<p><strong>WMATA Policy</strong></p><p>a. Restrict the use of disk drives, diskettes, internal and external hard drives, and portable devices, including backup media, removable media, and mobile devices on information systems or system components using security safeguards; and</p><p>b. Prohibit the use of non-WMATA-issued portable storage devices in organizational systems when such devices have no identifiable owner.</p><p>Related Controls: AC-19, AC-20, PL-4, PM-12, SC-41</p><p><strong>In addition to the above NIST controls, the following cybersecurity requirements further define WMATA policy:</strong></p><p><strong>Destructive Techniques</strong><br>For assets that are not sanitized, destructive techniques may be used to protect WMATA information.</p><p></p>', N'Media Protection', N'Media Use', NULL, NULL, N'WMATA', NULL, NULL, NULL, 66, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37774, N'PE-1', N'a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:     1. [Selection (one or more): Organization-level; Mission/business process-level; System-level] physical and environmental protection policy      that:          (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and           compliance; and          (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and     2. Procedures to facilitate the implementation of the physical and environmental protection policy and the associated physical and      environmental protection controls;b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the physical and environmental protection policy and procedures; andc. Review and update the current physical and environmental protection:     1. Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and     2. Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].', N'<p><strong>WMATA Policy</strong></p><p>Reference P/I 15.28 Cybersecurity Policy for requirements.</p><p><strong><u>OT Systems Only:</strong></u> The policy specifically addresses the unique properties and requirements of OT and the relationship to non-OT systems. The OT components can be distributed over a large facility footprint or geographic area and can be any entry point into the entire organizational network OT. Regulatory controls may also apply.</p><p>Related Controls: AT-3, PM-9, PS-8, SI-12</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: The policy specifically addresses the unique properties and requirements of OT and the relationship to non-OT systems. The OT components can be distributed over a large facility footprint or geographic area and can be an entry point into the entire organizational network OT. Regulatory controls may also apply. </p>', N'Physical and Environmental Protection', N'Physical and Environmental Protection Policy and Procedures', NULL, NULL, N'WMATA', NULL, NULL, NULL, 68, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37775, N'PE-10', N'a. Provide the capability of shutting off power to [Assignment: organization-defined system or individual system components] in emergency situations;b. Place emergency shutoff switches or devices in [Assignment: organization-defined location by system or system component] to facilitate access for authorized personnel; andc. Protect emergency power shutoff capability from unauthorized activation.', N'<p><strong>WMATA Policy</strong></p><p>a.  Provide the capability of shutting off power to systems or individual system components in emergency situations for facilities with concentrations of system resources (e.g., data centers, mainframe computer rooms, server rooms, and areas with computer-controlled machinery);</p><p>b. Place emergency shutoff switches or devices in accessible locations to facilitate access for authorized personnel;</p><p>c. Protect emergency power shutoff capability from unauthorized activation; and</p><p>d. Appoint a WMATA employee or contractor to manage all emergency shutoff capabilities.</p><p><strong><u>OT Systems Only:</strong></u> It may not be possible or advisable to shut off power to some OT. The [organization-defined parameters] for this control should be implemented in consultation with safety and operational personnel. Example compensating controls include failing to a known state and emergency procedures. </p><p>Related Controls: PE-15</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: It may not be possible or advisable to shut off power to some OT. The organizational-defined parameters for this control should be implemented in consultation with safety and operational personnel. Example compensating controls include failing to a known state and emergency procedures. </p>', N'Physical and Environmental Protection', N'Emergency Shutoff', NULL, NULL, N'WMATA', NULL, NULL, NULL, 68, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37776, N'PE-11', N'Provide an uninterruptible power supply to facilitate [Selection (one or more): an orderly shutdown of the system; transition of the system to long-term alternate power] in the event of a primary power source loss.', N'<p><strong>WMATA Policy</strong></p><p>a.  Provide an uninterruptible power supply to facilitate an orderly shutdown of the system and transition of the system to long-term alternate power in the event of a primary power source loss; and</p><p>b. Appoint a WMATA employee or contractor to manage all emergency power capabilities.</p><p>Related Controls: AT-3, CP-2, CP-7</p><p>c. Security Controls Enhancement(s):</p>', N'Physical and Environmental Protection', N'Emergency Power', NULL, NULL, N'WMATA', NULL, NULL, NULL, 68, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37777, N'PE-11 (1)', N'Provide an alternate power supply for the system that is activated [Selection: manually; automatically] and that can maintain minimally required operational capability in the event of an extended loss of the primary power source.', N'<p><strong>WMATA Policy</strong></p><p>(1) WMATA shall provide an automatic alternate power supply for systems to ensure required operational capability in the event of an extended loss of the primary power source.</p><p>(2) In the event both the primary and alternate power supply, a graceful shutdown of the system shall occur in accordance with Control 3.19 System and Services Acquisition<br>control.</p>', N'Physical and Environmental Protection', N'Emergency Power', NULL, NULL, N'WMATA', NULL, NULL, NULL, 68, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37778, N'PE-11 (2)', N'Provide an alternate power supply for the system that is activated [Selection: manually; automatically] and that is:(a) Self-contained;(b) Not reliant on external power generation; and(c) Capable of maintaining [Selection: minimally required operational capability; full operational capability] in the event of an extended loss of the primary power source.', N'<p><strong>WMATA Policy</strong></p><p>Provide an alternate power supply for the system that is activated [Selection: manually; automatically] and that is:</p><p>(1)  Self-contained;<br>(2)  Not reliant on external power generation; and<br>(3)  Capable of maintaining [Selection: minimally required operational capability; full operational capability] in the event of an extended loss of the primary power source. </p>', N'Physical and Environmental Protection', N'Emergency Power', NULL, NULL, N'WMATA', NULL, NULL, NULL, 68, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37779, N'PE-12', N'Employ and maintain automatic emergency lighting for the system that activates in the event of a power outage or disruption and that covers emergency exits and evacuation routes within the facility.', N'<p><strong>WMATA Policy</strong></p><p>Employ and maintain automatic emergency lighting for the system that activates in the event of a power outage or disruption and that covers emergency exits and evacuation routes within the facility.</p><p>Related Controls: CP-2, CP-7</p>', N'Physical and Environmental Protection', N'Emergency Lighting', NULL, NULL, N'WMATA', NULL, NULL, NULL, 68, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37780, N'PE-13', N'Employ and maintain fire detection and suppression systems that are supported by an independent energy source.', N'<p><strong>WMATA Policy</strong></p><p>a. Employ and maintain fire detection and suppression systems that are supported by an independent energy source.</p><p><strong><u>OT Systems Only: </strong></u>Fire suppression mechanisms should take the OT environment into account (e.g., water sprinkler systems could be hazardous in specific environments). </p><p>Related Controls: AT-3</p><p>b. Security Controls Enhancement(s):</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Fire suppression mechanisms should take the OT environment into account (e.g., water sprinkler systems could be hazardous in specific environments).</p>', N'Physical and Environmental Protection', N'Fire Protection', NULL, NULL, N'WMATA', NULL, NULL, NULL, 68, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37781, N'PE-13 (1)', N'Employ fire detection systems that activate automatically and notify [Assignment: organization-defined personnel or roles] and [Assignment: organization-defined emergency responders] in the event of a fire.', N'<p><strong>WMATA Policy</strong></p><p>Employ fire detection systems that activate automatically and notify MTPD, Office of Emergency Management, Facilities, MEMC, Cyber Fusion Center, and emergency responders in the event of a fire.</p>', N'Physical and Environmental Protection', N'Fire Protection', NULL, NULL, N'WMATA', NULL, NULL, NULL, 68, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37782, N'PE-13 (2)', N'(a) Employ fire suppression systems that activate automatically and notify [Assignment: organization-defined personnel or roles] and [Assignment: organization-defined emergency responders]; and(b) Employ an automatic fire suppression capability when the facility is not staffed on a continuous basis.', N'<p><strong>WMATA Policy</strong></p><p>Employ fire suppression systems that activate automatically and notify MTPD, Office of Emergency Management, Facilities, MEMC, Cyber Fusion Center, and emergency responders.</p>', N'Physical and Environmental Protection', N'Fire Protection', NULL, NULL, N'WMATA', NULL, NULL, NULL, 68, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37783, N'PE-14', N'a. Maintain [Selection (one or more): temperature; humidity; pressure; radiation; [Assignment: organization-defined environmental control]] levels within the facility where the system resides at [Assignment: organization-defined acceptable levels]; andb. Monitor environmental control levels [Assignment: organization-defined frequency].', N'<p><strong>WMATA Policy</strong></p><p>Maintain temperature, humidity, pressure, radiation, and other applicable environmental control levels within facilities that contain concentrations of system resources (e.g., data centers, mainframe computer rooms, and server rooms) where systems reside at [Assignment: organization-defined acceptable levels]; and</p><p>b. Monitor environmental control levels at least twice daily.</p><p><strong><u>OT Systems Only:</strong></u> Temperature and humidity controls are typically components of other OT systems such as the HVAC, process, or lighting systems, or can be a standalone and unique OT system. OT can operate in extreme environments and both interior and exterior locations. For a specific OT, the temperature and humidity design and operational parameters dictate the performance specifications. As OT and IT become interconnected and the network provides connectivity across the hybrid domain, power circuits, distribution closets, routers, and switches that support fire protection and life safety systems must be maintained at the proper temperature and humidity. When environmental controls cannot be implemented, use hardware that is engineered to withstand the unique environmental hazards.</p><p>Related Controls: AT-3, CP-2</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Temperature and humidity controls are typically components of other OT systems (e.g., HVAC, process, or lighting systems) or can be a stand-alone and unique OT system. OT can operate in extreme environments and both interior and exterior locations. For a specific OT, the temperature and humidity design and operational parameters dictate the performance specifications. Power circuits, distribution closets, routers, and switches that <br>support fire protection and life safety systems must be maintained at the proper temperature and humidity. When environmental controls cannot be implemented, use hardware that is engineered to withstand the OT’s unique environmental hazards.</p>', N'Physical and Environmental Protection', N'Environmental Controls', NULL, NULL, N'WMATA', NULL, NULL, NULL, 68, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37784, N'PE-15', N'Protect the system from damage resulting from water leakage by providing master shutoff or isolation valves that are accessible, working properly, and known to key personnel.', N'<p><strong>WMATA Policy</strong></p><p>a. Protect systems from damage resulting from water leakage by providing master shutoff or isolation valves that are accessible, working properly, and known to key personnel.</p><p><strong><u>OT Systems Only: </strong></u>Water damage protection and use of shutoff and isolation valves is both a procedural action and a specific type of OT. OT used in the manufacturing, hydropower, transportation/navigation, water, and wastewater industries rely on the movement of water and are specifically designed to manage the quantity/flow and pressure of water. As OT and IT become interconnected and the network provides connectivity across the hybrid domain, power circuits, distribution closets, routers and switches that support fire protection and life safety systems should ensure that water will not disable the system (e.g., a fire that activates the sprinkler system does not spray onto the fire control servers, router, switches and short out the alarms, egress systems, emergency lighting, and suppression systems).</p><p>Related Controls: AT-3, PE-10</p><p>b. Security Controls Enhancement(s):</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Water damage protection and the use of shutoff and isolation valves are procedural actions and specific types of OT. OT used in the manufacturing, hydropower, transportation/navigation, water, and wastewater industries rely on the movement of water and are specifically designed to manage the quantity, flow, and pressure of water. Power circuits, <br>distribution closets, routers, and switches that support fire protection and life safety systems should ensure that water will not disable the system (e.g., a fire that activates the sprinkler system does not spray onto the fire control servers, routers, or switches or short out the alarms, egress systems, emergency lighting, or suppression systems). </p>', N'Physical and Environmental Protection', N'Water Damage Protection', NULL, NULL, N'WMATA', NULL, NULL, NULL, 68, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37785, N'PE-15 (1)', N'Detect the presence of water near the system and alert [Assignment: organization-defined personnel or roles] using [Assignment: organization-defined automated mechanisms].', N'<p><strong>WMATA Policy</strong></p><p>Detect the presence of water near the system and alert MTPD, Office of Emergency Management, Facilities, MEMC, and Cyber Fusion Center using automated mechanisms.</p>', N'Physical and Environmental Protection', N'Water Damage Protection', NULL, NULL, N'WMATA', NULL, NULL, NULL, 68, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37786, N'PE-16', N'a. Authorize and control [Assignment: organization-defined types of system components] entering and exiting the facility; andb. Maintain records of the system components.', N'<p><strong>WMATA Policy</strong></p><p>a. Authorize and control systems and system components that enter or exit facilities or secured areas to include areas designated for delivery, maintenance/service, or media libraries.</p><p>b. Maintain records of the system components in an organizational asset management system.</p><p>Related Controls: CM-3, CM-8, MA-2, MA-3, MP-5, SR-2, SR-3, SR-4, SR-6</p>', N'Physical and Environmental Protection', N'Delivery and Removal', NULL, NULL, N'WMATA', NULL, NULL, NULL, 68, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37787, N'PE-17', N'a. Determine and document the [Assignment: organization-defined alternate work sites] allowed for use by employees;b. Employ the following controls at alternate work sites: [Assignment: organization-defined controls];c. Assess the effectiveness of controls at alternate work sites; andd. Provide a means for employees to communicate with information security and privacy personnel in case of incidents.', N'<p><strong>WMATA Policy</strong></p><p>a.  Determine and document approved alternate work sites allowed for use by employees during contingency operations;</p><p>b. Employ the following controls at alternate work sites:</p><p>i)  Use of facilities not owned or operated by WMATA and not covered in accordance with P/I 7.4 Telework Policy are subject to approval for operating or accessing systems by the AO; and</p><p>ii)  For alternate work sites without access to MetroNet, personnel shall only connect to MetroNet using approved secure means (e.g., Virtual Private Network (VPN), Virtual Desktop Infrastructure (VDI), etc.).</p><p>c. Assess the effectiveness of controls at alternate work sites; and</p><p>d.  Provide a means for employees to communicate with information security and privacy personnel in case of incidents.</p><p>Related Controls: AC-17, AC-18, CP-7</p>', N'Physical and Environmental Protection', N'Alternate Work Site', NULL, NULL, N'WMATA', NULL, NULL, NULL, 68, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37788, N'PE-18', N'Position system components within the facility to minimize potential damage from [Assignment: organization-defined physical and environmental hazards] and to minimize the opportunity for unauthorized access.', N'<p><strong>WMATA Policy</strong></p><p>Position system components within the facility to minimize potential damage from physical and environmental hazards and to minimize the opportunity for unauthorized access.</p><p>Related Controls: CP-2, PE-5, RA-3</p>', N'Physical and Environmental Protection', N'Location of System Components', NULL, NULL, N'WMATA', NULL, NULL, NULL, 68, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37789, N'PE-2', N'a. Develop, approve, and maintain a list of individuals with authorized access to the facility where the system resides;b. Issue authorization credentials for facility access;c. Review the access list detailing authorized facility access by individuals [Assignment: organization-defined frequency]; andd. Remove individuals from the facility access list when access is no longer required.', N'<p><strong>WMATA Policy</strong></p><p>a. Develop, approve, and maintain a list of employees and contractors with authorized access to the facility and sensitive area where systems reside;</p><p>b. Issue authorization credentials for facility and sensitive area access;</p><p>c. Review the access list detailing authorized facility and sensitive area access by individuals <br>quarterly; and</p><p>d. Remove individuals from facility and sensitive area access lists when access is no longer <br>required.</p><p>Related Controls: AT-3, AU-9, IA-4, MA-5, MP-2, PE-3, PE-4, PE-5, PE-8, PM-12, PS-3, PS-4, PS-5, PS-6</p>', N'Physical and Environmental Protection', N'Physical Access Authorizations', NULL, NULL, N'WMATA', NULL, NULL, NULL, 68, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37790, N'PE-21', N'Employ [Assignment: organization-defined protective measures] against electromagnetic pulse damage for [Assignment: organization-defined systems and system components].', N'<p><strong>WMATA Policy</strong></p><p>Employ [Assignment: organization-defined protective measures] against electromagnetic pulse damage for [Assignment: organization-defined systems and system components]. </p><p><strong><u>OT Systems Only:</strong></u> Organizations managing OT equipment may choose to utilize electromagnetic (EM) pulse protection to prevent adversarial or environmental EM threats. Organizations may select to follow National Coordinating Center for Communications (NCC) guidelines on EM pulse protection.<br>	<br>Related Controls: PE-18</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Organizations that manage OT equipment may choose to utilize EMP protection to prevent adversarial or environmental electromagnetic threats. Organizations may select to follow National Coordinating Center for Communications (NCC) guidelines on EM pulse protection.</p>', N'Physical and Environmental Protection', N'Electromagnetic Pulse Protection', NULL, NULL, N'WMATA', NULL, NULL, NULL, 68, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37791, N'PE-22', N'Mark [Assignment: organization-defined system hardware components] indicating the impact level or classification level of the information permitted to be processed, stored, or transmitted by the hardware component.', N'<p><strong>WMATA Policy</strong></p><p>Mark [Assignment: organization-defined system hardware components] indicating the impact level or classification level of the information permitted to be processed, stored, or transmitted by the hardware component. </p><p>OT Systems Only: Hardware components are marked or labeled to indicate which information is processed, stored, or transmitted. Component markings can be useful in differentiating between safety and control systems, OT and IT equipment, and internally and externally connected systems. Marking components reduces the probability of mismanaging the system or performing maintenance on an incorrect device.</p><p>Related Controls: AC-3, AC-4, MP-3</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Hardware components are marked or labeled to indicate information that is processed, stored, or transmitted. Component markings can be useful for differentiating between safety and control systems, OT and IT equipment, and internally and externally connected systems. Marking components reduces the probability of mismanaging the system or performing maintenance on an incorrect device. </p><p>Rationale for adding PE-22 to MOD and HIGH baselines: OT is unique in that it may look like an IT component but perform a very different function. Visible differentiation between components that perform different functions can help reduce reliability incidents due to maintenance errors.<br></p>', N'Physical and Environmental Protection', N'Component Marking', NULL, NULL, N'WMATA', NULL, NULL, NULL, 68, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37792, N'PE-3', N'a. Enforce physical access authorizations at [Assignment: organization-defined entry and exit points to the facility where the system resides] by:     1. Verifying individual access authorizations before granting access to the facility; and     2. Controlling ingress and egress to the facility using [Selection (one or more): [Assignment: organization-defined physical access control      systems or devices]; guards];b. Maintain physical access audit logs for [Assignment: organization-defined entry or exit points];c. Control access to areas within the facility designated as publicly accessible by implementing the following controls: [Assignment: organization-defined physical access controls];d. Escort visitors and control visitor activity [Assignment: organization-defined circumstances requiring visitor escorts and control of visitor activity];e. Secure keys, combinations, and other physical access devices;f. Inventory [Assignment: organization-defined physical access devices] every [Assignment: organization-defined frequency]; andg. Change combinations and keys [Assignment: organization-defined frequency] and/or when keys are lost, combinations are compromised, or when individuals possessing the keys or combinations are transferred or terminated.', N'<p><strong>WMATA Policy</strong></p><p>a. Enforce physical access authorizations at entry and exit points to facilities and sensitive <br>areas where systems reside by:</p><p>i)  Verifying individual access authorizations before granting access to the facility and sensitive areas; and</p><p>ii)  Controlling ingress and egress to the facility and sensitive areas using physical access <br>control personnel (e.g., guards), or systems and devices.</p><p>b.  Maintain physical access audit logs for all controlled entry or exit points for all facilities, <br>and secured areas within facilities to include those secured areas listed in accordance with <br>Control 3.14 Physical and Environmental Protection, Section 4, “PE-4 Access Control for <br>Transmission” and areas that store, process or transmit sensitive information in accordance with Control 3.8 Data Sensitivity;</p><p>c.  Control access to areas within the facility designated as publicly accessible by implementing the following controls: physical access control logs/records, guards, and physical access devices and barriers to prevent movement from publicly accessible areas to non-public areas;</p><p>d. WMATA employees shall escort visitors and control visitor activity at all times;</p><p>e. Secure keys, combinations, and other physical access devices;</p><p>f.  Inventory and centrally manage physical access devices to include keys, locks, combinations, safes, biometric readers, and card readers and systems every year; and</p><p>g.  Change combinations and keys annually and/or when keys are lost, combinations are compromised, or when individuals possessing the keys or combinations are transferred or terminated.</p><p><strong><u>OT Systems Only:</strong></u> The organization considers OT safety and security interdependencies. The organization considers access requirements in emergency situations. During an emergency-related event, the organization may restrict access to OT facilities and assets to authorized individuals only. OT systems are often constructed of devices that either do not have or cannot use comprehensive access control capabilities due to time-restrictive safety constraints. Physical access controls and defense-in-depth measures are used by the organization when necessary and possible to supplement OT security when electronic mechanisms are unable to fulfill the security requirements of the organization’s security plan.</p><p>Related Controls: AT-3, AU-2, AU-6, AU-9, CP-10, IA-3, IA-8, MA-5, MP-2, MP-4, PE-2, PE-4, PE-5, PE-8, PS-2, PS-3, PS-6, PS-7, RA-3, SC-28, SI-4, SR-3</p><p>h. Security Controls Enhancement(s):</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: The organization considers OT safety and security interdependencies and access requirements in emergency situations. During an emergency, the organization may restrict access to OT facilities and assets to authorized individuals only. OT systems are often constructed of devices that do not have or cannot use comprehensive access control capabilities due to timerestrictive safety constraints. Physical access controls and defense-in-depth measures are used by the organization when necessary and possible to supplement OT security when electronic mechanisms are unable to fulfill the security requirements of the organization’s security plan. </p><p></p>', N'Physical and Environmental Protection', N'Physical Access Control', NULL, NULL, N'WMATA', NULL, NULL, NULL, 68, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37793, N'PE-3 (1)', N'Enforce physical access authorizations to the system in addition to the physical access controls for the facility at [Assignment: organization-defined physical spaces containing one or more components of the system].', N'<p><strong>WMATA Policy</strong></p><p>Enforce physical access authorizations to systems and applicable system components in addition to the physical access controls for the facility.</p>', N'Physical and Environmental Protection', N'Physical Access Control', NULL, NULL, N'WMATA', NULL, NULL, NULL, 68, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37794, N'PE-4', N'Control physical access to [Assignment: organization-defined system distribution and transmission lines] within organizational facilities using [Assignment: organization-defined security controls].', N'<p><strong>WMATA Policy</strong></p><p>Control physical access to system distribution and transmission lines within organizational facilities using security controls to include disconnected or locked spare jacks, locked wiring closets, protection of cabling by conduit or cable trays, and wiretapping sensors.</p><p>Related Controls: AT-3, IA-4, MP-2, MP-4, PE-2, PE-3, PE-5, PE-9, SC-7, SC-8</p>', N'Physical and Environmental Protection', N'Access Control For Transmission', NULL, NULL, N'WMATA', NULL, NULL, NULL, 68, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37795, N'PE-5', N'Control physical access to output from [Assignment: organization-defined output devices] to prevent unauthorized individuals from obtaining the output.', N'<p><strong>WMATA Policy</strong></p><p>Control physical access to output devices which display sensitive information (e.g., rail command and control, law enforcement sensitive, etc.) or display devices processing internal or sensitive information visible to the general public to prevent unauthorized individuals from obtaining output. Ensure that output devices are:</p><p>a. Located in locked rooms or other secured areas that only allow access to authorized individuals;</p><p>b. Placed in locations that can be monitored by authorized personnel; and</p><p>c. Installed with monitor or screen filters (when applicable).</p><p>Related Controls: PE-2, PE-3, PE-4, PE-18</p>', N'Physical and Environmental Protection', N'Access Control For Output Devices', NULL, NULL, N'WMATA', NULL, NULL, NULL, 68, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37796, N'PE-6', N'a. Monitor physical access to the facility where the system resides to detect and respond to physical security incidents;b. Review physical access logs [Assignment: organization-defined frequency] and upon occurrence of [Assignment: organization-defined events or potential indications of events]; andc. Coordinate results of reviews and investigations with the organizational incident response capability.', N'<p><strong>WMATA Policy</strong></p><p>a. Implement layered physical security controls to provide authorized access to facilities and systems;</p><p>b.  Monitor physical access to the facility where systems reside to detect and respond to physical security incidents;</p><p>c.  Review physical access logs monthly and upon occurrence of indications of security violations, suspicious physical access activities, and when notified of suspicious logical access activities that can be correlated with physical access control events; and</p><p>d. Coordinate results of reviews and investigations with the organizational incident response capability.</p><p>Related Controls: AU-2, AU-6, AU-9, AU-12, CA-7, CP-10, IR-4, IR-8</p><p>e. Security Controls Enhancement(s):</p>', N'Physical and Environmental Protection', N'Monitoring Physical Access', NULL, NULL, N'WMATA', NULL, NULL, NULL, 68, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37797, N'PE-6 (1)', N'Monitor physical access to the facility where the system resides using physical intrusion alarms and surveillance equipment.', N'<p><strong>WMATA Policy</strong></p><p>Monitor physical access to the facility where systems reside using physical intrusion alarms and surveillance equipment.</p>', N'Physical and Environmental Protection', N'Monitoring Physical Access', NULL, NULL, N'WMATA', NULL, NULL, NULL, 68, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37798, N'PE-6 (4)', N'<p><b>Monitoring Physical Access | Monitoring Physical Access to Systems</b></p>Monitor physical access to the system in addition to the physical access monitoring of the facility at [Assignment: organization-defined physical spaces containing one or more components of the system].', N'<p><strong>WMATA Policy</strong></p><p>Monitor physical access to systems in addition to the physical access monitoring of the facility at physical spaces containing one or more components of the system.</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>Rationale for adding PE-6 (4) to MOD baseline: Many of the OT components are in remote geographical and dispersed locations. Other components may be in ceilings, floors, or distribution closets. Furthermore, physical access controls are frequently used as compensating controls when devices lack the ability to enforce logical access restrictions. </p>', N'Physical and Environmental Protection', N'Monitoring Physical Access', NULL, NULL, N'WMATA', NULL, NULL, NULL, 68, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37799, N'PE-8', N'a. Maintain visitor access records to the facility where the system resides for [Assignment: organization-defined time period];b. Review visitor access records [Assignment: organization-defined frequency]; andc. Report anomalies in visitor access records to [Assignment: organization-defined personnel].', N'<p><strong>WMATA Policy</strong></p><p>a.  Maintain visitor access records to the facility where the system resides for five years. <br>Visitor access records include the names and organizations of individuals visiting, visitor <br>signatures, forms of identification, dates of access, entry and departure times, purpose of visits, and the names and organizations of individuals visited.</p><p>b.  Review visitor access records for sensitive areas within the facility where systems reside <br>monthly. Access record reviews determine if access authorizations were and still are required to support organizational mission and business functions.</p><p>c.  Report anomalies in visitor access records to MTPD. In addition, all anomalies for sensitive areas that house systems shall be reported to Metro Enterprise Monitoring Center (MEMC) and the Cyber Fusion Center.</p><p>Related Controls: PE-2, PE-3, PE-6</p><p>d. Security Controls Enhancement(s):</p>', N'Physical and Environmental Protection', N'Visitor Access Records', NULL, NULL, N'WMATA', NULL, NULL, NULL, 68, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37800, N'PE-8 (1)', N'Maintain and review visitor access records using [Assignment: organization-defined automated mechanisms].', N'<p><strong>WMATA Policy</strong></p><p>Maintain and review visitor access records using automated mechanisms.</p>', N'Physical and Environmental Protection', N'Visitor Access Records', NULL, NULL, N'WMATA', NULL, NULL, NULL, 68, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37801, N'PE-8 (3)', N'Limit personally identifiable information contained in visitor access records to the following elements identified in the privacy risk assessment: [Assignment: organization-defined elements].', N'<p><strong>WMATA Policy</strong></p><p>Limit personally identifiable information contained in visitor access records to include the full name of the individual, Driver’s License Number (or other approved identifier if not available), and the escort name and badge number.</p><p>Related Controls: RA-3, SA-8</p>', N'Physical and Environmental Protection', N'Visitor Access Records', NULL, NULL, N'WMATA', NULL, NULL, NULL, 68, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37802, N'PE-9', N'Protect power equipment and power cabling for the system from damage and destruction.', N'<p><strong>WMATA Policy</strong></p><p>Protect power equipment and power cabling for the system from damage and destruction.</p><p>Related Controls: PE-4</p>', N'Physical and Environmental Protection', N'Power Equipment And Cabling', NULL, NULL, N'WMATA', NULL, NULL, NULL, 68, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37803, N'PL-1', N'a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:     1. [Selection (one or more): Organization-level; Mission/business process-level; System-level] planning policy that:          (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and           compliance; and          (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and     2. Procedures to facilitate the implementation of the planning policy and the associated planning controls;b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the planning policy and procedures; andc. Review and update the current planning:     1. Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and     2. Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].', N'<p><strong>WMATA Policy</strong></p><p><strong>Additional Security Documentation<br></strong>
a. At the discretion of the AO, following documents may be required to be developed for systems:</p>
<ul style="list-style-type:none;">
    <li>i) Privacy Impact Assessment (PIA)</li>
<p>ii) Privacy Threshold Assessment (PTA)</p>
<p>iii) Disaster Recovery Plan (DRP)</p>
<p>iv) Information Type Survey</p>
<p>v) Security Assessment Report (SAR)</p>
<p>vi) Plan of Action and Milestones (POAM)</p>
<p>vii) Information System Contingency Plan (ISCP) – also known as Continuity of Operations (COP)</p>
<p>viii) Configuration Management Plan (CMP)</p>
<p>ix) Incident Response Plan (IRP)</p>
<p>x) System Architecture/Topology/Data Flow</p>
<p>xi) Hardware/Software Inventory List</p>
<p>xii) Physical Security Plan</p>
<p>xiii) Personnel Security Plan</p>
<p>xiv) Patch Management Process/ System Approval documentation</p>
<p>xv) Ports, Protocols, and Services (PPS) List</p>
<p>xvi) Processing Standard (FIPS) 199 Categorization Form xvii)Cryptographic Key Management Information</p>
<p>xviii) Interconnected Information Systems and Identifiers</p>
</ul>
<p>b. At the discretion of the AO, the following documents may be required to be developed for the enterprise:</p>
<ul>
<p>i) Security Classification Guide</p>
<p>ii) System Configuration Guide</p>
<p>iii) Configuration Validation Checklist</p>
<p>iv) Processing Standard (FIPS) 199 Categorization Template</p>
</ul>
 <p>Reference P/I 15.28 Cybersecurity Policy for requirements.</p><p>Related Controls: PM-9, PS-8, SI-12</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: The policy specifically addresses the unique properties and requirements of OT and the relationship to non-OT systems.</p>', N'Planning', N'Planning Policy and Procedures', NULL, NULL, N'WMATA', NULL, NULL, NULL, 34, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37804, N'PL-10', N'Select a control baseline for the system.', N'<p><strong>WMATA Policy</strong></p><p>Security control baselines shall be in place for all systems. Deviations to control baselines shall be approved by the AO.</p><p>Related Controls: PL-2, PL-11, RA-2, RA-3, SA-8</p>', N'Planning', N'Baseline Selection', NULL, NULL, N'WMATA', NULL, NULL, NULL, 34, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37805, N'PL-11', N'Tailor the selected control baseline by applying specified tailoring actions.', N'<p><strong>WMATA Policy</strong></p><p>Tailoring of selected control baselines shall be performed in consultation with DMCS and approval by the AO.</p><p>Related Controls: PL-10, RA-2, RA-3, RA-9, SA-8</p>', N'Planning', N'Baseline Tailoring', NULL, NULL, N'WMATA', NULL, NULL, NULL, 34, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37806, N'PL-2', N'a. Develop security and privacy plans for the system that:     1. Are consistent with the organization’s enterprise architecture;     2. Explicitly define the constituent system components;     3. Describe the operational context of the system in terms of mission and business processes;     4. Identify the individuals that fulfill system roles and responsibilities;     5. Identify the information types processed, stored, and transmitted by the system;     6. Provide the security categorization of the system, including supporting rationale;     7. Describe any specific threats to the system that are of concern to the organization;     8. Provide the results of a privacy risk assessment for systems processing personally identifiable information;     9. Describe the operational environment for the system and any dependencies on or connections to other systems or system components;   10. Provide an overview of the security and privacy requirements for the system;   11. Identify any relevant control baselines or overlays, if applicable;   12. Describe the controls in place or planned for meeting the security and privacy requirements, including a rationale for any tailoring decisions;   13. Include risk determinations for security and privacy architecture and design decisions;   14. Include security- and privacy-related activities affecting the system that require planning and coordination with [Assignment: organization-     defined individuals or groups]; and   15. Are reviewed and approved by the authorizing official or designated representative prior to plan implementation.b. Distribute copies of the plans and communicate subsequent changes to the plans to [Assignment: organization-defined personnel or roles];c. Review the plans [Assignment: organization-defined frequency];d. Update the plans to address changes to the system and environment of operation or problems identified during plan implementation or control    assessments; ande. Protect the plans from unauthorized disclosure and modification.', N'<p><strong>WMATA Policy</strong></p><p>a. Develop system security plan for the system that:</p><p>i)  Are consistent with the organization’s enterprise architecture;</p><p>ii) Explicitly define the constituent system components;</p><p>iii) Describe the operational context of the system in terms of mission and business processes;</p><p>iv) Identify the individuals that fulfill system roles and responsibilities;</p><p>v) Identify the information types processed, stored, and transmitted by the system;</p><p>vi) Provide the security categorization of the system, including supporting rationale;</p><p>vii) Describe any specific threats to the system that are of concern to the organization;</p><p>viii) Describe the operational environment for the system and any dependencies on or connections to other systems or system components;</p><p>ix) Provide an overview of the System Security Plan (SSP) requirements for the system;</p><p>x) Identify any relevant control baselines or overlays, if applicable;</p><p>xi) Describe the controls in place or planned for meeting the security and privacy requirements, including a rationale for any tailoring decisions;</p><p>xii) Include risk determinations for security and privacy architecture and design decisions;</p><p>xiii) Document and map to applicable security controls or system documentation security- and privacy-related emergency and non-emergency activities that require planning and coordination with other organizational individuals, teams, or groups to include assessments, audits, inspections, hardware and software maintenance, acquisition and supply chain risk management, patch management, and ISCP testing; and</p><p>xiv) Are reviewed and approved by the authorizing official or designated representative prior to plan implementation.</p><p>b. Distribute copies of the SSP and communicate subsequent changes to the plans to required holders;</p><p>c. Review the SSP annually;</p><p>d.  Update the SSP to address changes to the system and environment of operation or problems identified during plan implementation or control assessments; and</p><p>e. Protect the plans from unauthorized disclosure and modification.</p><p><strong><u>OT Systems Only:</strong></u> When systems are highly interconnected, coordinated planning is essential. A low-impact system could adversely affect a higher-impact system. </p><p><br>Related Controls:  AC-2, AC-6, AC-14, AC-17, AC-20, CA-2, CA-3, CA-7, CM-9, CP-2, CP-4, IR-4, IR-8, MA-4, MA-5, MP-4, MP-5, PL-7, PL-8, PL-10, PL-11, PM-1, PM-7, PM-8, PM-9, PM-10R, PM-11, RA-3, RA-8, RA-9, SA-5, SA-17, SA-22, SI-12, SR-2, SR-4</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: When systems are highly interconnected, coordinated planning is essential. A low-impact system could adversely affect a higher-impact system.<br></p>', N'Planning', N'System Security and Privacy Plans', NULL, NULL, N'WMATA', NULL, NULL, NULL, 34, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37807, N'PL-4', N'a. Establish and provide to individuals requiring access to the system, the rules that describe their responsibilities and expected behavior for information and system usage, security, and privacy;b. Receive a documented acknowledgment from such individuals, indicating that they have read, understand, and agree to abide by the rules of behavior, before authorizing access to information and the system;c. Review and update the rules of behavior [Assignment: organization-defined frequency]; andd. Require individuals who have acknowledged a previous version of the rules of behavior to read and re-acknowledge [Selection (one or more): [Assignment: organization-defined frequency]; when the rules are revised or updated].', N'<p><strong>WMATA Policy</strong></p><p>a. Maintain general user rules of behavior agreement and privileged user rules of behavior <br>agreement.</p><p>b. Establish and provide to individuals requiring access to the system the rules that describe their responsibilities and expected behavior for information and system usage and security;</p><p>c.  Receive a documented acknowledgment from such individuals, indicating that they have read, understand, and agree to abide by the rules of behavior, before authorizing access to information and the system;</p><p>d. Review and update the rules of behavior annually; and</p><p>e. Require users who have acknowledged a previous version of the rules of behavior to read and re-acknowledge rules of behavior annually or when they are revised or updated.</p><p>f.  Document in the privileged rules of behavior agreement that privileged users are authorized (and therefore, trusted) to perform security-relevant functions that ordinary users are not authorized to perform.</p><p>Related Controls:  AC-2, AC-6, AC-8, AC-17, AC-18, AC-19, AC-20, AT-2, AT-3, CM-11, IA-2, IA-4, IA-5, MP-7, PS-6, PS-8, SA-5, SI-12</p><p>h.  Security Controls Enhancement(s):</p>', N'Planning', N'Rules Of Behavior', NULL, NULL, N'WMATA', NULL, NULL, NULL, 34, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37808, N'PL-4 (1)', N'Include in the rules of behavior, restrictions on:(a) Use of social media, social networking sites, and external sites/applications;(b) Posting organizational information on public websites; and(c) Use of organization-provided identifiers (e.g., email addresses) and authentication secrets (e.g., passwords) for creating accounts on external sites/applications.', N'<p><strong>WMATA Policy</strong></p><p>Include in the rules of behavior restrictions on:</p><p>(1) Use of social media, social networking sites, and external sites/applications;</p><p>(2) Posting organizational information on public websites; and</p><p>(3) Use of organization-provided identifiers (e.g., email addresses) and authentication secrets (e.g., passwords) for creating accounts on external sites/applications.</p><p>Related Controls:  AC-22</p><p>h. Define personally acceptable use of WMATA technology.</p>', N'Planning', N'Rules Of Behavior', NULL, NULL, N'WMATA', NULL, NULL, NULL, 34, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37809, N'PL-7', N'a. Develop a Concept of Operations (CONOPS) for the system describing how the organization intends to operate the system from the perspective of information security and privacy; andb. Review and update the CONOPS [Assignment: organization-defined frequency].', N'<p><strong>WMATA Policy</strong></p><p>a. Develop a Concept of Operations (CONOPS) for the system describing how the organization intends to operate the system from the perspective of information security; and</p><p>b. Review and update the CONOPS annually. This requirement is waived if the components of the CONOPS is fully documented within the organizational Governance, Risk, and Compliance tool.</p><p>c. Require an updated CONOPS, at the discretion of the AO, if there is a substantial change to the functionality of the system.</p><p><strong><u>OT Systems Only:</strong></u> Organizations need to consider documenting known operational procedures and exploring how they relate to the combination of IT and OT technologies within the environment.</p><p>Related Controls: PL-2, SA-2, SI-12</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Organizations need to consider documenting known operational procedures and exploring how they relate to the combination of IT and OT technologies within the environment. </p>', N'Planning', N'Concept of Operations', NULL, NULL, N'WMATA', NULL, NULL, NULL, 34, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37810, N'PL-8', N'a. Develop security and privacy architectures for the system that:     1. Describe the requirements and approach to be taken for protecting the confidentiality, integrity, and availability of organizational information;     2. Describe the requirements and approach to be taken for processing personally identifiable information to minimize privacy risk to individuals;     3. Describe how the architectures are integrated into and support the enterprise architecture; and     4. Describe any assumptions about, and dependencies on, external systems and services;b. Review and update the architectures [Assignment: organization-defined frequency] to reflect changes in the enterprise architecture; andc. Reflect planned architecture changes in security and privacy plans, Concept of Operations (CONOPS), criticality analysis, organizational procedures, and procurements and acquisitions.', N'<p><strong>WMATA Policy</strong></p><p>a. Develop security and privacy architectures for the system that:</p><p>i)  Describe the requirements and approach to be taken for protecting the confidentiality, <br>integrity, and availability of organizational information;</p><p>ii)  Describe the requirements and approach to be taken for processing personally identifiable information to minimize privacy risk to individuals;</p><p>iii) Describe how the architectures are integrated into and support the enterprise architecture; and</p><p>iv) Describe any assumptions about, and dependencies on, external systems and services;</p><p>b.  Review and update system architectures annually, and when there is a change to the system, enterprise architecture, or enterprise security architecture; and</p><p>c. Reflect planned architecture changes in security plans, Concept of Operations (CONOPS), <br>criticality analysis, organizational procedures, and procurements and acquisitions.</p><p>Related Controls: CM-2, CM-6, PL-2, PL-7, PL-9, PM-5, PM-7, RA-9, SA-3, SA-5, SA-8, SA-17, SC-7</p><p>i.  Security Controls Enhancement(s):</p>', N'Planning', N'Security and Privacy Architectures', NULL, NULL, N'WMATA', NULL, NULL, NULL, 34, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37811, N'PL-8 (1)', N'<p><b>Security and Privacy Architectures | Defense in Depth</b></p>Design the security and privacy architectures for the system using a defense-in-depth approach that:(a) Allocates [Assignment: organization-defined controls] to [Assignment: organization-defined locations and architectural layers]; and(b) Ensures that the allocated controls operate in a coordinated and mutually reinforcing manner.', N'<p><strong>WMATA Policy</strong></p><p>(1)  Allocates [Assignment: organization-defined controls] to [Assignment: organization-defined locations and architectural layers]; and</p><p>(2)  Ensures that the allocated controls operate in a coordinated and mutually reinforcing manner.</p><p><strong><u>OT Systems Only:</strong></u> Defense in depth is considered a common practice for security architecture within OT environments. </p><p>Related Controls: SC-2, SC-3</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Defense in depth is considered a common practice for security architecture within OT environments. </p>', N'Planning', N'Security and Privacy Architectures', NULL, NULL, N'WMATA', NULL, NULL, NULL, 34, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37812, N'PL-9', N'Centrally manage [Assignment: organization-defined controls and related processes].', N'<p><strong>WMATA Policy</strong></p><p>Organizational common (inherited) controls and related processes shall be centrally managed. Systems shall employ to the maximum extent possible organizational common (inherited) controls and all deviations shall be approved by the AO.</p><p><strong><u>OT Systems Only:</strong></u> If the architecture allows, consider centrally managing flaw remediation, malicious code protection, logging, incident detection, etc. </p><p>Related Controls: PL-8, PM-9</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: If the architecture allows for it, consider centrally managing flaw remediation, malicious code protection, logging, and incident detection.</p>', N'Planning', N'Central Management', NULL, NULL, N'WMATA', NULL, NULL, NULL, 34, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37813, N'PM-1', N'a. Develop and disseminate an organization-wide information security program plan that:     1. Provides an overview of the requirements for the security program and a description of the security program management controls and      common controls in place or planned for meeting those requirements;     2. Includes the identification and assignment of roles, responsibilities, management commitment, coordination among organizational entities,      and compliance;     3. Reflects the coordination among organizational entities responsible for information security; and     4. Is approved by a senior official with responsibility and accountability for the risk being incurred to organizational operations (including      mission, functions, image, and reputation), organizational assets, individuals, other organizations, and the Nation;b. Review and update the organization-wide information security program plan [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; andc. Protect the information security program plan from unauthorized disclosure and modification.', N'<p><strong>WMATA Policy</strong></p><p>a)  Develop and disseminate an organization-wide information security program plan that: </p><p>i)  Provides an overview of the requirements for the security program and a description of the security program management controls and common controls in place or planned for meeting those requirements; </p><p>ii)  Includes the identification and assignment of roles, responsibilities, management commitment, coordination among organizational entities, and compliance; </p><p>iii)  Reflects the coordination among organizational entities responsible for information security; and </p><p>iv)  Is approved by a senior official with responsibility and accountability for the risk being incurred to organizational operations (including mission, functions, image, and reputation), organizational assets, individuals, other organizations, and the Nation; </p><p>b)  Review and update the organization-wide information security program plan [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and </p><p>c)  Protect the information security program plan from unauthorized disclosure and modification. </p><p>Related Controls: PL-2, PM-18, PM-30, RA-9, SI-12, SR-2 </p>', N'Program Management', N'Information Security Program Plan', NULL, NULL, N'WMATA', NULL, NULL, NULL, 69, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37814, N'PM-10', N'a. Manage the security and privacy state of organizational systems and the environments in which those systems operate through authorization processes;b. Designate individuals to fulfill specific roles and responsibilities within the organizational risk management process; andc. Integrate the authorization processes into an organization-wide risk management program.', N'<p><strong>WMATA Policy</strong></p><p>(a) Manage the security and privacy state of organizational systems and the environments in which those systems operate through authorization processes; </p><p>(b) Designate individuals to fulfill specific roles and responsibilities within the organizational risk management process; and </p><p>(c) Integrate the authorization processes into an organization-wide risk management program.</p><p>Related Controls: CA-6, CA-7, PL-2</p>', N'Program Management', N'Authorization Process', NULL, NULL, N'WMATA', NULL, NULL, NULL, 69, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37815, N'PM-11', N'a. Define organizational mission and business processes with consideration for information security and privacy and the resulting risk to organizational operations, organizational assets, individuals, other organizations, and the Nation; andb. Determine information protection and personally identifiable information processing needs arising from the defined mission and business processes; andc. Review and revise the mission and business processes [Assignment: organization-defined frequency].', N'<p><strong>WMATA Policy</strong></p><p>(a) Define organizational mission and business processes with consideration for information security and privacy and the resulting risk to organizational operations, organizational assets, individuals, and other organizations; </p><p>(b) Determine information protection and sensitive information processing needs arising from the defined mission and business processes; and </p><p>(c) Review and revise the mission and business processes annually or as required.</p><p>Related Controls: CP-2, PL-2, PM-7, PM-8, RA-2, RA-3, RA-9, SA-2</p>', N'Program Management', N'Mission and Business Process Definition', NULL, NULL, N'WMATA', NULL, NULL, NULL, 69, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37816, N'PM-12', N'Implement an insider threat program that includes a cross-discipline insider threat incident handling team.', N'<p><strong>WMATA Policy</strong></p><p>Implement an insider threat program that includes a cross-discipline insider threat incident handling team.</p><p>Related Controls: AC-6, AT-2, AU-6, AU-7, AU-10, AU-12, CA-7, IA-4, IR-4, MP-7, PE-2, PM-14, PM-16, PS-3, PS-4, PS-5, PS-7, PS-8, SC-7, SI-4</p>', N'Program Management', N'Insider Threat Program', NULL, NULL, N'WMATA', NULL, NULL, NULL, 69, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37817, N'PM-13', N'Establish a security and privacy workforce development and improvement program.', N'<p><strong>WMATA Policy</strong></p><p>Establish a security and privacy workforce development and improvement program.</p><p>Related Controls: AT-2, AT-3</p>', N'Program Management', N'Security and Privacy Workforce', NULL, NULL, N'WMATA', NULL, NULL, NULL, 69, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37818, N'PM-14', N'a. Implement a process for ensuring that organizational plans for conducting security and privacy testing, training, and monitoring activities associated with organizational systems:     1. Are developed and maintained; and     2. Continue to be executed; andb. Review testing, training, and monitoring plans for consistency with the organizational risk management strategy and organization-wide priorities for risk response actions.', N'<p><strong>WMATA Policy</strong></p><p>a) Implement a process for ensuring that organizational plans for conducting security and privacy testing, training, and monitoring activities associated with organizational systems: </p><p>i) Are developed and maintained; and</p><p>ii) Continue to be executed; and </p><p>b) Review testing, training, and monitoring plans for consistency with the organizational risk management strategy and organization-wide priorities for risk response actions. </p><p>Related Controls: AT-2, AT-3, CA-7, CP-4, IR-3, PM-12, SI-4</p>', N'Program Management', N'Testing, Training, and Monitoring', NULL, NULL, N'WMATA', NULL, NULL, NULL, 69, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37819, N'PM-15', N'Establish and institutionalize contact with selected groups and associations within the security and privacy communities:a. To facilitate ongoing security and privacy education and training for organizational personnel;b. To maintain currency with recommended security and privacy practices, techniques, and technologies; andc. To share current security and privacy information, including threats, vulnerabilities, and incidents.', N'<p><strong>WMATA Policy</strong></p><p>Establish and institutionalize contact with selected groups and associations within the security and privacy communities: </p><p>a) To facilitate ongoing security and privacy education and training for organizational personnel; </p><p>b) To maintain currency with recommended security and privacy practices, techniques, and technologies; and </p><p>c) To share current security and privacy information, including threats, vulnerabilities, and incidents. </p><p><strong><u>OT Systems Only:</strong></u> Organizations should be familiar with relevant security-focused and industry-specific groups or associations, including government sector specific agencies (SSAs), information sharing and analysis centers (ISAC), and industry trade organizations.</p><p>Related Controls: SA-11, SI-5</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Organizations should be familiar with relevant security-focused and industryspecific groups or associations, including government sector-specific agencies (SSAs), Information Sharing and Analysis Centers (ISACs), and industry trade organizations.</p>', N'Program Management', N'Security and Privacy Groups and Associations', NULL, NULL, N'WMATA', NULL, NULL, NULL, 69, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37820, N'PM-16', N'Implement a threat awareness program that includes a cross-organization information-sharing capability for threat intelligence.', N'<p><strong>WMATA Policy</strong></p><p>Implement a threat awareness program that includes a cross-organization information-sharing capability for threat intelligence; suitable for addressing policy directives satisfying CISA data reporting standards.</p><p><strong><u>OT Systems Only:</strong></u> The organization should collaborate and share information about potential incidents on a timely basis. CISA serves as a centralized location where operational elements involved in cybersecurity and communications reliance are coordinated and integrated. Organizations should consider having both an unclassified and classified information sharing capability.</p><p>Related Controls: IR-4, PM-12</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: The organization should collaborate and share information about potential incidents on a timely basis. CISA serves as a centralized location where operational elements involved in cybersecurity and communications reliance are coordinated and integrated. Organizations should consider having both an unclassified and classified information sharing  capability. </p>', N'Program Management', N'Threat Awareness Program', NULL, NULL, N'WMATA', NULL, NULL, NULL, 69, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37821, N'PM-16 (1)', N'Employ automated mechanisms to maximize the effectiveness of sharing threat intelligence information.', N'<p><strong>WMATA Policy</strong></p><p>(i)  Employ automated mechanisms to maximize the effectiveness of sharing threat intelligence information.</p>', N'Program Management', N'Threat Awareness Program', NULL, NULL, N'WMATA', NULL, NULL, NULL, 69, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37822, N'PM-17', N'a. Establish policy and procedures to ensure that requirements for the protection of controlled unclassified information that is processed, stored or transmitted on external systems, are implemented in accordance with applicable laws, executive orders, directives, policies, regulations, and standards; andb. Review and update the policy and procedures [Assignment: organization-defined frequency].', N'<p><strong>WMATA Policy</strong></p><p>a) Establish policy and procedures to ensure that requirements for the protection of controlled unclassified information that is processed, stored or transmitted on external systems, are implemented in accordance with applicable laws, executive orders, directives, policies, regulations, and standards; and </p><p>b) Review and update the policy and procedures [Assignment: organization-defined frequency]. </p><p><strong><u>OT Systems Only:</strong></u> This control applies to federal organizations and other organizations supporting the government that process Controlled Unclassified Information (CUI).</p><p>Related Controls: CA-6, PM-10</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: This control applies to federal agencies and other organizations that support the Government and process controlled unclassified information (CUI).</p>', N'Program Management', N'Protecting Controlled Unclassified Information on External Systems', NULL, NULL, N'WMATA', NULL, NULL, NULL, 69, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37823, N'PM-18', N'a. Develop and disseminate an organization-wide privacy program plan that provides an overview of the agency’s privacy program, and:     1. Includes a description of the structure of the privacy program and the resources dedicated to the privacy program;     2. Provides an overview of the requirements for the privacy program and a description of the privacy program management controls and      common controls in place or planned for meeting those requirements;     3. Includes the role of the senior agency official for privacy and the identification and assignment of roles of other privacy officials and staff and      their responsibilities;     4. Describes management commitment, compliance, and the strategic goals and objectives of the privacy program;     5. Reflects coordination among organizational entities responsible for the different aspects of privacy; and     6. Is approved by a senior official with responsibility and accountability for the privacy risk being incurred to organizational operations (including      mission, functions, image, and reputation), organizational assets, individuals, other organizations, and the Nation; andb. Update the plan [Assignment: organization-defined frequency] and to address changes in federal privacy laws and policy and organizational changes and problems identified during plan implementation or privacy control assessments.', N'<p><strong>WMATA Policy</strong></p><p>a) Develop and disseminate an organization-wide privacy program plan that provides an overview of the agency’s privacy program, and:</p><p>i) Includes a description of the structure of the privacy program and the resources dedicated to the privacy program; </p><p>ii) Provides an overview of the requirements for the privacy program and a description of the privacy program management controls and common controls in place or planned for meeting those requirements; </p><p>iii) Includes the role of the senior agency official for privacy and the identification and assignment of roles of other privacy officials and staff and their responsibilities; </p><p>iv) Describes management commitment, compliance, and the strategic goals and objectives of the privacy program; </p><p>v) Reflects coordination among organizational entities responsible for the different aspects of privacy; and </p><p>vi) Is approved by a senior official with responsibility and accountability for the privacy risk being incurred to organizational operations (including mission, functions, image, and reputation), organizational assets, individuals, other organizations, and the Nation; and </p><p>b) Update the plan [Assignment: organization-defined frequency] and to address changes in federal privacy laws and policy and organizational changes and problems identified during plan implementation or privacy control assessments. </p><p>Related Controls: PM-8, PM-9, PM-19</p>', N'Program Management', N'Privacy Program Plans', NULL, NULL, N'WMATA', NULL, NULL, NULL, 69, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37824, N'PM-19', N'Appoint a senior agency official for privacy with the authority, mission, accountability, and resources to coordinate, develop, and implement, applicable privacy requirements and manage privacy risks through the organization-wide privacy program.', N'<p><strong>WMATA Policy</strong></p><p>Appoint a senior agency official for privacy with the authority, mission, accountability, and resources to coordinate, develop, and implement, applicable privacy requirements and manage privacy risks through the organization-wide privacy program.</p><p>Related Controls: PM-18, PM-20, PM-23, PM-24, PM-27</p>', N'Program Management', N'Privacy Program Leadership Role', NULL, NULL, N'WMATA', NULL, NULL, NULL, 69, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37825, N'PM-2', N'Appoint a senior agency information security officer with the mission and resources to coordinate, develop, implement, and maintain an organization-wide information security program.', N'<p><strong>WMATA Policy</strong></p><p>Appoint a senior agency information security officer with the mission and resources to coordinate, develop, implement, and maintain an organization-wide information security program.</p>', N'Program Management', N'Information Security Program Leadership Role', NULL, NULL, N'WMATA', NULL, NULL, NULL, 69, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37826, N'PM-20', N'Maintain a central resource webpage on the organization’s principal public website that serves as a central source of information about the organization’s privacy program and that:a. Ensures that the public has access to information about organizational privacy activities and can communicate with its senior agency official for privacy;b. Ensures that organizational privacy practices and reports are publicly available; andc. Employs publicly facing email addresses and/or phone lines to enable the public to provide feedback and/or direct questions to privacy offices regarding privacy practices.', N'<p><strong>WMATA Policy</strong></p><p>Maintain a central resource webpage on the organization’s principal public website that serves as a central source of information about the organization’s privacy program and that: </p><p>a) Ensures that the public has access to information about organizational privacy activities and can communicate with its senior agency official for privacy; </p><p>b) Ensures that organizational privacy practices and reports are publicly available; and </p><p>c) Employs publicly facing email addresses and/or phone lines to enable the public to provide feedback and/or direct questions to privacy offices regarding privacy practices. </p><p>Related Controls: AC-3, PM-19, PT-5, PT-6, PT-7, RA-8</p>', N'Program Management', N'Dissemination of Privacy Program Information', NULL, NULL, N'WMATA', NULL, NULL, NULL, 69, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37827, N'PM-21', N'a. Develop and maintain an accurate accounting of disclosures of personally identifiable information, including:     1. Date, nature, and purpose of each disclosure; and     2. Name and address, or other contact information of the individual or organization to which the disclosure was made;b. Retain the accounting of disclosures for the length of the time the personally identifiable information is maintained or five years after the disclosure is made, whichever is longer; andc. Make the accounting of disclosures available to the individual to whom the personally identifiable information relates upon request.', N'<p><strong>WMATA Policy</strong></p><p>a) Develop and maintain an accurate accounting of disclosures of personally identifiable information, including: </p><p>i) Date, nature, and purpose of each disclosure; and </p><p>ii) Name and address, or other contact information of the individual or organization to which the disclosure was made; </p><p>b) Retain the accounting of disclosures for the length of the time the personally identifiable information is maintained or five years after the disclosure is made, whichever is longer; and </p><p>c) Make the accounting of disclosures available to the individual to whom the personally identifiable information relates upon request. </p><p>Related Controls: AC-3, AU-2, PT-2</p>', N'Program Management', N'Accounting of Disclosures', NULL, NULL, N'WMATA', NULL, NULL, NULL, 69, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37828, N'PM-22', N'Develop and document organization-wide policies and procedures for:a. Reviewing for the accuracy, relevance, timeliness, and completeness of personally identifiable information across the information life cycle;b. Correcting or deleting inaccurate or outdated personally identifiable information;c. Disseminating notice of corrected or deleted personally identifiable information to individuals or other appropriate entities; andd. Appeals of adverse decisions on correction or deletion requests.', N'<p><strong>WMATA Policy</strong></p><p>a) Develop and document organization-wide policies and procedures for: </p><p>i) Reviewing for the accuracy, relevance, timeliness, and completeness of personally identifiable information across the information life cycle; </p><p>ii) Correcting or deleting inaccurate or outdated personally identifiable information; </p><p>iii) Disseminating notice of corrected or deleted personally identifiable information to individuals or other appropriate entities; and </p><p>iv) Appeals of adverse decisions on correction or deletion requests. </p><p>Related Controls: PM-23, SI-18</p>', N'Program Management', N'Personally Identifiable Information Quality Management', NULL, NULL, N'WMATA', NULL, NULL, NULL, 69, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37829, N'PM-23', N'Establish a Data Governance Body consisting of [Assignment: organization-defined roles] with [Assignment: organization-defined responsibilities].', N'<p><strong>WMATA Policy</strong></p><p>(a) Establish a Data Governance Body minimally consisting of Chief Digital Officer and Chief Information Security Officer with responsibility for: </p><p>(1) Establishing policies, procedures, and standards that facilitate data governance so that data, including PII, is effectively managed and maintained in accordance with applicable laws, executive orders, directives, regulations, policies, standards, and guidance; and </p><p>(2) Developing and implementing guidelines that support data modeling, quality, integrity, and the de-identification needs of PII across the information life cycle as well as reviewing and approving applications to release data outside of the organization, archiving the applications and the released data, and performing post-release monitoring to ensure that the assumptions made as part of the data release continue to be valid.</p><p>Related Controls: AT-2, AT-3, PM-19, PM-22, PM-24, PT-7, SI-4, SI-19</p>', N'Program Management', N'Data Governance Body', NULL, NULL, N'WMATA', NULL, NULL, NULL, 69, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37830, N'PM-24', N'Establish a Data Integrity Board to:a. Review proposals to conduct or participate in a matching program; andb. Conduct an annual review of all matching programs in which the agency has participated.', N'<p><strong>WMATA Policy</strong></p><p>Establish a Data Integrity Board to: </p><p>a) Review proposals to conduct or participate in a matching program; and </p><p>b) Conduct an annual review of all matching programs in which the agency has participated. </p><p>Related Controls: AC-4, PM-19, PM-23, PT-2, PT-8</p>', N'Program Management', N'Data Integrity Board', NULL, NULL, N'WMATA', NULL, NULL, NULL, 69, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37831, N'PM-25', N'a. Develop, document, and implement policies and procedures that address the use of personally identifiable information for internal testing, training, and research;b. Limit or minimize the amount of personally identifiable information used for internal testing, training, and research purposes;c. Authorize the use of personally identifiable information when such information is required for internal testing, training, and research; andd. Review and update policies and procedures [Assignment: organization-defined frequency].', N'<p><strong>WMATA Policy</strong></p><p>Implement a process for receiving and responding to complaints, concerns, or questions from individuals about the organizational security and privacy practices that includes:</p><p>a) Develop, document, and implement policies and procedures that address the use of personally identifiable information for internal testing, training, and research; </p><p>b) Limit or minimize the amount of personally identifiable information used for internal testing, training, and research purposes; </p><p>c) Authorize the use of personally identifiable information when such information is required for internal testing, training, and research; and </p><p>d) Review and update policies and procedures [Assignment: organization-defined frequency]. </p><p>Related Controls: PM-23, PT-3, SA-3, SA-8, SI-12</p>', N'Program Management', N'Minimization of PII Used In Testing, Training, and Research', NULL, NULL, N'WMATA', NULL, NULL, NULL, 69, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37832, N'PM-26', N'Implement a process for receiving and responding to complaints, concerns, or questions from individuals about the organizational security and privacy practices that includes:a. Mechanisms that are easy to use and readily accessible by the public;b. All information necessary for successfully filing complaints;c. Tracking mechanisms to ensure all complaints received are reviewed and addressed within [Assignment: organization-defined time period];d. Acknowledgement of receipt of complaints, concerns, or questions from individuals within [Assignment: organization-defined time period]; ande. Response to complaints, concerns, or questions from individuals within [Assignment: organization-defined time period].', N'<p><strong>WMATA Policy</strong></p><p>Implement a process for receiving and responding to complaints, concerns, or questions from individuals about the organizational security and privacy practices that includes: </p><p>a)  Mechanisms that are easy to use and readily accessible by the public; </p><p>b)  All information necessary for successfully filing complaints; </p><p>c)  Tracking mechanisms to ensure all complaints received are reviewed and addressed within [Assignment: organization-defined time period]; </p><p>d)  Acknowledgement of receipt of complaints, concerns, or questions from individuals within [Assignment: organization-defined time period]; and </p><p>e)  Response to complaints, concerns, or questions from individuals within [Assignment: organization-defined time period]. </p><p>Related Controls: IR-7, IR-9, PM-22, SI-18</p>', N'Program Management', N'Complaint Management', NULL, NULL, N'WMATA', NULL, NULL, NULL, 69, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37833, N'PM-27', N'a. Develop [Assignment: organization-defined privacy reports] and disseminate to:     1. [Assignment: organization-defined oversight bodies] to demonstrate accountability with statutory, regulatory, and policy privacy mandates;      and     2. [Assignment: organization-defined officials] and other personnel with responsibility for monitoring privacy program compliance; andb. Review and update privacy reports [Assignment: organization-defined frequency].', N'<p><strong>WMATA Policy</strong></p><p>Develop [Assignment: organization-defined privacy reports] and disseminate to: </p><p>a)  [Assignment: organization-defined oversight bodies] to demonstrate accountability with statutory, regulatory, and policy privacy mandates; and </p><p>b)  [Assignment: organization-defined officials] and other personnel with responsibility for monitoring privacy program compliance; and </p><p>c) Review and update privacy reports [Assignment: organization-defined frequency].  </p><p>Related Controls: IR-9, PM-19</p>', N'Program Management', N'Privacy Reporting', NULL, NULL, N'WMATA', NULL, NULL, NULL, 69, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37834, N'PM-28', N'a. Identify and document:     1. Assumptions affecting risk assessments, risk responses, and risk monitoring;     2. Constraints affecting risk assessments, risk responses, and risk monitoring;     3. Priorities and trade-offs considered by the organization for managing risk; and     4. Organizational risk tolerance;b. Distribute the results of risk framing activities to [Assignment: organization-defined personnel]; andc. Review and update risk framing considerations [Assignment: organization-defined frequency].', N'<p><strong>WMATA Policy</strong></p><p>(a) Identify and document: </p><p>(1) Assumptions affecting risk assessments, risk responses, and risk monitoring; </p><p>(2) Constraints affecting risk assessments, risk responses, and risk monitoring; </p><p>(3) Priorities and trade-offs considered by the organization for managing risk; and </p><p>(4) Organizational risk tolerance; </p><p>(b) Distribute the results of risk framing activities to organizational personnel, including mission and business owners, information owners or stewards, system owners, the authorizing official, Chief Information Security Officer, and Chief Risk Officer; and </p><p>(c) Review and update risk framing considerations annually.</p><p>Related Controls: CA-7, PM-9, RA-3, RA-7</p>', N'Program Management', N'Risk Framing', NULL, NULL, N'WMATA', NULL, NULL, NULL, 69, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37835, N'PM-29', N'a. Appoint a Senior Accountable Official for Risk Management to align organizational information security and privacy management processes with strategic, operational, and budgetary planning processes; andb. Establish a Risk Executive (function) to view and analyze risk from an organization-wide perspective and ensure management of risk is consistent across the organization.', N'<p><strong>WMATA Policy</strong></p><p>(a) Designate an Authorizing Official to align organizational information security and privacy management processes with strategic, operational, and budgetary planning processes; and  </p><p>(i) Appoint a Senior Accountable Official for Risk Management to align organizational information security and privacy management processes with strategic, operational, and budgetary planning processes; and </p><p>(b) Designate a Chief Risk Officer to view and analyze risk from an organization-wide perspective and ensure management of risk is consistent across the organization.</p><p>(i) Establish a Risk Executive (function) to view and analyze risk from an organization-wide perspective and ensure management of risk is consistent across the organization. <br>	<br>Related Controls: PM-2, PM-19</p>', N'Program Management', N'Risk Management Program Leadership Roles', NULL, NULL, N'WMATA', NULL, NULL, NULL, 69, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37836, N'PM-3', N'a. Include the resources needed to implement the information security and privacy programs in capital planning and investment requests and document all exceptions to this requirement;b. Prepare documentation required for addressing information security and privacy programs in capital planning and investment requests in accordance with applicable laws, executive orders, directives, policies, regulations, standards; andc. Make available for expenditure, the planned information security and privacy resources.', N'<p><strong>WMATA Policy</strong></p><p>a) Include the resources needed to implement the information security and privacy programs in capital planning and investment requests and document all exceptions to this requirement; </p><p>b) Prepare documentation required for addressing information security and privacy programs in capital planning and investment requests in accordance with applicable laws, executive orders, directives, policies, regulations, standards; and </p><p>c) Make available for expenditure, the planned information security and privacy resources. </p><p>Related Controls: PM-4, SA-2</p>', N'Program Management', N'Information Security and Privacy Resources', NULL, NULL, N'WMATA', NULL, NULL, NULL, 69, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37837, N'PM-30', N'a. Develop an organization-wide strategy for managing supply chain risks associated with the development, acquisition, maintenance, and disposal of systems, system components, and system services;b. Implement the supply chain risk management strategy consistently across the organization; andc. Review and update the supply chain risk management strategy on [Assignment: organization-defined frequency] or as required, to address organizational changes.', N'<p><strong>WMATA Policy</strong></p><p>(a) Develop an organization-wide strategy for managing supply chain risks associated with the development, acquisition, maintenance, and disposal of systems, system components, and system services; </p><p>(b) Implement the supply chain risk management strategy consistently across the organization; </p><p>(c) Review and update the supply chain risk management strategy annually or as required, to address organizational changes; and </p><p>(d) Align all cybersecurity related supply chain risk management strategy to the Chief Information Security Officer and incorporate cybersecurity requirements into the enterprise supply chain risk management strategy as determined by the Chief Information Security Officer: </p><p>Related Controls: CM-10, PM-9, SR-1, SR-2, SR-3, SR-4, SR-5, SR-6, SR-7, SR-8, SR-9, SR-11</p>', N'Program Management', N'Supply Chain Risk Management Strategy', NULL, NULL, N'WMATA', NULL, NULL, NULL, 69, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37838, N'PM-30 (1)', N'Identify, prioritize, and assess suppliers of critical or mission-essential technologies, products, and services.', N'<p><strong>WMATA Policy</strong></p><p>(i)  Identify, prioritize, and assess suppliers of critical or mission-essential technologies, products, and services.</p>', N'Program Management', N'Supply Chain Risk Management Strategy', NULL, NULL, N'WMATA', NULL, NULL, NULL, 69, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37839, N'PM-31', N'Develop an organization-wide continuous monitoring strategy and implement continuous monitoring programs that include:a. Establishing the following organization-wide metrics to be monitored: [Assignment: organization-defined metrics];b. Establishing [Assignment: organization-defined frequencies] for monitoring and [Assignment: organization-defined frequencies] for assessment of control effectiveness;c. Ongoing monitoring of organizationally-defined metrics in accordance with the continuous monitoring strategy;d. Correlation and analysis of information generated by control assessments and monitoring;e. Response actions to address results of the analysis of control assessment and monitoring information; andf. Reporting the security and privacy status of organizational systems to [Assignment: organization-defined personnel or roles] [Assignment: organization-defined frequency].', N'<p><strong>WMATA Policy</strong></p><p>Develop an organization-wide continuous monitoring strategy and implement continuous monitoring programs that include: </p><p>(a) Establishing the following organization-wide metrics to be monitored: </p><p>(1) Scan coverage; <br>(2) Vulnerability management; <br>(3) Incident management; <br>(4) Patch management; <br>(5) Configuration management; <br>(6) Change management; <br>(7) Application security; <br>(8) Financial metrics; <br>(9) IT awareness and training; </p><p>(b) Establishing control review frequencies for monitoring and document such frequencies in policy and review continuous monitoring requirements annually for assessment of control effectiveness; </p><p>(c) Ongoing monitoring of organizationally defined metrics in accordance with the continuous monitoring strategy; </p><p>(d) Correlation and analysis of information generated by control assessments and monitoring; </p><p>(e) Response actions to address results of the analysis of control assessment and monitoring information; and </p><p>(f) Reporting the security and privacy status of organizational systems to executive management and the board of directors quarterly.</p><p>Related Controls: AC-2, AC-6, AC-17, AT-4, AU-6, CA-2, CA-5, CA-6, CA-7, CM-3, CM-4, CM-6, CM-11, IA-5, IR-5, MA-2, MA-3, MA-4, PE-3, PE-6, PE-14, PE-16, PL-2, PM-4, PM-6, PM-9, PM-10, PM-12, PM-14, PM-23, PM-28, PS-7, PT-7, RA-3, RA-5, RA-7, SA-9, SA-11, SC-5, SC-7, SC-18, SI-3, SI-4, SI-12, SR-2, SR-4</p>', N'Program Management', N'Continuous Monitoring Strategy', NULL, NULL, N'WMATA', NULL, NULL, NULL, 69, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37840, N'PM-32', N'Analyze [Assignment: organization-defined systems or systems components] supporting mission essential services or functions to ensure that the information resources are being used consistent with their intended purpose.', N'<p><strong>WMATA Policy</strong></p><p>Analyze systems categorized by Digital Modernization Cyber Security as critical to supporting mission essential services or functions to ensure that the information resources are being used consistent with their intended purpose.</p><p>Related Controls: CA-7, PL-2, RA-3, RA-9</p>', N'Program Management', N'Purposing', NULL, NULL, N'WMATA', NULL, NULL, NULL, 69, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37841, N'PM-4', N'a. Implement a process to ensure that plans of action and milestones for the information security, privacy, and supply chain risk management programs and associated organizational systems:     1. Are developed and maintained;     2. Document the remedial information security, privacy, and supply chain risk management actions to adequately respond to risk to      organizational operations and assets, individuals, other organizations, and the Nation; and     3. Are reported in accordance with established reporting requirements.b. Review plans of action and milestones for consistency with the organizational risk management strategy and organization-wide priorities for risk response actions.', N'<p><strong>WMATA Policy</strong></p><p>a) Implement a process to ensure that plans of action and milestones for the information security, privacy, and supply chain risk management programs and associated organizational systems: </p><p>i) Are developed and maintained; </p><p>ii) Document the remedial information security, privacy, and supply chain risk management actions to adequately respond to risk to organizational operations and assets, individuals, other organizations, and the Nation; and </p><p>iii) Are reported in accordance with established reporting requirements. </p><p>b) Review plans of action and milestones for consistency with the organizational risk management strategy and organization-wide priorities for risk response actions. </p><p>Related Controls: CA-5, CA-7, PM-3, RA-7, SI-12</p>', N'Program Management', N'Plan Of Action And Milestones Process', NULL, NULL, N'WMATA', NULL, NULL, NULL, 69, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37842, N'PM-5', N'Develop and update [Assignment: organization-defined frequency] an inventory of organizational systems.', N'<p><strong>WMATA Policy</strong></p><p>(a) Develop and update quarterly an inventory of organizational systems. </p>', N'Program Management', N'System Inventory', NULL, NULL, N'WMATA', NULL, NULL, NULL, 69, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37843, N'PM-5 (1)', N'Establish, maintain, and update [Assignment: organization-defined frequency] an inventory of all systems, applications, and projects that process personally identifiable information.', N'<p><strong>WMATA Policy</strong></p><p>(i)  Establish, maintain, and update quarterly inventory of all systems, applications, and projects that process sensitive information.</p>', N'Program Management', N'System Inventory', NULL, NULL, N'WMATA', NULL, NULL, NULL, 69, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37844, N'PM-6', N'Develop, monitor, and report on the results of information security and privacy measures of performance.', N'<p><strong>WMATA Policy</strong></p><p>Develop, monitor, and report on the results of information security and privacy measures of performance.</p>', N'Program Management', N'Measures of Performance', NULL, NULL, N'WMATA', NULL, NULL, NULL, 69, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37845, N'PM-7', N'Develop and maintain an enterprise architecture with consideration for information security, privacy, and the resulting risk to organizational operations and assets, individuals, other organizations, and the Nation.', N'<p><strong>WMATA Policy</strong></p><p>Develop and maintain an enterprise architecture with consideration for information security, privacy, and the resulting risk to organizational operations and assets, individuals, other organizations, and the Nation</p><p>Related Controls: AU-6, PL-2, PL-8, PM-11, RA-2, SA-3, SA-8, SA-17</p>', N'Program Management', N'Enterprise Architecture', NULL, NULL, N'WMATA', NULL, NULL, NULL, 69, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37846, N'PM-7 (1)', N'Offload [Assignment: organization-defined non-essential functions or services] to other systems, system components, or an external provider.', N'<p><strong>WMATA Policy</strong></p><p>(i)  Offload printing, copying, or any non-essential functions or services to other systems, system components, or an external provider. Non-essential functions or services are those which, whenever feasible, are not co-located with the functions or services that support essential mission or business functions. Maintaining such functions on the same system or system component increases the attack surface of the organization’s mission-essential functions or services.</p>', N'Program Management', N'Enterprise Architecture', NULL, NULL, N'WMATA', NULL, NULL, NULL, 69, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37847, N'PM-8', N'Address information security and privacy issues in the development, documentation, and updating of a critical infrastructure and key resources protection plan.', N'<p><strong>WMATA Policy</strong></p><p>Address information security and privacy issues in the development, documentation, and updating of a critical infrastructure and key resources protection plan.</p><p><strong><u>OT Systems Only:</strong></u> Organizations should be familiar with protection requirements and guidance defined by executive orders, government sector specific agencies (SSAs), and industry trade organizations.</p><p>Related Controls: CP-2, CP-4, PE-18, PL-2, PM-9, PM-11, PM-18, RA-3, SI-12</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Organizations should be familiar with the protection requirements and guidance defined by Executive Orders, government sector-specific agencies (SSAs), and industry trade organizations. </p>', N'Program Management', N'Critical Infrastructure Plan', NULL, NULL, N'WMATA', NULL, NULL, NULL, 69, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37848, N'PM-9', N'a. Develops a comprehensive strategy to manage:     1. Security risk to organizational operations and assets, individuals, other organizations, and the Nation associated with the operation and use      of organizational systems; and     2. Privacy risk to individuals resulting from the authorized processing of personally identifiable information;b. Implement the risk management strategy consistently across the organization; andc. Review and update the risk management strategy [Assignment: organization-defined frequency] or as required, to address organizational changes.', N'<p><strong>WMATA Policy</strong></p><p>a) Develops a comprehensive strategy to manage: </p><p>i) Security risk to organizational operations and assets, individuals, other organizations, and the Nation associated with the operation and use of organizational systems; and </p><p>ii) Privacy risk to individuals resulting from the authorized processing of personally identifiable information; </p><p>b) Implement the risk management strategy consistently across the organization; and </p><p>c) Review and update the risk management strategy [Assignment: organization-defined frequency] or as required, to address organizational changes. </p><p>Related Controls: AC-1, AT-1, AU-1, CA-1, CA-2, CA-5, CA-6, CA-7, CM-1, CP-1, IA-1, IR-1, MA-1, MP-1, PE-1, PL-1, PL-2, PM-2, PM-8, PM-18, PM-28, PM-30, PS-1, PT-1, PT-2, PT-3, RA-1, RA-3, RA-9, SA-1, SA-4, SC-1, SI-1, SI-12, SR-1, SR-2</p>', N'Program Management', N'Risk Management Strategy', NULL, NULL, N'WMATA', NULL, NULL, NULL, 69, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37849, N'PS-1', N'a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:     1. [Selection (one or more): Organization-level; Mission/business process-level; System-level] personnel security policy that:          (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and           compliance; and          (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and      2. Procedures to facilitate the implementation of the personnel security policy and the associated personnel security controls;b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the personnel security policy and procedures; andc. Review and update the current personnel security:     1. Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and     2. Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].', N'<p><strong>WMATA Policy</strong></p><p>Reference P/I 15.28 Cybersecurity Policy for requirements.</p><p>Related Controls: PM-9, PS-8, SI-12</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: The policy specifically addresses the unique properties and requirements of OT and the relationship to non-OT systems.</p>', N'Personnel Security', N'Personnel Security Policy and Procedures', NULL, NULL, N'WMATA', NULL, NULL, NULL, 67, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37850, N'PS-2', N'a. Assign a risk designation to all organizational positions;b. Establish screening criteria for individuals filling those positions; andc. Review and update position risk designations [Assignment: organization-defined frequency].', N'<p><strong>WMATA Policy</strong></p><p>a. Assign a risk designation to all organizational positions;</p><p>b. Establish screening criteria for individuals filling those positions; and</p><p>c. Review and update position risk designations annually.</p><p><strong><u>OT Systems Only:</strong></u> Private organizations should utilize existing sector specific regulations, laws, policy, or guidance for determining appropriate risk designations for positions. </p><p>Related Controls: AC-5, AT-3, PE-2, PE-3, PL-2, PS-3, PS-6, SA-5, SA-21, SI-12</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Private organizations should utilize existing sector-specific regulations, laws, policy, and guidance for determining appropriate risk designations for positions.</p>', N'Personnel Security', N'Position Risk Designation', NULL, NULL, N'WMATA', NULL, NULL, NULL, 67, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37851, N'PS-3', N'a. Screen individuals prior to authorizing access to the system; andb. Rescreen individuals in accordance with [Assignment: organization-defined conditions requiring rescreening and, where rescreening is so indicated, the frequency of rescreening].', N'<p><strong>WMATA Policy</strong></p><p>a. Determine screening tiers and requirements based on the sensitivity of the position;</p><p>b. Screen individuals prior to authorizing access to the system;</p><p>c. Rescreen individuals every five years;</p><p>d. Conduct continuous screening for defined factors for sensitive positions; and</p><p>e. Notify employees of screening criteria, and when updates are made to the screening criteria, prior to screening.</p><p>Related Controls: AC-2, IA-4, MA-5, PE-2, PM-12, PS-2, PS-6, PS-7, SA-21</p>', N'Personnel Security', N'Personnel Screening', NULL, NULL, N'WMATA', NULL, NULL, NULL, 67, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37852, N'PS-4', N'Upon termination of individual employment:a. Disable system access within [Assignment: organization-defined time period];b. Terminate or revoke any authenticators and credentials associated with the individual;c. Conduct exit interviews that include a discussion of [Assignment: organization-defined information security topics];d. Retrieve all security-related organizational system-related property; ande. Retain access to organizational information and systems formerly controlled by terminated individual.', N'<p><strong>WMATA Policy</strong></p><p>Upon termination of individual employment:</p><p>a. Provide appropriate notification and disable physical and logical access to all systems in <br>accordance with:</p><p>i)  Control 3.1 Access Control, Section 2, “AC-2 Account Management";</p><p>ii) Control 3.1 Access Control, Section 2, (l), (iii), “AC-2 (3) Disable Accounts”;</p><p>iii) Control 3.1 Access Control, Section 2, (l), (viii), “AC-2 (13) Disable Accounts for High-<br>Risk Individuals”; and</p><p>iv) P/I 7.3.3 Separation from Employment Policy.</p><p>b. Terminate or revoke any authenticators and credentials associated with the individual;</p><p>c. Conduct exit interviews that include a discussion of:</p><p>i)  The security constraints imposed by being former employees;</p><p>ii) Receipt/retrieval and accountability of system-related property;</p><p>iii) Reminders of NDAs and potential limitations on future employment; and</p><p>iv) Sensitive personnel matters for involuntary separations in accordance with P/I 7.3.3 Separation from Employment Policy.</p><p>d.  Retrieve all security-related organizational system-related property. System property includes hardware authentication tokens, system administration technical manuals, keys, identification cards, and building passes;</p><p>e. Retrieve all organizational information and property in accordance with P/I 7.3.3 Separation from Employment Policy; and</p><p>f.  Retain access to organizational information and systems formerly controlled by terminated individual.</p><p>Related Controls: AC-2, IA-4, PE-2, PM-12, PS-6, PS-7</p><p>g. Security Controls Enhancement(s):</p>', N'Personnel Security', N'Personnel Termination', NULL, NULL, N'WMATA', NULL, NULL, NULL, 67, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37853, N'PS-4 (2)', N'Use [Assignment: organization-defined automated mechanisms] to [Selection (one or more): notify [Assignment: organization-defined personnel or roles] of individual termination actions; disable access to system resources].', N'<p><strong>WMATA Policy</strong></p><p>Use automated mechanisms to both notify personnel or roles of individual termination actions and to disable access to system resources.</p>', N'Personnel Security', N'Personnel Termination', NULL, NULL, N'WMATA', NULL, NULL, NULL, 67, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37854, N'PS-5', N'a. Review and confirm ongoing operational need for current logical and physical access authorizations to systems and facilities when individuals are reassigned or transferred to other positions within the organization;b. Initiate [Assignment: organization-defined transfer or reassignment actions] within [Assignment: organization-defined time period following the formal transfer action];c. Modify access authorization as needed to correspond with any changes in operational need due to reassignment or transfer; andd. Notify [Assignment: organization-defined personnel or roles] within [Assignment: organization-defined time period].', N'<p><strong>WMATA Policy</strong></p><p>a.  Review and confirm ongoing operational need for current logical and physical access <br>authorizations to systems and facilities when individuals are reassigned or transferred to other positions within the organization;</p><p>b. Initiate transfer or reassignment actions prior to the transfer date;</p><p>c. Modify access authorization as needed to correspond with any changes in operational need due to reassignment or transfer; and</p><p>d. Notify required stakeholders prior to the transfer date.</p><p>Related Controls: AC-2, IA-4, PE-2, PM-12, PS-4, PS-7</p>', N'Personnel Security', N'Personnel Transfer', NULL, NULL, N'WMATA', NULL, NULL, NULL, 67, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37855, N'PS-6', N'a. Develop and document access agreements for organizational systems;b. Review and update the access agreements [Assignment: organization-defined frequency]; andc. Verify that individuals requiring access to organizational information and systems:     1. Sign appropriate access agreements prior to being granted access; and     2. Re-sign access agreements to maintain access to organizational systems when access agreements have been updated or [Assignment:      organization-defined frequency].', N'<p><strong>WMATA Policy</strong></p><p>a. Develop and document access agreements for organizational systems;</p><p>b.  Review and update the access agreements to include NDAs, acceptable use agreements, rules of behavior (RoB), and conflict-of-interest agreements annually, and in accordance with:</p><p>i)  Control 3.15 Planning, Section 3, “PL-4 Rules of Behavior”; and</p><p>ii) Control 3.1 Access Control, Section 8, “AC-8 System Use Notification”.</p><p>c. Verify that individuals requiring access to organizational information and systems:</p><p>i)  Sign appropriate access agreements prior to being granted access; and</p><p>ii) Re-sign access agreements to maintain access to organizational systems annually and when access agreements have been updated.</p><p>Related Controls: AC-8, AC-17, PE-2, PL-4, PS-2, PS-3, PS-6, PS-7, PS-8, SA-21, SI-12</p>', N'Personnel Security', N'Access Agreements', NULL, NULL, N'WMATA', NULL, NULL, NULL, 67, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37856, N'PS-7', N'a. Establish personnel security requirements, including security roles and responsibilities for external providers;b. Require external providers to comply with personnel security policies and procedures established by the organization;c. Document personnel security requirements;d. Require external providers to notify [Assignment: organization-defined personnel or roles] of any personnel transfers or terminations of external personnel who possess organizational credentials and/or badges, or who have system privileges within [Assignment: organization-defined time period]; ande. Monitor provider compliance with personnel security requirements.', N'<p><strong>WMATA Policy</strong></p><p>a. Establish personnel security requirements, including security roles and responsibilities for external providers;</p><p>b. Require external providers to comply with personnel security policies and procedures established by the organization;</p><p>c. Document personnel security requirements;</p><p>d.  External providers shall notify Contract Administrator (CA)/Contracting Officer''s Technical Representative (COTRs) and required stakeholders of any personnel transfers or terminations of external personnel who possess organizational credentials and/or badges or who have system privileges immediately unless otherwise specified in:</p><p>i)  Control 3.1 Access Control, Section 2, “AC-2 Account Management";</p><p>ii) P/I 7.2.2 Recruitment and Hiring Policy; and</p><p>iii) P/I 7.3.3 Separation from Employment Policy.</p><p>e. Monitor provider compliance with personnel security requirements.</p><p>Related Controls: AC-2, AT-2, AT-3, MA-5, PE-3, PS-2, PS-3, PS-4, PS-5, PS-6, SA-5, SA-9, SA-21</p>', N'Personnel Security', N'External Personnel Security', NULL, NULL, N'WMATA', NULL, NULL, NULL, 67, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37857, N'PS-8', N'a. Employ a formal sanctions process for individuals failing to comply with established information security and privacy policies and procedures; andb. Notify [Assignment: organization-defined personnel or roles] within [Assignment: organization-defined time period] when a formal employee sanctions process is initiated, identifying the individual sanctioned and the reason for the sanction.', N'<p><strong>WMATA Policy</strong></p><p>a. Employ a formal sanctions process for individuals failing to comply with established security and privacy policies and procedures; and</p><p>b. Notify the CA and COTR regarding external provider actions and notify appropriate stakeholders based on the nature of the infraction within 24 hours (or less if directed by other policy) when a formal employee sanctions process is initiated, identifying the individual sanctioned and the reason for the sanction.</p><p>Related Controls: All XX-1 Controls, PL-4, PM-12, PS-6, PT-1</p>', N'Personnel Security', N'Personnel Sanctions', NULL, NULL, N'WMATA', NULL, NULL, NULL, 67, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37858, N'PS-9', N'Incorporate security and privacy roles and responsibilities into organizational position descriptions.', N'<p><strong>WMATA Policy</strong></p><p>Incorporate security and privacy roles and responsibilities into organizational position descriptions, as applicable.</p>', N'Personnel Security', N'Position Descriptions', NULL, NULL, N'WMATA', NULL, NULL, NULL, 67, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37859, N'PT-1', N'a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:      1. [Selection (one or more): Organization-level; Mission/business process-level; System-level] personally identifiable information processing       and transparency policy that:          (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and           compliance; and          (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and     2. Procedures to facilitate the implementation of the personally identifiable information processing and transparency policy and the associated      personally identifiable information processing and transparency controls;b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the personally identifiable information processing and transparency policy and procedures; andc. Review and update the current personally identifiable information processing and transparency:     1. Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and     2. Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].', N'<p><strong>WMATA Policy</strong></p><p>Reference P/I 15.28 Cybersecurity Policy for requirements. This control family does not apply to the activities of the Privacy Administrator described in P/I 9.2 Privacy Policy or the PARP Administrator described in P/I 9.3 Public Access to Records Policy.</p>', N'Personally Identifiable Information Processing and Transparency', N'Policy & Procedures', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1086, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37860, N'PT-2', N'a. Determine and document the [Assignment: organization-defined authority] that permits the [Assignment: organization-defined processing] of personally identifiable information; andb. Restrict the [Assignment: organization-defined processing] of personally identifiable information to only that which is authorized.', N'<p><strong>WMATA Policy</strong></p><p>a.  Document all storage, processing, and transmission (includes, but is not limited to, the creation, collection, use, processing, storage, maintenance, dissemination, disclosure, disposal, logging, generation, transformation, analysis, replication, and data mining) of sensitive information in System Security Plan (SSP);</p><p>b.  Obtain approval for the processing of sensitive information as documented in SSP in accordance with Control 3.15 Planning, Section 2, “PL-2 System Security Plans”;</p><p>c.  Restrict the storage, processing, transmission, and replication of sensitive information to only what is authorized in the SSP; and</p><p>d. Ensure all sensitive information is encrypted in storage and in transit, in accordance with:</p><p>i)  Control 3.17, System and Communications Protection, Section 7, (i), “SC-8 (1) Cryptographic Protection”; Section 10, “SC-13 Cryptographic Protection”; Section 19, (i), “SC-28 (1) Cryptographic Protection”; and</p><p>ii) Control 3.5 Contingency Planning, Section 8, “CP-9 System Backup” and (d), (v), “CP-9<br>(8) Cryptographic Protection”.</p><p>Related Controls: AC-2, AC-3, IR-9, PM-9, PM-24, PT-1, PT-3, PT-5, PT-6, RA-3, RA-8, SI-12, SI-18</p>', N'Personally Identifiable Information Processing and Transparency', N'Authority to Process Personally Identifiable Information', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1086, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37861, N'PT-2 (1)', N'Attach data tags containing [Assignment: organization-defined authorized processing] to [Assignment: organization-defined elements of personally identifiable information].', N'<p><strong>WMATA Policy</strong></p><p>Attach data tags containing [Assignment: organization-defined authorized processing] to <br>[Assignment: organization-defined elements of personally identifiable information].</p><p>Related Controls: AC-16, CA-6, CM-12, PM-5, PM-22, PT-4, SC-16, SC-43, SI-10, SI-15, SI-19</p>', N'Personally Identifiable Information Processing and Transparency', N'Authority to Process Personally Identifiable Information', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1086, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37862, N'PT-2 (2)', N'Manage enforcement of the authorized processing of personally identifiable information using [Assignment: organization-defined automated mechanisms].', N'<p><strong>WMATA Policy</strong></p><p>Manage enforcement of the authorized processing of personally identifiable information<br>using [Assignment: organization-defined automated mechanisms].</p><p>Related Controls: CA-6, CM-12, PM-5, PM-22, PT-4, SC-16, SC-43, SI-10, SI-15, SI-19</p>', N'Personally Identifiable Information Processing and Transparency', N'Authority to Process Personally Identifiable Information', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1086, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37863, N'PT-3', N'a. Identify and document the [Assignment: organization-defined purpose(s)] for processing personally identifiable information;b. Describe the purpose(s) in the public privacy notices and policies of the organization;c. Restrict the [Assignment: organization-defined processing] of personally identifiable information to only that which is compatible with the identified purpose(s); andd. Monitor changes in processing personally identifiable information and implement [Assignment: organization-defined mechanisms] to ensure that any changes are made in accordance with [Assignment: organization-defined requirements].', N'<p><strong>WMATA Policy</strong></p><p>a. Identify and document the approved reasons for processing sensitive information;</p><p>b. Restrict the storage, processing, and transmission of sensitive information to only that which is compatible with the identified purpose(s);</p><p>c.  Monitor changes in processing sensitive information and implement mechanisms to ensure any changes are made in accordance with defined requirements to allow or restrict new processing, as appropriate. Mechanisms may include obtaining consent from individuals or other measures to manage privacy risks that arise from changes in sensitive information processing purposes; and</p><p>d. All existing uses of sensitive information are subject to review and reauthorization or restriction.</p><p>Related Controls: AC-2, AC-3, AT-3, IR-9, PM-9, PM-25, PT-2, PT-5, PT-6, PT-7, RA-8, SI-12, SI-18</p>', N'Personally Identifiable Information Processing and Transparency', N'Personally Identifiable Information Processing Purposes', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1086, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37864, N'PT-3 (1)', N'Attach data tags containing the following purposes to [Assignment: organization-defined elements of personally identifiable information]: [Assignment: organization-defined processing purposes].', N'<p><strong>WMATA Policy</strong></p><p>Attach data tags containing the following purposes to [Assignment: organization-defined <br>elements of personally identifiable information]: [Assignment: organization-defined <br>processing purposes].</p><p>Related Controls: CA-6, CM-12, PM-5, PM-22, SC-16, SC-43, SI-10, SI-15, SI-19</p>', N'Personally Identifiable Information Processing and Transparency', N'Personally Identifiable Information Processing Purposes', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1086, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37865, N'PT-3 (2)', N'Track processing purposes of personally identifiable information using [Assignment: organization-defined automated mechanisms].', N'<p><strong>WMATA Policy</strong></p><p>Track processing purposes of personally identifiable information using [Assignment: <br>organization-defined automated mechanisms].</p><p>Related Controls: CA-6, CM-12, PM-5, PM-22, SC-16, SC-43, SI-10, SI-15, SI-19</p>', N'Personally Identifiable Information Processing and Transparency', N'Personally Identifiable Information Processing Purposes', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1086, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37866, N'PT-4', N'Implement [Assignment: organization-defined tools or mechanisms] for individuals to consent to the processing of their personally identifiable information prior to its collection that facilitate individuals’ informed decision-making.', N'<p><strong>WMATA Policy</strong></p><p>Implement mechanisms for individuals to consent to the processing of their sensitive information prior to its collection that facilitate individuals’ informed decision-making.</p><p>Related Controls:  PT-2, PT-5</p>', N'Personally Identifiable Information Processing and Transparency', N'Consent', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1086, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37867, N'PT-4 (1)', N'Provide [Assignment: organization-defined mechanisms] to allow individuals to tailor processing permissions to selected elements of personally identifiable information.', N'<p><strong>WMATA Policy</strong></p><p>Provide [Assignment: organization-defined mechanisms] to allow individuals to tailor <br>processing permissions to selected elements of personally identifiable information.</p><p>Related Controls: PT-2</p>', N'Personally Identifiable Information Processing and Transparency', N'Consent', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1086, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37868, N'PT-4 (2)', N'Present [Assignment: organization-defined consent mechanisms] to individuals at [Assignment: organization-defined frequency] and in conjunction with [Assignment: organization-defined personally identifiable information processing].', N'<p><strong>WMATA Policy</strong></p><p>Present [Assignment: organization-defined consent mechanisms] to individuals at <br>[Assignment: organization-defined frequency] and in conjunction with [Assignment: <br>organization-defined personally identifiable information processing].</p><p>Related Controls: PT-2</p>', N'Personally Identifiable Information Processing and Transparency', N'Consent', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1086, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37869, N'PT-4 (3)', N'Implement [Assignment: organization-defined tools or mechanisms] for individuals to revoke consent to the processing of their personally identifiable information.', N'<p><strong>WMATA Policy</strong></p><p>Implement [Assignment: organization-defined tools or mechanisms] for individuals to <br>revoke consent to the processing of their personally identifiable information. </p><p>Related Controls: PT-2</p>', N'Personally Identifiable Information Processing and Transparency', N'Consent', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1086, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37870, N'PT-5', N'Provide notice to individuals about the processing of personally identifiable information that:a. Is available to individuals upon first interacting with an organization, and subsequently at [Assignment: organization-defined frequency];b. Is clear and easy-to-understand, expressing information about personally identifiable information processing in plain language;c. Identifies the authority that authorizes the processing of personally identifiable information;d. Identifies the purposes for which personally identifiable information is to be processed; ande. Includes [Assignment: organization-defined information].', N'<p><strong>WMATA Policy</strong></p><p>Provide notice to individuals about the processing of sensitive information that:</p><p>a.  Is available to individuals upon first interacting with an organization, and subsequently on an annual basis;</p><p>b.  Is clear and easy-to-understand, expressing information about sensitive information processing in plain language;</p><p>c.  Identifies the authority that authorizes the processing of sensitive information; </p><p>d.  Identifies the purposes for which sensitive information is to be processed; and<br>e.  Privacy Notices shall list all privacy-related information, to include:</p><p>i)  Name, such as full name, maiden name, mother‘s maiden name, or alias;</p><p>ii)  Personal identification number, such as social security number (SSN), passport number, driver‘s license number, taxpayer identification number, patient identification number, and financial account or credit card number;</p><p>iii)  Address information, such as street address or email address;</p><p>iv)  Asset information, such as Internet Protocol (IP) or Media Access Control (MAC) address or other host-specific persistent static identifier that consistently links to a particular person or small, well-defined group of  people;</p><p>v)  Telephone numbers, including mobile, business, and personal numbers;</p><p>vi)  Personal characteristics, including photographic image (especially of face or other distinguishing characteristic), x-rays, fingerprints, or other biometric image or template data (e.g., retina scan, voice signature, facial geometry);</p><p>vii)  Information identifying personally owned property, such as vehicle registration number or title number and related information; and</p><p>viii)  Information about an individual that is linked or linkable to one of the above (e.g., date of birth, place of birth, race, religion, weight, activities, geographical indicators, employment information, medical information, education information, financial information).</p><p>Related Controls: PT-2, PT-3, PT-4, PT-7, RA-3, SI-18</p><p>f.	Security Controls Enhancement(s):</p>', N'Personally Identifiable Information Processing and Transparency', N'Privacy Notice', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1086, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37871, N'PT-5 (1)', N'Present notice of personally identifiable information processing to individuals at a time and location where the individual provides personally identifiable information or in conjunction with a data action, or [Assignment: organization-defined frequency].', N'<p><strong>WMATA Policy</strong></p><p>Present notice of personally identifiable information processing to individuals at a time <br>and location where the individual provides personally identifiable information or in <br>conjunction with a data action, or [Assignment: organization-defined frequency].</p><p>Related Controls: PM-21</p>', N'Personally Identifiable Information Processing and Transparency', N'Privacy Notice', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1086, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37872, N'PT-5 (2)', N'Include Privacy Act statements on forms that collect information that will be maintained in a Privacy Act system of records, or provide Privacy Act statements on separate forms that can be retained by individuals.', N'<p><strong>WMATA Policy</strong></p><p>(1)  Include privacy statements on forms that collect information that will be maintained in a privacy system of records, or provide privacy statements on separate forms that can be retained by individuals.</p><p>Related Controls: PT-6</p>', N'Personally Identifiable Information Processing and Transparency', N'Privacy Notice', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1086, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37873, N'PT-6', N'For systems that process information that will be maintained in a Privacy Act system of records:a. Draft system of records notices in accordance with OMB guidance and submit new and significantly modified system of records notices to the OMB and appropriate congressional committees for advance review;b. Publish system of records notices in the Federal Register; andc. Keep system of records notices accurate, up-to-date, and scoped in accordance with policy.', N'<p><strong>WMATA Policy</strong></p><p>For systems that process sensitive information that will be maintained in a system of records:	</p><p>a.  Establish system of records notices and submit new and modified system of records notices for review to the CPO and ITCS; and</p><p>b.  Keep system of records notices accurate, up-to-date, and scoped in accordance with policy.</p><p>Related Controls: AC-3, PM-20,  PT-2, PT-3, PT-5</p><p>c.  Security Controls Enhancement(s):</p>', N'Personally Identifiable Information Processing and Transparency', N'System of Records Notice', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1086, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37874, N'PT-6 (1)', N'Review all routine uses published in the system of records notice at [Assignment: organization-defined frequency] to ensure continued accuracy, and to ensure that routine uses continue to be compatible with the purpose for which the information was collected.', N'<p><strong>WMATA Policy</strong></p><p>Review all routine uses published in the system of records notice annually to ensure continued accuracy, and to ensure that routine uses continue to be compatible with the purpose for which the information was collected.</p>', N'Personally Identifiable Information Processing and Transparency', N'System of Records Notice', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1086, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37875, N'PT-6 (2)', N'Review all Privacy Act exemptions claimed for the system of records at [Assignment: organization-defined frequency] to ensure they remain appropriate and necessary in accordance with law, that they have been promulgated as regulations, and that they are accurately described in the system of records notice.', N'<p><strong>WMATA Policy</strong></p><p>Review all sensitive information exemptions claimed for the system of records annually to ensure they remain appropriate and necessary in accordance with law, that they have been promulgated as regulations, and that they are accurately described in the system of records notice.</p>', N'Personally Identifiable Information Processing and Transparency', N'System of Records Notice', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1086, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37876, N'PT-7', N'Apply [Assignment: organization-defined processing conditions] for specific categories of personally identifiable information.', N'<p><strong>WMATA Policy</strong></p><p><strong>Categorization of Information</strong></p><p>Categorize information by types associated with user information and system information. Categorized information applies to either electronic or non-electronic mediums. Categorized information shall be leveraged to assess appropriate information system categories.</p><p>Except for information that is otherwise covered by P/I 9.2 Privacy Policy or P/I 9.4 Public Access to Records Policy, as applicable, dissemination of restricted WMATA information is limited to the discretion of the Data Owner or a more senior executive in their chain of command. Dissemination shall not compromise ongoing investigations, safety, or the confidentiality, integrity, or availability of systems. To the extent the information is also covered by P/I 9.2 Privacy Policy or P/I 9.4 Public Access to Records Policy, the Privacy Administrator or PARP Administrator, as applicable, must also review prior to dissemination of the information.</p><p>Security categorization requires an assessment of potential impacts to confidentiality, integrity, and availability associated with the particular information type.</p><p>The following are the defined categories of information types:  SEE Cybersecurity Policy Manual Version 1.1, pages 59 - 61.</p>
<p>a. Apply security controls for information systems in accordance with the security categorization in Control 3.16 Risk Assessment, Section 2, “RA-2 Security Categorization”:</p><p>Related Controls: IR-9, PT-2, PT-3, RA-2, RA-3</p><p>b. Security Controls Enhancement(s):</p>', N'Personally Identifiable Information Processing and Transparency', N'Specific Categories of Personally Identifiable Information', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1086, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37877, N'PT-7 (1)', N'When a system processes Social Security numbers:(a) Eliminate unnecessary collection, maintenance, and use of Social Security numbers, and explore alternatives to their use as a personal identifier;(b) Do not deny any individual any right, benefit, or privilege provided by law because of such individual’s refusal to disclose his or her Social Security number; and(c) Inform any individual who is asked to disclose his or her Social Security number whether that disclosure is mandatory or voluntary, by what statutory or other authority such number is solicited, and what uses will be made of it.', N'<p><strong>WMATA Policy</strong></p><p>When an information system processes Social Security numbers:<br>(1) Eliminate unnecessary collection, maintenance, and use of Social Security Numbers (SSNs) and other sensitive information;</p><p>•  Use unique identifiers (e.g., Employee Identifier (EID) or Contractor Identifier (CID)) to <br>differentiate between personnel; and</p><p>•  Only use the SSN where necessary for essential business functions (e.g., financial processing, <br>payroll, benefits, etc.) or other uses consistent with state and federal law;</p><p>(2)  Do not deny any individual any right, benefit, or privilege provided by law because of such individual’s refusal to disclose his or her SSN; and</p><p>(3)  Inform any individual who is asked to disclose his or her Social Security number whether that disclosure is mandatory or voluntary, by what statutory or other authority such number is solicited, and what uses will be made of it.</p><p>Related Controls: IA-4</p>', N'Personally Identifiable Information Processing and Transparency', N'Specific Categories of Personally Identifiable Information', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1086, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37878, N'PT-7 (2)', N'Prohibit the processing of information describing how any individual exercises rights guaranteed by the First Amendment unless expressly authorized by statute or by the individual or unless pertinent to and within the scope of an authorized law enforcement activity.', N'<p><strong>WMATA Policy</strong></p><p>Prohibit the processing of information describing how any individual exercises rights guaranteed by the First Amendment unless expressly authorized by statute or by the individual or unless pertinent to and within the scope of an authorized law enforcement activity.</p>', N'Personally Identifiable Information Processing and Transparency', N'Specific Categories of Personally Identifiable Information', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1086, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37879, N'PT-8', N'When a system or organization processes information for the purpose of conducting a matching program:a. Obtain approval from the Data Integrity Board to conduct the matching program;b. Develop and enter into a computer matching agreement;c. Publish a matching notice in the Federal Register;d. Independently verify the information produced by the matching program before taking adverse action against an individual, if required; ande. Provide individuals with notice and an opportunity to contest the findings before taking adverse action against an individual.', N'<p><strong>WMATA Policy</strong></p><p>When an information system or organization processes information for the purpose of conducting a matching program:</p><p>a.  Obtain approval from the AO to conduct the matching program;</p><p>b.  Develop and enter into a computer matching agreement; and </p><p>c.  Sponsoring system owner shall submit to the AO all documentation pursuant to 5 U.S.C. 552a(o)(1), or in the case of a state agency, submit all documentation pursuant to similar or analogous state statutory authority.</p><p>Related Controls: PM-24</p>', N'Personally Identifiable Information Processing and Transparency', N'Computer Matching Requirements', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1086, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37880, N'RA-1', N'a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:     1. [Selection (one or more): Organization-level; Mission/business process-level; System-level] risk assessment policy that:          (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and           compliance; and          (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and     2. Procedures to facilitate the implementation of the risk assessment policy and the associated risk assessment controls;b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the risk assessment policy and procedures; andc. Review and update the current risk assessment:     1. Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and     2. Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].', N'<p><strong>WMATA Policy</strong></p><p>Reference P/I 15.28 Cybersecurity Policy for requirements:</p><p>Related Controls: PM-9, PS-8, SI-12</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: The policy specifically addresses the unique properties and requirements of OT and the relationship to non-OT systems.</p>', N'Risk Assessment', N'Risk Assessment Policy and Procedures', NULL, NULL, N'WMATA', NULL, NULL, NULL, 70, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37881, N'RA-2', N'a. Categorize the system and information it processes, stores, and transmits;b. Document the security categorization results, including supporting rationale, in the security plan for the system; andc. Verify that the authorizing official or authorizing official designated representative reviews and approves the security categorization decision.', N'<p><strong>WMATA Policy</strong></p><p>a. Categorize the system and information it processes, stores, and transmits;</p><p>b. Document the security categorization results, including supporting rationale, in the SSP for the system; and</p><p>c. Verify that the AO or AODR reviews and approves the security categorization decision.</p><p><strong><u>OT Systems Only:</strong></u> Process hazard analysis (PHA), functional safety assessments, and other organization-established risk assessments can be referenced to identify the impact level of the OT systems. </p><p>Related Controls : CM-8, MP-4, PL-2, PL-10, PL-11, PM-7, RA-3, RA-5, RA-7, RA-8, SA-8, SC-7, SI-12</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: PHA, functional safety assessments, and other organization-established risk assessments can be referenced to identify the impact level of the OT systems.</p>', N'Risk Assessment', N'Security Categorization', NULL, NULL, N'WMATA', NULL, NULL, NULL, 70, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37882, N'RA-3', N'a. Conduct a risk assessment, including:     1. Identifying threats to and vulnerabilities in the system;     2. Determining the likelihood and magnitude of harm from unauthorized access, use, disclosure, disruption, modification, or destruction of the      system, the information it processes, stores, or transmits, and any related information; and     3. Determining the likelihood and impact of adverse effects on individuals arising from the processing of personally identifiable information;b. Integrate risk assessment results and risk management decisions from the organization and mission or business process perspectives with system-level risk assessments;c. Document risk assessment results in [Selection: security and privacy plans; risk assessment report; [Assignment: organization-defined document]];d. Review risk assessment results [Assignment: organization-defined frequency];e. Disseminate risk assessment results to [Assignment: organization-defined personnel or roles]; andf. Update the risk assessment [Assignment: organization-defined frequency] or when there are significant changes to the system, its environment of operation, or other conditions that may impact the security or privacy state of the system.', N'<p><strong>WMATA Policy</strong></p><p>a. Conduct a risk assessment, including:</p><p>i)  Identifying threats to and vulnerabilities in the system;</p><p>ii)  Determining the likelihood and magnitude of harm from unauthorized access, use, disclosure, disruption, modification, or destruction of the system, the information it processes, stores, or transmits, and any related information; and</p><p>iii) Determining the likelihood and impact of adverse effects on individuals arising from the processing of PII;</p><p>b. Integrate risk assessment results and risk management decisions from the organization and mission or business process perspectives with system-level risk assessments;</p><p>c. Document risk assessment results in the Governance, Risk, and Compliance (GRC) tool;</p><p>d. Review risk assessment results annually;</p><p>e. Disseminate risk assessment results to the required stakeholders; and</p><p>f.  Update the risk assessment annually or when there are significant changes to the system, its <br>environment of operation, or other conditions that may impact the security or privacy state of the system.</p><p>Related Controls:  CA-3, CA-6, CM-4, CP-6, CP-7, IA-8, MA-5, PE-3, PE-8, PE-18, PL-2, PL-10, PL-11, PM-8, PM-9, PM-28, PT-2, PT-7, RA-2, RA-5, RA-7, SA-8, SA-9, SI-12</p>', N'Risk Assessment', N'Risk Assessment', NULL, NULL, N'WMATA', NULL, NULL, NULL, 70, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37883, N'RA-3 (1)', N'(a) Assess supply chain risks associated with [Assignment: organization-defined systems, system components, and system services]; and(b) Update the supply chain risk assessment [Assignment: organization-defined frequency], when there are significant changes to the relevant supply chain, or when changes to the system, environments of operation, or other conditions may necessitate a change in the supply chain.', N'<p><strong>WMATA Policy</strong></p><p>(a) Assess supply chain risks associated with [Assignment: organization-defined systems, <br>system components, and system services]; and</p><p>(b) Update the supply chain risk assessment [Assignment: organization-defined <br>frequency], when there are significant changes to the relevant supply chain, or when <br>changes to the system, environments of operation, or other conditions may <br>necessitate a change in the supply chain.</p><p>Related Controls: RA-2, RA-9, PM-17, PM-30, SR-2</p>', N'Risk Assessment', N'Risk Assessment', NULL, NULL, N'WMATA', NULL, NULL, NULL, 70, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37884, N'RA-5', N'a. Monitor and scan for vulnerabilities in the system and hosted applications [Assignment: organization-defined frequency and/or randomly in accordance with organization-defined process] and when new vulnerabilities potentially affecting the system are identified and reported;b. Employ vulnerability monitoring tools and techniques that facilitate interoperability among tools and automate parts of the vulnerability management process by using standards for:     1. Enumerating platforms, software flaws, and improper configurations;     2. Formatting checklists and test procedures; and     3. Measuring vulnerability impact;c. Analyze vulnerability scan reports and results from vulnerability monitoring;d. Remediate legitimate vulnerabilities [Assignment: organization-defined response times] in accordance with an organizational assessment of risk;e. Share information obtained from the vulnerability monitoring process and control assessments with [Assignment: organization-defined personnel or roles] to help eliminate similar vulnerabilities in other systems; andf. Employ vulnerability monitoring tools that include the capability to readily update the vulnerabilities to be scanned.', N'<p><strong>WMATA Policy</strong></p><p>a. Monitor and scan for vulnerabilities in the system and hosted applications monthly and when new vulnerabilities potentially affecting the system are identified and reported;</p><p>b. Employ vulnerability monitoring tools and techniques that facilitate interoperability among tools and automate parts of the vulnerability management process by using standards for:</p><p>i)  Enumerating platforms, software flaws, and improper configurations;</p><p>ii) Formatting checklists and test procedures; and</p><p>iii) Measuring vulnerability impact;</p><p>c. Analyze vulnerability scan reports and results from vulnerability monitoring;</p><p>d. Remediate vulnerabilities within the following timelines:</p><p>i)  Critical vulnerabilities: immediately but no more than 15 days after notification;</p><p>ii) High vulnerabilities: within 30 days of notification;</p><p>iii) Medium vulnerabilities: within 60 days of notification; and</p><p>iv) Low vulnerabilities: within 90 days of notification;</p><p>All system changes are subject to implementation in accordance with Control 3.4 Configuration Management.</p><p>e.  Share information obtained from the vulnerability monitoring process and control assessments with the required system owner(s) and with other stakeholders on a need-to-know basis, to help eliminate similar vulnerabilities in other systems; and</p><p>f.  Employ vulnerability monitoring tools that include the capability to readily update the vulnerabilities to be scanned.</p><p><strong><u>OT Systems Only: </strong></u>The organization makes a risk-based determination of how to monitor or scan for vulnerabilities on their system. This may include active scanning, passive monitoring, or compensating controls, depending on the system being scanned. For example, vulnerability examination may be performed using passive monitoring and manual visual inspection to maintain an up-to-date inventory of assets. That inventory can be cross-referenced against a list of known vulnerabilities (e.g., CISA advisories and NIST NVD). Production may need to be taken off-line before active scans can be conducted. Scans are scheduled to occur during planned OT outages whenever possible. If vulnerability scanning tools are used on adjacent non-OT networks, extra care is taken to ensure that they do not mistakenly scan the OT network. Automated network scanning is not applicable to non-routable communications such as serial networks. Compensating controls include providing a replicated or simulated system for conducting scans or host-based vulnerability applications.</p><p>Related Controls : CA-2, CA-7, CA-8, CM-2, CM-4, CM-6, CM-8, RA-2, RA-3, SA-11, SA-15, SI-2, SI-3, SI-4, SI-7, SR-11</p><p>g. Security Controls Enhancement(s):</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: The organization makes a risk-based determination of how to monitor or scan for vulnerabilities on their system. This may include active scanning, passive monitoring, or compensating controls, depending on the system being scanned. For example, vulnerability examination may be performed using passive monitoring and manual visual inspection to <br>maintain an up-to-date inventory of assets. That inventory can be cross-referenced against a list of known vulnerabilities (e.g., CISA advisories, NIST NVD). Production may need to be taken offline before active scans can be conducted. Scans are scheduled to occur during planned OT outages whenever possible. If vulnerability scanning tools are used on adjacent non-OT networks, extra care is taken to ensure that they do not mistakenly scan the OT network. Automated network scanning is not applicable to non-routable communications, such as serial networks. Compensating controls include providing a replicated or simulated system for conducting scans or host-based vulnerability applications. </p>', N'Risk Assessment', N'Vulnerability Monitoring and Scanning', NULL, NULL, N'WMATA', NULL, NULL, NULL, 70, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37885, N'RA-5 (11)', N'<p><b>Vulnerability Monitoring and Scanning | Public Disclosure Program</b></p>Establish a public reporting channel for receiving reports of vulnerabilities in organizational systems and system components.', N'<p><strong>WMATA Policy</strong></p><p>Establish a public reporting channel for receiving reports of vulnerabilities in organizational systems and system components.</p><p><strong><u>OT Systems Only: </strong></u>For federal organizations, CISA Binding Operational Directive 20-01 requires individual federal civilian executive branch agencies to develop and publish a vulnerability disclosure policy (VDP) for their internet-accessible systems and services, and maintain processes to support their VDP. A VDP may be implemented at the organization level, rather than for each individual system. Non-federal as well as federal organizations could achieve this control by creating and monitoring an email address published on a public-facing website for contacting the organization regarding disclosures.</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: For federal organizations, CISA Binding Operational Directive 20-01 requires individual federal civilian executive branch agencies to develop and publish a vulnerability disclosure policy (VDP) for their internet-accessible systems and services and maintain processes to support their VDP. A VDP may be implemented at the organization level rather than for each individual system. Federal and non-federal organizations could achieve this control by creating and monitoring an email address published on a public-facing website for contacting the organization regarding disclosures. </p>', N'Risk Assessment', N'Vulnerability Monitoring and Scanning', NULL, NULL, N'WMATA', NULL, NULL, NULL, 70, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37886, N'RA-5 (2)', N'Update the system vulnerabilities to be scanned [Selection (one or more): [Assignment: organization-defined frequency]; prior to a new scan; when new vulnerabilities are identified and reported].', N'<p><strong>WMATA Policy</strong></p><p>Update the system vulnerabilities to be scanned daily and when new vulnerabilities are identified and reported.</p><p>Related Controls: SI-5</p>', N'Risk Assessment', N'Vulnerability Monitoring and Scanning', NULL, NULL, N'WMATA', NULL, NULL, NULL, 70, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37887, N'RA-5 (4)', N'<p><b>Vulnerability Monitoring and Scanning | Discoverable Information</b></p>Determine information about the system that is discoverable and take [Assignment: organization-defined corrective actions].', N'<p><strong>WMATA Policy</strong></p><p>Determine information about the system that is discoverable and notify appropriate organizational personnel, remove designated information, and/or change the system to make the designated information less relevant or attractive to adversaries.</p><p><strong><u>OT Systems Only: </strong></u>Examples of discoverable information in OT could include information about key personnel or technical information relating to systems and configurations. Locations that may need to be monitored or scanned include technical forums, blogs, or vendor/contractor websites. </p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Examples of discoverable information in OT could include information about key personnel or technical information related to systems and configurations. Locations that may need to be monitored or scanned include technical forums, blogs, and vendor or contractor websites. </p>', N'Risk Assessment', N'Vulnerability Monitoring and Scanning', NULL, NULL, N'WMATA', NULL, NULL, NULL, 70, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37888, N'RA-5 (5)', N'Implement privileged access authorization to [Assignment: organization-defined system components] for [Assignment: organization-defined vulnerability scanning activities].', N'<p><strong>WMATA Policy</strong></p><p>Implement privileged access authorization to systems and system components for all vulnerability scanning activities.</p>', N'Risk Assessment', N'Vulnerability Monitoring and Scanning', NULL, NULL, N'WMATA', NULL, NULL, NULL, 70, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37889, N'RA-7', N'Respond to findings from security and privacy assessments, monitoring, and audits in accordance with organizational risk tolerance.', N'<p><strong>WMATA Policy</strong></p><p>Respond to findings from security and privacy assessments, monitoring, and audits in accordance with organizational risk tolerance.</p>', N'Risk Assessment', N'Risk Response', NULL, NULL, N'WMATA', NULL, NULL, NULL, 70, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37890, N'RA-8', N'Conduct privacy impact assessments for systems, programs, or other activities before:a. Developing or procuring information technology that processes personally identifiable information; andb. Initiating a new collection of personally identifiable information that:1. Will be processed using information technology; and2. Includes personally identifiable information permitting the physical or virtual (online) contacting of a specific individual, if identical questions have been posed to, or identical reporting requirements imposed on, ten or more individuals, other than agencies, instrumentalities, or employees of the federal government.', N'<p><strong>WMATA Policy</strong></p><p>a. Conduct sensitivity impact assessments for systems, programs, or other activities, and document results in the GRC tool before:</p><p>i)  Developing or procuring information technology that processes sensitive information;</p><p>ii)  Initiating a new collection of sensitive information that will be processed using information <br>technology; and</p><p>iii) The results of the sensitivity impact assessment may require the completion of a privacy impact assessment or other documentation specific to the type of sensitive information processed.</p><p>b.  Conduct privacy impact assessments for systems, programs, or other activities, and document results in the GRC tool before:</p><p>i)  Developing or procuring information technology that processes personally identifiable information; and</p><p>ii) Initiating a new collection of personally identifiable information that will be processed using information technology;</p><p>Related Controls : CM-4, CM-9, PT-2, PT-3, PT-5, RA-1, RA-2, RA-3, RA-7</p>', N'Risk Assessment', N'Privacy Impact Assessment', NULL, NULL, N'WMATA', NULL, NULL, NULL, 70, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37891, N'RA-9', N'Identify critical system components and functions by performing a criticality analysis for [Assignment: organization-defined systems, system components, or system services] at [Assignment: organization-defined decision points in the system development life cycle].', N'<p><strong>WMATA Policy</strong></p><p>Identify critical system components and functions by performing a criticality analysis for systems, system components, and system services throughout the Project Lifecycle Management (PLM) process/System Development Life Cycle (SDLC). All new systems shall conduct a criticality analysis as a part of the project intake phase.</p><p>Related Controls:  CP-2, PL-2, PL-8, PL-11, PM-1, PM-11, RA-2, SA-8, SA-15, SR-5</p>', N'Risk Assessment', N'Criticality Analysis', NULL, NULL, N'WMATA', NULL, NULL, NULL, 70, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37892, N'SA-1', N'a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:     1. [Selection (one or more): Organization-level; Mission/business process-level; System-level] system and services acquisition policy that:          (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and           compliance; and         (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and     2. Procedures to facilitate the implementation of the system and services acquisition policy and the associated system and services acquisition      controls; b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the system and  services acquisition policy and procedures; and c. Review and update the current system and services acquisition:     1. Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and     2. Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].', N'<p><strong>WMATA Policy</strong></p><p>Reference P/I 15.28 Cybersecurity Policy for requirements.</p><p>Related Controls: PM-9, PS-8, SA-8, SI-12</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: The policy specifically addresses the unique properties and requirements of OT and the relationship to non-OT systems.</p><p></p>', N'System and Services Acquisition', N'System and Services Acquisition Policy and Procedures', NULL, NULL, N'WMATA', NULL, NULL, NULL, 48, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37893, N'SA-10', N'Require the developer of the system, system component, or system service to:a. Perform configuration management during system, component, or service [Selection (one or more): design; development; implementation; operation; disposal];b. Document, manage, and control the integrity of changes to [Assignment: organization-defined configuration items under configuration management];c. Implement only organization-approved changes to the system, component, or service;d. Document approved changes to the system, component, or service and the potential security and privacy impacts of such changes; ande. Track security flaws and flaw resolution within the system, component, or service and report findings to [Assignment: organization-defined personnel].', N'<p><strong>WMATA Policy</strong></p><p>a.  Perform configuration management during system, component, or service design; development; implementation; operation; disposal, in accordance with the SDLC;</p><p>b.  Document, manage, and control the integrity of changes to all system and system component configuration items under configuration management;</p><p>c. Implement only organization-approved changes to the system, component, or service;</p><p>d. Document approved changes to the system, component, or service and the potential security and privacy impacts of such changes; and</p><p>e. Track security flaws and flaw resolution within the system, component, or service and report findings to required stakeholders.</p><p>Related Controls: CM-2, CM-3, CM-4, CM-7, CM-9, SA-4, SA-5, SA-8, SA-15, SI-2, SR-3, SR-4, SR-5, SR-6</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Personnel with knowledge about security and privacy requirements are included in the change management process for the developer.</p>', N'System and Services Acquisition', N'Developer Configuration Management', NULL, NULL, N'WMATA', NULL, NULL, NULL, 48, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37894, N'SA-11', N'Require the developer of the system, system component, or system service, at all post-design stages of the system development life cycle, to:a. Develop and implement a plan for ongoing security and privacy control assessments;b. Perform [Selection (one or more): unit; integration; system; regression] testing/evaluation [Assignment: organization-defined frequency] at [Assignment: organization-defined depth and coverage];c. Produce evidence of the execution of the assessment plan and the results of the testing and evaluation;d. Implement a verifiable flaw remediation process; ande. Correct flaws identified during testing and evaluation.', N'<p><strong>WMATA Policy</strong></p><p>Require the developer of the system, system component, or system service, at all post-design stages of the SDLC, to:</p><p>a. Develop and implement a plan for ongoing security and privacy control assessments;</p><p>b. Perform unit, integration, system, and regression testing/evaluation for releases and changes to the system or system components as specified in the SDLC at a depth and coverage that enable the DMCS-defined security and privacy objectives for the system to be implemented and approved by the AO;</p><p>c. All contracts shall specify acceptance criteria for security and privacy controls and plans commensurate with the security category or classification level of the system;</p><p>d. Produce evidence of the execution of the assessment plan and the results of the testing and evaluation;</p><p>e. Implement a verifiable flaw remediation process; and</p><p>f. Correct flaws identified during testing and evaluation.</p><p>Related Controls: CA-2, CA-7, CM-4, SA-3, SA-4, SA-5, SA-8, SA-15, SA-17, SI-2, SR-5, SR-6, SR-7</p>', N'System and Services Acquisition', N'Developer Testing and Evaluation', NULL, NULL, N'WMATA', NULL, NULL, NULL, 48, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37895, N'SA-15', N'a. Require the developer of the system, system component, or system service to follow a documented development process that:     1. Explicitly addresses security and privacy requirements;     2. Identifies the standards and tools used in the development process;     3. Documents the specific tool options and tool configurations used in the development process; and     4. Documents, manages, and ensures the integrity of changes to the process and/or tools used in development; andb. Review the development process, standards, tools, tool options, and tool configurations [Assignment: organization-defined frequency] to determine if the process, standards, tools, tool options and tool configurations selected and employed can satisfy the following security and privacy requirements: [Assignment: organization-defined security and privacy requirements].', N'<p><strong>WMATA Policy</strong></p><p>a.  Require the developer of the system, system component, or system service to follow a documented development process that:</p><p>i)  Explicitly addresses security and privacy requirements;</p><p>ii) Identifies the standards and tools used in the development process;</p><p>iii) Documents the specific tool options and tool configurations used in the development process; and</p><p>iv) Documents, manages, and ensures the integrity of changes to the process and/or tools used in development;</p><p>b.  Review the development process, standards, tools, tool options, and tool configurations annually to determine if the process, standards, tools, tool options and tool configurations selected and employed can satisfy the security and privacy requirements throughout the SDLC.</p><p>Related Controls: MA-6, SA-3, SA-4, SA-8, SA-10, SA-11, SR-3, SR-4, SR-5, SR-6, SR-9</p><p>c. Security Controls Enhancement(s):</p>', N'System and Services Acquisition', N'Development Process, Standards, and Tools', NULL, NULL, N'WMATA', NULL, NULL, NULL, 48, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37896, N'SA-15 (3)', N'Require the developer of the system, system component, or system service to perform a criticality analysis:(a) At the following decision points in the system development life cycle: [Assignment: organization-defined decision points in the system development life cycle]; and(b) At the following level of rigor: [Assignment: organization-defined breadth and depth of criticality analysis].', N'<p><strong>WMATA Policy</strong></p><p>Require the developer of the system, system component, or system service to perform a criticality analysis:</p><p>(1) As a part of the SDLC Design Phase (also known as Initiation Phase of the SDLC as defined by NIST 800-64);</p><p>(2) As a part of the A&A Categorization Phase; and</p><p>(3) At the discretion of the AO based on major changes to the system.</p><p>Related Controls: RA-9</p>', N'System and Services Acquisition', N'Development Process, Standards, and Tools', NULL, NULL, N'WMATA', NULL, NULL, NULL, 48, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37897, N'SA-16', N'Require the developer of the system, system component, or system service to provide the following training on the correct use and operation of the implemented security and privacy functions, controls, and/or mechanisms: [Assignment: organization-defined training].', N'<p><strong>WMATA Policy</strong></p><p>Require the developer of the system, system component, or system service to provide training on the correct use and operation of the implemented security and privacy functions, controls, and/or mechanisms.</p><p>Related Controls: AT-2, AT-3, PE-3, SA-4, SA-5</p>', N'System and Services Acquisition', N'Developer-Provided Training', NULL, NULL, N'WMATA', NULL, NULL, NULL, 48, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37898, N'SA-17', N'Require the developer of the system, system component, or system service to produce a design specification and security and privacy architecture that:a. Is consistent with the organization’s security and privacy architecture that is an integral part the organization’s enterprise architecture;b. Accurately and completely describes the required security and privacy functionality, and the allocation of controls among physical and logical components; andc. Expresses how individual security and privacy functions, mechanisms, and services work together to provide required security and privacy capabilities and a unified approach to protection.', N'<p><strong>WMATA Policy</strong></p><p>Require the developer of the system, system component, or system service to produce a design specification and security and privacy architecture that:</p><p>a. Is consistent with the organization’s security and privacy architecture that is an integral part of the organization’s enterprise architecture;</p><p>b. Accurately and completely describes the required security and privacy functionality and the allocation of controls among physical and logical components; and</p><p>c.  Expresses how individual security and privacy functions, mechanisms, and services work together to provide required security and privacy capabilities and a unified approach to protection.</p><p>Related Controls: PL-2, PL-8, PM-7, SA-3, SA-4, SA-8, SC-7</p>', N'System and Services Acquisition', N'Developer Security and Privacy Architecture and Design', NULL, NULL, N'WMATA', NULL, NULL, NULL, 48, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37899, N'SA-2', N'a. Determine the high-level information security and privacy requirements for the system or system service in mission and business process planning;b. Determine, document, and allocate the resources required to protect the system or system service as part of the organizational capital planning and investment control process; andc. Establish a discrete line item for information security and privacy in organizational programming and budgeting documentation.', N'<p><strong>WMATA Policy</strong></p><p>a. Determine the high-level information security and privacy requirements for the system or system service in mission and business process planning;</p><p>b. Determine, document, and allocate the resources required to protect the system or system service as part of the organizational capital planning and investment control process; and</p><p>c. Establish a discrete line item for information security and privacy in organizational programming and budgeting documentation.</p><p>Related Controls: PL-7, PM-3, PM-11, SA-9, SR-3, SR-5</p>', N'System and Services Acquisition', N'Allocation Of Resources', NULL, NULL, N'WMATA', NULL, NULL, NULL, 48, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37900, N'SA-21', N'Require that the developer of [Assignment: organization-defined system, system component, or system service]:a. Has appropriate access authorizations as determined by assigned [Assignment: organization-defined official government duties]; andb. Satisfies the following additional personnel screening criteria: [Assignment: organization-defined additional personnel screening criteria].', N'<p><strong>WMATA Policy</strong></p><p>Require that the developer of a system, system component, or system service:</p><p>a. Have appropriate access authorizations as determined by assigned official duties or as specified in an associated contract; and</p><p>b. Satisfy the following personnel screening criteria:</p><p>i)  Successful completion and adjudication of all required WMATA background checks. All contractors shall provide WMATA with contractually obligated background information; and</p><p>ii)  Review and analysis of company ownership and relationships that the company has with entities that may potentially affect the quality and reliability of the systems, components, or services being developed.</p><p>Related Controls: PS-2, PS-3, PS-6, PS-7, SA-4, SR-6</p>', N'System and Services Acquisition', N'Developer Screening', NULL, NULL, N'WMATA', NULL, NULL, NULL, 48, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37901, N'SA-22', N'a. Replace system components when support for the components is no longer available from the developer, vendor, or manufacturer; orb. Provide the following options for alternative sources for continued support for unsupported components [Selection (one or more): in-house support; [Assignment: organization-defined support from external providers]].', N'<p><strong>WMATA Policy</strong></p><p>a. Replace system components when support for the components is no longer available from the developer, vendor, or manufacturer. All systems shall employ vendor-supported products that are not end-of-life (EOL) and that are regularly maintained in accordance with Control 3.11 Maintenance.</p><p>b. Vulnerabilities identified on unsupported devices must be addressed using mitigating security controls as defined by DMCS.</p><p><strong><u>OT Systems Only:</strong></u> OT systems may contain system components that are no longer supported by the developer, vendor, or manufacturer and have not been replaced due to various operational, safety, availability, or lifetime constraints. Organizations identify alternative methods to continue supported operation of such system components and consider additional compensating controls to mitigate against known threats and vulnerabilities to unsupported system components. </p><p>Related Controls: PL-2, SA-3 </p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: OT systems may contain system components that are no longer supported by the developer, vendor, or manufacturer and have not been replaced due to various operational, safety, availability, or lifetime constraints. Organizations identify alternative methods to continue <br>supported operation of such system components and consider additional compensating controls to mitigate against known threats and vulnerabilities to unsupported system components. </p>', N'System and Services Acquisition', N'Unsupported System Components', NULL, NULL, N'WMATA', NULL, NULL, NULL, 48, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37902, N'SA-3', N'a. Acquire, develop, and manage the system using [Assignment: organization-defined system development life cycle] that incorporates information security and privacy considerations;b. Define and document information security and privacy roles and responsibilities throughout the system development life cycle;c. Identify individuals having information security and privacy roles and responsibilities; andd. Integrate the organizational information security and privacy risk management process into system development life cycle activities.', N'<p><strong>WMATA Policy</strong></p><p>a. Acquire, develop, and manage the system using the SDLC that incorporates information security and privacy considerations;</p><p>b. Define and document information security and privacy roles and responsibilities throughout the SDLC;</p><p>c. Identify individuals having information security and privacy roles and responsibilities; and</p><p>d. Integrate the organizational information security and privacy risk management process into SDLC activities.</p><p>e. Publishing code to a public code repository requires the express written authorization of the AO.</p><p>Related Controls: AT-3, PL-8, PM-7, SA-4, SA-5, SA-8, SA-11, SA-15, SA-17, SA-22, SR-3, SR-4, SR-5, SR-9</p><p>a.  Security Controls Enhancement(s):</p><p></p>', N'System and Services Acquisition', N'System Development Life Cycle', NULL, NULL, N'WMATA', NULL, NULL, NULL, 48, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37903, N'SA-3 (1)', N'<p><b>System Development Life Cycle | Manage Preproduction Environment</b></p>Protect system preproduction environments commensurate with risk throughout the system development life cycle for the system, system component, or system service.', N'<p><strong>WMATA Policy</strong></p><p>Protect system preproduction environments commensurate with risk throughout the system development life cycle of the system, system component, or system service. </p><p><strong><u>OT Systems Only:</strong></u> Organizations that do not maintain local preproduction environments and utilize a third-party integrator should ensure contracts are developed to limit the security and privacy risks. </p><p>Related Controls: CM-2, CM-4, RA-3, RA-9, SA-4</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Organizations that do not maintain local preproduction environments and utilize a third-party integrator should ensure that contracts are developed to limit security and privacy risks. </p>', N'System and Services Acquisition', N'System Development Life Cycle', NULL, NULL, N'WMATA', NULL, NULL, NULL, 48, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37904, N'SA-3 (3)', N'<p><b>System Development Life Cycle | Technology Refresh</b></p>Plan for and implement a technology refresh schedule for the system throughout the system development life cycle.', N'<p><strong>WMATA Policy</strong></p><p>Plan for and implement a technology refresh schedule for the system throughout the system development life cycle. </p><p><strong><u>OT Systems Only:</strong></u> Many OT systems have an expected life cycle that is longer than most IT components. Technology refresh is addressed in budget planning to limit the use of obsolete systems that present security or reliability risks. </p><p>Related Controls: MA-6</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Many OT systems have an expected life cycle that is longer than most IT components. Technology refresh is addressed in budget planning to limit the use of obsolete systems that present security or reliability risks.</p>', N'System and Services Acquisition', N'System Development Life Cycle', NULL, NULL, N'WMATA', NULL, NULL, NULL, 48, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37905, N'SA-4', N'Include the following requirements, descriptions, and criteria, explicitly or by reference, using [Selection (one or more): standardized contract language; [Assignment: organization-defined contract language]] in the acquisition contract for the system, system component, or system service:a. Security and privacy functional requirements;b. Strength of mechanism requirements;c. Security and privacy assurance requirements;d. Controls needed to satisfy the security and privacy requirements.e. Security and privacy documentation requirements;f. Requirements for protecting security and privacy documentation;g. Description of the system development environment and environment in which the system is intended to operate;h. Allocation of responsibility or identification of parties responsible for information security, privacy, and supply chain risk management; andi. Acceptance criteria.', N'<p><strong>WMATA Policy</strong></p><p>Include the following requirements, descriptions, and criteria, explicitly or by reference, using standardized contract language in the acquisition contract for the system, system component, or system service:</p><p>a. Security and privacy functional requirements for all stages of the SDLC as required in Control 3.19 System and Services Acquisition, Section 3, “SA-3 System Development Life Cycle” to include user and administrator guidance for the implementation and operation of controls;</p><p>b. Strength of mechanism requirements associated with capabilities, functions, and mechanisms to include a degree of correctness, completeness, resistance to tampering or bypass, and resistance to direct attack;</p><p>c. Security and privacy assurance requirements to include development processes, procedures, and methodologies as well as the evidence from development and assessment activities that provide grounds for confidence that the required functionality is implemented and possesses the required strength of mechanism;</p><p>d. Controls needed to satisfy the security and privacy requirements;</p><p>e. Security and privacy documentation requirements;</p><p>f. Requirements for protecting security and privacy documentation;</p><p>g. Description of the system development environment and environment in which the system is intended to operate;</p><p>h. Allocation of responsibility or identification of parties responsible for information security, privacy, and supply chain risk management; and</p><p>i. Acceptance criteria.</p><p>j. Providers of defined external information systems are required to identify the location of information systems that receive, process, store, or transmit WMATA data, with special emphasis on sensitive information to include, but is not limited to, Personally Identifiable Information (PII), Federal Tax Information (FTI), etc.</p><p><strong><u>OT Systems Only:</strong></u> Organizations engage with OT suppliers to raise awareness of cybersecurity needs. The SCADA/Control Systems Procurement Project provides example cybersecurity procurement language for OT. </p><p>Related Controls: CM-6, CM-8, PS-7, SA-3, SA-5, SA-8, SA-11, SA-15, SA-16, SA-17, SA-21, SR-3, SR-5</p><p>k. Security Controls Enhancement(s):</p><p><strong><u>NIST 800-82 Rev 3:<br></strong></u>OT Discussion: Organizations engage with OT suppliers to raise awareness of cybersecurity needs. The <em><u>SCADA/Control Systems Procurement Project</em></u> provides example cybersecurity procurement language for OT.<br></p>', N'System and Services Acquisition', N'Acquisition Process', NULL, NULL, N'WMATA', NULL, NULL, NULL, 48, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37906, N'SA-4 (1)', N'<p><b>Acquisition Process | Functional Properties of Controls</b></p>Require the developer of the system, system component, or system service to provide a description of the functional properties of the controls to be implemented.', N'<p><strong>WMATA Policy</strong></p><p>Require the developer of the system, system component, or system service to provide a description of the functional properties of the controls to be implemented.</p><p><strong><u>OT Systems Only:</strong></u> When acquiring OT products, consideration for security requirements may not have been incorporated into the design. Procurement may need to consider alternative products or complementary hardware, or plan for compensating controls. </p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: When acquiring OT products, consideration for security requirements may not have been incorporated into the design. Procurement may need to consider alternative products or complementary hardware or plan for compensating controls. <br></p>', N'System and Services Acquisition', N'Acquisition Process', NULL, NULL, N'WMATA', NULL, NULL, NULL, 48, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37907, N'SA-4 (10)', N'<p><b>Acquisition Process | Use of Approved PIV Products</b></p>Employ only information technology products on the FIPS 201-approved products list for Personal Identity Verification (PIV) capability implemented within organizational systems.', N'<p><strong>WMATA Policy</strong></p><p>Employ only information technology products on the FIPS 201-approved products list for PIV capability implemented within organizational systems.</p><p><strong><u>OT Systems Only:</strong></u> The use of approved PIV products is only required for organizations that follow OMB Memorandum M-19-17, e.g., federal agencies and contractors. Example compensating controls include employing external products on the FIPS 201-approved products list for PIV capability in conjunction with OT products. </p><p>Related Controls: IA-2, IA-8, PM-9</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: The use of approved PIV products is only required for organizations that follow OMB Memorandum M-19-17 (e.g., federal agencies and contractors). Example compensating controls include employing external products on the FIPS 201-approved products list for PIV capabilities in conjunction with OT products.</p>', N'System and Services Acquisition', N'Acquisition Process', NULL, NULL, N'WMATA', NULL, NULL, NULL, 48, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37908, N'SA-4 (12)', N'<p><b>Acquisition Process | Data Ownership</b></p>(a) Include organizational data ownership requirements in the acquisition contract; and(b) Require all data to be removed from the contractor’s system and returned to the organization within [Assignment: organization-defined time frame].', N'<p><strong>WMATA Policy</strong></p><p>(1)  Include organization data ownership requirements in the acquisition contract; and </p><p>(2)  Require all data to be removed from the contractor’s system and returned to the organization within [Assignment: organization-defined time frame].</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>Rationale for adding SA-4 (12) to LOW, MOD, and HIGH baselines: Organizationally sensitive or proprietary OT data is often provided to contractors for project development or support, so data ownership should be defined prior to exchanging data with a vendor or integrator. The potential sharing of data with other parties and the potential deletion of the data after project completion should be determined. OT systems that are operated by contractors on behalf of the organization may be subject to the same requirements (e.g., legal, regulatory, etc.) for data ownership and retention.</p>', N'System and Services Acquisition', N'Acquisition Process', NULL, NULL, N'WMATA', NULL, NULL, NULL, 48, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37909, N'SA-4 (2)', N'<p><b>Acquisition Process | Design and Implementation Information for Controls</b></p>Require the developer of the system, system component, or system service to provide design and implementation information for the controls that includes: [Selection (one or more): security-relevant external system interfaces; high-level design; low-level design; source code or hardware schematics; [Assignment: organization-defined design and implementation information]] at [Assignment: organization-defined level of detail].', N'<p><strong>WMATA Policy</strong></p><p>Require the developer of the system, system component, or system service to provide design and implementation information for controls that includes:</p><p>(1) Security-relevant system interfaces with external systems;</p><p>(2) Security-relevant system interfaces with internal systems;</p><p>(3) High-level design for the system expressed in terms of subsystems and the interfaces between subsystems with security-relevant functionality/information;</p><p>(4) Low-level design for the system expressed in terms of modules and the interfaces between modules with security-relevant functionality/information;</p><p>(5) Design and implementation documentation to include manufacturer, version, serial number, verification hash signature, software libraries used, date of purchase or download, and the vendor or download source;</p><p>(6) Source code or hardware schematics and any other implementation information at a level of detail necessary for successful review and implementation of the system;</p><p>(7) List of all Ports, Protocols and Services required for the functionality of the system;</p><p>(8) Data Flow Diagram (DFD) that represents a flow of a data in the system (if applicable);</p><p>(9) Data Classification Matrix including data definition, access restrictions and minimum controls specific for your service; and</p><p>(10) Application Boundary Diagram that illustrates the relationships between the application components and hosted environments (if applicable).</p><p><strong><u>OT Systems Only:</strong></u> When acquiring OT products, consideration for security requirements may not have been incorporated into the design. Procurement may need to consider alternative products or complementary hardware, or plan for compensating controls.</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: When acquiring OT products, consideration for security requirements may not have been incorporated into the design. Procurement may need to consider alternative products or complementary hardware or plan for compensating controls. </p>', N'System and Services Acquisition', N'Acquisition Process', NULL, NULL, N'WMATA', NULL, NULL, NULL, 48, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37910, N'SA-4 (5)', N'Require the developer of the system, system component, or system service to:(a) Deliver the system, component, or service with [Assignment: organization-defined security configurations] implemented; and(b) Use the configurations as the default for any subsequent system, component, or service reinstallation or upgrade.', N'<p><strong>WMATA Policy</strong></p><p>Require the developer of the system, system component, or system service to:</p><p>(1) Deliver the system, component, or service with the following implemented:</p><p>(a) Secure baselines based on all relevant/applicable STIGs in accordance with Control 3.4 <br>Configuration Management, Section 6, “CM-6 Configuration Settings”;</p><p>(b) Cybersecurity requirements including limitations on deprecated or disallowed functions, ports, protocols, and services; and</p><p>(c) Default passwords changed in accordance with Control 3.9 Identification and Authentication; and</p><p>(2) Use the configurations as the default for any subsequent system, component, or<br>service reinstallation or upgrade.</p><p>Related Controls: CM-6</p>', N'System and Services Acquisition', N'Acquisition Process', NULL, NULL, N'WMATA', NULL, NULL, NULL, 48, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37911, N'SA-4 (9)', N'<p><b>Acquisition Process | Functions, Ports, Protocols, and Services in Use</b></p>Require the developer of the system, system component, or system service to identify the functions, ports, protocols, and services intended for organizational use.', N'<p><strong>WMATA Policy</strong></p><p>Require the developer of the system, system component, or system service to identify the functions, ports, protocols, and services intended for organizational use.</p><p><strong><u>OT Systems Only:</strong></u> When acquiring OT products, consideration for security requirements may not have been incorporated into the design. Procurement may need to consider alternative products or complementary hardware, or plan for compensating controls.</p><p>Related Controls: CM-7, SA-9</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: When acquiring OT products, consideration for security requirements may not have been incorporated into the design. Procurement may need to consider alternative products or complementary hardware or plan for compensating controls. </p>', N'System and Services Acquisition', N'Acquisition Process', NULL, NULL, N'WMATA', NULL, NULL, NULL, 48, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37912, N'SA-5', N'a. Obtain or develop administrator documentation for the system, system component, or system service that describes:     1. Secure configuration, installation, and operation of the system, component, or service;     2. Effective use and maintenance of security and privacy functions and mechanisms; and     3. Known vulnerabilities regarding configuration and use of administrative or privileged functions;b. Obtain or develop user documentation for the system, system component, or system service that describes:     1. User-accessible security and privacy functions and mechanisms and how to effectively use those functions and mechanisms;     2. Methods for user interaction, which enables individuals to use the system, component, or service in a more secure manner and protect      individual privacy; and     3. User responsibilities in maintaining the security of the system, component, or service and privacy of individuals;c. Document attempts to obtain system, system component, or system service documentation when such documentation is either unavailable or nonexistent and take [Assignment: organization-defined actions] in response; andd. Distribute documentation to [Assignment: organization-defined personnel or roles].', N'<p><strong>WMATA Policy</strong></p><p>a. Obtain or develop (externally or internally) administrator documentation for the system, system component, or system service that describes:</p><p>i)  Secure configuration, installation, and operation of the system, component, or service;</p><p>ii) Effective use and maintenance of security and privacy functions and mechanisms; and</p><p>iii) Known vulnerabilities regarding configuration and use of administrative or privileged tions;</p><p>b.  Obtain or develop (externally or internally) user documentation for the system, system <br>component, or system service that describes:</p><p>i)  User-accessible security and privacy functions and mechanisms and how to effectively use those functions and mechanisms;</p><p>ii)  Methods for user interaction, which enables individuals to use the system, component, or <br>service in a more secure manner and protect individual privacy; and</p><p>iii) User responsibilities in maintaining the security of the system, component, or service and <br>privacy of individuals;</p><p>c.  Document attempts to obtain system, system component, or system service documentation when such documentation is either unavailable or nonexistent; and take actions to recreate the documentation if it is essential to the implementation or operation of the controls in response; and</p><p>d. Distribute documentation to required stakeholders.</p><p>Related Controls: CM-4, CM-6, CM-7, CM-8, PL-2, PL-4, PL-8, PS-2, SA-3, SA-4, SA-8, SA-9, SA-10, SA-11, SA-15, SA-16, SA-17, SI-12, SR-3</p>', N'System and Services Acquisition', N'System Documentation', NULL, NULL, N'WMATA', NULL, NULL, NULL, 48, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37913, N'SA-8', N'Apply the following systems security and privacy engineering principles in the specification, design, development, implementation, and modification of the system and system components: [Assignment: organization-defined systems security and privacy engineering principles].', N'<p><strong>WMATA Policy</strong></p><p>The application of security engineering principles must be integrated into the SDLC. Security engineering principles are primarily targeted at information systems under new development and information systems undergoing major upgrades. For legacy information systems, security engineering principles must be applied to system upgrades and modifications, to the extent feasible, given the current state of the hardware, software, and firmware components within the system.</p><p>Apply the following systems security and privacy engineering principles in the specification, design, development, implementation, and modification of the system and system components:</p><p>a. Developing layered protections;</p><p>b. Establishing sound security policy, architecture, and controls as the foundation for design;</p><p>c. Incorporating security into the SDLC;</p><p>d. Delineating physical and logical security boundaries;</p><p>e. Ensuring system developers and integrators are trained on how to develop secure software;</p><p>f.  Tailoring security controls to meet organizational and operational needs;</p><p>g. Reducing risk to acceptable levels, thus enabling informed risk management decisions;</p><p>h. Establishing network segmentation; and</p><p>i.  Performing threat modeling to identify use cases, threat agents, attack vectors and patterns, design patterns, and compensating controls needed to mitigate risk.</p><p>Related Controls: PL-8, PM-7, RA-2, RA-3, RA-9, SA-3, SA-4, SA-15, SA-17, SC-2, SC-3, SC-32, SC-39, SR-2, SR-3, SR-4, SR-5</p><p>j.  Security Controls Enhancement(s):</p>', N'System and Services Acquisition', N'Security and Privacy Engineering Principles', NULL, NULL, N'WMATA', NULL, NULL, NULL, 48, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37914, N'SA-8 (33)', N'Implement the privacy principle of minimization using [Assignment: organization-defined processes].', N'<p><strong>WMATA Policy</strong></p><p>Implement the privacy principle of minimization through discrete processes, which detail how systems only process PII or other sensitive information in accordance with Control 3.8 Data Sensitivity that is directly relevant and necessary to accomplish an authorized purpose and should only maintain PII for as long as is necessary to accomplish the purpose. All uses of PII shall be approved by the AO in consultation with the Privacy Administrator in accordance with P/I 9.2 Privacy Policy.</p><p>Related Controls: PE-8, PM-25, SI-12</p>', N'System and Services Acquisition', N'Security and Privacy Engineering Principles', NULL, NULL, N'WMATA', NULL, NULL, NULL, 48, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37915, N'SA-9', N'a. Require that providers of external system services comply with organizational security and privacy requirements and employ the following controls: [Assignment: organization-defined controls];b. Define and document organizational oversight and user roles and responsibilities with regard to external system services; andc. Employ the following processes, methods, and techniques to monitor control compliance by external service providers on an ongoing basis: [Assignment: organization-defined processes, methods, and techniques].', N'<p><strong>WMATA Policy</strong></p><p>a. Providers of external system services (including any third-party vendors) shall comply with organizational security and privacy requirements and employ applicable security controls per policy;</p><p>b. Define and document organizational oversight and user roles and responsibilities regarding external system services; and</p><p>c. Employ the following processes, methods, and techniques to monitor control compliance by external service providers on an ongoing basis:</p><p>i)  Leverage organizationally controlled monitoring of external system services; and/or</p><p>ii)  Require annual attestation from external system service providers regarding compliance with applicable security controls.</p><p>Related Controls: AC-20, CA-3, CP-2, IR-4, IR-7, PL-10, PL-11, PS-7, SA-2, SA-4, SR-3, SR-5</p><p>d. Security Controls Enhancement(s):</p>', N'System and Services Acquisition', N'External System Services', NULL, NULL, N'WMATA', NULL, NULL, NULL, 48, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37916, N'SA-9 (2)', N'Require providers of the following external system services to identify the functions, ports, protocols, and other services required for the use of such services: [Assignment: organization-defined external system services].', N'<p><strong>WMATA Policy</strong></p><p>Require providers of external system services to identify the functions, ports, protocols, and other services required for the use of such services.</p><p>Related Controls: CM-6, CM-7</p>', N'System and Services Acquisition', N'External System Services', NULL, NULL, N'WMATA', NULL, NULL, NULL, 48, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37917, N'SC-1', N'a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:     1. [Selection (one or more): Organization-level; Mission/business process-level; System-level] system and communications protection policy      that:          (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and           compliance; and          (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and     2. Procedures to facilitate the implementation of the system and communications protection policy and the associated system and      communications protection controls;b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the system and communications protection policy and procedures; andc. Review and update the current system and communications protection:     1. Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and     2. Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].', N'<p><strong>WMATA Policy</strong></p><p>Reference P/I 15.28 Cybersecurity Policy for requirements.</p><p>Related Controls: PM-9, PS-8, SA-8, SI-12</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: The policy specifically addresses the unique properties and requirements of OT and the relationship to non-OT systems.</p>', N'System and Communications Protection', N'System and Communication Protection Policy and Procedures', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37918, N'SC-10', N'Terminate the network connection associated with a communications session at the end of the session or after [Assignment: organization-defined time period] of inactivity.', N'<p><strong>WMATA Policy</strong></p><p>Terminate the network connection associated with a communications session at the end of the session or after 15 minutes of inactivity.</p><p>Related Controls: AC-17, SC-23</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>Rationale for removing SC-10 from MOD and HIGH baselines: The intent of this control is effectively covered by AC-17 (9) for OT systems. </p>', N'System and Communications Protection', N'Network Disconnect', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37919, N'SC-12', N'Establish and manage cryptographic keys when cryptography is employed within the system in accordance with the following key management requirements: [Assignment: organization-defined requirements for key generation, distribution, storage, access, and destruction].', N'<p><strong>WMATA Policy</strong></p><p>Establish and manage cryptographic keys when cryptography is employed within the system in accordance with the following key management requirements:</p><p>a.  Use FIPS 140-2 compliant encryption mechanisms when protecting WMATA Restricted – Medium Sensitivity or WMATA Restricted – High Sensitivity data. Products and modules that have been validated by the AO as FIPS 140-2 compliant will be listed in the Approved Product List (APL).</p><p>b.  All key-based data encryption systems must implement a key escrow system to guarantee access to encrypted data when needed. Key escrow data shall be routinely backed up. Recovery procedures must be tested at least annually to ensure access and availability to encrypted data.</p><p>c.  Ensure that only authorized personnel have access to keys used to access WMATA Restricted – Medium Sensitivity or WMATA Restricted – High Sensitivity data and must ensure encryption keys are properly stored (separate from data) and available, if needed, for later decryption. Users will ensure the following:</p><p>i)  Separation of duties or dual control procedures are enforced.</p><p>ii) Any theft or loss of electronic keys results in the notification of management.</p><p>iii) All keys are protected against modification, substitution, and destruction, and secret/private keys are protected against unauthorized disclosure.</p><p>iv) Cryptographic keys are replaced or retired when keys have reached the end of their life or the integrity of the key has been weakened or compromised.</p><p>v) Physical protection is employed to protect equipment used to synchronize, store, and archive keys.</p><p>vi) An electronic key management and recovery system, including all relevant key escrow procedures, is documented and in place. This shall be handled through key escrow procedures.</p><p>vii) Custodians of cryptographic keys formally acknowledge they understand and accept their key custodian responsibilities.</p><p>d. Encrypted data are recoverable at any point in time, even when the person(s) who encrypted the data is no longer available.</p><p>e. Only digital certificates either issued by and/or approved by DMCS can be used to access the WMATA network, applications, and/or systems</p><p>Related Controls : AC-17, AU-9, AU-10, CM-3, IA-3, IA-7, SA-4, SA-8, SA-9, SC-8, SC-12, SC-13, SC-17, SC-20, SI-3, SI-7</p><p>f.  Security Controls Enhancement(s):</p>', N'System and Communications Protection', N'Cryptographic Key Establishment and Management', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37920, N'SC-12 (1)', N'Maintain availability of information in the event of the loss of cryptographic keys by users.', N'<p><strong>WMATA Policy</strong></p><p>Maintain the availability of information using key escrow systems, techniques, and procedures in the event of the loss of cryptographic keys by users.</p><p></p>', N'System and Communications Protection', N'Cryptographic Key Establishment and Management', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37921, N'SC-13', N'a. Determine the [Assignment: organization-defined cryptographic uses]; andb. Implement the following types of cryptography required for each specified cryptographic use: [Assignment: organization-defined types of cryptography for each specified cryptographic use].', N'<p><strong>WMATA Policy</strong></p><p>a. Determine and document the system’s use of cryptography to include cryptographic algorithms, key sizes, solutions, and solution components; and</p><p>b. Implement cryptography leveraging the latest versions of FIPS 140-2, NIST SP800-131A, or NSA CNSA Suite encryption at the direction of the AO.</p><p>Related Controls:  AC-2, AC-3, AC-7, AC-17, AC-18, AC-19, AU-9, AU-10, CM-11, CP-9, IA-3, IA-5, IA-7, MA-4, MP-2, MP-4, MP-5, SA-4, SA-8, SA-9, SC-8, SC-12, SC-20, SC-23, SC-28, SI-3, SI-7</p>', N'System and Communications Protection', N'Cryptographic Protection', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37922, N'SC-15', N'a. Prohibit remote activation of collaborative computing devices and applications with the following exceptions: [Assignment: organization-defined exceptions where remote activation is to be allowed]; andb. Provide an explicit indication of use to users physically present at the devices.', N'<p><strong>WMATA Policy</strong></p><p>a. Prohibit remote activation of collaborative computing devices and applications including remote meeting devices and applications, networked whiteboards, cameras, and microphones unless authorized by the AO. Only devices and applications listed on the organizational APL may be used.</p><p>b. Provide an explicit indication of use to users physically present at the devices.</p><p>Related Controls: AC-21</p>', N'System and Communications Protection', N'Collaborative Computing Devices and Applications', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37923, N'SC-17', N'a. Issue public key certificates under an [Assignment: organization-defined certificate policy] or obtain public key certificates from an approved service provider; andb. Include only approved trust anchors in trust stores or certificate stores managed by the organization.', N'<p><strong>WMATA Policy</strong></p><p>a. Obtain public key certificates from DMCS-approved service provider(s); and</p><p>b. Include only approved trust anchors in trust stores or certificate stores managed by the organization.</p><p>Related Controls: AU-10, IA-5, SC-12</p>', N'System and Communications Protection', N'Public Key Infrastructure Certificates', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37924, N'SC-18', N'a. Define acceptable and unacceptable mobile code and mobile code technologies; andb. Authorize, monitor, and control the use of mobile code within the system.', N'<p><strong>WMATA Policy</strong></p><p>a.  Define acceptable and unacceptable mobile code and mobile code technologies. Only AO- approved technologies are allowed and shall be developed in accordance with Control 3.4, Configuration Management, Section 6, “CM-6 Configuration Settings”.</p><p>b. Authorize, monitor, and control the use of mobile code within the system.</p><p>Related Controls: AU-2, AU-12, CM-2, CM-6, SI-3</p><p>c. Security Controls Enhancement(s):</p>', N'System and Communications Protection', N'Mobile Code', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37925, N'SC-18 (1)', N'Identify [Assignment: organization-defined unacceptable mobile code] and take [Assignment: organization-defined corrective actions].', N'<p><strong>WMATA Policy</strong></p><p>Unapproved mobile code and mobile code technologies shall be removed from the WMATA environment. The System Owner shall document a POA&M identifying corrective actions and associated timeline subject to the approval of the AO.</p>', N'System and Communications Protection', N'Mobile Code', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37926, N'SC-18 (2)', N'Verify that the acquisition, development, and use of mobile code to be deployed in the system meets [Assignment: organization-defined mobile code requirements].', N'<p><strong>WMATA Policy</strong></p><p>Verify that the acquisition, development, and use of mobile code to be deployed in the system meets DM-defined mobile code requirements in accordance with Control 3.17, Section 13, “SC-18 Mobile Code”, a.</p><p>Related Controls: SC-18</p>', N'System and Communications Protection', N'Mobile Code', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37927, N'SC-18 (3)', N'Prevent the download and execution of [Assignment: organization-defined unacceptable mobile code].', N'<p><strong>WMATA Policy</strong></p><p>Prevent the download and execution of unapproved mobile code and mobile code technologies.</p>', N'System and Communications Protection', N'Mobile Code', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37928, N'SC-18 (4)', N'Prevent the automatic execution of mobile code in [Assignment: organization-defined software applications] and enforce [Assignment: organization-defined actions] prior to executing the code.', N'<p><strong>WMATA Policy</strong></p><p>Prevent the automatic execution of mobile code in software applications and enforce the following actions prior to executing the code:</p><p>(1) Email - prompt users prior to opening attachments or clicking on web links;</p><p>(2) Software - prevent the automatic execution of mobile code by disabling auto-execute features on system components that employ portable storage devices, such as<br>compact discs, digital versatile discs, and universal serial bus devices</p>', N'System and Communications Protection', N'Mobile Code', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37929, N'SC-18 (5)', N'Allow execution of permitted mobile code only in confined virtual machine environments.', N'<p><strong>WMATA Policy</strong></p><p>Allow execution of permitted mobile code only in confined virtual machine environments.</p><p>Related Controls: SI-7</p>', N'System and Communications Protection', N'Mobile Code', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37930, N'SC-2', N'Separate user functionality, including user interface services, from system management functionality.', N'<p><strong>WMATA Policy</strong></p><p>Separate user functionality, including user interface services, from system management functionality.</p><p><strong><u>OT Systems Only: </strong></u>Physical separation includes using separate systems for managing the OT than for operating OT components. Logical separation includes the use of different user accounts for administrative and operator privileges. Example compensating controls including providing increased auditing measures. </p><p>Related Controls: AC-6, SA-4, SA-8, SC-3, SC-7, SC-22, SC-32, SC-39</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Physical separation includes using separate systems for managing the OT and for operating OT components. Logical separation includes the use of different user accounts for administrative and operator privileges. Example compensating controls include providing increased auditing measures.</p>', N'System and Communications Protection', N'Separation of System and User Functionality', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37931, N'SC-20', N'a. Provide additional data origin authentication and integrity verification artifacts along with the authoritative name resolution data the system returns in response to external name/address resolution queries; andb. Provide the means to indicate the security status of child zones and (if the child supports secure resolution services) to enable verification of a chain of trust among parent and child domains, when operating as part of a distributed, hierarchical namespace.', N'<p><strong>WMATA Policy</strong></p><p>a. Provide additional data origin authentication and integrity verification artifacts along with the authoritative name resolution data the system returns in response to external name/address resolution queries; and</p><p>b.  Provide the means to indicate the security status of child zones and (if the child supports secure resolution services) to enable verification of a chain of trust among parent and child domains when operating as part of a distributed, hierarchical namespace.</p><p><strong><u>OT Systems Only:</strong></u> The use of secure name/address resolution services should be determined only after careful consideration and after verification that it does not adversely impact the operational performance of the OT. </p><p>Related Controls: AU-10, SC-8, SC-12, SC-13, SC-21, SC-22</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Secure name/address resolution services should only be used after careful consideration and verification that they do not adversely impact the operational performance of the OT.</p>', N'System and Communications Protection', N'Secure Name/address Resolution Service (authoritative Source)', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37932, N'SC-21', N'Request and perform data origin authentication and data integrity verification on the name/address resolution responses the system receives from authoritative sources.', N'<p><strong>WMATA Policy</strong></p><p>Request and perform data origin authentication and data integrity verification on the name/address resolution responses the system receives from authoritative sources.</p><p><strong><u>OT Systems Only:</strong></u> The use of secure name/address resolution services should be determined only after careful consideration and after verification that it does not adversely impact the operational performance of the OT. </p><p>Related Controls: SC-20, SC-22</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Secure name/address resolution services should only be used after careful consideration and verification that they do not adversely impact the operational performance of the OT.</p>', N'System and Communications Protection', N'Secure Name/address Resolution Service (recursive or Caching Resolver)', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37933, N'SC-22', N'Ensure the systems that collectively provide name/address resolution service for an organization are fault-tolerant and implement internal and external role separation.', N'<p><strong>WMATA Policy</strong></p><p>Ensure the systems that collectively provide name/address resolution service for an organization are fault-tolerant and implement internal and external role separation.</p><p><strong><u>OT Systems Only:</strong></u> The use of secure name/address resolution services should be determined only after careful consideration and after verification that it does not adversely impact the operational performance of the OT.  </p><p>Related Controls: SC-2, SC-20, SC-21, SC-24</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Secure name/address resolution services should only be used after careful consideration and verification that they do not adversely impact the operational performance of the OT.</p>', N'System and Communications Protection', N'Architecture and Provisioning for Name/address Resolution Service', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37934, N'SC-23', N'Protect the authenticity of communications sessions.', N'<p><strong>WMATA Policy</strong></p><p>Protect the authenticity of communications sessions.</p><p><strong><u>OT Systems Only:</strong></u> Example compensating controls include auditing measures. </p><p>Related Controls: AU-10, SC-8, SC-10</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Example compensating controls include auditing measures. </p>', N'System and Communications Protection', N'Session Authenticity', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37935, N'SC-24', N'Fail to a [Assignment: organization-defined known system state] for the following failures on the indicated components while preserving [Assignment: organization-defined system state information] in failure: [Assignment: list of organization-defined types of system failures on organization-defined system components].', N'<p><strong>WMATA Policy</strong></p><p>Systems shall fail to a known, secure system state following failures on system components while preserving system state information.</p><p><strong><u>OT Systems Only:</strong></u> The organization selects an appropriate failure state. Preserving OT state information includes consistency among OT state variables and the physical state which the OT represents (e.g., whether valves are open or closed, communication permitted or blocked, continue operations). </p><p>Related Controls: CP-2, CP-4, CP-10, CP-12, SA-8, SC-7, SC-22, SI-13</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: The organization selects an appropriate failure state. Preserving OT state information includes consistency among OT state variables and the physical state that the OT represents (e.g., whether valves are open or closed, communication permitted or blocked, continue operations). </p><p>Rationale for adding SC-24 to MOD baseline: As part of the architecture and design of the OT, the organization selects an appropriate failure state in accordance with the function performed by the OT and the operational environment. The ability to choose the failure mode for the physical <br>part of OT differentiates OT systems from other IT systems. This choice may be a significant influence in mitigating the impact of a failure since it may be disruptive to ongoing physical processes (e.g., valves failing in closed position may adversely affect system cooling).</p><p></p>', N'System and Communications Protection', N'Fail in Known State', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37936, N'SC-28', N'Protect the [Selection (one or more): confidentiality; integrity] of the following information at rest: [Assignment: organization-defined information at rest].', N'<p><strong>WMATA Policy</strong></p><p>a. Protect the confidentiality and integrity of information at rest.</p><p><strong><u>OT Systems Only:</strong></u> The use of cryptographic mechanisms is implemented only after careful consideration and after verification that it does not adversely impact the operational performance of the OT. Cryptographic mechanisms may not be feasible on certain OT devices. In these cases, compensating controls may be relocating the data to a location that does not support cryptographic mechanisms. </p><p>Related Controls: AC-3, AC-4, AC-6, AC-19, CA-7, CM-3, CM-5, CM-6, CP-9, MP-4, MP-5, PE-3, SC-8, SC-12, SC-13, SI-3, SI-7, SI-16</p><p>b. Security Controls Enhancement(s):</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Cryptographic mechanisms are implemented only after careful consideration and verification that they do not adversely impact the operational performance of the OT. When cryptographic mechanisms are not feasible on certain OT devices, compensating controls may include relocating the data to a location that does support cryptographic mechanisms. </p>', N'System and Communications Protection', N'Protection of Information at Rest', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37937, N'SC-28 (1)', N'Implement cryptographic mechanisms to prevent unauthorized disclosure and modification of the following information at rest on [Assignment: organization-defined system components or media]: [Assignment: organization-defined information].', N'<p><strong>WMATA Policy</strong></p><p>Implement cryptographic mechanisms to prevent unauthorized disclosure and modification of sensitive information on system components or media commensurate with the security category or classification of the information in accordance with Control 3.8 Data Sensitivity.</p>', N'System and Communications Protection', N'Protection of Information at Rest', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37938, N'SC-3', N'Isolate security functions from nonsecurity functions.', N'<p><strong>WMATA Policy</strong></p><p>Isolate security functions from non-security functions.</p><p><strong><u>OT Systems Only:</strong></u> Organizations consider implementing this control when designing new architectures or updating existing components. An example compensating control includes access controls. </p><p>Related Controls: AC-3, AC-6, AC-25, CM-2, CM-4, SA-4, SA-5, SA-8, SA-15, SA-17, SC-2, SC-7, SC-32, SC-39, SI-16</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Organizations consider implementing this control when designing new architectures or updating existing components. An example compensating control includes access controls.</p>', N'System and Communications Protection', N'Security Function Isolation', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37939, N'SC-32', N'Partition the system into [Assignment: organization-defined system components] residing in separate [Selection: physical; logical] domains or environments based on [Assignment: organization-defined circumstances for physical or logical separation of components].', N'<p><strong>WMATA Policy</strong></p><p>Partition the system into [Assignment: organization-defined system components] residing in separate [Selection: physical; logical] domains or environments based on [Assignment: organization-defined circumstances for physical or logical separation of components].</p><p>a. Security Controls Enhancement(s):</p>', N'System and Communications Protection', N'System Partitioning', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37940, N'SC-32 (1)', N'<p><b>System Partitioning | Separate Physical Domains for Privileged Functions</b></p>Partition privileged functions into separate physical domains.', N'<p><strong>WMATA Policy</strong></p><p>Partition privileged functions into separate physical domains.</p><p><strong><u>OT Systems Only:</strong></u> Organizations consider separate physical domains for privileged functions such as those affecting security and safety.</p><p>Related Controls: AC-19, SC-12, SC-13</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Organizations consider separate physical domains for privileged functions, such as those that affect security and safety.</p>', N'System and Communications Protection', N'System Partitioning', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37941, N'SC-39', N'Maintain a separate execution domain for each executing system process.', N'<p><strong>WMATA Policy</strong></p><p>Maintain a separate execution domain for each executing system process.</p><p><strong><u>OT System Only:</strong></u> Example compensating controls include partition processes to separate platforms.</p><p>Related Controls: AC-3, AC-4, AC-6, AC-25, SA-8, SC-2, SC-3, SI-16</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Example compensating controls include partition processes to separate platforms. </p>', N'System and Communications Protection', N'Process Isolation', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37942, N'SC-4', N'Prevent unauthorized and unintended information transfer via shared system resources.', N'<p><strong>WMATA Policy</strong></p><p>Prevent unauthorized and unintended information transfer via shared system resources.</p><p><strong><u>OT Systems Only: </strong></u>This control is especially relevant for OT systems that process confidential data. Example compensating controls include architecting the use of the OT to prevent sharing system resources.</p><p>Related Controls: AC-3, AC-4, SA-8</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: This control is especially relevant for OT systems that process confidential data. <br>Example compensating controls include engineering the use of the OT to prevent sharing system <br>resources.</p>', N'System and Communications Protection', N'Information in Shared System Resources', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37943, N'SC-41', N'[Selection: Physically; Logically] disable or remove [Assignment: organization-defined connection ports or input/output devices] on the following systems or system components: [Assignment: organization-defined systems or system components].', N'<p><strong>WMATA Policy</strong></p><p>[Selection: Physically; Logically] disable or remove [Assignment: organization-defined connection ports or input/output devices] on the following systems or system components: [Assignment: organization-defined systems or system components].<br>	<br>Related Controls: AC-20, MP-7</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>Rationale for adding SC-41 to LOW, MOD, and HIGH baselines: OT functionality is generally defined in advance and does not change often. </p>', N'System and Communications Protection', N'Port and I/O Device Access', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37944, N'SC-45', N'Synchronize system clocks within and between systems and system components.', N'<p><strong>WMATA Policy</strong></p><p>a)  Synchronize system clocks within and between systems and system components.</p><p>OT System: Organizations coordinate time synchronization on OT to allow for accurate troubleshooting and forensics. </p><p>Related Controls: AC-3, AU-8, IA-2, IA-8</p><p>b)  Security Controls Enhancement(s):</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Organizations coordinate time synchronization on OT to allow for accurate <br>troubleshooting and forensics. </p><p>Rationale for adding SC-45 to LOW, MOD, and HIGH baselines: Organizations may find relative system time beneficial for many OT systems to ensure the safe and reliable delivery of essential functions. Time synchronization can also make root cause analysis more efficient by ensuring that audit logs from different systems are aligned so that organizations have an accurate <br>view of events across multiple systems when the logs are aggregated.<br></p>', N'System and Communications Protection', N'System Time Synchronization', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37945, N'SC-45 (1)', N'<p><b>System Time Synchronization | Synchronization with Authoritative Time Source</b></p>(a) Compare the internal system clocks [Assignment: organization-defined frequency] with [Assignment: organization-defined authoritative time source]; and(b) Synchronize the internal system clocks to the authoritative time source when the time difference is greater than [Assignment: organization-defined time period].', N'<p><strong>WMATA Policy</strong></p><p>(1)  Compare the internal system clocks [Assignment: organization-defined frequency] with [Assignment: organization-defined authoritative time source]; and</p><p>(2)  Synchronize the internal system clocks to the authoritative time source when the time difference is greater than [Assignment: organization-defined time period].<br>	<br><strong><u>OT Systems Only:</strong></u> Syncing with an authoritative time source may be selected as a control when data is being correlated across organizational boundaries. OT employ suitable mechanisms (e.g., GPS, IEEE 1588) for time stamps.</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Syncing with an authoritative time source may be selected as a control when data is being correlated across organizational boundaries. OT employ suitable mechanisms (e.g., GPS, IEEE 1588) for timestamps.</p><p></p>', N'System and Communications Protection', N'System Time Synchronization', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37946, N'SC-47', N'Establish [Assignment: organization-defined alternate communications paths] for system operations organizational command and control.', N'<p><strong>WMATA Policy</strong></p><p>Establish [Assignment: organization-defined alternate communications paths] for system operations organizational command and control.</p><p>OT Systems Only: Organization considers which systems require alternate communications paths to ensure a loss of communication does not lead to an unacceptable loss of view, control or safety event.</p><p>Related Controls: CP-2, CP-8</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Organizations consider which systems require alternate communication paths to ensure that a loss of communication does not lead to an unacceptable loss of view or control or to a safety event.</p><p>Rationale for adding SC-47 to HIGH baseline: For continuity of operations during an incident, organizations should consider establishing alternate communications paths for command-andcontrol purposes to continue to operate and take appropriate actions for high-impact systems when the loss of availability or integrity may result in severe or catastrophic adverse impacts, including impacts to safety and critical service delivery.</p>', N'System and Communications Protection', N'Alternate Communication Paths', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37947, N'SC-5', N'a. [Selection: Protect against; Limit] the effects of the following types of denial-of-service events: [Assignment: organization-defined types of denial-of-service events]; andb. Employ the following controls to achieve the denial-of-service objective: [Assignment: organization-defined controls by type of denial-of-service event].', N'<p><strong>WMATA Policy</strong></p><p>a. Protect against and limit the effects of denial-of-service events; and</p><p>b. Employ the controls to achieve the denial-of-service objective to include, but not limited to:</p><p>i)  Requiring implementation of enterprise boundary protection devices (e.g., firewall, web application firewall, etc.) at all network access points</p><p>ii) Requiring system integration with enterprise boundary protection devices;</p><p>iii) Periodically scanning network and devices for malware;</p><p>iv) Providing detection and monitoring capabilities to detect indicators of attack against WMATA;</p><p>v) Monitoring system resource utilization to ensure sufficient capacity;</p><p>vi) Managing excess capacity, bandwidth, or other redundancy;</p><p>vii) Deploying authentication mechanisms wherever technically configurable;</p><p>viii) Designing and implementing networks for maximum resiliency that incorporate high availability (e.g., load balancing, redundant systems, etc.) and automated disaster recovery (e.g., automated failover and isolated restoration capabilities);</p><p>ix) Developing specific plans for responding to DoS and DDoS attacks in the WMATA incident response plan, a system’s disaster recovery and continuity of operations plan,<br>and the enterprise business continuity plan;</p><p><strong><u>OT Systems Only:</strong></u>  Some OT equipment may be more susceptible to DoS attacks due to the time criticality of some OT applications. Risk-based analysis informs prioritization of DoS protection and establishment of policy and procedure. </p><p>Related Controls:  CP-2, IR-4, SC-7</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Some OT equipment may be more susceptible to DoS attacks due to the time criticality of some OT applications. Risk-based analysis informs the prioritization of DoS protection and the establishment of policy and procedure.<br></p>', N'System and Communications Protection', N'Denial-of-service Protection', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37948, N'SC-51', N'a. Employ hardware-based, write-protect for [Assignment: organization-defined system firmware components]; andb. Implement specific procedures for [Assignment: organization-defined authorized individuals] to manually disable hardware write-protect for firmware modifications and re-enable the write-protect prior to returning to operational mode.', N'<p><strong>WMATA Policy</strong></p><p>a)  Employ hardware-based, write-protect for [Assignment: organization-defined system firmware components]; and</p><p>b)  Implement specific procedures for [Assignment: organization-defined authorized individuals] to manually disable hardware write-protect for firmware modifications and re-enable the write-protect prior to returning to operational mode. </p><p><strong><u>OT Systems Only:</strong></u> Some OT systems support write-protection by implementing physical key switches or write-protect switches. Organizations define the systems for which write-protection will be enables and develop a process for how to take the system out of write-protect mode. </p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Some OT systems support write-protection by implementing physical key switches or write-protect switches. Organizations define the systems for which write-protection will be enabled and develop a process for how to take the system out of write-protect mode. </p>', N'System and Communications Protection', N'Hardware-Based Protection', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37949, N'SC-7', N'a. Monitor and control communications at the external managed interfaces to the system and at key internal managed interfaces within the system;b. Implement subnetworks for publicly accessible system components that are [Selection: physically; logically] separated from internal organizational networks; andc. Connect to external networks or systems only through managed interfaces consisting of boundary protection devices arranged in accordance with an organizational security and privacy architecture.', N'<p><strong>WMATA Policy</strong></p><p>a. Monitor and control communications at the external managed interfaces to the system and at key internal managed interfaces (e.g., gateways, routers, firewalls, guards, network-based malicious code analysis, virtualization systems, or encrypted tunnels) within the system;</p><p>b. Implement subnetworks for publicly accessible system components that are physically and logically separated from internal organizational networks; and</p><p>c.  Connect to external networks or systems only through managed interfaces consisting of boundary protection devices arranged in accordance with an organizational security and privacy architecture.</p><p>Related Controls:  AC-4, AC-17, AC-18, AC-19, AC-20, CA-3, CM-2, CM-4, CM-7, CM-10, CP-8, CP-10, IR-4, MA-4, PE-3, PL-8, PM-12, SA-8, SA-17, SC-5, SC-32</p><p>d. Security Controls Enhancement(s):</p>', N'System and Communications Protection', N'Boundary Protection', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37950, N'SC-7 (11)', N'Only allow incoming communications from [Assignment: organization-defined authorized sources] to be routed to [Assignment: organization-defined authorized destinations].', N'<p><strong>WMATA Policy</strong></p><p>Only allow incoming communications from [Assignment: organization-defined authorized <br>sources] to be routed to [Assignment: organization-defined authorized destinations].</p><p>Related Controls: AC-3</p>', N'System and Communications Protection', N'Boundary Protection', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37951, N'SC-7 (18)', N'<p><b>Boundary Protection | Fail Secure</b></p>Prevent systems from entering unsecure states in the event of an operational failure of a boundary protection device.', N'<p><strong>WMATA Policy</strong></p><p>Prevent systems from entering unsecure states in the event of an operational failure of a boundary protection device.</p><p><strong><u>OT Systems Only:</strong></u> The organization selects an appropriate failure mode (e.g., permit or block all communications).</p><p>Related Controls: CP-2, CP-12, SC-24</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: The organization selects an appropriate failure mode (e.g., permit or block all communications). </p><p>Rationale for adding SC-7 (18) to MOD baseline: The ability to choose the failure mode for the physical part of the OT differentiates the OT from other IT systems. This choice may be a significant influence in mitigating the impact of a failure. </p>', N'System and Communications Protection', N'Boundary Protection', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37952, N'SC-7 (20)', N'Provide the capability to dynamically isolate [Assignment: organization-defined system components] from other system components.', N'<p><strong>WMATA Policy</strong></p><p>Provide the capability to dynamically isolate [Assignment: organization-defined system <br>components] from other system components.</p>', N'System and Communications Protection', N'Boundary Protection', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37953, N'SC-7 (21)', N'Employ boundary protection mechanisms to isolate [Assignment: organization-defined system components] supporting [Assignment: organization-defined missions and/or business functions].', N'<p><strong>WMATA Policy</strong></p><p>Employ additional boundary protection mechanisms to isolate system components supporting critical or essential missions and/or business functions (e.g., financial systems, health systems, payment card systems, industrial control systems, etc.).</p><p>Related Controls: CA-9</p>', N'System and Communications Protection', N'Boundary Protection', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37954, N'SC-7 (24)', N'For systems that process personally identifiable information:(a) Apply the following processing rules to data elements of personally identifiable information: [Assignment: organization-defined processing rules];(b) Monitor for permitted processing at the external interfaces to the system and at key internal boundaries within the system;(c) Document each processing exception; and(d) Review and remove exceptions that are no longer supported.', N'<p><strong>WMATA Policy</strong></p><p>For systems that process PII:</p><p>(1) Apply the following processing rules to data elements of personally identifiable<br>information:</p><p>(a) Implement Data Loss Prevention technologies and processes designed to enforce the proper handling of PII, as defined in P/I 9.3 Public Access to Records Policy and Control 3.8 Data Sensitivity.</p><p>(2) Monitor for permitted processing at the external interfaces to the system and at key internal boundaries within the system;</p><p>(3) Document each processing exception and require AO approval; and</p><p>(4) Review and remove exceptions that are no longer supported.</p><p>Related Controls:  PT-2</p>', N'System and Communications Protection', N'Boundary Protection', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37955, N'SC-7 (28)', N'<p><b>Boundary Protection | Connections to Public Networks </b></p>Prohibit the direct connection of [Assignment: organization-defined system] to a public network.', N'<p><strong>WMATA Policy</strong></p><p>Prohibit the direct connection of [Assignment: organization-defined system] to a public network.<br>	<br><strong><u>OT Systems Only:</strong></u> Organizations consider the need for a direct connection to a public network for each OT system, including potential benefits, additional threat vectors, and potential adverse impact specifically relevant to what type of public access that connection introduces. </p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Organizations consider the need for a direct connection to a public network for each OT system, including potential benefits, additional threat vectors, and potential adverse impacts that are specifically relevant to the type of public access that connection introduces.</p><p>Rationale for adding SC-7 (28) to LOW, MOD, and HIGH baselines: Access to OT should be restricted to the individuals required for operation. A connection made from the OT directly to a public network has limited applicability in OT environments but significant potential risk. <br></p>', N'System and Communications Protection', N'Boundary Protection', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37956, N'SC-7 (29)', N'<p><b>Boundary Protection | Separate Subnets to Isolate Functions </b></p>Implement [Selection: physically; logically] separate subnetworks to isolate the following critical system components and functions: [Assignment: organization-defined critical system components and functions].', N'<p><strong>WMATA Policy</strong></p><p>Implement [Selection: physically; logically] separate subnetworks to isolate the following critical system components and functions: [Assignment: organization-defined critical system components and functions]. </p><p><strong><u>OT Systems Only: </strong></u>Subnets can be used to isolate low-risk functions from higher-risk ones, and control from safety. Subnets should be considered along with other boundary protection technologies.</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Subnets can be used to isolate low-risk functions from higher-risk ones and control from safety. Subnets should be considered along with other boundary protection technologies.</p><p>Rationale for adding SC-7 (29) to LOW, MOD, and HIGH baselines: In OT environments, subnets and zoning are common practices for isolating functions. </p>', N'System and Communications Protection', N'Boundary Protection', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37957, N'SC-7 (3)', N'Limit the number of external network connections to the system.', N'<p><strong>WMATA Policy</strong></p><p>Limit the number of external network connections to the system. External network connections must be documented via a System Architecture/Topology/Data Flow and PPS/M. An ISA may be required at the discretion of the AO.</p><p></p>', N'System and Communications Protection', N'Boundary Protection', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37958, N'SC-7 (4)', N'(a) Implement a managed interface for each external telecommunication service;(b) Establish a traffic flow policy for each managed interface;(c) Protect the confidentiality and integrity of the information being transmitted across each interface;(d) Document each exception to the traffic flow policy with a supporting mission or business need and duration of that need;(e) Review exceptions to the traffic flow policy [Assignment: organization-defined frequency] and remove exceptions that are no longer supported by an explicit mission or business need;(f) Prevent unauthorized exchange of control plane traffic with external networks;(g) Publish information to enable remote networks to detect unauthorized control plane traffic from internal networks; and(h) Filter unauthorized control plane traffic from external networks.', N'<p><strong>WMATA Policy</strong></p><p>(1) Implement a managed interface for each external telecommunication service;<br>(2) Establish a traffic flow policy for each managed interface;</p><p>(3) Protect the confidentiality and integrity of the information being transmitted across each interface;</p><p>(4) Document each exception to the traffic flow policy with a supporting mission or business need and the duration of that need;</p><p>(5) Review exceptions to the traffic flow policy at least semi-annually and remove exceptions that are no longer supported by an explicit mission or business need;</p><p>(6) Prevent unauthorized exchange of control plane traffic (e.g., Border Gateway Protocol (BGP) routing, Domain Name System (DNS), and management protocols) with external networks;</p><p>(7) Publish information to enable remote networks to detect unauthorized control plane traffic from internal networks; and (8) Filter unauthorized control plane traffic from external networks.</p><p>(8) Filter unauthorized control plane traffic from external networks.</p><p>Related Controls: AC-3, SC-8, SC-20, SC-21, SC-22</p><p><br></p>', N'System and Communications Protection', N'Boundary Protection', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37959, N'SC-7 (5)', N'Deny network communications traffic by default and allow network communications traffic by exception [Selection (one or more): at managed interfaces; for [Assignment: organization-defined systems]].', N'<p><strong>WMATA Policy</strong></p><p>Deny network communications traffic by default. Any explicit rules to allow network communications traffic by default or exception shall be authorized by the AO.</p>', N'System and Communications Protection', N'Boundary Protection', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37960, N'SC-7 (7)', N'Prevent split tunneling for remote devices connecting to organizational systems unless the split tunnel is securely provisioned using [Assignment: organization-defined safeguards].', N'<p><strong>WMATA Policy</strong></p><p>Prevent split tunneling for remote devices connecting to organizational systems unless the split tunnel is authorized by the AO.</p>', N'System and Communications Protection', N'Boundary Protection', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37961, N'SC-7 (8)', N'Route [Assignment: organization-defined internal communications traffic] to [Assignment: organization-defined external networks] through authenticated proxy servers at managed interfaces.', N'<p><strong>WMATA Policy</strong></p><p>Route internal communications traffic to external networks through authenticated proxy servers at managed interfaces.</p><p>(1) Inappropriate Web Content and Filtering</p><p>(a) The use of Metro information technology systems to access inappropriate web content is strictly prohibited and will be blocked. Any user attempting to access such content will be subject to disciplinary action, up to and including termination of employment.</p><p>(b) Web content filtering shall be employed to prevent access to internet sites and web pages that are non-business related. Filtering shall disallow, segregate, or reject certain internet listings. </p><p>The following web content categories will be blocked:</p><p>(i) Sexually explicit and obscene material (including any and all forms of pornography, adult humor, profanity, dating services/personals);</p><p>(ii) Websites selling drugs, firearms, and other weapons;</p><p>(iii) Websites advocating or involving terrorism, hacking, gambling, fraud or any other criminal conduct or enterprises;</p><p>(iv) Harassing material, including racial, religious, national origin, sexual or sexual orientation harassment; and/or</p><p>(v) Information that violates federal laws on discrimination.</p><p>(c) Miscategorized websites and requests appropriate and necessary business access to restricted websites shall be referred to the DM Helpdesk.</p><p>(d) Website categorization decisions and exceptions to access restricted websites<br>shall be managed by DMCS.</p><p>Related Controls: AC-3</p>', N'System and Communications Protection', N'Boundary Protection', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37962, N'SC-8', N'Protect the [Selection (one or more): confidentiality; integrity] of transmitted information.', N'<p><strong>WMATA Policy</strong></p><p>a. Protect the confidentiality and integrity of transmitted information.</p><p>Related Controls:  AC-17, AC-18, AU-10, IA-3, IA-8, MA-4, PE-4, SA-4, SA-8, SC-7, SC-20, SC-23, SC-28</p><p>b. Security Controls Enhancement(s):</p>', N'System and Communications Protection', N'Transmission Confidentiality and Integrity', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37963, N'SC-8 (1)', N'<p><b>Transmission Confidentiality and Integrity | Cryptographic Protection</b></p>Implement cryptographic mechanisms to [Selection (one or more): prevent unauthorized disclosure of information; detect changes to information] during transmission.', N'<p><strong>WMATA Policy</strong></p><p>Implement cryptographic mechanisms to prevent unauthorized disclosure of information and detect changes to information during transmission.</p><p><strong><u>OT Systems Only: </strong></u>When transmitting across untrusted network segments, the organization explores all possible cryptographic integrity mechanisms (e.g., digital signature, hash function) to protect confidentiality and integrity of the information. Example compensating controls include physical protections, such as a secure conduit (e.g., point-to-point link) between two system components. </p><p>Related Controls: SC-12, SC-13</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: When transmitting across untrusted network segments, the organization explores all possible cryptographic integrity mechanisms (e.g., digital signature, hash function) to protect the confidentiality and integrity of the information. Example compensating controls include physical protections, such as a secure conduit (e.g., point-to-point link) between two system components. <br></p>', N'System and Communications Protection', N'Transmission Confidentiality and Integrity', NULL, NULL, N'WMATA', NULL, NULL, NULL, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37964, N'SI-1', N'a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:     1. [Selection (one or more): Organization-level; Mission/business process-level; System-level] system and information integrity policy that:          (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and           compliance; and          (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and     2. Procedures to facilitate the implementation of the system and information integrity policy and the associated system and information integrity      controls;b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the system and information integrity policy and procedures; andc. Review and update the current system and information integrity:     1. Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and     2. Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].', N'<p><strong>WMATA Policy</strong></p><p>Reference P/I 15.28 Cybersecurity Policy for requirements.</p><p>Related Controls: PM-9, PS-8, SA-8, SI-12</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: The policy specifically addresses the unique properties and requirements of OT <br>and the relationship to non-OT systems.</p>', N'System and Information Integrity', N'System and Information Integrity Policy and Procedures', NULL, NULL, N'WMATA', NULL, NULL, NULL, 73, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37965, N'SI-10', N'Check the validity of the following information inputs: [Assignment: organization-defined information inputs to the system].', N'<p><strong>WMATA Policy</strong></p><p>a. Character set, length, numerical range, and acceptable values;</p><p>b. Username and password combinations;</p><p>c. Attributes used to validate a password reset request (e.g., security questions);</p><p>d. PII (excluding unique username identifiers provided as a normal part of a transactional record) or other Sensitive Information in accordance with Control 3.8 Data Sensitivity;</p><p>e. Content related to internal security functions: private encryption keys, whitelist or blacklist rules, object permission attributes and settings;</p><p>f. Content received from system interfaces that is passed to interpreters that can unintentionally be interpreted as commands and to prevent cross-site scripting and injection attacks;</p><p>g. User-supplied data is validated, filtered, and sanitized;</p><p>h. Context-aware escaping is used for dynamic queries and non-parameterized calls when used directly in the interpreter;</p><p>i. Hostile data is not used within object-relational mapping search parameters to extract additional, sensitive records; and</p><p>j. Hostile data is not directly used or concatenated, such that the SQL or command contains both structure and hostile data in dynamic queries, commands, or stored procedures.</p>', N'System and Information Integrity', N'Information Input Validation', NULL, NULL, N'WMATA', NULL, NULL, NULL, 73, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37966, N'SI-11', N'a. Generate error messages that provide information necessary for corrective actions without revealing information that could be exploited; andb. Reveal error messages only to [Assignment: organization-defined personnel or roles].', N'<p><strong>WMATA Policy</strong></p><p>a. Generate error messages that provide information necessary for corrective actions without revealing information that could be exploited; and</p><p>b. Reveal error messages only to users and administrators in accordance with assigned roles and responsibilities.</p><p>Related Controls: AU-2, AU-3, SI-2</p>', N'System and Information Integrity', N'Error Handling', NULL, NULL, N'WMATA', NULL, NULL, NULL, 73, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37967, N'SI-12', N'Manage and retain information within the system and information output from the system in accordance with applicable laws, executive orders, directives, regulations, policies, standards, guidelines and operational requirements.', N'<p><strong>WMATA Policy</strong></p><p>a. Manage and retain information within the system and information output from the system in accordance with applicable laws, directives, regulations, policies, standards, guidelines and operational requirements.</p><p>Related Controls: All XX-1 Controls, AU-5, AU-11, CA-2, CA-3, CA-5, CA-6, CA-7, CA-9, CM-5, CM-9, CP-2, IR-8, MP-2, MP-3, MP-4, MP-6, PL-2, PL-4, PM-4, PM-8, PM-9, PS-2, PS-6, PT-2, PT-3, RA-2, RA-3, SA-5, SA-8, SR-2</p><p>b. Security Controls Enhancement(s):</p>', N'System and Information Integrity', N'Information Management and Retention', NULL, NULL, N'WMATA', NULL, NULL, NULL, 73, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37968, N'SI-12 (1)', N'Limit personally identifiable information being processed in the information life cycle to the following elements of personally identifiable information: [Assignment: organization-defined elements of personally identifiable information].', N'<p><strong>WMATA Policy</strong></p><p>Limit Personally Identifiable Information (PII) being processed in the information life cycle (i.e. information creation, collection, use, processing, storage, maintenance, dissemination, disclosure, and disposition) to the minimum necessary to enable the purpose of the system.</p><p>Related Controls: PM-25</p>', N'System and Information Integrity', N'Information Management and Retention', NULL, NULL, N'WMATA', NULL, NULL, NULL, 73, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37969, N'SI-12 (2)', N'Use the following techniques to minimize the use of personally identifiable information for research, testing, or training: [Assignment: organization-defined techniques].', N'<p><strong>WMATA Policy</strong></p><p>Use the following techniques to minimize the use of Sensitive Information for research, testing, or training:</p><p>(1) De-identification or subsetting of live production data (“live data”); or</p><p>(2) Use of synthetic data.</p><p>Related Controls: PM-22, PM-25, SI-19</p>', N'System and Information Integrity', N'Information Management and Retention', NULL, NULL, N'WMATA', NULL, NULL, NULL, 73, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37970, N'SI-12 (3)', N'Use the following techniques to dispose of, destroy, or erase information following the retention period: [Assignment: organization-defined techniques].', N'<p><strong>WMATA Policy</strong></p><p>Use techniques to dispose of, destroy, or erase information following the retention period applicable to each type of data.</p><p></p>', N'System and Information Integrity', N'Information Management and Retention', NULL, NULL, N'WMATA', NULL, NULL, NULL, 73, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37971, N'SI-13', N'a. Determine mean time to failure (MTTF) for the following system components in specific environments of operation: [Assignment: organization-defined system components]; andb. Provide substitute system components and a means to exchange active and standby components in accordance with the following criteria: [Assignment: organization-defined MTTF substitution criteria].', N'<p><strong>WMATA Policy</strong></p><p>a.  Determine mean time to failure (MTTF) for the following system components in specific environments of operation: [Assignment: organization-defined system components]; and</p><p>b.  Provide substitute system components and a means to exchange active and standby components in accordance with the following criteria: [Assignment: organization-defined MTTF substitution criteria]. <br>	<br>Related Controls: CP-2, CP-10, MA-2, MA-6, SA-8</p><p><br><strong><u>NIST 800-82 Rev 3:</strong></u><br>Rationale for adding SI-13 control to HIGH baseline: OT are designed and built with certain boundary conditions, design parameters, and assumptions about their environment and mode of operation. OT may run much longer than conventional systems, allowing latent flaws that are not manifest in other environments to become effective. For example, integer overflow might never occur in systems that are re-initialized more frequently than the occurrence of the overflow. Experience and forensic studies of anomalies and incidents in OT can lead to the identification of emergent properties that were previously unknown, unexpected, or unanticipated. Preventative and restorative actions (e.g., restarting the system or application) are prudent but may not be acceptable in OT for operational reasons.</p>', N'System and Information Integrity', N'Predictable Failure Protection', NULL, NULL, N'WMATA', NULL, NULL, NULL, 73, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37972, N'SI-16', N'Implement the following controls to protect the system memory from unauthorized code execution: [Assignment: organization-defined controls].', N'<p><strong>WMATA Policy</strong></p><p>Implement controls to protect the system memory from unauthorized code execution through data execution prevention controls that are either hardware-enforced or software-enforced such as data execution prevention, address space layout randomization, and implementation of secure configuration settings.</p><p>Related Controls: AC-25, SC-3, SI-7</p>', N'System and Information Integrity', N'Memory Protection', NULL, NULL, N'WMATA', NULL, NULL, NULL, 73, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37973, N'SI-17', N'Implement the indicated fail-safe procedures when the indicated failures occur: [Assignment: organization-defined list of failure conditions and associated fail-safe procedures].', N'<p><strong>WMATA Policy</strong></p><p>Implement the indicated fail-safe procedures when the indicated failures occur: [Assignment: organization-defined list of failure conditions and associated fail-safe procedures].</p><p><strong><u>OT Systems Only: </strong></u>The selected failure conditions and corresponding procedures may vary among baselines. The same failure event may trigger different responses, depending on the impact level mechanical and analog systems can be sued to provide mechanisms to ensure fail-safe procedures. Fail-safe states should incorporate potential impacts to human safety, physical systems, and the environment. Related controls: CP-6.</p><p>Related Controls: CP-6, CP-12, SC-24, SI-13</p><p><br><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: The selected failure conditions and corresponding procedures may vary among baselines. The same failure event may trigger different responses, depending on the impact level. Mechanical and analog systems can be used to provide mechanisms to ensure fail-safe procedures. Fail-safe states should incorporate potential impacts to human safety, physical systems, and the environment. A related controls is CP-6. </p><p>Rationale for adding SI-17 to LOW, MOD, and HIGH baselines: This control provides a structure for the organization to identify its policy and procedures for dealing with failures and other incidents. Creating a written record of the decision process for selecting incidents and appropriate responses in light of a changing environment of operations is part of risk management. </p>', N'System and Information Integrity', N'Fail-Safe Procedures', NULL, NULL, N'WMATA', NULL, NULL, NULL, 73, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37974, N'SI-18', N'a. Check the accuracy, relevance, timeliness, and completeness of personally identifiable information across the information life cycle [Assignment: organization-defined frequency]; andb. Correct or delete inaccurate or outdated personally identifiable information.', N'<p><strong>WMATA Policy</strong></p><p>a. Check the accuracy, relevance, timeliness, and completeness of PII across the information life cycle annually; and</p><p>b. Correct or delete inaccurate or outdated personally identifiable information.</p><p>c. Individual requests for access or amendment to PII will be processed according to the procedures set forth in P/I 9.2 Privacy Policy sections 7.2-7.5.</p><p>Related Controls: PM-22, PM-24, PT-2, SI-4</p><p>d.  Security Controls Enhancement(s):</p>', N'System and Information Integrity', N'Personally Identifiable Information Quality Operations', NULL, NULL, N'WMATA', NULL, NULL, NULL, 73, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37975, N'SI-18 (4)', N'Correct or delete personally identifiable information upon request by individuals or their designated representatives.', N'<p><strong>WMATA Policy</strong></p><p>Correct or delete PII upon request by individuals or their designated representatives. Discretion shall be used when determining if PII is to be corrected or deleted based on the scope of request, the change(s) sought, the impact of the change(s), and applicable law, regulation, and policy. </p><p>Consult with the Privacy Officer and Legal Counsel regarding appropriate measures to be taken for requests to correct or delete PII based on balancing the rights of the individual with the needs of the organization. </p>', N'System and Information Integrity', N'Personally Identifiable Information Quality Operations', NULL, NULL, N'WMATA', NULL, NULL, NULL, 73, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37976, N'SI-19', N'a. Remove the following elements of personally identifiable information from datasets: [Assignment: organization-defined elements of personally identifiable information]; andb. Evaluate [Assignment: organization-defined frequency] for effectiveness of de-identification.', N'<p><strong>WMATA Policy</strong></p><p>a. Remove sensitive information about individuals that can be used to distinguish or trace an individual’s identity (e.g., name, social security number, date and place of birth, mother’s maiden name, or biometric records, financial records, educational records, etc.) from datasets unless otherwise authorized by the Privacy Administrator under P/I 9.2 Privacy Policy and AO. See also Control 3.18 System and Information Integrity, Section 11, (a), (ii), “S1-12 (2) Minimize Sensitive Information in Testing, Training, and Research”;</p><p>b. Personally identifiable information is removed from datasets by trained individuals when such information is not (or no longer) necessary to satisfy the requirements envisioned for the data (e.g., if the dataset is only used to produce aggregate statistics, the identifiers that are not needed for producing those statistics are removed); and</p><p>c. Evaluate annually for the effectiveness of de-identification.</p><p>Related Controls: MP-6, PM-22, PM-23, PM-24, RA-2, SI-12</p>', N'System and Information Integrity', N'De-Identification', NULL, NULL, N'WMATA', NULL, NULL, NULL, 73, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37977, N'SI-2', N'a. Identify, report, and correct system flaws;b. Test software and firmware updates related to flaw remediation for effectiveness and potential side effects before installation;c. Install security-relevant software and firmware updates within [Assignment: organization-defined time period] of the release of the updates; andd. Incorporate flaw remediation into the organizational configuration management process.', N'<p><strong>WMATA Policy</strong></p><p>a. Identify, report, and correct system flaws;</p><p>b. Test software and firmware updates related to flaw remediation for effectiveness and potential side effects before installation;</p><p>c. Install security-relevant software and firmware updates within a timeframe set per Control 3.16 Risk Assessment of the release of the updates; and</p><p>d. Incorporate flaw remediation into the organizational configuration management process.</p><p><strong><u>OT Systems Only:</strong></u> Flaw remediation, or patching, is complicated since many OT employ OSs and other software no longer maintained by the vendors. OT operators may also not have the resources or capability to test patches and are dependent on vendors to validate the operability of a patch. Sometimes the organization has no choice but to accept the additional risk if no vendor patch is available, patching requires additional time to complete validation/testing, or deployment requires an unacceptable operations shutdown. In these situations, compensating controls should be implemented (e.g., limiting the exposure of these vulnerable system, restricting vulnerable services, implementing virtual patching). Other compensating controls that do not decrease the residual risk but increase the ability to respond may be desirable (e.g., provide a timely response in case of an incident; devise a plan to ensure the OT can identify the exploitation of the flaw). Testing flaw remediation in an OT may exceed the organization’s available resources. </p><p>Related Controls: CA-5, CM-3, CM-4, CM-5, CM-6, CM-8, MA-2, RA-5, SA-8, SA-10, SA-11, SI-3, SI-5, SI-7, SI-11</p><p>e. Security Controls Enhancement(s):</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Flaw remediation, or patching, is complicated since many OT employ OSs and other software that are no longer maintained by the vendors. OT operators may also not have the resources or capability to test patches and are dependent on vendors to validate the operability of a patch. Sometimes, the organization has no choice but to accept additional risk if no vendor patch is available, if patching requires additional time to complete validation or testing, or if deployment requires an unacceptable operations shutdown. In these situations, compensating controls should be implemented (e.g., limiting the exposure of the vulnerable system, restricting vulnerable services, implementing virtual patching). Other compensating controls that do not decrease the residual risk but increase the ability to respond may be desirable (e.g., provide a timely response in case of an incident, devise a plan to ensure that the OT can identify exploitation of the flaw). Testing flaw remediation in an OT may exceed the organization’s available resources.</p>', N'System and Information Integrity', N'Flaw Remediation', NULL, NULL, N'WMATA', NULL, NULL, NULL, 73, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37978, N'SI-2 (2)', N'Determine if system components have applicable security-relevant software and firmware updates installed using [Assignment: organization-defined automated mechanisms] [Assignment: organization-defined frequency].', N'<p><strong>WMATA Policy</strong></p><p>Determine if system components have applicable security-relevant software and firmware updates installed using automated mechanisms in accordance with Control 3.16 Risk Assessment, Section 4, “RA-5 Vulnerability Monitoring and Scanning“.</p><p>Related Controls: CA-7, RA-5, SI-4</p>', N'System and Information Integrity', N'Flaw Remediation', NULL, NULL, N'WMATA', NULL, NULL, NULL, 73, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37979, N'SI-22', N'a. Identify the following alternative sources of information for [Assignment: organization-defined essential functions and services]: [Assignment: organization-defined alternative information sources]; andb. Use an alternative information source for the execution of essential functions or services on [Assignment: organization-defined systems or system components] when the primary source of information is corrupted or unavailable.', N'<p><strong>WMATA Policy</strong></p><p>a.  Identify the following alternative sources of information for [Assignment: organization-defined essential functions and services]: [Assignment: organization-defined alternative information sources];</p><p>b.  Use an alternative information source for the execution of essential functions or services on [Assignment: organization-defined systems or system components] when the primary source of information is corrupted or unavailable. </p><p><strong><u>OT Systems Only:</strong></u> Many OT systems use information diversity in their design in order to achieve reliability requirements. Some examples of information diversity for an OT system include sensor voting and state estimation. </p><p><br><strong><u>NIST 800-82 Rev 3:<br></strong></u>OT Discussion: Many OT systems use information diversity in their design to achieve reliability requirements. Some examples of information diversity for an OT system include sensor voting and state estimation. </p>', N'System and Information Integrity', N'Information Diversity', NULL, NULL, N'WMATA', NULL, NULL, NULL, 73, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37980, N'SI-3', N'a. Implement [Selection (one or more): signature based; non-signature based] malicious code protection mechanisms at system entry and exit points to detect and eradicate malicious code;b. Automatically update malicious code protection mechanisms as new releases are available in accordance with organizational configuration management policy and procedures;c. Configure malicious code protection mechanisms to:     1. Perform periodic scans of the system [Assignment: organization-defined frequency] and real-time scans of files from external sources at      [Selection (one or more): endpoint; network entry and exit points] as the files are downloaded, opened, or executed in accordance with      organizational policy; and     2. [Selection (one or more): block malicious code; quarantine malicious code; take [Assignment: organization-defined action]]; and send alert      to [Assignment: organization-defined personnel or roles] in response to malicious code detection; andd. Address the receipt of false positives during malicious code detection and eradication and the resulting potential impact on the availability of the system.', N'<p><strong>WMATA Policy</strong></p><p>a. Implement non-signature based malicious code protection mechanisms at system entry and exit points to detect and eradicate malicious code;</p><p>b. Automatically update malicious code protection mechanisms as new releases are available in accordance with organizational configuration management control family and procedures;</p><p>c. Configure malicious code protection mechanisms to:</p><p>i) Perform real-time monitoring to detect attempts of malicious code execution at endpoints, servers, between security zones, and at network entry and exit points;</p><p>ii) Conduct scans of files and embedded code which are attached to, or included in email communication; and</p><p>iii) Block or quarantine malicious code and send alert to required stakeholders in response to malicious code detection.</p><p>d. Address the receipt of false positives during malicious code detection and eradication and the resulting potential impact on the availability of the system.</p><p><strong><u>OT Systems Only:</strong></u> The use and deployment of malicious code protection is determined after careful consideration and after verification that it does not adversely impact the operation of the OT. Malicious code protection tools should be configured to minimize their potential impact on the OT (e.g., employ notification rather than quarantine). Example compensating controls include increase traffic monitoring and auditing. </p><p>Related Controls: AC-4, AC-19, CM-3, CM-8, IR-4, MA-3, MA-4, PL-9, RA-5, SC-7, SC-23, SC-28, SI-2, SI-4, SI-7, SI-8</p><p><strong><u>NIST 800-82 Rev 3:<br></strong></u>OT Discussion: Malicious code protection should only be deployed after careful consideration and verification that it does not adversely impact the operation of the OT. Malicious code protection tools should be configured to minimize their potential impact on the OT (e.g., employ notification rather than quarantine). Example compensating controls include increased traffic monitoring and auditing.</p>', N'System and Information Integrity', N'Malicious Code Protection', NULL, NULL, N'WMATA', NULL, NULL, NULL, 73, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37981, N'SI-4', N'a. Monitor the system to detect:     1. Attacks and indicators of potential attacks in accordance with the following monitoring objectives: [Assignment: organization-defined      monitoring objectives]; and     2. Unauthorized local, network, and remote connections;b. Identify unauthorized use of the system through the following techniques and methods: [Assignment: organization-defined techniques and methods];c. Invoke internal monitoring capabilities or deploy monitoring devices:     1. Strategically within the system to collect organization-determined essential information; and     2. At ad hoc locations within the system to track specific types of transactions of interest to the organization;d. Analyze detected events and anomalies;e. Adjust the level of system monitoring activity when there is a change in risk to organizational operations and assets, individuals, other organizations, or the Nation;f. Obtain legal opinion regarding system monitoring activities; andg. Provide [Assignment: organization-defined system monitoring information] to [Assignment: organization-defined personnel or roles] [Selection (one or more): as needed; [Assignment: organization-defined frequency]].', N'<p><strong>WMATA Policy</strong></p><p>a. Monitor the system to detect:</p><p>i) Attacks and indicators of potential attacks in accordance with the following monitoring objectives:</p><p>(1) Systems shall be monitored in real-time to assure the proper functioning of system processes and controls at external interfaces to the system and within the system; and</p><p>(2) For assurance that the system is functioning in an optimal, resilient, and secure state and that any irregularities or anomalies that are indicators of a system malfunction or compromise are detected;</p><p>ii) Unauthorized local, network, and remote connections;</p><p>b. Identify unauthorized use of the system via the following tools, techniques and methods: intrusion detection and prevention systems, malicious code protection software, scanning tools, audit record monitoring software, and network monitoring software;</p><p>c. Invoke internal monitoring capabilities or deploy monitoring devices:</p><p>i) Strategically within the system to collect organization-determined essential information; and</p><p>ii) At ad hoc locations within the system to track specific types of transactions of interest to the organization;</p><p>d. Analyze detected events and anomalies;</p><p>e. Adjust the level of system monitoring activity when there is a change in risk to organizational operations and assets, individuals, other organizations, or the Nation;</p><p>f. Obtain legal advice regarding system monitoring activities; and</p><p>g. Provide information system monitoring information to personnel with administration, monitoring, and/or security responsibilities; continuously.</p><p><strong><u>OT Systems Only:</strong></u> The organization ensures that use of monitoring tools and techniques does not adversely impact the operational performance of the OT. Example compensating controls include deploying sufficient network process, and physical monitoring. </p><p>Related Controls: AC-2, AC-3, AC-4, AC-8, AC-17, AU-2, AU-6, AU-7, AU-9, AU-12, CA-7, CM-3, CM-6, CM-8, CM-11, IR-4, MA-3, MA-4, PL-9, PM-12, RA-5, SC-5, SC-7, SC-18, SI-3, SI-6, SI-7, SR-9, SR-10</p><p>h. Security Controls Enhancement(s):</p><p><br><strong><u>NIST 800-82 Rev 3:<br></strong></u>OT Discussion: The organization ensures that the use of monitoring tools and techniques does not adversely impact the operational performance of the OT. Example compensating controls include deploying sufficient network, process, and physical monitoring.</p>', N'System and Information Integrity', N'System Monitoring', NULL, NULL, N'WMATA', NULL, NULL, NULL, 73, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37982, N'SI-4 (10)', N'Make provisions so that [Assignment: organization-defined encrypted communications traffic] is visible to [Assignment: organization-defined system monitoring tools and mechanisms].', N'<p><strong>WMATA Policy</strong></p><p>Make provisions so that encrypted communications traffic is visible to organizational monitoring tools and mechanisms.</p>', N'System and Information Integrity', N'System Monitoring', NULL, NULL, N'WMATA', NULL, NULL, NULL, 73, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37983, N'SI-4 (12)', N'Alert [Assignment: organization-defined personnel or roles] using [Assignment: organization-defined automated mechanisms] when the following indications of inappropriate or unusual activities with security or privacy implications occur: [Assignment: organization-defined activities that trigger alerts].', N'<p><strong>WMATA Policy</strong></p><p>Alert required stakeholders using automated mechanisms when there are indications of inappropriate or unusual activities with security or privacy implications.</p>', N'System and Information Integrity', N'System Monitoring', NULL, NULL, N'WMATA', NULL, NULL, NULL, 73, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37984, N'SI-4 (14)', N'Employ a wireless intrusion detection system to identify rogue wireless devices and to detect attack attempts and potential compromises or breaches to the system.', N'<p><strong>WMATA Policy</strong></p><p>Employ a wireless intrusion detection system to identify rogue wireless devices and to detect attack attempts and potential compromises or breaches to the system.</p><p>Related Controls: AC-18, IA-3</p>', N'System and Information Integrity', N'System Monitoring', NULL, NULL, N'WMATA', NULL, NULL, NULL, 73, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37985, N'SI-4 (2)', N'<p><b>System Monitoring | Automated Tools and Mechanisms for Real-time Analysis</b></p>Employ automated tools and mechanisms to support near real-time analysis of events.', N'<p><strong>WMATA Policy</strong></p><p>Employ automated tools and mechanisms to support near real-time analysis of events.</p><p>OT Systems Only: In situations where the OT cannot support the use of automated tools to support near-real-time analysis of events, the organization employs compensating controls (e.g., providing an auditing capability on a separate system, nonautomated mechanisms or procedures) in accordance with the general tailoring guidance. </p><p>Related Controls: PM-23, PM-25</p><p><strong><u>NIST 800-82 Rev 3:<br></strong></u>OT Discussion: When the OT cannot support the use of automated tools for near-real-time analysis of events, the organization employs compensating controls (e.g., providing an auditing capability on a separate system, nonautomated mechanisms or procedures) in accordance with the general tailoring guidance.</p>', N'System and Information Integrity', N'System Monitoring', NULL, NULL, N'WMATA', NULL, NULL, NULL, 73, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37986, N'SI-4 (20)', N'Implement the following additional monitoring of privileged users: [Assignment: organization-defined additional monitoring].', N'<p><strong>WMATA Policy</strong></p><p>Implement the following additional monitoring of privileged users:</p><p>(1) Monitoring of all privileged actions taken or attempted; and</p><p>(2) Actions that violate normal or expected behaviors.</p><p>Related Controls: AC-18</p>', N'System and Information Integrity', N'System Monitoring', NULL, NULL, N'WMATA', NULL, NULL, NULL, 73, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37987, N'SI-4 (22)', N'(a) Detect network services that have not been authorized or approved by [Assignment: organization-defined authorization or approval processes]; and(b) [Selection (one or more): Audit; Alert [Assignment: organization-defined personnel or roles]] when detected.', N'<p><strong>WMATA Policy</strong></p><p>Detect network services that have not been authorized or approved by the DM Change Control Board and audit and alert when detected.</p><p>Related Controls: CM-7</p>', N'System and Information Integrity', N'System Monitoring', NULL, NULL, N'WMATA', NULL, NULL, NULL, 73, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37988, N'SI-4 (4)', N'(a) Determine criteria for unusual or unauthorized activities or conditions for inbound and outbound communications traffic;(b) Monitor inbound and outbound communications traffic [Assignment: organization-defined frequency] for [Assignment: organization-defined unusual or unauthorized activities or conditions].', N'<p><strong>WMATA Policy</strong></p><p>(1) Determine criteria for unusual or unauthorized activities or conditions for inbound and outbound communications traffic;</p><p>(2) Monitor inbound and outbound communications traffic continuously for unusual or unauthorized activities or conditions.</p><p></p>', N'System and Information Integrity', N'System Monitoring', NULL, NULL, N'WMATA', NULL, NULL, NULL, 73, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37989, N'SI-4 (5)', N'<p><b>System Monitoring | System-generated Alerts</b></p>Alert [Assignment: organization-defined personnel or roles] when the following system-generated indications of compromise or potential compromise occur: [Assignment: organization-defined compromise indicators].', N'<p><strong>WMATA Policy</strong></p><p>Alert required stakeholders when the following system-generated indications of compromise or potential compromise occur. At a minimum, compromise indicators may include but shall not be limited to the following:</p><p>(1) Protected system files or directories have been modified without notification from the appropriate change/configuration management channels;</p><p>(2) System performance indicates resource consumption that is inconsistent with expected operating conditions;</p><p>(3) Auditing functionality has been disabled or modified to reduce audit visibility;</p><p>(4) Audit or log records have been deleted or modified without explanation;</p><p>(5) The system is raising alerts or faults in a manner that indicates the presence of an abnormal condition;</p><p>(6) Resource or service requests are initiated from clients that are outside of the expected client membership set;</p><p>(7) The system reports failed logins or password changes for administrative or key service accounts;</p><p>(8) Processes and services are running that are outside of the baseline system profile; and</p><p>(9) Utilities, tools, or scripts have been saved or installed on production systems without a clear indication of their use or purpose.</p><p><strong><u>OT Systems Only: </strong></u>Example compensating controls include manual methods of generating alerts. </p><p>Related Controls: AU-4, AU-5, PE-6</p><p><br><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Example compensating controls include manually generating alerts. </p>', N'System and Information Integrity', N'System Monitoring', NULL, NULL, N'WMATA', NULL, NULL, NULL, 73, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37990, N'SI-5', N'a. Receive system security alerts, advisories, and directives from [Assignment: organization-defined external organizations] on an ongoing basis;b. Generate internal security alerts, advisories, and directives as deemed necessary;c. Disseminate security alerts, advisories, and directives to: [Selection (one or more): [Assignment: organization-defined personnel or roles]; [Assignment: organization-defined elements within the organization]; [Assignment: organization-defined external organizations]]; andd. Implement security directives in accordance with established time frames, or notify the issuing organization of the degree of noncompliance.', N'<p><strong>WMATA Policy</strong></p><p>a. Receive system security alerts, advisories, and directives from supply chain partners, external mission or business partners, external service providers, other peer or supporting organizations, Cybersecurity and Infrastructure Agency, Information Sharing and Analysis Centers, and other resources as determined by DMCS on an ongoing basis;</p><p>b. Generate internal security alerts, advisories, and directives as deemed necessary;</p><p>c. Disseminate security alerts, advisories, and directives to all staff with system administration, monitoring, and/or security responsibilities; and other required stakeholders; and</p><p>d. Implement security directives in accordance with established time frames or notify the issuing organization of the degree of noncompliance.</p><p><strong><u>OT Systems Only:</strong></u> CISA generates security alerts and advisories relative to OT at https://www.cisa.gove/uscert/ics. Industry-specific  ISACs often provide tailored advisories and alerts, which can be found at https://www.nationalisacs.org/.</p><p>Related Controls: PM-15, RA-5, SI-2</p><p>e. Security Controls Enhancement(s):</p><p><br><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: CISA generates security alerts and advisories relative to OT at <br><font color=#305496>https://www.cisa.gov/uscert/ics</font>. Industry-specific ISACs often provide tailored advisories and alerts, which can be found at <font color=#305496>https://www.nationalisacs.org/</font>.</p>', N'System and Information Integrity', N'Security Alerts, Advisories, and Directives', NULL, NULL, N'WMATA', NULL, NULL, NULL, 73, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37991, N'SI-5 (1)', N'Broadcast security alert and advisory information throughout the organization using [Assignment: organization-defined automated mechanisms].', N'<p><strong>WMATA Policy</strong></p><p>Broadcast security alerts and advisory information throughout the organization using automated mechanisms.</p>', N'System and Information Integrity', N'Security Alerts, Advisories, and Directives', NULL, NULL, N'WMATA', NULL, NULL, NULL, 73, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37992, N'SI-6', N'a. Verify the correct operation of [Assignment: organization-defined security and privacy functions];b. Perform the verification of the functions specified in SI-6a [Selection (one or more): [Assignment: organization-defined system transitional states]; upon command by user with appropriate privilege; [Assignment: organization-defined frequency]];c. Alert [Assignment: organization-defined personnel or roles] to failed security and privacy verification tests; andd. [Selection (one or more): Shut the system down; Restart the system; [Assignment: organization-defined alternative action(s)]] when anomalies are discovered.', N'<p><strong>WMATA Policy</strong></p><p>a. Verify the correct operation of system security and privacy functions;</p><p>b. Perform the verification of the system security and privacy functions during system startup, restart, shutdown, and abort and upon command by the user with appropriate privilege annually or as a part of information system continuous monitoring;</p><p>c. Alert required stakeholders to fail security and privacy verification tests; and</p><p>d. Audits shall be captured in accordance with Control 3.3 Audit and Accountability to reflect sufficient details as to the anomaly that occurred, appropriate action taken (e.g., shutdown of the system) as specified in the System Security Plan (SSP), and/or Control 3.5 Contingency Planning, Section 2, “CP-2 Information System Contingency Plan”, and personnel identified in Section 4, (g), (iii), “SI-4, (5) System-Generated Alerts” and Section 4, (g), (v), “SI-4 (12) Automated Organization-Generated Alerts”, and alerted when anomalies are discovered.</p><p>e. If the system is shut down due to a privacy-related anomaly, the relevant Control 3.3 Audit and Accountability and Control 3.5 Contingency Planning controls shall be updated in the SSP and the Information System Contingency Plan (ISCP)/Disaster Recovery Plan (DRP) to reflect how operations shall be maintained in the event of a system or system component outage.</p><p><strong><u>OT Systems Only:</strong></u> Shutting down and restarting the OT may not always be feasible upon the identification of an anomaly; these actions should be scheduled according to OT operational requirements. </p><p>Related Controls: CA-7, CM-4, CM-6, CP-2, SI-4, SI-7</p><p><strong><u>NIST 800-82 Rev 3:<br></strong></u>OT Discussion: Shutting down and restarting the OT may not always be feasible upon the identification of an anomaly. These actions should be scheduled according to OT operational requirements.</p>', N'System and Information Integrity', N'Security and Privacy Function Verification', NULL, NULL, N'WMATA', NULL, NULL, NULL, 73, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37993, N'SI-7', N'a. Employ integrity verification tools to detect unauthorized changes to the following software, firmware, and information: [Assignment: organization-defined software, firmware, and information]; andb. Take the following actions when unauthorized changes to the software, firmware, and information are detected: [Assignment: organization-defined actions].', N'<p><strong>WMATA Policy</strong></p><p>a. Employ integrity verification tools to detect unauthorized changes to system software, firmware, information, and data; and</p><p>b. Take the following actions when unauthorized changes to the software, firmware, and information are detected:</p><p>i) Audit the changes made in accordance with Control 3.3 Audit and Accountability;</p><p>ii) Notify/alert required stakeholders; and</p><p>iii) Take the appropriate action (e.g., shutdown or halting the system, reversing the changes, or triggering audit alerts) as specified in the SSP and/or Control 3.5 Contingency Planning, Section 2, “CP-2 Information System Contingency Plan”. If the system is shut down due to unauthorized changes, the relevant Control 3.3 Audit and Accountability and Control 3.5 Contingency Planning controls shall be updated in the SSP and the CP/DRP to reflect how operations shall be maintained in the event of a system or system component outage.</p><p><strong><u>OT Systems Only:</strong></u> The organization determines whether the use of integrity verification applications would adversely impact operation of the ICS and employs compensating controls (e.g., manual integrity verifications that do not affect performance). </p><p>Related Controls: AC-4, CM-3, CM-7, CM-8, CP-2, MA-3, MA-4, RA-5, SA-8, SA-9, SA-10, SC-8, SC-12, SC-13, SC-28, SI-3, SR-3, SR-4, SR-5, SR-6, SR-9, SR-10, SR-11</p><p><br><strong><u>NIST 800-82 Rev 3:<br></strong></u>OT Discussion: The organization determines whether the use of integrity verification <br>applications would adversely impact operation of the ICS and employs compensating controls <br>(e.g., manual integrity verifications that do not affect performance).</p>', N'System and Information Integrity', N'Software, Firmware, and Information Integrity', NULL, NULL, N'WMATA', NULL, NULL, NULL, 73, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37994, N'SI-7 (1)', N'<p><b>Software, Firmware, and Information Integrity | Integrity Checks</b></p>Perform an integrity check of [Assignment: organization-defined software, firmware, and information] [Selection (one or more): at startup; at [Assignment: organization-defined transitional states or security-relevant events]; [Assignment: organization-defined frequency]].', N'<p><strong>WMATA Policy</strong></p><p>Perform an integrity check of software, firmware, and information at least monthly and at system startup, restart, shutdown, abort, and during configuration changes or security-relevant events.</p><p><strong><u>OT Systems Only:</strong></u> The organization ensures that the use of integrity verification applications does not adversely impact the operational performance of the OT. </p><p><strong><u>NIST 800-82 Rev 3:<br></strong></u>OT Discussion: The organization ensures that the use of integrity verification applications does not adversely impact the operational performance of the OT. </p>', N'System and Information Integrity', N'Software, Firmware, and Information Integrity', NULL, NULL, N'WMATA', NULL, NULL, NULL, 73, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37995, N'SI-7 (15)', N'<p><b>Software, Firmware, and Information Integrity | Code Authentication</b></p>Implement cryptographic mechanisms to authenticate the following software or firmware components prior to installation: [Assignment: organization-defined software or firmware components].', N'<p><strong>WMATA Policy</strong></p><p>Implement cryptographic mechanisms that authenticate software and firmware components and provide digitally signed certificates from trusted authorities approved by DMCS prior to installation.</p><p><strong><u>OT Systems Only:</strong></u> Code authentication provides assurance to the organization that the software and firmware have not been tampered with. If automated mechanisms are not available, organizations could verify code authentication by manually using a combination of techniques including verifying hashes, downloading from reputable sources, verifying version numbers with the vendor, or testing software/firmware in offline/test environment. </p><p>Related Controls: CM-5, SC-12, SC-13</p><p><br><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Code authentication provides assurance that the software and firmware have not been tampered with. If automated mechanisms are not available, organizations could manually verify code authentication by using a combination of techniques, including verifying hashes, downloading from reputable sources, verifying version numbers with the vendor, or testing software and firmware in offline or test environments.</p>', N'System and Information Integrity', N'Software, Firmware, and Information Integrity', NULL, NULL, N'WMATA', NULL, NULL, NULL, 73, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37996, N'SI-7 (2)', N'<p><b>Software, Firmware, and Information Integrity | Automated Notifications of Integrity Violations</b></p>Employ automated tools that provide notification to [Assignment: organization-defined personnel or roles] upon discovering discrepancies during integrity verification.', N'<p><strong>WMATA Policy</strong></p><p>Employ automated tools that provide notification to required stakeholders upon discovering discrepancies during integrity verification.</p><p><strong><u>OT Systems Only:</strong></u> In situations where the organization cannot employ automated tools that provide notification of integrity discrepancies, the organization employs nonautomated mechanisms or procedures. Example compensating controls include performing scheduled manual inspections for integrity violations. </p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: When the organization cannot employ automated tools that provide notifications about integrity discrepancies, the organization employs nonautomated mechanisms or procedures. Example compensating controls include performing scheduled manual inspections for integrity violations. </p>', N'System and Information Integrity', N'Software, Firmware, and Information Integrity', NULL, NULL, N'WMATA', NULL, NULL, NULL, 73, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37997, N'SI-7 (5)', N'<p><b>Software, Firmware, and Information Integrity | Automated Response to Integrity Violations</b></p>Automatically [Selection (one or more): shut the system down; restart the system; implement [Assignment: organization-defined controls]] when integrity violations are discovered.', N'<p><strong>WMATA Policy</strong></p><p>Automatically act and implement controls (e.g., shutdown or halting the system, reversing the changes, or triggering audit alerts) when integrity violations are discovered. If the system is shut down due to unauthorized changes, the relevant security controls shall be updated in the SSP and the CP/DRP to reflect how operations shall be maintained in the event of a system or system component outage.</p><p><strong><u>OT Systems Only:</strong></u> Shutting down and restarting the ICS may not always be feasible upon identification of an anomaly; these actions should be scheduled according to ICS operational requirements. </p><p><strong><u>NIST 800-82 Rev 3:<br></strong></u>OT Discussion: Shutting down and restarting the ICS may not always be feasible upon identification of an anomaly. These actions should be scheduled according to ICS operational requirements.</p>', N'System and Information Integrity', N'Software, Firmware, and Information Integrity', NULL, NULL, N'WMATA', NULL, NULL, NULL, 73, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37998, N'SI-7 (7)', N'<p><b>Software, Firmware, and Information Integrity | Integration of Detection and Response</b></p>Incorporate the detection of the following unauthorized changes into the organizational incident response capability: [Assignment: organization-defined security-relevant changes to the system].', N'<p><strong>WMATA Policy</strong></p><p>Incorporate the detection of unauthorized system changes to include unauthorized changes to established configuration settings or baselines or unauthorized elevation of system privileges into the organizational incident response capability.</p><p><strong><u>OT Systems Only:</strong></u> In situations where the ICS cannot detect unauthorized security-relevant changes, the organization employs compensating controls (e.g., manual procedures) in accordance with the general tailoring guidance.</p><p>Related Controls: AU-2, AU-6, IR-4, IR-5, SI-4</p><p><br><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: When the ICS cannot detect unauthorized securityrelevant changes, the organization employs compensating controls (e.g., manual procedures) in accordance with the general tailoring guidance.</p>', N'System and Information Integrity', N'Software, Firmware, and Information Integrity', NULL, NULL, N'WMATA', NULL, NULL, NULL, 73, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (37999, N'SI-8', N'a. Employ spam protection mechanisms at system entry and exit points to detect and act on unsolicited messages; andb. Update spam protection mechanisms when new releases are available in accordance with organizational configuration management policy and procedures.', N'<p><strong>WMATA Policy</strong></p><p>a. Employ spam protection mechanisms at system entry and exit points to detect and act on unsolicited messages; and</p><p>b. Update spam protection mechanisms when new releases are available in accordance with organizational configuration management control family and procedures.</p><p><strong><u>OT Systems Only:</strong></u> OT organizations implement spam protection by removing spam transport mechanisms, functions, and services (e.g., electronic mail, web browsing) from the OT. </p><p>Related Controls: PL-9, SC-5, SC-7, SI-3, SI-4</p><p>c. Security Controls Enhancement(s):</p><p><strong><u>NIST 800-82 Rev 3:<br></strong></u>OT Discussion: OT organizations implement spam protection by removing spam transport mechanisms, functions, and services (e.g., electronic mail, web browsing) from the OT. </p>', N'System and Information Integrity', N'Spam Protection', NULL, NULL, N'WMATA', NULL, NULL, NULL, 73, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (38000, N'SI-8 (2)', N'<p><b>Spam Protection | Automatic Updates</b></p>Automatically update spam protection mechanisms [Assignment: organization-defined frequency].', N'<p><strong>WMATA Policy</strong></p><p>Automatically and continuously update spam protection mechanisms to ensure that updates occur on a regular basis and provide the latest content and protection capabilities.</p><p><strong><u>NIST 800-82 Rev 3:<br></strong></u>Rationale for removing SI-8 (2) from MOD and HIGH baselines: Spam transport mechanisms are disabled or removed from the OT, so automatic updates are not necessary. </p>', N'System and Information Integrity', N'Spam Protection', NULL, NULL, N'WMATA', NULL, NULL, NULL, 73, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (38001, N'SR-1', N'a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:     1. [Selection (one or more): Organization-level; Mission/business process-level; System-level] supply chain risk management policy that:          (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and           compliance; and          (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and     2. Procedures to facilitate the implementation of the supply chain risk management policy and the associated supply chain risk management      controls;b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the supply chain risk management policy and procedures; andc. Review and update the current supply chain risk management:     1. Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and     2. Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].', N'<p><strong>WMATA Policy</strong></p><p>Reference P/I 15.28 Cybersecurity Policy for requirements.</p><p><strong><u>OT Systems Only: </strong></u>Supply chain and procedures for OT should consider components received as well as components produced. Many OT systems use legacy components that cannot meet modern supply chain expectations. Appropriate compensating controls should be developed to achieve organization supply chain expectations for legacy systems. </p><p>Related Controls: PM-9, PM-30, PS-8, SI-12</p><p><br><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Supply chain policies and procedures for OT should consider both components received and components produced. Many OT systems use legacy components that cannot meet modern supply chain expectations. Appropriate compensating controls should be developed to achieve organizational supply chain expectations for legacy systems.</p>', N'Supply Chain Risk Management', N'Cybersecurity Supply Chain Risk Management Policy and Procedures', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1087, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (38002, N'SR-10', N'Inspect the following systems or system components [Selection (one or more): at random; at [Assignment: organization-defined frequency], upon [Assignment: organization-defined indications of need for inspection]] to detect tampering: [Assignment: organization-defined systems or system components].', N'<p><strong>WMATA Policy</strong></p><p>Inspect systems or system components for physical and logical tampering:<br>a.  Immediately upon delivery of a new system or system component and when there is a significant <br>change to a hardware, software, or firmware component;</p><p>b.  Immediately when a system or system component is removed and returned from travel to high-risk <br>locations or travel outside organizationally-controlled areas or facilities (other than when <br>personnel are in telework status in the contiguous US);</p><p>c.  Randomly when there are indications of a need for inspection to include changes in packaging, <br>specifications, factory location, entities, or locations in which the part is purchased; and</p><p>d. At the discretion of DMCS.</p><p>Related Controls: AT-3, PM-30, SI-4, SI-7, SR-3, SR-4, SR-5, SR-9, SR-11</p>', N'Supply Chain Risk Management', N'Inspection of Systems or Components', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1087, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (38003, N'SR-11', N'a. Develop and implement anti-counterfeit policy and procedures that include the means to detect and prevent counterfeit components from entering the system; andb. Report counterfeit system components to [Selection (one or more): source of counterfeit component; [Assignment: organization-defined external reporting organizations]; [Assignment: organization-defined personnel or roles]].', N'<p><strong>WMATA Policy</strong></p><p>a. Develop and implement anti-counterfeit procedures that include the validation of authenticity of <br>any system with the authorized vendor.</p><p>b. Report counterfeit system components to DMCS.</p><p>Related Controls: PE-3, SA-4, SI-7, SR-9, SR-10</p><p>c. Security Controls Enhancement(s):</p>', N'Supply Chain Risk Management', N'Component Authenticity', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1087, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (38004, N'SR-11 (1)', N'Train [Assignment: organization-defined personnel or roles] to detect counterfeit system components (including hardware, software, and firmware).', N'<p><strong>WMATA Policy</strong></p><p>Train System Owners to detect counterfeit system components (including hardware, software, and firmware).</p><p>Related Controls: AT-3</p>', N'Supply Chain Risk Management', N'Component Authenticity', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1087, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (38005, N'SR-11 (2)', N'Maintain configuration control over the following system components awaiting service or repair and serviced or repaired components awaiting return to service: [Assignment: organization-defined system components].', N'<p><strong>WMATA Policy</strong></p><p>Validate authenticity of any system being returned to service or coming back from repair with the authorized vendor.</p><p>Related Controls: CM-3, MA-2, MA-4, SA-10</p>', N'Supply Chain Risk Management', N'Component Authenticity', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1087, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (38006, N'SR-12', N'Dispose of [Assignment: organization-defined data, documentation, tools, or system components] using the following techniques and methods: [Assignment: organization-defined techniques and methods].', N'<p><strong>WMATA Policy</strong></p><p>Dispose of data, documentation, tools, or system components only after media sanitization techniques and methods in accordance with Control 3.12 Media Protection, Section 6, “MP-6 Media Sanitization”.</p><p>Related Controls: MP-6 </p>', N'Supply Chain Risk Management', N'Component Disposal', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1087, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (38007, N'SR-2', N'a. Develop a plan for managing supply chain risks associated with the research and development, design, manufacturing, acquisition, delivery, integration, operations and maintenance, and disposal of the following systems, system components or system services: [Assignment: organization-defined systems, system components, or system services];b. Review and update the supply chain risk management plan [Assignment: organization-defined frequency] or as required, to address threat, organizational or environmental changes; andc. Protect the supply chain risk management plan from unauthorized disclosure and modification.', N'<p><strong>WMATA Policy</strong></p><p>a. Develop a plan for managing supply chain risks associated with the research and development, design, manufacturing, acquisition, delivery, integration, operations and maintenance, and disposal of information and operational technology (IT/OT) systems, system components, or system services;</p><p>b. Review and update the supply chain risk management plan annually or as required, to address threat, organizational or environmental changes; and</p><p>c. Protect the supply chain risk management plan from unauthorized disclosure and modification.</p><p>Related Controls: CA-2, CP-4, IR-4, MA-2, MA-6, PE-16, PL-2, PM-9, PM-30, RA-3, RA-7, SA-8, SI-4</p><p>d. Security Controls Enhancement(s):</p>', N'Supply Chain Risk Management', N'Supply Chain Risk Management Plan', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1087, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (38008, N'SR-2 (1)', N'Establish a supply chain risk management team consisting of [Assignment: organization-defined personnel, roles, and responsibilities] to lead and support the following SCRM activities: [Assignment: organization-defined supply chain risk management activities].', N'<p><strong>WMATA Policy</strong></p><p>Establish a supply chain risk management team consisting of Procurement, the Legal Department, CORs/COTRs, CISO, AO, BISO, Cybersecurity SCRM Team, and other personnel/roles as deemed necessary to lead and support the following SCRM activities:</p><p>(1) Leading and supporting SCRM activities on projects and programs with a nexus to technology;</p><p>(2) Identification, assessment, and analysis of supply chain risks and the supply chain risk management program;</p><p>(3) Management and mitigation of supply chain risks; and</p><p>(4) Communication with internal and external partners or stakeholders (including third-party vendors (TPV)).</p>', N'Supply Chain Risk Management', N'Supply Chain Risk Management Plan', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1087, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (38009, N'SR-3', N'a. Establish a process or processes to identify and address weaknesses or deficiencies in the supply chain elements and processes of [Assignment: organization-defined system or system component] in coordination with [Assignment: organization-defined supply chain personnel];b. Employ the following controls to protect against supply chain risks to the system, system component, or system service and to limit the harm or consequences from supply chain-related events: [Assignment: organization-defined supply chain controls]; andc. Document the selected and implemented supply chain processes and controls in [Selection: security and privacy plans; supply chain risk management plan; [Assignment: organization-defined document]].', N'<p><strong>WMATA Policy</strong></p><p>a. Establish a process or processes to identify and address weaknesses or deficiencies in the supply chain elements and processes of systems in coordination with the SCRM Team;</p><p>b. Employ security controls in compliance with WMATA policy and instructions to protect against cybersecurity supply chain risks to the system, system component, or system service and to limit the harm or consequences from supply chain-related events; and</p><p>c. As a part of the acquisition process for any new technology, document the selected and implemented cybersecurity supply chain processes and controls in the Cybersecurity Supply Chain Risk Management Plan (CSCRMP).</p><p>i) All WMATA IT/OT systems, upon completion of the acquisition process but prior to operational use, are subject to the Assessment & Authorization (A&A) process and shall document or reference selected and implemented cybersecurity supply chain controls and processes annotated in the CSCRMP in System Security Plans (SSPs) affiliated with the A&A process.</p><p>Related Controls: CA-2, MA-2, MA-6, PE-3, PE-16, PL-8, PM-30, SA-2, SA-3, SA-4, SA-5, SA-8, SA-9, SA-10, SA-15, SC-7, SI-7, SR-6, SR-9, SR-11</p><p>d. Security Controls Enhancement(s):</p><p></p>', N'Supply Chain Risk Management', N'Supply Chain Controls and Processes', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1087, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (38010, N'SR-3 (1)', N'<p><b>Supply Chain Controls and Processes | Diverse Supply Base</b></p>Employ a diverse set of sources for the following system components and services: [Assignment: organization-defined system components and services].', N'<p><strong>WMATA Policy</strong></p><p>Employ a diverse set of sources for all system components and services.</p><p><strong><u>OT Systems Only:</strong></u> Using a diverse set of suppliers in the OT environment can improve reliability by reducing common cause failures. This is not always possible since some technologies have limited supply options that meet the operational requirements. </p><p><br><strong><u>NIST 800-82 Rev 3:<br></strong></u>OT Discussion: Using a diverse set of suppliers in the OT environment can improve reliability by reducing common cause failures. This is not always possible since some technologies have limited supply options that meet the operational requirements.</p><p></p>', N'Supply Chain Risk Management', N'Supply Chain Controls and Processes', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1087, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (38011, N'SR-3 (2)', N'Employ the following controls to limit harm from potential adversaries identifying and targeting the organizational supply chain: [Assignment: organization-defined controls].', N'<p><strong>WMATA Policy</strong></p><p>In order to limit harm from potential adversaries identifying and targeting the organizational supply chain, evaluate vendors prior to contract award and throughout the lifecycle of the contract for controls designed to reduce the probability of adversaries successfully identifying and targeting the supply chain, including:</p><p>(1) Avoiding the purchase of custom or non-standardized configurations;</p><p>(2) Employing approved vendor lists with standing reputations in the industry;</p><p>(3) Following pre-agreed maintenance schedules and update and patch delivery mechanisms;</p><p>(4) Maintaining a contingency plan in case of a supply chain event;</p><p>(5) Using procurement carve-outs that provide exclusions to commitments or obligations; and</p><p>(6) Minimizing the time between purchase decisions and delivery.</p>', N'Supply Chain Risk Management', N'Supply Chain Controls and Processes', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1087, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (38012, N'SR-3 (3)', N'Ensure that the controls included in the contracts of prime contractors are also included in the contracts of subcontractors.', N'<p><strong>WMATA Policy</strong></p><p>Ensure that the controls included in the contracts of prime contractors are also included in the contracts of subcontractors.</p><p>Related Controls: SR-5, SR-8</p>', N'Supply Chain Risk Management', N'Supply Chain Controls and Processes', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1087, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (38013, N'SR-4', N'Document, monitor, and maintain valid provenance of the following systems, system components, and associated data: [Assignment: organization-defined systems, system components, and associated data].', N'<p><strong>WMATA Policy</strong></p><p>a. Monitoring and documenting the chronology of the origin, development, ownership, location, and changes to a system or system component and the associated data, including personnel and processes used to interact with or make modifications to the system, component, or associated data. Document, monitor, and maintain valid provenance for systems, system components, and associated data, including procedures for allocating responsibilities for the creation, maintenance, and monitoring of provenance for systems and system components; transferring provenance documentation and responsibility between organizations; and preventing and monitoring for unauthorized changes to the provenance records.</p><p>Related Controls: CM-8, MA-2, MA-6, RA-9, SA-3, SA-8, SI-4</p><p>b. Security Controls Enhancement(s):</p>', N'Supply Chain Risk Management', N'Provenance', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1087, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (38014, N'SR-4 (1)', N'Establish and maintain unique identification of the following supply chain elements, processes, and personnel associated with the identified system and critical system components: [Assignment: organization-defined supply chain elements, processes, and personnel associated with organization-defined systems and critical system components].', N'<p><strong>WMATA Policy</strong></p><p>Establish and maintain unique identification (methods sufficient to support an investigation in case of a supply chain change (e.g., if a supply company is purchased), compromise, or event) of cybersecurity supply chain elements, processes, and personnel associated with the identified system and critical system components, including:</p><p>(1) Cybersecurity supply chain elements to include organizations, entities, or tools used for the research and development, design, manufacturing, acquisition, delivery, integration, operations, maintenance, and disposal of systems and system components.</p><p>(2) Cybersecurity supply chain processes to include development processes for hardware, software, and firmware; shipping and handling procedures; configuration management tools, techniques, and measures to maintain provenance; personnel and physical security programs; or other programs, processes, or procedures associated with the production and distribution of supply chain elements.</p><p>(3) Cybersecurity supply chain personnel to include individuals with specific roles and responsibilities related to the secure research and development, design, manufacturing, acquisition, delivery, integration, operations and maintenance, and disposal of a system or system component.</p><p>Related Controls: IA-2, IA-8, PE-16</p>', N'Supply Chain Risk Management', N'Provenance', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1087, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (38015, N'SR-4 (2)', N'Establish and maintain unique identification of the following systems and critical system components for tracking through the supply chain: [Assignment: organization-defined systems and critical system components].', N'<p><strong>WMATA Policy</strong></p><p>Establish and maintain unique identification (e.g., system components may be labeled using serial numbers or tagged using radio-frequency identification tags) of systems and critical system components for tracking through the supply chain.</p><p>Related Controls: IA-2, IA-8, PE-16</p>', N'Supply Chain Risk Management', N'Provenance', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1087, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (38016, N'SR-4 (3)', N'Employ the following controls to validate that the system or system component received is genuine and has not been altered: [Assignment: organization-defined controls].', N'<p><strong>WMATA Policy</strong></p><p>Employ controls (e.g., optical and nanotechnology tagging, physically unclonable functions, side-channel analysis, cryptographic hash verifications or digital signatures, and visible anti-tamper labels or stickers) to validate that the system or system component received is genuine and has not been altered, including:</p><p>(1) Monitoring for out of specification performance, which can be an indicator of tampering or counterfeits.</p><p>(2) Leveraging supplier and contractor processes for validating that a system or component is genuine and has not been altered and for replacing a suspect system or component.</p><p>(3) Monitoring for tampering that may be visible and addressable before accepting delivery, such as inconsistent packaging, broken seals, and incorrect labels.</p><p>Related Controls: AT-3, SR-9, SR-10, SR-11</p>', N'Supply Chain Risk Management', N'Provenance', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1087, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (38017, N'SR-4 (4)', N'Employ [Assignment: organization-defined controls] and conduct [Assignment: organization-defined analysis] to ensure the integrity of the system and system components by validating the internal composition and provenance of critical or mission-essential technologies, products, and services.', N'<p><strong>WMATA Policy</strong></p><p>Conduct assessments to ensure the integrity of the system and system components by validating the internal composition and provenance of critical or mission-essential technologies, products, and services. For microelectronics, this includes material composition of components. For software, this includes the composition of open-source and proprietary code, including the version of the component at a given point in time.</p><p>The validation of the internal composition and provenance shall be achieved by requiring various evidentiary artifacts or records from manufacturers and suppliers which are produced during the research and development, design, manufacturing, acquisition, delivery, integration, operations and maintenance, and disposal of technology, products, and services. Evidentiary artifacts include, but are not limited to, software identification (SWID) tags, software component inventory, the manufacturers’ declarations of platform attributes (e.g., serial numbers, hardware component inventory), and measurements (e.g., firmware hashes) that are tightly bound to the hardware itself.</p><p>Related Controls: RA-3</p>', N'Supply Chain Risk Management', N'Provenance', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1087, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (38018, N'SR-5', N'Employ the following acquisition strategies, contract tools, and procurement methods to protect against, identify, and mitigate supply chain risks: [Assignment: organization-defined acquisition strategies, contract tools, and procurement methods].', N'<p><strong>WMATA Policy</strong></p><p>Employ the following acquisition strategies, contract tools, and procurement methods to protect against, identify, and mitigate supply chain risks:</p><p>All solicitations shall be reviewed by DMCS and shall include cybersecurity specifications and the cybersecurity questionnaire as applicability is determined by DMCS. Where cybersecurity requirements have been applied to a solicitation, cybersecurity shall be included as an element of the selection criteria.</p><p>Acquisition strategies to include:</p><p>a. Requiring tamper-evident packaging or using trusted or controlled distribution;</p><p>b. Training, education, and awareness programs for personnel regarding supply chain risk, available mitigation strategies, and when the programs should be employed; and</p><p>c. Methods for reviewing and protecting development plans, documentation, and <br>evidence commensurate with the security and privacy requirements of the organization.</p><p>Related Controls: AT-3, SA-2, SA-3, SA-4, SA-5, SA-8, SA-9, SA-10, SA-15, SR-6, SR-9, SR-10, SR-11</p><p>d. Security Controls Enhancement(s):</p>', N'Supply Chain Risk Management', N'Acquisition Strategies, Tools, and Methods', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1087, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (38019, N'SR-5 (1)', N'<p><b>Acquisition Strategies, Tools, and Methods |Adequate Supply</b></p>Employ the following controls to ensure an adequate supply of [Assignment: organization-defined critical system components]: [Assignment: organization-defined controls].', N'<p><strong>WMATA Policy</strong></p><p>Ensure an adequate supply of critical system components through the following cybersecurity controls pertaining to HVA, as determined by DMCS:</p><p>(1) Track systems and component mean time to failure to mitigate the loss of temporary or permanent system function;</p><p>(2) The use of multiple suppliers throughout the supply chain for the identified critical components;</p><p>(3) Stockpiling spare components to ensure operation during mission-critical times; and</p><p>(4) The identification of functionally identical or similar components that may be used, if necessary.</p><p><strong><u>OT Systems Only:</strong></u> Vendor relationships and spare parts strategies are developed to ensure an adequate supply of critical components is available to meet operational needs. </p><p>Related Controls: RA-9</p><p><strong><u>NIST 800-82 Rev 3:</strong></u><br>OT Discussion: Vendor relationships and spare parts strategies are developed to ensure that an adequate supply of critical components is available to meet operational needs. </p><p>Rationale for adding SR-5 (1) to MOD and HIGH baselines: OT systems and system components are often built for purpose and have a limited number of vendors or suppliers for a specific component. Organizations identify critical OT system components and controls to ensure an adequate supply in the event of supply chain disruptions. </p>', N'Supply Chain Risk Management', N'Acquisition Strategies, Tools, and Methods', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1087, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (38020, N'SR-5 (2)', N'Assess the system, system component, or system service prior to selection, acceptance, modification, or update.', N'<p><strong>WMATA Policy</strong></p><p>Assess the system, system component, or system service prior to selection, acceptance, modification, or update.</p><p>Related Controls: CA-8, RA-5, SA-11, SI-7</p>', N'Supply Chain Risk Management', N'Acquisition Strategies, Tools, and Methods', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1087, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (38021, N'SR-6', N'Assess and review the supply chain-related risks associated with suppliers or contractors and the system, system component, or system service they provide [Assignment: organization-defined frequency].', N'<p><strong>WMATA Policy</strong></p><p>a. Assess and review the supply chain-related risks associated with suppliers or contractors and the system, system component, or system service they provide at the discretion of DMCS.</p><p>Related Controls: SR-3, SR-5</p><p>b. Security Controls Enhancement(s):</p>', N'Supply Chain Risk Management', N'Supplier Assessments and Reviews', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1087, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (38022, N'SR-6 (1)', N'Employ [Selection (one or more): organizational analysis; independent third-party analysis; organizational testing; independent third-party testing] of the following supply chain elements, processes, and actors associated with the system, system component, or system service: [Assignment: organization-defined supply chain elements, processes, and actors].', N'<p><strong>WMATA Policy</strong></p><p>Employ organizational analysis; independent third-party analysis; organizational testing; <br>independent third-party testing of systems, system components, or system services, which includes:</p><p>(1) Supply chain elements including organizations, entities, or tools that are used for the <br>research and development, design, manufacturing, acquisition, delivery, integration, operations, <br>maintenance, and disposal of systems, system components, or system services.</p><p>(2) Supply chain processes including supply chain risk management programs; SCRM strategies and <br>implementation plans; personnel and physical security programs; hardware, software, and firmware <br>development processes; configuration management tools, techniques, and measures to maintain <br>provenance; shipping and handling procedures; and programs, processes, or procedures associated <br>with the production and distribution of supply chain elements.</p><p>(3) Supply chain actors including individuals with specific roles and responsibilities in<br>the supply chain.</p><p>Related Controls: CA-8, SI-4</p>', N'Supply Chain Risk Management', N'Supplier Assessments and Reviews', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1087, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (38023, N'SR-7', N'Employ the following Operations Security (OPSEC) controls to protect supply chain-related information for the system, system component, or system service: [Assignment: organization-defined Operations Security (OPSEC) controls].', N'<p><strong>WMATA Policy</strong></p><p>Employ the following Operations Security (OPSEC) controls to protect supply chain-related information for the system, system component, or system service, including identifying critical information, analyzing friendly actions related to operations, and other activities to identify actions that can be observed by potential adversaries, determining indicators that potential adversaries might obtain that could be interpreted or pieced together to derive information in sufficient time to cause harm to WMATA, implementing safeguards or countermeasures to eliminate or reduce exploitable vulnerabilities and risk to an acceptable level, and considering how aggregated information may expose users or specific uses of the supply chain. Supply chain information includes user identities; uses for systems, system components, and system services; supplier identities; security and privacy requirements; system and component configurations; supplier processes; design specifications; and testing and evaluation results.</p>', N'Supply Chain Risk Management', N'Supply Chain Operations Security', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1087, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (38024, N'SR-8', N'Establish agreements and procedures with entities involved in the supply chain for the system, system component, or system service for the [Selection (one or more): notification of supply chain compromises; results of assessments or audits; [Assignment: organization-defined information]].', N'<p><strong>WMATA Policy</strong></p><p>Establish agreements and procedures with entities involved in the supply chain for the system, system component, or system service for the notification of supply chain compromises; and the sharing of results from assessments, audits or other sources that can assist the mitigation and resolution of supply chain risks or improve its processes.</p><p>Related Controls: IR-4, IR-6, IR-8</p>', N'Supply Chain Risk Management', N'Notification Agreements', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1087, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (38025, N'SR-9', N'Implement a tamper protection program for the system, system component, or system service.', N'<p><strong>WMATA Policy</strong></p><p>a. Implement a tamper protection program for the system, system component, or system service.</p><p>Related Controls: PE-3, PM-30, SA-15, SI-4, SI-7, SR-3, SR-4, SR-5, SR-10, SR-11</p><p>b. Security Controls Enhancement(s):</p>', N'Supply Chain Risk Management', N'Tamper Resistance and Detection', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1087, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (38026, N'SR-9 (1)', N'Employ anti-tamper technologies, tools, and techniques throughout the system development life cycle.', N'<p><strong>WMATA Policy</strong></p><p>Employ anti-tamper technologies, tools, and techniques throughout the system development life cycle.</p><p>Related Controls: SA-3</p>', N'Supply Chain Risk Management', N'Tamper Resistance and Detection', NULL, NULL, N'WMATA', NULL, NULL, NULL, 1087, NULL, NULL)
